\begin{eqnarray}
     \left[K\nabla^2-c(Q_{eq}^2- Q_0^2)+2\alpha^2\mu\right]\delta Q_{ij}+c(\delta Q_{kl}Q_{kl}^{(0)} +Q_{kl}^{(0)}\delta Q_{kl})Q_{ij}^{(0)}= -\alpha \sigma_{ij}.
\end{eqnarray}
Notice that the perturbation depends both on the magnitude and the orientation of the reference nematic field relative to the applied stress. Since both $\sigma_{ij}$ and $Q_{ij}$ have two independent components, the equation above corresponds to two coupled equations for the independent components. Let us first evaluate 
\begin{eqnarray*}
\delta Q_{kl}Q_{kl}^{(0)} &=& \delta Q_{xx}Q_{xx}^{(0)} +\delta Q_{xy}Q_{xy}^{(0)}+\delta Q_{yx}Q_{yx}^{(0)}+\delta Q_{yy}Q_{yy}^{(0)}\\
&=&2(\delta Q_{xx}Q_{xx}^{(0)}+\delta Q_{xy}Q_{xy}^{(0)})
\end{eqnarray*}
Thus, 
\begin{eqnarray*}
\delta Q_{kl}Q_{kl}^{(0)}+Q_{kl}^{(0)}\delta Q_{kl} &=& 4(Q_{xx}^{(0)}\delta Q_{xx}+Q_{xy}^{(0)}\delta Q_{xy})
\end{eqnarray*}
Hence, the two coupled equations read as 
\begin{eqnarray*}
     \left[K\nabla^2-c(Q_{eq}^2- Q_0^2)+2\alpha^2\mu\right]\delta Q_{xx}+4c(Q_{xx}^{(0)}\delta Q_{xx}+Q_{xy}^{(0)}\delta Q_{xy})Q_{xx}^{(0)} &=& -\alpha \sigma_{xx}\\
     \left[K\nabla^2-c(Q_{eq}^2- Q_0^2)+2\alpha^2\mu\right]\delta Q_{xy}+4c(Q_{xx}^{(0)}\delta Q_{xx}+Q_{xy}^{(0)}\delta Q_{xy})Q_{xy}^{(0)} &=& -\alpha \sigma_{xy}\\
\end{eqnarray*}
or equivalently, by arranging terms, 
\begin{eqnarray*}
     \left[K\nabla^2-c(Q_{eq}^2- Q_0^2-4Q_{xx}^{(0)})+2\alpha^2\mu\right]\delta Q_{xx}+4c Q_{xy}^{(0)}Q_{xx}^{(0)}\delta Q_{xy} &=& -\alpha \sigma_{xx}\\
     \left[K\nabla^2-c(Q_{eq}^2- Q_0^2-4Q_{xy}^{(0)})+2\alpha^2\mu\right]\delta Q_{xy}+4c Q_{xx}^{(0)}Q_{xy}^{(0)}\delta Q_{xx} &=& -\alpha \sigma_{xy}.
\end{eqnarray*}
Let us simplify these equations further by considering that the magnitude of the reference nematics is $Q_0 = Q_{eq}$. The components of the nematic tensors in terms of the orientation of the nematic director $\hat {\bm{n}} = [\cos(\theta); \sin(\theta)]$ are 
\[Q_{xx} = \frac{S}{2}\cos(2\theta), \qquad Q_{xy} = \frac{S}{2}\sin(2\theta)\]
Thus, 
\begin{eqnarray*}
     \left[K\nabla^2+2c S_0\cos(2\theta_0)+2\alpha^2\mu\right]\delta Q_{xx}+c \frac{S_0^2}{2}\sin(4\theta_0) \delta Q_{xy} &=& -\alpha \sigma_{xx}\\
     \left[K\nabla^2+2cS_0\sin(2\theta_0)+2\alpha^2\mu\right]\delta Q_{xy}+c\frac{S_0^2}{2}\sin(4\theta_0)\delta Q_{xx} &=& -\alpha \sigma_{xy}.
\end{eqnarray*}
In the Fourier space, these equations reduce to 
\begin{eqnarray*}
     \left[-K q^2+2c S_0\cos(2\theta_0)+2\alpha^2\mu\right]\delta{\hat Q}_{xx}+c \frac{S_0^2}{2}\sin(4\theta_0) \delta {\hat Q_{xy}} &=& -\alpha \sigma_{xx}\delta(\mathbf k)\\
     \left[-K q^2+2cS_0\sin(2\theta_0)+2\alpha^2\mu\right]\delta{\hat{Q}}_{xy}+c\frac{S_0^2}{2}\sin(4\theta_0)\delta{\hat Q}_{xx} &=& -\alpha \sigma_{xy}\delta(\mathbf k).
\end{eqnarray*}
Without loss of generality, let us consider that the reference nematic is along the $x$-axis, i.e. $\theta_0=0$. Then the two components decouple as
\begin{eqnarray*}
     \left[-K q^2+2c S_0+2\alpha^2\mu\right]\delta{\hat Q}_{xx} &=& -\alpha \sigma_{xx}\delta(\mathbf q)\\
     \left[-K q^2+2\alpha^2\mu\right]\delta{\hat{Q}}_{xy} &=& -\alpha \sigma_{xy}\delta(\mathbf q).
\end{eqnarray*}
The solutions follow as 
\begin{eqnarray}
    \delta Q_{xx} &=& -\frac{\alpha \sigma_{xx}}{2\alpha^2\mu+2cS_0} \\
    \delta Q_{xy} &=& -\frac{\sigma_{xy}}{2\alpha\mu}
\end{eqnarray}
Thus, under simple shear, i.e. $\sigma_{xx} =0$, 
\[\sin(2\delta\theta) =\pm 1\Rightarrow \delta \theta = \pm \frac{\pi}{4}\]
meaning that the nematic director, original along $x$-direction, is now aligned at $45$ degrees. The sign is determined by the direction of shear. 

Similarly for pure shear, i.e. $\sigma_{xy} = 0$ and $\sigma_{xx} = -\sigma_{yy}$, 
\[\cos(2\delta\theta) = \pm 1 \Rightarrow \delta \theta = \frac{\pi}{2} \ \rm{or} \ \delta \theta =0\]
meaning that the nematic director is aligned at $90$ degrees or remains along the $x$ axis depending on the compression/extension directions. 

Finally, to see how the effective shear modulus is  altered by the nematic reorientation, we evaluate the Erickson stress, 
\begin{eqnarray*}
    \sigma_{ij} &=& 2\mu \delta\varepsilon_{ij} +2\mu \delta Q_{ij}.
\end{eqnarray*}
For simple shear, this means 
\begin{eqnarray*}
    \sigma_{xy} &=& 2\mu \varepsilon_{xy} -\frac{\sigma_{xy}}{\alpha} \Rightarrow \\
    \sigma_{xy} &=& \frac{2\alpha\mu}{\alpha+1}\delta\varepsilon_{xy}
\end{eqnarray*}
For simple shear, the relation becomes 
\begin{eqnarray}
    \sigma_{xx} &=& 2\mu \delta\varepsilon_{xx} -\frac{\sigma_{xx}}{\alpha(1+\frac{cS_0}{\alpha^2\mu})}\Rightarrow \\
    \sigma_{xx} &=& 2\mu \frac{\alpha^2\mu +c S_0}{\alpha^2\mu +c S_0+\alpha\mu}\delta\varepsilon_{xx}
\end{eqnarray}

