\begin{abstract}
    We consider an $N$-soliton  solution of the focusing nonlinear Schr\"{o}dinger equations.  We give conditions for the synchronous collision  of these $N$ solitons. When the solitons velocities are well separated  and the solitons have equal amplitude,  we  show that the local  wave profile at the collision point   scales as  the   \( \sinc(x) \) function. We show that this behaviour persists when the amplitudes of the solitons are  i.i.d. sub-exponential random variables.  Namely the {central collision peak} exhibits \emph{universality}: its spatial profile converges   to the $\sinc(x)$ function, independently of the distribution. We derive Central Limit Theorems for the fluctuations of the profile in the near-field regime (near the collision point) and in the far-regime.
\end{abstract}

% \tableofcontents


\section{Introduction and Main Results}

We consider the focusing Nonlinear Schr\"{o}dinger (fNLS) equation in $1+1$ dimensions
\begin{equation}\label{eq:nls}
    \ii \psi_t + \frac{1}{2}\psi_{xx} + |\psi|^2 \psi = 0, \quad (x,t) \in \R\times [0,+\infty)\ .
\end{equation}
This equation has countless applications both in physics and engineering. It serves as a model of nonlinear waves: in particular, water waves of small amplitude over
infinite depth \cite{Zakharov68} and finite depth \cite{BenneyRoskes69, HasimotoOno72}, as well as almost monochromatic waves in a weakly nonlinear dispersive medium \cite{BenneyNewell67,CalogeroEckhaus87} and rogue waves  \cite{Chabchoubetal11,Peregrine83}.  It also appears in the study of the propagation of signal in fiber optics \cite{Suret2011, Chiaoetal64, Talanov64}, plasma of fluids \cite{Zakharov71},  Bose–Einstein condensations  \cite{PethickSmith02}, to mention a few. 
In this manuscript  we analyze the behaviour of soliton interactions.  In particular
\begin{itemize}
    \item 
we identify the 
 soliton  parameters that maximizes the  amplitude of the wave profile at the interaction time;
 \item we prove that a train  of   solitons of equal amplitudes and  well separated velocities  has a distinguished  collision profile given by the $sinc$  function;
\item  we prove the universality of  the $sinc$  profile   by showing that it surprisingly persists when the soliton amplitudes are  sampled from a probability  distribution  and  the velocities  are well separated. 
\end{itemize}
We further   confirm   the well known fact  that fast solitons interact linearly at leading order, and  we provide an explicit expression of the sub-leading (nonlinear) corrections that is instrumental to obtain our results.
Below we explain in detail our results.



\subsection{Deteministic  Soliton Solutions}

The fNLS equation \eqref{eq:nls} is an example of an integrable equation that admits {\em soliton solutions}. The simplest of these is the family of one-soliton solutions 
\begin{equation}
\label{one_soliton}
\begin{cases}
\psi(x,t;z,c) = \mu \sech\big(\mu(x-x_0-v t  )\big) \ee^{\ii \lp x v - \tfrac{t}{2}(v^2-\mu^2) - \phi_0- \pi \rp}, \\
z = \tfrac12(-v+ \ii \mu) \in \C^+, \quad c = \ii \mu \ee^{\mu x_0 + \ii \phi_0} \in \C_*=\C\setminus\{0\}.
\end{cases}
\end{equation}
Each such solution describes a localized traveling wave with velocity $v$ and maximum amplitude $\mu$. Given $2N$ complex constants, which we call \emph{reflectionless scattering data},
\begin{equation}\label{eq:soliton parameters}
    \{(z_k, c_k)\}_{k=1}^N \in \mathbb{C}^+ \times \mathbb{C}_*,  \qquad z_k = \tfrac12(-v_k+ \ii \mu_k), \quad c_k = \ii \mu_k \ee^{\mu_k x_k + \ii \phi_k},
\end{equation}
equation \eqref{eq:nls} also admits an $N$-soliton solutions, which we denote by \( \psi_N(x,t) \), whose absolute value has the following determinantal representation  
\begin{equation}\label{eq:nls Kay-Moses}
    |\psi_N(x,t)|^2 = \partial_{xx} \log \det \big( {\boldsymbol I}_N + {\boldsymbol \Phi}_N(x,t) \overline{\boldsymbol \Phi_N(x,t)} \big),
\end{equation}
where $\boldsymbol\Phi_N(x,t)$ is the $N \times N$ matrix with entries
\begin{equation}
    \left[ \boldsymbol\Phi_N(x,t) \right]_{jk} = \frac{ \sqrt{c_j \overline c_k} \ee^{2\ii(\theta(z_j,x,t)-\theta(\overline z_k,x,t))}}{\ii(z_j-\overline z_k)},
    \qquad
    \theta(z,x,t) = x z + t z^2.
\end{equation}
The wave field of an $N$-soliton solution can become very complex for large $N$. However,
the scattering theory for the reflectionless fNLS provides a general upper bound on the wave amplitude in terms of the scattering data: 
\begin{equation}\label{eq:upper_bound_result}
    | \psi_N(x,t)| \leq \sum_{k=1}^N \mu_k.
\end{equation}
In fact, this upper bound is tight, and the following proposition gives a precise description of how it can be realized.    
\begin{proposition}
\label{thm:darboux_intro}
The  $N$-soliton solution $\psi_N(x,t)$ of \eqref{eq:nls} described by reflectionless scattering data \eqref{eq:soliton parameters} with 
    norming constant 
    \begin{equation}\label{eq:max_norming_const}
    \displaystyle c_k =  \frac{\ee^{-2\ii z_k x_0 -2\ii z_k^2 t_0}}{B'(z_k)} \ , \quad  \forall \, k=1,\ldots, N\ , \qquad
    B(z) := \prod_{k=1}^N\frac{z-z_k}{z-\overline z_k}\ ,
\end{equation}
    realizes the upper bound in \eqref{eq:upper_bound_result} at \( x=x_0 \) and $t =t_0$, namely,
    \begin{equation}
    \label{upper bound}
        |\psi_N(x_0,t_0)|= \sum_{k=1}^N \mu_k\,.
    \end{equation}
\end{proposition}


Additionally, it is well known, see \cite{Jenkins2018}, that whenever the velocities $v_k = -2\Re(z_k)$ are distinct, such a solution resolves asymptotically in the large time limit to the sum of one-soliton solutions
\begin{equation}
    \psi_N(x,t) = \sum_{k=1}^N \psi(x-x^\pm_k,t;z_k,c_k) e^{\ii \phi_k^\pm} + \bigo{e^{-\kappa|t|}}, \qquad t \to \pm \infty,
\end{equation}
where $\kappa >0$ depends on the eigenvalues $z_k$, $k=1,\dots N$, and the asymptotic phase shifts are given by
\begin{equation}\label{eq:NLS phase shifts}
    x_k^+ - x_k^- = \frac{2}{\mu_k} \sum_{j \neq k}^N \sgn(v_j-v_k) \log \left| \frac{ z_k-z_j}{z_k - \overline z_j} \right|, 
    \qquad
    \phi_k^+ - \phi_k^- = 2\sum_{j \neq k}^N \sgn(v_j-v_k) \arg\left( \frac{ z_k-z_j}{z_k - \overline z_j} \right).
\end{equation}
This formula is the justification for the statement that soliton interactions are asymptotically elastic, i.e. the physical characteristics (velocity and amplitude) of the solitons are asymptotically invariant; the only effect of the collision is the induced phase shifts. 


On the other hand, for intermediate times the interactions of the ``individual'' solitons can generate very large wave peaks as supported by Proposition~\ref{thm:darboux_intro}. 
In this setting, the solitons interact almost linearly, indeed at the level of \eqref{eq:NLS phase shifts} one sees that 
% This happens when individual solitons have well separated velocities. Informally, one can understand this by arguing that the time interval in which the soliton supports overlap is too short to have meaningful effect on their evolution. 
%At the level of \eqref{eq:NLS phase shifts} one sees that 
 \begin{equation}
  \frac{ z_k - z_j}{z_k - \overline z_j} = 1 + \frac{2\ii \mu_j}{v_k - v_j} + \bigo{(v_k -v_j)^{-2}} ,  
\end{equation}
so that, when the soliton velocities are well separated, the phase shifts due to the pairwise soliton interactions become small. 
Our first main result gives a precise characterization of the asymptotic linearity of the soliton interactions when their velocities are well-separated. Moreover, it provides an explicit first correction to the leading order linearity with bounds on the higher order corrections. 



\begin{theorem}
\label{thm:1}
Given $N \in \mathbb{N}$, consider the  $N$-soliton solution $\psi_N(x,t)$ of \eqref{eq:nls} corresponding to the reflectionless spectral data \eqref{eq:soliton parameters} with distinct velocities. Define 
\[
\Delta := \min_{j\neq k}|v_j-v_k|>0.
\]
Let \( \boldsymbol\mu=(\mu_1,\mu_2,\ldots,\mu_N) \) be the vector of soliton amplitudes. Then there exists $C_*>0$  such that for all $\Delta>C_*\|\boldsymbol\mu\|_\infty$ it holds that
\begin{multline} 
\label{linear interaction}
    \psi_N(x,t) 
   = \sum_{k=1}^N \psi^{(k)}(x,t) + \\
  \qquad  \frac{1}{2\ii } \sum_{j=1}^N\sum_{\substack{ k=1 \\ k \neq j}}^N
   \left[  \frac{\psi^{(k)}(x,t){m^{(j)}(x,t)}}{z_j - \overline z_k} - \frac{m^{(k)}(x,t) \psi^{(j)}(x,t)}{\overline z_j - \overline z_k}
    \right]
    + \bigo{\frac{\|\boldsymbol\mu\|_\infty \| \boldsymbol\mu\|_2^2}{\Delta^{2}}},
\end{multline}
where \( \psi^{(k)}(x,t) =\psi(x,t;z_k,c_k)\) is the one-soliton solution \eqref{one_soliton} and \( m^{(k)}(x,t) = \int_x^\infty |\psi^{(k)}(s,t)|^2 \di s \). The error bounds are uniform for all $(x,t)\in \R^2$ and depend on $N$ only through the norms $\| \boldsymbol\mu \|_\infty := \sup_{1\leq k \leq N} |\mu_k|$ and $\| \boldsymbol{\mu}\|_2^2 := \sum_{k=1}^N | \mu_k |^2 $.
\end{theorem} 

\begin{remark}
\label{error terms}
    The proof of Theorem~\ref{thm:1} shows that the first correction term, the double sum in \eqref{linear interaction}, is of order \( \|\boldsymbol{\mu}\|_2^2/\Delta \). In particular, if the magnitudes \( \mu_k \) are uniformly (independently of \( N\)) bounded above and away from zero, then \( \|\boldsymbol{\mu}\|_2^2 \sim N \). In this case, the leading term in \eqref{linear interaction} can be of order \( N \) (see \eqref{upper bound} and \eqref{sinc profile} further below), the first correction term is of order \( N/\Delta \), while the remaining error terms are of order \( N/\Delta^2 \).
\end{remark}

Theorem~\ref{thm:1} shows that for well separated velocities the phase shifts induced by soliton interactions become negligible. In what follows, we tune the discrete spectral data so that: (1) the  solitons all collide at a fixed point in space time $(x_0,t_0)$, that in view of the Galilean invariance of the fNLS equation, we assume without loss of generality to be \( (0,1) \); and (2) the soliton phases are tuned so that the maximum of the solution at collision time is exactly equal to the sum of the soliton amplitudes, as proven in Proposition \ref{thm:darboux_intro}.

