\subsection{Stochastic  Soliton Solution}


We now consider synchronized solitons with \emph{random scattering data}. We assume that  the magnitudes $\mu_k$ of the scattering data are random, while we keep the velocities $v_k$ deterministic. In order to control probabilistic fluctuations we need sufficiently strong control on the error terms in Theorem~\ref{thm:1}. To this end, we make the following assumptions.
\begin{assumption} \label{hp:random_scattering_intro}
In our probabilistic calculations we assume the following:
\begin{enumerate}
 \item The velocities are deterministic, equally spaced with spacing which grows with the number of solitons:
 \begin{equation}\label{eq:scalingDelta}
   v_k = k\Delta, \quad \Delta = \beta N^\gamma \ , \qquad \beta>0, ~~ \gamma > \tfrac{1}{2};
 \end{equation}
\item The amplitudes $\mu_k$ are independent identically distributed (i.i.d.) random variables 
\begin{equation}
\mu_k \ \sim \ \mathcal D,
\end{equation}
where $\mathcal D$ is any distribution with positive support, mean $\mu_{\mathcal D}$,  and sub exponential with parameters $(\nu,\alpha)$  (see Definition \ref{def:subexp})
\item The norming constants are random variables
\begin{equation}
    c_k = \ii \mu_k \ee^{-2\ii z_k^2}\,, \qquad z_k := \tfrac12(-k\Delta + \ii \mu_k) \ .
\end{equation}
\end{enumerate}
\end{assumption}

Under these assumptions, the $N$-soliton solution $\psi_N(x,t)$ becomes a random variable, where the solitons have random amplitudes and velocities proportional to $N$. 
In this setting, we prove a law of large numbers at the collision point showing that the emerging sinc-profile is universal, independent from the choice of the random distribution (Proposition \ref{prop:prop_CLT_intro}). This result is consistent with the deterministic case (Corollary \ref{cor:sinc}). Furthermore, we obtain central limit theorems for the fluctuations of the profile, both in the near-field region, close to the rogue wave peak (Theorem \ref{thm:local_CLT_intro}), and in the far-field region (Theorem \ref{thm:envelope_intro}). 

\begin{proposition}[\bf Universal $\sinc$-profile]
\label{prop:prop_CLT_intro}
    By choosing random soliton amplitudes according to Assumption \ref{hp:random_scattering_intro},  it holds for each fixed pair $(X,T)\in \R^2$ that
        \begin{equation}
        \frac{1}{\mu_{\mathcal D} N}\psi_N\left(\frac{2X}{\Delta N}, 1 +\frac{T}{\Delta^2N^2} \right) \to \psi_0(X,T) \quad \text{as $N\to \infty$,  in probability}\,,
    \end{equation}
    where $\mu_\cD$ is the mean value of the distribution $\cD$ and $\psi_0(X,T)$ was defined in \eqref{fresnel}.
    In particular, at collision time ($T=0$), we have 
       \begin{equation}
       \label{eq:sinc_univeral}
        \frac{1}{\mu_{\mathcal D} N} \psi_N\left(\frac{2X}{
        \Delta N},1\right) \to -\frac{\sin(X)}{X}e^{\ii X} \quad \text{as $N\to \infty$, in probability}\,.
    \end{equation}
\end{proposition}

Equation \eqref{eq:sinc_univeral} shows that a universal macroscopic profile emerges in the large $N$ limit near the collision singularity, which we illustrate numerically on \figurename~\ref{fig:sinc_universal}. 

