In fact, Proposition~\ref{prop:prop_CLT_intro} is a consequence of the following more general  theorem.

\begin{theorem}[{\bf Central Limit Theorem in the near-field regime}]
 \label{thm:local_CLT_intro} 
    Under Assumption \ref{hp:random_scattering_intro}, for all $X, T \in \R$, the following holds
    \begin{align}
    \label{eq:clt_re}
        &  \frac{\Re\Big( \psi_{N}\lp \frac{2X}{\Delta N},1+ \frac{T}{\Delta^2N^2}\rp - N\mu_{\mathcal D}\, \psi_0(X,T)\Big)}{ \sqrt{N \Var_{\cD}}} \xrightarrow[N\to\infty]{\text{law}} \mathcal{N}\big( 0,\sigma_+(X,T)\big)\,, \\
        \label{eq:clt_im}
          &  \frac{\Im\Big(\psi_{N}\lp \frac{2X}{\Delta N},1+ \frac{T}{\Delta^2N^2}\rp - N \mu_{\mathcal D}\, \psi_0(X,T)\Big)}{ \sqrt{N \Var_{\cD}} } \xrightarrow[N\to\infty]{\text{law}}  \mathcal{N}\big( 0,\sigma_-(X,T) \big) \, ,\\
          \label{eq:clt_mod}
        &  \frac{\left \vert \psi_{N}\lp \frac{2X}{\Delta N},1+\frac{T}{\Delta^2N^2}\rp - N \mu_{\mathcal D}\,\psi_0(X,T)  \right \vert}{ \sqrt{N \Var_{\cD}}}  \xrightarrow[N\to\infty]{\text{law}}  \mathcal H(\varphi(X,T))\,,
    \end{align}
     where $\Var_{\cD} $ is the variance of the distribution $\mathcal D$,  $\mathcal H(\varphi)$ is the Hoyt distribution (see Lemma \ref{lem:CLT_approx}), and
    \[
    \sigma_{\pm}(X,T) = \frac{1}{2}\left(1 \pm \int_0^1 \cos \left( 4Xs - Ts^2 \right) \di s \right)  \ .
    \]
\end{theorem}




