\begin{remark}
    The variances $\sigma_\pm$ in \eqref{eq:clt_re}-\eqref{eq:clt_im} can be expressed as
\begin{multline}
    \sigma_\pm(X,T)= 
    \frac{1}{2}\left( 
    1 \pm \sqrt{\tfrac{\pi}{2T}} 
    \left\{ \cos(\xi^2) 
    \left[ 
      C\left( \sqrt{\tfrac{2}{\pi} } (\sqrt{T} - \xi) \right)
      +C\left( \sqrt{\tfrac{2}{\pi}}  \xi \right) 
    \right] 
     \right. \right. \\ \left. \left.
     + \sin(\xi^2)
      \left[
       S\left( \sqrt{\tfrac{2}{\pi} } (\sqrt{T} - \xi) \right)
       +S\left( \sqrt{\tfrac{2}{\pi}}  \xi \right) 
     \right]
    \right\}
    \right)\ ,  
\end{multline}
where $\xi(X, T) = \frac{2X}{\sqrt{T}}$, and $C(\cdot)$ and $S(\cdot)$ are the Fresnel integrals \cite[Formula 7.2.7 and 7.2.8]{DLMF}. 
\end{remark}

Notice that the limiting variances in \eqref{eq:clt_re}--\eqref{eq:clt_mod} are {independent} from the distribution $\cD$, thus universal. In \figurename~\ref{fig:fluctuations} we show the results for the Beta distribution and the uniform distribution. 


\begin{remark}
\label{rem:first_clt}
For $(X,T)=(0,0)$, the variance of the normal distribution in \eqref{eq:clt_im} vanishes, which implies that the random variable  $\Im( \psi_{N}(0,0))$ is deterministically equal to $0$ in the limit as $N\to \infty$. This is consistent with the decomposition in Theorem \ref{thm:1}, where the leading term is real for $(X,T)=(0,0)$, and the remaining terms are asymptotically small with high probability (see Lemma \ref{prop:prob_error_estimate} and \eqref{eq:error_estimate_prob1}-\eqref{eq:error_estimate_prob2}).
\end{remark}


Finally, we analyze the fluctuations of the global profile of the $N$-soliton solution at collision time $\psi_N(x,1)$ over the whole spatial domain. 
\begin{theorem}[\bf Central Limit Theorem for the global profile at collision time]
\label{thm:envelope_intro}
     Let $x\in \R$. Under Assumption \ref{hp:random_scattering_intro}, consider the  \( N \)-soliton solution $\psi_{N}(x,t)$ of the fNLS equation \eqref{eq:nls}. Then the following  holds
    \begin{align}
    \label{eq:clt_envelope_re}
        &  \frac{\Re\lp\psi_N(x,1) \rp- \omega_\cD(x) \cos\lp  \frac{x\Delta(N+1)}{2}\rp D_N(x\Delta) }{\sigma_{N,\Re}(x)} \xrightarrow[N\to\infty]{\text{law}}  \cN(0,1)\,, \\
        \label{eq:clt_envelope_im}
        &  \frac{\Im\lp \psi_N(x,1) \rp - \omega_\cD(x) \sin\lp  \frac{x\Delta N}{2}\rp D_{N+1}(x\Delta)}{\sigma_{N,{\Im}}(x)} \xrightarrow[N\to\infty]{\text{law}}  \cN(0,1)\,, \quad {\text{for } x\neq 0\,,}
    \end{align}
    where $D_N(x) := \frac{\sin\lp \frac{x N}{2}\rp}{\sin \lp \frac{x}{2}\rp}$ is the Dirichlet kernel,
    \begin{align}
        & \omega_\cD(x) = - \meanval{\frac{\xi}{\cosh( x\xi)}}\, , \quad \xi\sim \cD\, , \label{eq:omega_D}\\
        \label{eq:real_var_envelope}
        &\sigma^2_{N,\Re}(x) = \Var\lp\frac{\xi}{\cosh( x\xi)}  \rp\lp \frac{N-1}{2} + \frac{1}{2} \cos\lp x\Delta N \rp D_{N+1}(2x\Delta) \rp \,,  \\ 
        &\sigma^2_{N,\Im}(x) = \Var\lp\frac{\xi}{\cosh( x\xi)}  \rp\lp \frac{N+1}{2} - \frac{1}{2}  \cos\lp x\Delta N \rp D_{N+1}(2x\Delta) \rp \, ,
    \end{align}
    and $\Var(\cdot) $ is the variance of the given random variable. Moreover, 
    \begin{equation}
    \label{eq:clt_envelope_mod}
        \lim_{N\to\infty} \frac{1}{N} \Big( \left|\psi_N(x,1)\right| - \left|\omega_\cD(x)D_N(x\Delta)\right|\Big) \to 0
    \end{equation}
    in probability.

\end{theorem}

We define the function $|\omega_\cD(x)|$ as the {\em envelope}, meaning a smooth curve outlining the extremes of an oscillating signal. 
As an example, if $\cD \sim \chi^2(2)$, 
% i.e.
% \begin{equation}
%     \meanval{f(\cD)} = \frac{1}{2}\int_{0}^\infty f(y)\ee^{-\frac{y}{2}}\di y\,,
% \end{equation}
the envelope is equal to
\[
 |\omega_{\mathcal D}(x)| = \frac{\Psi ^{(1)}\left(\frac{| x| +1}{4 | x| }\right)-\Psi ^{(1)}\left(\frac{1}{4} \left(3+\frac{1}{| x| }\right)\right)}{8 x^2}\,,
\]
where $\Psi^{(1)}$ is the $1^{st}$ poly-gamma function \cite[Ch. 5]{DLMF}. 
In \figurename~\ref{fig:envelope}, we show the envelope profile $|\omega_{\mathcal D}(x)|$, its modulation through the Dirichlet kernel $ D_N(x\Delta)$ and the numerical average of the solution for several choice of distributions $\cD$. 

