In order to apply Theorem~\ref{thm:1} in a stochastic setting and obtain a CLT-type result, we will need to control the subleading terms of \eqref{eq:sum_sols} and we will approximate the leading term in an appropriate way. \\ 
We start by deriving a probabilistic bound for $\widetilde \psi$ \eqref{eq:second_order}.
\begin{lemma}\label{prop:prob_error_estimate}
Under Assumption \ref{hp:random_scattering_intro}, there exists a constant $K_\cD$, dependent on the distribution $\cD$, but independent of $N$, such that for any $ 0 \leq \varepsilon < \gamma - \frac{1}{2}$, 
\begin{equation}
\label{eq:delta_uniform}
    \P\left( \big| \wt \psi(x,t) \big| > N^{\frac{1}{2} -\varepsilon}\right) \leq K_\cD \frac{\ln(N)}{N^{\gamma - \frac{1}{2} - \varepsilon}}\, , \qquad \meanval{ \big| \wt \psi(x,t) \big|} \leq K_\cD \frac{\ln(N)}{N^{\gamma-1}}\,.
\end{equation}
where $\wt \psi(x,t)$  has been defined in \eqref{eq:second_order}.
\end{lemma}
\begin{proof}
First, we notice that, by exchanging $j,k$, in \eqref{eq:second_order}, we can rewrite the general term of the double sum as
\begin{equation}
   m^{(k)}\psi^{(j)}\left(\frac{2 \wo{\lambda_j} - \lambda_k - \wo{\lambda_k} }{(\wo{\lambda_j} - \wo{\lambda_k})(\lambda_k - \wo{\lambda_j})} \right) =  m^{(k)} \psi^{(j)}\left( \frac{-2}{(\wo{\lambda_j} - \wo{\lambda_k})} + \frac{\lambda_k - \wo{\lambda_k} }{(\wo{\lambda_j} - \wo{\lambda_k})(\lambda_k - \wo{\lambda_j})} \right)\,.
\end{equation}
Using $| \wo{\lambda_j} - \wo{\lambda_k}| \geq |k-j|$ and estimates \eqref{eq:estimates}, the expected value of the first term is bounded by
\begin{equation}\label{eq:error_estimate_prob1}
    \meanval{\left \vert m^{(k)}(x,t)\psi^{(j)}(x,t)\frac{2}{(\wo{\lambda_j} - \wo{\lambda_k})} \right\vert } \leq \frac{2 \meanval{\left| m^{(k)}(x,t)\right| \, \left|\psi^{(j)}(x,t)\right|}}{|k-j|} \leq \frac{4\mu^2_{\cD}}{|k-j|}\ ,
\end{equation}
where we also used independency of the $\mu_k$'s. Analogously, the expected value of the second term can be estimated as
\begin{equation}\label{eq:error_estimate_prob2}
    \meanval{\left \vert m^{(k)}(x,t)\psi^{(j)}(x,t)\frac{\lambda_k - \wo{\lambda_k} }{(\wo{\lambda_j} - \wo{\lambda_k})(\lambda_k - \wo{\lambda_j})} \right\vert } \leq \frac{\meanval{\left| m^{(k)}(x,t)\right| \, \left| \psi^{(j)}(x,t)\right| \mu_k}}{\Delta |k-j|^2} \leq \frac{2 \mu_{\mathcal D} \meanval{ \mu^2_k}}{\Delta |k-j|^2}\ .
\end{equation}
Therefore, from \eqref{eq:error_estimate_prob1}-\eqref{eq:error_estimate_prob2}, there exists a constant $K_{\cD}$ independent of $N,\Delta$, but depending on the distribution of the $\mu_k$ such that
\begin{equation}
\begin{split}
    \meanval{ \big| \wt \psi(x,t) \big|} & \leq \frac{1}{\Delta}\sum_{j=1}^N \sum_{\substack{ k=1 \\ k \neq j}}^N  \left(\frac{2\mu^2_{\cD}}{|k-j|} + \frac{\mu_{\mathcal D} \meanval{ \mu^2_k}}{\Delta |k-j|^2}\right)\ \leq \widetilde K_{\cD}\frac1\Delta \sum_{j=1}^N \sum_{\substack{ k=1 \\ k \neq j}}^N \left(\frac{1}{|k-j|} + \frac{1}{\Delta |k-j|^2} \right)\\& \leq \frac{K_\cD}{2} \left(\frac{N\ln(N)}\Delta + \frac{N}{\Delta^2} \right) \leq K_\cD\frac{N\ln(N)}{\Delta}  \,.
    \end{split}
\end{equation}
The statement of the Lemma  now follows by applying the Markov inequality that states that for any positive random variable $X$ and positive number $\lambda$, $\mathbb{P}(X>\lambda)<\frac{\meanval{X}}{\lambda}$ and then substituting $\Delta = \beta N^\gamma$.
\end{proof}

% \subsection{Universality and Central Limit Theorems}

Our goal is to study the fluctuations of the solutions $\psi_N(x,t)$ in a neighbourhood of the collision singularity (i.e. $x=0$ and $t=1$). Therefore, we rescale the space and time variables
\[
x = \frac{2X}{\Delta N} 
\qquad \text{ and } \qquad t-1 = \frac{T}{\Delta^2N^2} \ ;
\]
note that $T<0$ indicates a time before the collision and $T>0$ indicates a time after the collision. \\
% {\textbf{Notational convention:}} 
In a slight abuse of notation, we will express functions of the original variables $x$ and $t$ as functions of $X$ and $T$.  For example, $\psi_{N}(X,T)$ will be used instead of $\psi_{N}\left( \frac{2X}{\Delta N}, 1 +  \frac{T}{\Delta^2N^2} \right)$, and so on.

In the next Proposition we will show that the rescaled profile near the collision singularity 
\begin{equation}
\psi_N(X,T) =  - \sum_{k=1}^N \mu_k\sech \left( \mu_k \lp \frac{2  X}{\Delta N} - \frac{kT}{\Delta N^2}\rp \right) \ee^{\ii  \lp 2  \frac{k}{N}X - \tfrac{k^2}{2N^2}T   + \frac{\mu^2_k T}{2\Delta^2 N^2} \rp} + \wt \psi(X,T) +\bigo{\frac{\|\boldsymbol \mu\|_{\infty} \| \boldsymbol \mu\|_2^2}{\Delta^2}}
\end{equation}
can be approximated with high probability by the following function
\begin{equation}\label{eq:approx_NSS}
\widehat \psi_{N}(X,T) :=   -\sum_{k=1}^N \mu_k \ee^{\ii  \lp 2  \frac{k}{N}X - \tfrac{k^2}{2N^2}T   \rp}\ .
\end{equation} 
provided that $\Delta$ is large enough (i.e. we are in the small norm setting of Theorem \ref{thm:1}). 

To make this statement quantitative, we define the function $f_N(X,T)$ as

\begin{equation}
\label{eq:f_N}
    f_N(X,T) =  - \sum_{k=1}^N \mu_k\sech \left( \mu_k \lp \frac{2  X}{\Delta N} - \frac{kT}{\Delta N^2}\rp \right) \ee^{\ii  \lp 2  \frac{k}{N}X - \tfrac{k^2}{2N^2}T   + \frac{\mu^2_k T}{2\Delta^2 N^2} \rp} + \wt \psi(X,T)\,,
\end{equation}
then the following holds:

\begin{proposition}\label{prop:psi_approx}

Under Assumption \ref{hp:random_scattering_intro}, fix $(X,T)$ in a compact set and let $N>2$, then there exist two constants $C_\cD$, $ \hat C_{\mathcal{D}}$, depending on the distribution $\cD$, such that
\begin{equation}
\label{eq:approx_local}
    \meanval{ \Big|  f_N(X,T) - \widehat \psi_{N}(X,T)  \Big|} \leq C_\cD \frac{\ln(N)}{N^{\gamma - 1}} +   \hat C_{\mathcal D}\frac{(X^2 +T^2+|X T| + |T|)}{\beta^2N^{2\gamma + 1}} \ ,
\end{equation}
where $f_N(X,T)$ is defined in \eqref{eq:f_N} and $\widehat \psi_{N}(X,T)$ is defined in \eqref{eq:approx_NSS}.
\end{proposition}
\begin{proof}
By linearity of the expected value
\begin{equation}
       \meanval{ \Big|  f_N(X,T) - \widehat \psi_{N}(X,T)  \Big|}\leq  \meanval{\left\vert \sum_{k=1}^N \psi^{(k)}(X,T) - \widehat \psi_{N}(X,T) \right\vert}  + \wtmeanval{\vert\wt \psi(X,T)\vert} \,.
\end{equation}
 From Lemma \ref{prop:prob_error_estimate}, we bound the second term  as 
% From Proposition \ref{prop:prob_error_estimate}, we conclude that 
\begin{equation}
      \meanval{\vert\wt \psi(X,T)\vert}
   \leq  K_\cD \frac{\ln(N)}{ N^{\gamma -1}}
\end{equation}
for some constant $K_\cD>0$ depending on the distribution $\cD$. Next
\begin{equation}
\label{eq:markov}
    \begin{split}
          &  \meanval{\left|\sum_{k=1}^N\psi^{(k)}(X,T) - \widehat \psi_{N}(X,T) \right\vert } \\ 
          &   \leq  \left( \meanval{\left|\sum_{k=1}^N \psi^{(k)}(X,T) - \sum_{k=1}^N \wt{\psi^{(k)}}(X,T) \right\vert }  + \meanval{\left|\sum_{k=1}^N \wt{\psi^{(k)}}(X,T) - \widehat \psi_{N}(X,T) \right\vert }\right)\, ,
    \end{split}
\end{equation}
where
    \begin{equation}
        \wt{\psi^{(k)}}(X,T): =  - \mu_k\sech \left( \mu_k \lp \frac{2  X}{\Delta N} - \frac{kT}{\Delta N^2}\rp \right) \ee^{\ii  \lp 2  \frac{k}{N}X - \tfrac{k^2}{2N^2}T  \rp}\,.
    \end{equation}


The first term is estimated as follows
   \begin{eqnarray}
       \meanval{\left|\sum_{k=1}^N \psi^{(k)}(X,T) - \sum_{k=1}^N \wt{\psi^{(k)}}(X,T) \right\vert } &\leq& \sum_{k=1}^N \meanval{\left| \wt{\psi^{(k)}}(X,T) \right|\, \left| 1 - \ee^{\ii \frac{\mu^2_k T}{2\Delta^2 N^2} } \right|} \nonumber  \\ & 
        \leq& 2\sum_{k=1}^N \E\left[\mu_k^3  \right] \frac{|T|}{2\Delta^2  N^2}\leq \frac{c_{1,\cD} |T|}{\Delta^2 N} \label{eq:first_approx}
    \end{eqnarray}
for some constant $c_{1,\cD}$,  where in the second inequality we used $\left\vert 1- \ee^{s}\right\vert \leq 2|s|$ for $s \in i \mathbb{R}$.
The second term can be easily bounded in a similar way
    \begin{eqnarray}
          \meanval{\left|\sum_{k=1}^N \wt{\psi^{(k)}}(X,T) - \widehat \psi_{N}(X,T) \right| } &\leq& \sum_{k=1}^N \meanval{\left|\ii \mu_k \ee^{\ii  \lp 2  \frac{k}{N}X - \tfrac{k^2}{2N^2}T   \rp} \right| \, \left| 1 - \operatorname{sech} \left( \mu_k \lp \tfrac{2  X}{\Delta N} - \tfrac{kT}{\Delta N^2}\rp \right) \right| } \nonumber \\
          &\leq& \frac{c_{2,\cD}}{\Delta^2 N} \lp X^2 + T^2 + |XT| \rp \, ,
           \label{eq:second_term}
    \end{eqnarray}
    for some constant $c_{2,\cD}$, 
where we used the inequality $ \left \vert 1 - \operatorname{sech}(s)\right\vert \leq s^2$ for $s\in\mathbb{R}$. 

   Finally, substituting $\Delta = \beta N^\gamma$ concludes the proof.
\end{proof}




