We can now prove a CLT-type result for the approximating function $\widehat \psi_{N}(X,T)$. We will then be able to extend these results to the original $N$-soliton solution $\psi_N(x,t)$, using the results from Propositions \ref{prop:psi_approx}.

\begin{lemma}
\label{lem:CLT_approx}
    Fix $X,T\in \mathbb{R}$. Under Assumption \ref{hp:random_scattering_intro}, the following convergence results hold
    \begin{align}
    \label{eq:clt_re_approx}
        & \ \frac{\Re\lp \widehat \psi_{N}(X,T) - N \mu_\cD\psi_0(X,T)\rp}{ \sqrt{N \Var_{\cD}}} \xrightarrow[N\to\infty]{\text{law}}   \mathcal{N}\big( 0,\sigma_+(X,T) \big) \ , \\
        \label{eq:clt_im_approx}
          &  \frac{\Im\lp \widehat \psi_{N}(X,T) - N \mu_\cD\psi_0(X,T)\rp}{ \sqrt{N \Var_{\cD}} } \xrightarrow[N\to\infty]{\text{law}} \mathcal{N}\big( 0,\sigma_-(X,T) \big) \ , \\
          \label{eq:clt_mod_approx}
        &\frac{\left \vert  \widehat \psi_{N}(X,T) - N \mu_\cD\psi_0(X,T)  \right \vert}{ \sqrt{N \Var_{\cD}}} \xrightarrow[N\to\infty]{\text{law}}  \mathcal H\big(\varphi(X,T)\big)\ ,
    \end{align}
     where $\Var_{\cD}$ is the variance of the distribution $\mathcal D$,     
    \begin{equation}
    \psi_0(X,T) = - \int_0^1 \ee^{\ii\left( 2Xs - \tfrac{T}{2}s^2 \right)} \di s\ , \qquad \sigma_\pm(X,T) = \frac{1}{2}\left(1 \pm \int_0^1 \cos \left( 4Xs - Ts^2 \right) \right)\di s \ ,
    \end{equation}
    $\mathcal H(\varphi)$ is a special Hoyt distribution with probability density function 
    \begin{equation}
        \rho(\xi; \varphi) = \frac{2\xi\, {\rm e}^{-\frac{\xi^2 }{\sin^2(2\varphi)}}}{ | \sin (2 \varphi )| }  I_0\left(\xi^2 \cot (2 \varphi ) \csc (2 \varphi )\right)\ , \qquad \xi\in \R^+\ ,
    \end{equation}
    where $I_0$ is the modified Bessel function of first kind of order $\nu=0$ \cite[Formula 10.32.1]{DLMF}: 
\begin{equation}
I_0(z) 
=  \frac{1}{\pi} \int_0^\pi \ee^{\pm z\cos(\theta)} \di \theta = \frac{1}{\pi} \int_0^\pi \cosh(z\cos(\theta)) \di \theta \ .
\end{equation}
    and $\varphi\in \lb 0, \frac{\pi}{2}\rb$ is such that 

    \[ \cos(2\varphi) =   \int_0^1 \cos \left( 4Xs - Ts^2 \right) \di s\,. \]

\end{lemma}




\begin{proof}
We will resort to the Nagaev-Guivarc'h method, a fundamental technique to prove probabilistic limit theorems for dynamical systems, which we  briefly recall in Appendix \ref{app:probability_results}. 

We start by considering the real and imaginary parts of $\widehat \psi_{N}$ \eqref{eq:approx_NSS} separately.


It is enough to notice that 
\begin{align}
&\E \left[\ee^{- \ii \xi \Re\lp\widehat \psi_N \rp} \right] = \E \lb \ee^{ \ii \xi \lb \sum_{k=1}^N \mu_k  \cos \lp 2X \frac{k}{N}  - \frac{T}{2} \frac{k^2}{N^2} \rp \rb} \rb = \prod_{k=1}^N  \E \lb \ee^{ \ii \xi  y  \cos \lp  2X \frac{k}{N}  - \frac{T}{2} \frac{k^2}{N^2}  \rp } \rb = \prod_{k=1}^N \lambda_1(\xi; \tfrac{k}{N}) \ ,\\
 &\E \left[\ee^{-\ii \xi \Im\lp\widehat \psi_N \rp} \right] = \E \lb \ee^{ \ii \xi \lb \sum_{k=1}^N \mu_k  \sin \lp  2X \frac{k}{N}  - \frac{T}{2} \frac{k^2}{N^2} \rp \rb} \rb = \prod_{k=1}^N  \E \lb \ee^{\ii \xi  y  \sin \lp  2X \frac{k}{N}  - \frac{T}{2} \frac{k^2}{N^2} \rp } \rb = \prod_{k=1}^N \lambda_2(\xi; \tfrac{k}{N})\ , 
\end{align}
where $y\sim \mathcal{D}$ with mean $ \mu_\cD $ and variance $\Var_\cD$, and 
\begin{align}
\lambda_1(\xi;s) &= \operatorname{exp} \left\{ \log \E \lb e^{ \ii \xi  y  \cos \lp ( 2X s  - \frac{T}{2} s^2) \rp } \rb \right\} \\
&\nonumber = \operatorname{exp} \left\{  \ii \cos(2Xs - \tfrac{T}{2}s^2)\mu_\cD \xi - \cos^2(2Xs - \tfrac{T}{2}s^2) \,\Var_{\cD} \, \frac{\xi^2}{2} + o(\xi^{2}) \right\}\ , \\
\lambda_2(\xi;s) &= \operatorname{exp} \left\{ \log \E \lb e^{ \ii \xi  y  \sin \lp ( 2X s  - \frac{T}{2} s^2) \rp } \rb \right\} \\
& = \operatorname{exp} \left\{  \ii \sin(2Xs - \tfrac{T}{2}s^2) \mu_\cD \xi - \sin^2(2Xs - \tfrac{T}{2}s^2) \, \Var_{\cD}\, \frac{\xi^2}{2} + o(\xi^{2}) \right\}\  . \nonumber
\end{align}
We define 
\[
\psi_0(X,T) = -\int_0^1 \ee^{\ii \left(2Xs-\frac{T}{2}s^2\right)} \di s \ ,
\]
 and, by applying \cite[Theorem 4.2]{Mazzuca2024} (see also Appendix \ref{app:probability_results}), we directly obtain \eqref{eq:clt_re_approx}-\eqref{eq:clt_im_approx}.

The complex random variable $\hat \psi_{N}(X,T)$ has expected value $N\mu_\cD\psi_0(X,T)$, which implies  
\begin{equation}
    \lim_{N\to\infty } \frac{\widehat \psi_{N}(X,T)}{\mu_{\mathcal D} N} = \psi_0(X,T)\,\quad \text{almost surely} \ .
\end{equation}
 which is a \textit{universal profile}. 
From the previous calculations, it follows that the real random variable 
\[ \mathcal X_N(X,T):=  \frac{\left \vert \widehat \psi_{N}(X,T) - N \mu_\cD\psi_0(X,T) \right \vert}{\sqrt{N m_{2,\cD}}}\, \]
converges to the following probability distribution
\begin{equation}
       \mathcal X_N(X,T)
      \xrightharpoonup{N\to\infty} \mathcal{Z}(X,T) \ , \qquad 
      \mathcal{Z}(X,T) := \sqrt{\cU(X,T)^2 + \cV(X,T) ^2 } 
\end{equation}
pointwise in $(X,T)\in \R^2$,
where $\cU(X,T) \sim  \mathcal{N}\lp 0,\sigma_+(X,T) \rp$ and $\cV(X,T) \sim \mathcal{N}\lp 0,\sigma_-(X,T) \rp $, with
 \begin{gather}
     \sigma_\pm(X,T) = \frac{1}{2}\left(1 \pm \int_0^1 \cos \left( 4Xs - Ts^2 \right) \di s\right)\,. 
     \end{gather}
The cumulative distribution function of the modulus of a complex Gaussian is equal to
\begin{align}
\P \lp \left|\mathcal Z\right|\leq \xi \rp & = \P \lp \cU^2 + \cV^2  \leq  \xi^2 \rp =\frac{1}{2\pi \sqrt{\sigma_+(X,T) \sigma_-(X,T)}} \int_{u^2+v^2 \leq\xi^2}  \ee^{-\frac{1}{2} \left( \frac{u^2}{\sigma_+(X,T)}+ \frac{v^2}{\sigma_-(X,T)} \right)}  \di u \di v \nonumber \\
& = \frac{1}{|\sin(2\varphi) |\pi} \int_{u^2+v^2 \leq   \xi^2}  \ee^{- \frac{1}{2}\left( \frac{u^2}{\cos^2(\varphi)}+ \frac{v^2}{\sin^2(\varphi)} \right)}  \di u \di v , \qquad \forall \ \xi\geq 0\ ,
\end{align}
where we defined 
\[ \cos(2\varphi) =  \int_0^1 \cos \left( 4Xs - Ts^2 \right) \di s\,, \]
which implies that 
\[
\sigma_+(X,T) = \cos^2(\varphi) \qquad \text{and} \qquad \sigma_- (X,T)  =  \sin^2(\varphi)  \, .
\]
 From this expression, we can compute the probability density function (Hoyt distribution):
\begin{equation}
\rho(\xi; \varphi) = \frac{2 \xi\, {\rm e}^{-\frac{ \xi^2 }{ \sin^2(2\varphi)}}}{ | \sin (2 \varphi )| }  I_0\left(\xi^2 \cot (2 \varphi ) \csc (2 \varphi )\right),
\end{equation}
where $I_0$ is the modified Bessel function of first kind of order $\nu=0$ \cite[Formula 10.32.1]{DLMF}: 
\begin{equation}
\label{I0}
I_0(z) 
=  \frac{1}{\pi} \int_0^\pi \ee^{\pm z\cos(\theta)} \di \theta = \frac{1}{\pi} \int_0^\pi \cosh(z\cos(\theta)) \di \theta \ .
\end{equation}
This proves \eqref{eq:clt_mod_approx}.
\end{proof}


\subsection{Proof of the Central Limit Theorem \ref{thm:local_CLT_intro} and Proposition \ref{prop:prop_CLT_intro}.}


We will now prove Theorem \ref{thm:local_CLT_intro}, and   Proposition \ref{prop:prop_CLT_intro}, obtaining a CLT-type result for the solution $\psi_N(x,t)$ near the collision point $(x_0,t_0) = (0,1)$. 

We prove only the first limit \eqref{eq:clt_re}, since the proof in the other cases is analogous. The idea is to show since  $\psi_N(X,T)$ behaves like $\widehat \psi_N(X,T)$ in the limit as $N\to \infty$, with high probability, it obeys a CLT-type behaviour as well.

Consider the quantity
\begin{equation}
     \frac{\Re\Big( \psi_{N}(X,T)- N \mu_\cD\psi_0(X,T)\Big)}{\sqrt{N \Var_{\cD}}}  = \frac{\Re\lp\widehat \psi_{N}(X,T) - N \mu_\cD\psi_0(X,T)\rp}{ \sqrt{N \Var_{\cD}}}  + \frac{\Re\lp\psi_N(X,T) - \widehat \psi_{N}(X,T)\rp}{ \sqrt{N \Var_{\cD}}}\,.
\end{equation}
Thanks to Lemma \ref{lem:CLT_approx}, the first term will converge to a Gaussian with mean zero and prescribed variance. It remains to prove that there exists a $\delta>0$ such that
\begin{equation}
\label{eq:tail}
    \mathbb{P}\lp \frac{\left \vert \psi_N(X,T) - \widehat \psi_{N}(X,T)\right\vert }{ \sqrt{N \Var_{\cD}}} > N^{-\delta} \rp \xrightarrow{N\to\infty} 0\ ,
\end{equation}
for any $X,T\in \R$ and for any $\Delta >0$.

Fix $\frac{1}{2}>\delta>0$ and define the sets $\Omega$ and $A_\delta$ as 
\begin{align}\label{eq:Omega}
    &\Omega := \left\{\bm \mu \in \R^N_+ \, \Big\vert \, \,\,\|\bm \mu\|_\infty > N^{\frac{1}{3}} \,\right\} \,,\\
    &  A_\delta := \left \{ \bm \mu\in \R_+^N \, \Big \vert \, \left \vert \psi_N(X,T) - \widehat \psi_{N}(X,T)\right\vert > \sqrt{\Var_{\cD}} N^{\frac{1}{2} - \delta} \right\}  \subseteq \R_+^N\,.
\end{align}
Given $\Delta = \beta N^{\gamma}$ with $\gamma >\tfrac{1}{2}$, for $N$ big enough, $\Omega$ contains the set of vectors $\bm\mu$ for which $\|\bm \mu\|_\infty > \beta N^{\frac{1}{2}}$ (i.e. $\tfrac{\|\bm \mu\|_\infty }{\Delta}>1$) by construction; and we can rewrite \eqref{eq:tail} as

\begin{equation}
\label{eq:newclaim}\mathbb{P}\left(A_\delta\right)\xrightarrow{N\to\infty}0\,.
\end{equation}
Furthermore
\begin{equation}\label{eq:3.55}
    \mathbb{P}\left( A_\delta \right)  = \mathbb{P}\left(  A_\delta \cap \Omega \right) + \mathbb{P}\left(  A_\delta \cap (\R_+^N\setminus\Omega) \right)\,.
\end{equation}
One immediately notices (see Lemma \ref{lem:scaling_max} in Appendix \ref{app:probability_results}) that there exists a positive constant $c$ such that

\begin{equation}
\label{eq:no small norm}
    \mathbb{P}(A_\delta \cap \Omega)\leq \mathbb{P}(\Omega)\leq e^{-cN^{\frac{1}{4}}}\,.
\end{equation}
Therefore, we just need to estimate $\mathbb{P}(A_\delta\cap(\R_+^N\setminus\Omega))$. 
In this set, we can apply Theorem \ref{thm:1} and Proposition \ref{prop:psi_approx} therefore we conclude that there exist a function $\wt f(X,T,\boldsymbol{\mu},\Delta,N)$ and a constant $C$, independent of $(\boldsymbol{\mu},\Delta,N)$, such that

\begin{equation}
\label{eq:ftilde_bound}
\begin{split}
&    \psi_N(X,T) = f_N(X,T) + \wt f (X,T,\boldsymbol{\mu} ,\Delta,N)
    \mbox{ for all } \mu \in \mathbb{R}_{N}^{+}\setminus \Omega, \mbox{ and } \\
    &
    \qquad \vert \wt f(X,T,\boldsymbol{\mu},\Delta,N)\vert \leq C\frac{\|\boldsymbol \mu\|_{\infty} \| \boldsymbol \mu\|_2^2}{\Delta^2}\, \mbox{ for all } \mu \in \mathbb{R}_{+}^{N}.
\end{split}
\end{equation}
Indeed, one may use
\begin{eqnarray}
    \wt f(X,T,\boldsymbol{\mu},\Delta,N) = \begin{cases}
        \psi_{N}(X,T) - f_{N}(X,T) & \mbox{ if } C^{*} \| \boldsymbol \mu \|_{\infty} < \Delta \\
        \frac{C \| \boldsymbol \mu \|_{\infty} \| \boldsymbol \mu \|_{2}^{2}}{\Delta^{2}} & \mbox{ otherwise.} \\
    \end{cases}\ 
\end{eqnarray}
Then one can estimate $\mathbb{P}\lp A_\delta\cap(\R_+^N\setminus\Omega)\rp$ as follows.


\begin{equation}
\begin{split}
     \mathbb{P}\lp A_\delta\cap(\R_+^N\setminus\Omega)\rp& =  \mathbb{P}\lp \left\{\bmu\in \R^N_+ \Bigg\vert\frac{\left \vert \wh\psi_N(X,T) - f_N(X,T) - \wt f (X,T,\boldsymbol{\mu},\Delta,N)\right\vert }{ \sqrt{N \Var_{\cD}}} > N^{-\delta} \right\}\cap (\R_+^N\setminus\Omega)\rp \,\\
     & \leq \mathbb{P}\lp \left\{\bmu\in \R^N_+ \Bigg\vert\frac{\left \vert \wh\psi_N(X,T) - f_N(X,T) - \wt f (X,T,\boldsymbol{\mu},\Delta,N)\right\vert }{ \sqrt{N \Var_{\cD}}} > N^{-\delta} \right\}\rp\,.
     \end{split}
\end{equation}
By Markov inequality, that states that for a positive random variable $\fX$ and $\lambda>0$, $\mathbb{P}(\fX>\lambda)\leq \frac{\meanval{\fX}}{\lambda}$, we bound the last term as

\begin{equation}
    \begin{split}
        \mathbb{P}&\lp \frac{\left \vert \wh\psi_N(X,T) - f_N(X,T) - \wt f (X,T,\boldsymbol{\mu},\Delta,N)\right\vert }{ \sqrt{N \Var_{\cD}}} > N^{-\delta} \rp \leq \frac{\meanval{\left \vert \wh\psi_N(X,T) - f_N(X,T) - \wt f (X,T,\boldsymbol{\mu},\Delta,N)\right\vert }}{N^{\frac{1}{2} - \delta}\sqrt{\Var_\cD}}\\
        & \leq \frac{\meanval{\left \vert \wh\psi_N(X,T) - f_N(X,T) \right\vert} +\meanval{\left\vert \wt f (X,T,\boldsymbol{\mu},\Delta,N)\right\vert }}{N^{\frac{1}{2} - \delta}\sqrt{\Var_\cD}}\,.
    \end{split}
\end{equation}
We recall that for subexponential random variables, there exists a constant $\texttt{c}$ independent of $N$ such that $\meanval{\max_j\mu_j^3}\leq \texttt{c}\ln^3(N)$; therefore, by \eqref{eq:ftilde_bound} one deduces
\begin{equation}
    \meanval{\left\vert \wt f (X,T,\boldsymbol{\mu},\Delta,N)\right\vert} \leq C\frac{\ln^3(N)}{N^{2\gamma -1}}\,.
\end{equation}
So, applying Proposition \ref{prop:psi_approx}
we conclude that \eqref{eq:tail} holds and Theorem \ref{thm:local_CLT_intro} follows.
To prove Proposition \ref{prop:prop_CLT_intro}, one notices that once we have established \eqref{eq:clt_re}, i.e.
\begin{equation}
     \frac{\Re\Big( \psi_{N}(X,T) - N\mu_{\mathcal D}\, \psi_0(X,T)\Big)}{ \sqrt{N \Var_{\cD}}} \xrightarrow[N\to\infty]{\text{law}}  \mathcal{N}\big( 0,\sigma_+(X,T)\big) 
\end{equation}
it follows that 
\begin{equation}
  \frac{1}{\sqrt N}  \frac{\Re\Big( \psi_{N}(X,T) - N\mu_{\mathcal D}\, \psi_0(X,T)\Big)}{ \sqrt{N}} \xrightarrow{N\to\infty} 0  \qquad \text{ in probability,}
\end{equation}
since $\mathcal N(0,\sigma_+)$ is a continuous random variable. Finally, convergence in distribution to a constant implies convergence in probability, i.e.
\begin{equation}
    \lim_{N\to\infty} \mathbb P\left( \left| \Re\left( \frac{1}{N}\psi_{N}(X,T) - \mu_{\mathcal D}\, \psi_0(X,T)\right)\right| \geq \epsilon \right) =0 \quad \forall \ \epsilon>0\ .
\end{equation}

The same argument holds for the imaginary part of $\psi_N(X,T)$ (see $\eqref{eq:clt_im}$), thus implying that 
\begin{equation}
    \frac{1}{\mu_\cD N}\psi_N(X,T) \xrightarrow{N\to\infty} \psi_0(X,T) \qquad \text{in probability.} 
\end{equation}



\subsection{Proof of the Central Limit Theorem \ref{thm:envelope_intro}.}
Finally, we consider the general solution $\psi_N(x,1)$ at the collision time $t=1$ and we prove Theorem \ref{thm:local_CLT_intro}.
We first obtain a CLT-type result for the leading order term in the expansion \eqref{eq:sum_sols} at collision time $t=1$
\begin{equation}
\label{eq:approx_envelope}
   \varphi_N(x,1):= \sum_{k=1}^N \psi^{(k)}(x,1) = \sum_{k=1}^N \frac{- \mu_k}{\cosh \lp \mu_k x \rp} \ee^{\ii  k\Delta x}\,.
\end{equation}

\begin{lemma}
\label{lem:approx_envelope}
    Under Assumption \ref{hp:random_scattering_intro}, for any $x\in  \R$ the following convergence results hold
    \begin{align}
        & \frac{\Re\lp\varphi_N(x,1) \rp- \omega_\cD(x) \cos\lp x\Delta \frac{N+1}{2}\rp D_N\lp x\Delta\rp}{\sigma_{N,\Re}(x)} \xrightarrow[N\to\infty]{\text{law}}  \cN(0,1)\,, \label{eq:clt_envelope_approx_re} \\
        & \frac{\Im\lp \varphi_N(x,1) \rp - \omega_\cD(x) \sin\lp x\Delta \frac{N}{2}\rp D_{N+1}\lp x\Delta\rp}{\sigma_{N,{\Im}}(x)} \xrightarrow[N\to\infty]{\text{law}}  \cN(0,1)\,, \quad {\text{for } x\neq 0\,,} 
        \label{eq:clt_envelope_approx_im}
    \end{align}
     where $D_N(x) := \frac{\sin\lp \frac{x N}{2}\rp}{\sin \lp \frac{x}{2}\rp}$ is the Dirichlet kernel ,
    \begin{align}
        & \omega_\cD(x) = - \meanval{\frac{\xi}{\cosh( x\xi)}}\, , \quad \xi\sim \cD\, ,\\
        \label{eq:real_var_tilde}
        &\sigma^2_{N,\Re}(x) = \Var\lp\frac{\xi}{\cosh( x\xi)}  \rp\lp \frac{N-1}{2} + \frac{1}{2} \cos\lp x\Delta N \rp D_{N+1}(2x\Delta) \rp \,,  \\ 
        &\sigma^2_{N,\Im}(x) = \Var\lp\frac{\xi}{\cosh( x\xi)}  \rp\lp \frac{N+1}{2} - \frac{1}{2}  \cos\lp x\Delta N \rp D_{N+1}(2x\Delta) \rp \, ,
    \end{align}
    and $\Var(\cdot) $ is the variance of the given random variable. Moreover, 
    \begin{equation}\label{eq:clt_envelope_approx_mod}
        \frac{\left|\varphi_N(x,1)\right| - |\omega_\cD(x)D_{N}(x\Delta)|}{N} \to 0 \quad \text{as $N\to \infty$, in probability.}
    \end{equation}
\end{lemma}
\begin{remark}
    Notice that $\Im\lp\varphi_N(x,1) \rp =0$ deterministically, therefore we excluded the value $x=0$ in \eqref{eq:clt_envelope_approx_re}.
\end{remark}


\begin{proof} Let $x\in \R$. We will show the  proof of \eqref{eq:clt_envelope_approx_re} in detail. The proof of  \eqref{eq:clt_envelope_approx_im} is analogous.
The result easily follows from the classical result of Lyapounov's condition \cite{Billingsley2012}, which we recall in Appendix \ref{app:probability_results}.

Consider the real part of \eqref{eq:approx_envelope}:
$$\Re\lp \varphi_N(x,1) \rp = -\sum_{k=1}^N \mathcal X_k \cos(kx\Delta ) \, ,$$
where $\mathcal X_k$ is the random variable $\mathcal X_k(x) := \frac{\mu_k}{\cosh(\mu_k x)}$, $\mu_k\sim \cD$. 

Let $\sigma_{N,\Re}(x):= \sqrt{\sum_{k=1}^N \Var(\mathcal X_k)}$. We compute

    \begin{align}
        \sigma_{N,\Re}^4(x) & = \lp \sum_{k=1}^N \Var\lp \mathcal X_k \cos(kx\Delta ) \rp \rp^2= \Var\lp \mathcal X_1 \rp^2 \lp\sum_{k=1}^N  \cos^2(kx\Delta )\rp^2\, \nonumber \\
        & = \Var\lp \mathcal X_1\rp^2 \lp \frac{N}{2} - 1 + \frac{1}{2}\Re\lp \frac{1-\ee^{2\ii x\Delta(N+1)}}{1-\ee^{2\ii x\Delta}} \rp \rp^2 \, , \label{eq:denominator}
    \end{align}
since the amplitudes $\mu_k$'s are i.i.d., and
    \begin{align}
        \sum_{k=1}^N& \meanval{\Big( \mathcal X_k \cos(kx\Delta ) - \meanval{\mathcal X_k\cos(kx\Delta )} \Big)^4  }  
        = \meanval{\Big( \mathcal X_1 - \meanval{\mathcal X_1} \Big)^4}\sum_{k=1}^N \cos^4(kx\Delta ) \nonumber \\
         &= \meanval{\Big( \mathcal X_1 - \meanval{\mathcal X_1} \Big)^4} \lp \frac{3}{8}N - \frac{5}{8}+ \frac{1}{2} \Re\lp \frac{1-\ee^{2\ii x\Delta(N+1)}}{1-\ee^{2\ii x\Delta}} \rp +  \frac{1}{8} \Re\lp \frac{1-\ee^{4\ii x\Delta(N+1)}}{1-\ee^{4\ii x\Delta}} \rp\rp \,. \label{eq:numerator}
    \end{align}
Thus, the following Lyapounov's condition (with $\delta =2$) is satisfied
\[
\lim_{N\to \infty} \frac{1}{\sigma_{N,\Re}^4(x)} \sum_{k=1}^N \meanval{\Big( \mathcal X_k \cos(kx\Delta ) - \meanval{\mathcal X_k\cos(kx\Delta )} \Big)^4  }=0\ .
\]

Therefore, by the Lyapounov's condition Theorem \ref{thm:lyapounov}, the convergence result \eqref{eq:clt_envelope_approx_im}  follows

\begin{equation}
\frac{\Re\left(\varphi_N(x,1) - \meanval{ \varphi_N(x,1)}\right) }{\sigma_{N,\Re}(x)}   \xrightharpoonup{N\to\infty}  \cN(0,1)\ ,
\end{equation}
where
    \begin{equation}
       \meanval{\Re\left( \varphi_N(x,1)\right)}= -\meanval{\sum_{k=1}^N \mathcal X_k \cos(kx\Delta )} = 
       \omega_{\mathcal D}(x)\Re\lp \ee^{\ii x\Delta \frac{N+1}{2}} D_N(x\Delta)\rp\,.
    \end{equation}


Furthermore, since and $\sigma_{N,\Re}(x)$ is of the order $\bigo{N^{1/2}}$ for large $N$ ($\forall \, x\in\R$), Lyapounov's condition Theorem implies the following Law of Large Numbers result (see Proposition \ref{rem:almost_sure})
\begin{equation}
    \frac{1}{N} \left( \Re\lp\varphi_N(x,1)\rp - \omega_\cD(x)\cos\lp x\Delta \tfrac{N+1}{2}\rp D_N(x\Delta) \right)\to 0 \qquad \text{as $N \to \infty$, in probability;}
\end{equation}
similarly for the imaginary part of $\varphi_N(x,1)$. Therefore,  we can conclude that 
\begin{equation}
    \frac{\Big|\varphi_N(x,1)\Big| - |\omega_\cD(x)D_N(x\Delta)|}{N} \to 0 \qquad \text{as $N \to \infty$, in probability,}
\end{equation}
where we used the fact that 
 $ N^{-1}\lp \Big|\meanval{\varphi_N(x,1)}\Big| - \meanval{\Big|\varphi_N(x,1)\Big|}\rp  \to 0$, as $N\to\infty$,  and
    \begin{equation}
         \Big|\meanval{\varphi_N(x,1)}\Big| = \sqrt{\meanval{\Re(\varphi_N(x,1))}^2 + \meanval{\Im(\varphi_N(x,1))}^2 } \\ 
         = |\omega_\cD(x)D_N(x\Delta)| \,.
    \end{equation}
\end{proof}

Finally, in order to prove Theorem \ref{thm:envelope_intro}, we extend the result of the previous lemma to the solution $\psi_N(x)$ in the same way as in the proof of Theorem \ref{thm:local_CLT_intro}. We leave the details to the interested reader.


