\section[Facts about the $N$-soliton solution]{General facts about the $N$-soliton solution of the fNLS equation}\label{app:facts}
We report here some known facts about the RHP for $N$-soliton solutions, and we present a novel upper bound on the modulus of the solution $\psi_N(x,t)$.  Such a bound is suboptimal as compared to \eqref{eq:upper_bound_result} (see Theorem~\ref{thm:1}), but it shows  exponential decay of the tails. 
Given a set of spectral data $\{(z_k,c_k)\}_{k=1}^N$, the solution  \( \bbs M(z;x,t)\) of  the RHP \ref{rhp-sch} has the form (see \cite[Appendix B]{Jenkins2018})
\begin{equation}
\label{M_reflectionless}
    \bbs M(z;x,t) := \bbs I + \sum_{k=1}^N \frac1{z-z_k}\begin{bmatrix} \alpha_k(x,t) & 0 \smallskip \\ \beta_k(x,t) & 0  \end{bmatrix} + \sum_{k=1}^N \frac1{z-\overline z_k} \begin{bmatrix} 0 & -\overline{\beta_k(x,t)} \smallskip \\ 0 & \overline{\alpha_k(x,t)} \end{bmatrix},
\end{equation}
where \( \{\alpha_k(x,t),\beta_k(x,t)\}_{k=1}^N\) solve the following linear system
\begin{gather}
\label{alpha_beta} 
\alpha_k(x,t) = -\gamma_k(x,t) \sum_{j=1}^N\frac{\overline{\beta_j(x,t)}}{z_k-\overline z_j}
\quad \text{and} \quad
\beta_k(x,t) = \gamma_k(x,t) \left( 1 + \sum_{j=1}^N \frac{\overline{\alpha_j(x,t)}}{z_k-\overline z_j} \right), \\
\gamma_k(x,t) := c_k \ee^{2\ii\theta(z_k;x,t)}, \label{gamma}
\end{gather}
which follows directly from the residue conditions satisfied by \(\bbs M(z;x,t) \). 

\begin{proposition}
    The system \eqref{alpha_beta} is uniquely solvable, and the fNLS solution is given as 
    \begin{equation}
\label{reflectionless_sch}
\overline{\psi_N(x,t)} = 2\ii \sum_{k=1}^N \beta_k(x,t).
\end{equation}
\end{proposition}

\begin{proof} 
Unique solvability of system \eqref{alpha_beta} is equivalent to verify that
\begin{equation}
\label{matA}
\det\left(\bbs I + \bbs \Phi_N \overline{\bbs \Phi_N}\right) \neq 0, \quad \text{where } \   \bbs \Phi_N := \left[\frac{\sqrt{c_k} \sqrt{\overline {c_n} }}{z_k-\overline z_n}\ee^{\ii(\theta(z_k;x,t)-\theta(\overline z_n;x,t))}\right]_{k,n=1}^N,
\end{equation}
 \( \overline{\bbs \Phi_N} \) is the conjugate matrix of \( \bbs \Phi_N\), and  we consider the principal value of \( \sqrt {c_k}\). 

 We consider now the matrix $\ii \bbs \Phi_N$: since each entry  
 can be viewed as an inner product of linearly independent functions,
 \[
[\ii\bbs \Phi_N]_{k,n} = \int_0^\infty \big( \sqrt{c_k}\ee^{\ii\theta(z_k)} \big) \overline{\big( \sqrt{c_n}\ee^{\ii\theta(z_n)} \big)} \ee^{\ii(z_k-\overline z_n)s}\di s,
\]
\( \ii\bbs \Phi_N\) is a positive definite matrix. Let \( (\ii\bbs \Phi_N)^{1/2} \) be the unique positive definite square root of \( \ii\bbs \Phi_N\). The eigenvalues of \(\bbs \Phi_N \overline{\bbs \Phi_N} = (\ii\bbs \Phi_N)\overline{(\ii\bbs \Phi_N)}\) are the same as the eigenvalues of \((\ii\bbs \Phi_N)^{1/2} \overline{(\ii\bbs \Phi_N)} (\ii\bbs \Phi_N)^{1/2}\), which is also a positive definite matrix. If one labels these eigenvalues by \( \lambda_k>0 \), then
\[
\det\left(\bbs I + \bbs \Phi_N \overline{\bbs \Phi_N} \right)=\prod_{k=1}^N(1+\lambda_k)>0
\]
as needed. Finally, from \eqref{eq:recovery} and \eqref{M_reflectionless}, it  immediately follows that the corresponding solution \( \psi_N(x,t)\) of the fNLS equation \eqref{eq:nls} can be expressed as
\[
\overline{\psi_N(x,t)} = 2\ii \sum_{k=1}^N \beta_k(x,t). \qedhere
\]
\end{proof}

We derive now an alternative expression for the solution \( \psi_N(x,t)\), that will be used shortly to derive some estimates on the modulus of the solution.

\begin{lemma}
\label{prop:1}
Let \( B(z) \) be the Blaschke product from \eqref{eq:max_norming_const}. It holds that
\[
\psi_N(x,t) = 2\ii \sum_{k=1}^N \frac1{B^\prime(z_k)}\frac{\alpha_k(x,t)}{\gamma_k(x,t)},
\]
where $\alpha_k$ and $\gamma_k$ are defined in \eqref{alpha_beta} and \eqref{gamma} respectively.
\end{lemma}
\begin{proof}



It readily follows from \eqref{alpha_beta} that
\[
2\ii \sum_{n=1}^N \frac1{B^\prime(z_n)}\frac{\alpha_n(x,t)}{\gamma_n(x,t)} = \overline{2\ii \sum_{k=1}^N \left(\sum_{n=1}^N \frac1{\overline {B^\prime(z_n)}} \frac1{\overline z_n- z_k}\right) \beta_k(x,t)}.
\]
Since \( B(z) \) is a rational function with poles \( \overline z_1,\ldots,\overline z_N\) that is equal to \( 1 \) at infinity, it holds that
\[
B(z) = 1 + \sum_{n=1}^N \frac1{\overline{B^\prime(z_n)}} \frac1{z-\overline z_n}.
\]
As \( B(z_k)=0 \), it follows that \(\sum_{n=1}^N \frac1{\overline{B^\prime(z_n)}} \frac1{z_k-\overline z_n} = -1\), and we recover \eqref{reflectionless_sch}.
\end{proof}

The modulus of \( \psi_N(x,t) \) also admits expressions convenient for analysis. Indeed, it is known (see for example \cite[Equation (2.3)]{Jenkins2018}) that
\[
\partial_x\bbs M(z) = -\ii z\big[\sigma_3,\bbs M(z)\big] + \begin{bmatrix} 0 & \psi_N(x,t) \\ -\overline{\psi_N(x,t)} & 0 \end{bmatrix} \bbs M(z).
\]
Multiplying by \( z \) and taking the limit as \( z\to\infty \) of the \( (2,2) \)-entries of the above relation gives after conjugation that
\begin{equation}
\label{partial_alpha}
|\psi_N(x,t)|^2 = 2\ii \partial_x \left( \sum_{k=1}^N \alpha_k(x,t) \right).
\end{equation}
We recall that expression \eqref{partial_alpha} can further be rewritten using the famous determinantal formula \cite{faddeev2007hamiltonian}:
\[
|\psi_N(x,t)|^2 = \partial_{xx}\log\det\big(\bbs I + \bbs A \overline{\bbs A}\big) \ .
\]
We now present a novel, general upper bounds for \( |\psi_N(x,t)| \). Despite being suboptimal as compared to \eqref{eq:upper_bound_result} for finite $x,t \in \R\times\R^+$, it shows exponential decay for $|x|, |t| \gg 1$, which cannot be read from \eqref{eq:upper_bound_result}.

\begin{proposition}
\label{prop:3}
It holds that
\[
\frac12|\psi_N(x,t)| \leq \min \left\{\sum_{k=1}^N|\gamma_k(x,t)|, \;\;  \sum_{k=1}^N |B^\prime(z_k)|^{-1}, \;\; \sum_{k=1}^N |B^\prime(z_k)|^{-2}|\gamma_k(x,t)|^{-1} \right\}.
\]
\end{proposition}
\begin{proof}
Recall that if \( f(z) \) is analytic in a domain \( D \) then \( |f(z)|^2 \) is subharmonic there because \( \Delta |f(z)|^2 = 4\partial_z\partial_{\overline z}|f(z)|^2=4|f^\prime(z)|^2\geq 0 \). Let
\[
S_i(z) := \big| [\bbs M(z)]_{1,i} \big|^2 + \big| [\bbs M(z)]_{2,i} \big|^2, \quad i\in\{1,2\}.
\]
Since the second column of \( \bbs M(z) \) is analytic in \( \C_+ \), see \eqref{M_reflectionless}, \( S_2(z) \) is a subharmonic there. Clearly, \( \det \bbs M(z) \) is a rational function of \( z \) that is equal to \(1\) at infinity. Since only one column of \(\bbs M(z)\) can have a pole at a given point, \( \det \bbs M(z) \) can have at most simple poles. However, it is easy to check that the residue conditions for \( \bbs M(z) \) imply that the residues of \( \det\bbs M(z) \) are zero. Thus,  \( \det\bbs M(z)\equiv1 \). Since \( S_2(\infty) =1 \) and
\[
S_2(z) = [\bbs M(z)]_{2,2}(z)[\bbs M(z)]_{1,1} - [\bbs M(z)]_{1,2} [\bbs M(z)]_{2,1} = \det \bbs M(z) \equiv 1
\]
for \( z \) on the real line by \eqref{M_reflectionless}, the maximum principle for subharmonic functions implies that \( S_2(z) \leq 1 \) in \( \overline\C_+ \). 

These considerations can also be applied to the matrix \( \bbs M(z)B(z)^{\bbs \sigma_3} \), as it is still meromorphic with unit determinant. However, the roles of the columns are now reversed: the first one is analytic in \( \C_+ \) while the second one has poles therein. Thus, it now must hold that  \( (S_1|B|^2)(z) \leq 1 \) in \( \overline{\C_+} \). It readily follows from \eqref{M_reflectionless} and the residue conditions satisfied by \( \bbs M \) that
\[
\begin{bmatrix} \alpha_n \\ \beta_n \end{bmatrix} = \lim_{z\to z_n}(z-z_n)\begin{bmatrix} [\bbs M(z)]_{1,1} \\ [\bbs M(z)]_{2,1} \end{bmatrix} = \gamma_n\begin{bmatrix} [\bbs M(z_n)]_{1,2} \\ [\bbs M(z_n)]_{2,2} \end{bmatrix}.
\]
These relations now yield that
\[
\label{resM}
\sqrt{|\alpha_n|^2+|\beta_n|^2} =
\begin{cases}
|\gamma_n|\sqrt{S_2(z_n)}\leq |\gamma_n|, \medskip \\
\displaystyle \lim_{z\to z_n} |z-z_n|\sqrt{S_1(z)} \leq \lim_{z\to z_n} |z-z_n||B(z)|^{-1} = |B^\prime(z_n)|^{-1}.
 \end{cases}
\]
Recalling \eqref{reflectionless_sch}, we obtain the first bound of the proposition using the first estimate above, while the second bound follows from the second estimate above. Finally, the last bound is a consequence of Lemma~\ref{prop:1} and the second estimate above.
\end{proof}


\section{Results from Probability Theory}\label{app:probability_results}

In this Appendix we show in details some passages for the proof of Theorem~\ref{thm:local_CLT_intro}, and we report two results from Probability Theory that we used for the proof of Lemmas \ref{lem:CLT_approx} and \ref{lem:approx_envelope}. 

 \begin{lemma}
 \label{lem:scaling_max}
     Under Assumption \ref{hp:random_scattering_intro} and Definition \ref{def:subexp}, the following estimates hold:
     \begin{itemize}
         \item If $\alpha >0$ and $N>\exp\lp \frac{\nu^2}{2\alpha^2}\rp$, for all $s>0$ it holds that
    \[
         \mathbb{P}\lp \max_{i=1,\ldots,N} |\mu_i - \mu_{\mathcal D} | \geq 2\alpha \lp \ln(N) + s \rp \rp \leq 
             2e^{-s} \,.
     \]

     \item If $\alpha =0$, for all $s>0$ it holds that  
    \[
         \mathbb{P}\lp \max_{i=1,\ldots,N} |\mu_i - \mu_{\mathcal D} | \geq \nu \sqrt{2 \lp \ln(N) + s \rp} \rp \leq 2\ee^{-s} \,.
    \]
     \end{itemize}
 \end{lemma}

 \begin{proof}
 We prove only the first statement. The proof of the second one is analogous. Let $u= 2\alpha\lp\ln(N) + s\rp$. Then, from standard inequalities, 
\[
              \mathbb{P}\lp \max_{i=1,\ldots,N} |\mu_i - \mu_{\mathcal D}| \geq u \rp \leq \sum_{i=1}^N \mathbb{P}\lp |\mu_i - \mu_{\mathcal D}|  \geq u \rp \leq N \mathbb{P}\lp |\mu_1 - \mu_{\mathcal D} | \geq u \rp \,.
\]
Since $N>\exp\lp \frac{\nu^2}{2\alpha^2}\rp$,  we can apply \eqref{eq:subexp_prop} to conclude that
\[
    \mathbb{P}\lp \max_{i=1,\ldots,N} |\mu_i - \mu_{\mathcal D} |  \geq u \rp \leq 2 N \exp\lp -\frac{u}{2\alpha}\rp = 2 \ee^{-s}. \qedhere
\]   
 \end{proof}
