From Lemma \ref{lem:scaling_max}
% and Proposition \ref{prop:prob_small_norm} 
it follows that the set $\Omega$ defined in \eqref{eq:Omega} is exponentially small in probability as $N\to \infty$.





The next result is the so-called Nagaev--Guivarc’h method, which is a fundamental technique to prove probabilistic limit theorems for dynamical systems. We used the following theorem to prove Lemma \ref{lem:CLT_approx}, which is part of the proof of Theorem \ref{thm:local_CLT_intro}. 
\begin{theorem}[{\bf Nagaev--Guivarc’h method}, Theorem 4.2 in  \cite{Mazzuca2024}]\label{thm:Guido}
Let $X_1, X_2, \ldots$ be a sequence of real random variables and let $S_N := \sum_{j=1}^N X_j$. Assume that there exists $\delta>0$ and functions $\lambda(s,\xi) \in C^{1,0}([0,1) \times \R)$, $c_N(\xi) \in C^0(\R)$, and $h_n(\xi)$ continuous at zero, such that $\forall\ \xi \in [-\delta, \delta]$ and $\forall \ N \in \mathbb N$
\begin{equation}
\E \lb \ee^{- \ii \xi S_N }  \rb = c_N(\xi)\left(  \prod_{j=1}^N \lambda(\xi; \tfrac{j}{N})\right) \lp 1 + h_N(\xi)\rp \ .
\end{equation}
Moreover, assume that 
\begin{enumerate}
\item there exist functions $A, \sigma^2 :[0,1]\to \C$ such that 
\begin{equation}
\lambda(\xi;s) = \ee^{- \ii A(s) \xi  - \frac{\sigma^2(s)}{2}\xi^2 + o(\xi^2)} \ , \qquad \text{as } \xi \to 0\ ;
\end{equation}
\item $c_N(0)=1$ and  $\lim_{N\to \infty} c_N\left(\tfrac{\xi}{\sqrt{N}}\right) = \lim_{\xi\to \infty} c_N\left(\tfrac{\xi}{N}\right)=1$, $\forall \, \xi\in[-\delta,\delta]$;
\item  $h_N \to 0$ as $N\to \infty$, uniformly in $[-\delta,\delta]$ and $h_N(0)=0$.
\end{enumerate}
Then, $\int_0^1 A(s) \di s\in \R$ and $\int_0^1 \sigma^2(s) \di s \geq 0$ and 
\begin{equation}
\frac{S_N - N \int_0^1 A(s) \di s}{\sqrt{N}} \to \mathcal N \Big(0, \int_0^1\sigma^2(s) \di s \Big) \ , \qquad \text{as $N\to \infty$, in distribution.} 
\end{equation}
\end{theorem} 


 Finally, we used a classical Probability Theory result, known as { Lyapounov's condition} \cite{Billingsley2012}, to prove Lemma \ref{lem:approx_envelope}, which is part of the proof of Theorem \ref{thm:envelope_intro}.
\begin{theorem}[\bf Lyapounov's condition]
\label{thm:lyapounov}
    Let $X_1,\ldots, X_N$ be independent random variables with means $\mu_1,\ldots,\mu_N$ and variances $\sigma^2_1,\ldots,\sigma^2_N$.
    Define $s_N := \sqrt{\sum_{k=1}^N\sigma^2_k}$ and assume that there exists a $\delta>0$ such that
    \begin{equation}
    \label{eq:lyapounouv_condition}
        \lim_{N\to\infty} \frac{1}{s_N^{2+\delta}} \sum_{k=1}^N \meanval{|X_k - \mu_k|^{2+\delta}}=0 \,.
    \end{equation}
    Then
\begin{equation}
    \frac{1}{s_N}\sum_{k=1}^N \lp X_k - \mu_k \rp \xrightarrow{d} \cN(0,1)\,  \quad \text{as }N\to\infty\,.
\end{equation}
\end{theorem}


\begin{proposition}[\bf Law of Large Numbers]
\label{rem:almost_sure}
   Under the same assumption of Theorem \ref{thm:lyapounov}, if $s_N$ is asymptotically equal to $c N^{\alpha}$ for some $c>0$ and  $0<\alpha < 1$, then it implies that 
    \begin{equation}
        \frac{1}{N}\sum_{k=1}^N X_k  - \frac{1}{N} \sum_{k=1}^N \mu_k \xrightarrow{N\to\infty} 0\,
    \end{equation}
   in probability. 
\end{proposition}







