\title{\LARGE Robust Inference when Nuisance Parameters may be Partially Identified with Applications to Synthetic Controls}
%\title{A Robust Orthogonalized Estimator with Applications to Synthetic Controls}
\author[$\dagger$]{Joseph Fry}  
\affil[$\dagger$]{\footnotesize
Rutgers University, 75 Hamilton St, 08901, New Brunswick, New Jersey, United States\par\nopagebreak
