\textbf{Proof of Lemma \hyperref[L3.1]{3.1}:} If $S_{0,n}$ is a singleton for all $n \geq N$ for some $N$, then the results is implied directly by Lemma \hyperref[LB1]{B1}. Suppose then that, for infinitely many $n$, $S_{0,n}$ is not a singleton. Let $\{ \epsilon_n \}_{n \in \mathbb{N}}$ be a decreasing sequence with $\epsilon_n > 0$ and $\epsilon_n \rightarrow 0$. Then let $N_{\epsilon_n}(\theta_{0,n},\eta_{0,n})$ be an open $\epsilon$-ball using the $||\cdot||_1$ norm centered at $(\theta_{0,n},\eta_{0,n})$. For some fixed $\zeta > 0$ to be specified below, let $S_{0,n}^\zeta \coloneqq \{ (\theta,\eta) \in S_{0,n} : f(\theta,\eta) \leq f(\theta_{0,n},\eta_{0,n}) + \zeta\}$. Then let $\tau_n = d_H(S_{0,n}^\zeta, \{(\theta_{0,n},\eta_{0,n})\},||\cdot||_1)$, where $d_H(,,||\cdot||_1)$ denotes the Hausdorff distance using the $||\cdot||_1$ norm. Note $N_{\epsilon_n}^c(\theta_{0,n},\eta_{0,n}) \cap S_{0,n}^\zeta = \emptyset$ exactly when $\tau_n < \epsilon_n$, so $N_{\min\{\epsilon_n,\tau_n/2\}}^c(\theta_{0,n},\eta_{0,n}) \cap S_{0,n}^\zeta \ne \emptyset$ for all $n$. Because $S_{0,n}^\zeta$ is compact and $f$ is continuous on $S_{0,n}^\zeta$ for each $n$ by Assumption \hyperref[Ass3.1]{3.1.1}, $S_{0,n}^\zeta \cap N^c_{\min\{\epsilon_n,\tau/2\}}(\theta_{0,n},\eta_{0,n})$ is also compact for each $n$. Then we can define $$\gamma_n := \min_{(\theta,\eta) \in S_{0,n}^\zeta \cap N^c_{\min\{\epsilon_n,\tau_n/2\} }(\theta_{0,n},\eta_{0,n})} f(\theta,\eta) - f(\theta_{0,n},\eta_{0,n}).$$ 
\par 
Note that by Assumption \hyperref[Ass3.1]{3.1.5}, $$C_6 |f(\theta_1,\eta_1) - f(\theta_2,\eta_2)|^{\gamma_2} \leq ||\theta_1 - \theta_2||_1 + ||\eta_1 - \eta_2||_1$$ when $f(\theta_1,\eta_1),f(\theta_2,\eta_2) \leq f(\theta_{0,n},\eta_{0,n}) + C_5$. So if $\zeta$ is chosen such that $\zeta \leq C_5$, then for $\kappa_n = (\gamma_n/(4C_6))^{1/\gamma_2} > 0$, it holds that for all $(\theta_1,\eta_1),(\theta_2,\eta_2) \in S_n^\zeta \coloneqq \{(\theta,\eta) \in \Theta_n \times H \;:\; f(\theta,\eta) \leq f(\theta_{0,n},\eta_{0,n}) + \zeta \}$, if $||\theta_1 - \theta_2||_1 + ||\eta_1 - \eta_2||_1 < \kappa_n$, then $|f(\theta_1,\eta_1) - f(\theta_2,\eta_2)| < \gamma_n/4$. Letting $S_{0,n}^\zeta(\kappa)$ denote the closed $\kappa$ blow-up of $S_{0,n}$ using the $||\cdot||_1$ norm, we obtain that:
$$\min_{(\theta,\eta) \in S_{0,n}^\zeta(\kappa_n) \cap N^c_{\min\{\epsilon,\tau_n/2\}}(\theta_{0,n},\eta_{0,n})} f(\theta,\eta) - f(\theta_{0,n},\eta_{0,n}) > 3/4\gamma_n.$$
\par 
Since $(\hat{\theta},\hat{\eta}) \in \hat{S}_0$, then $$(\hat{\theta},\hat{\eta}) \in \hat{S}_0^\zeta \coloneqq \{(\theta,\eta) \in \hat{S}_0: f(\theta,\eta) \leq f(\theta_{0,n},\eta_{0,n}) + \zeta \}$$ when $|f(\hat{\theta},\hat{\eta}) -f(\theta_{0,n},\eta_{0,n})| \leq 3/4\gamma_n$, since by the definition of $\gamma_n$ we have that $3/4 \gamma_n \leq \gamma_n \leq \zeta$. Therefore, since $d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta;||\cdot||_1) < \kappa_n$ implies $\hat{S}_0^\zeta \subset S_{0,n}^\zeta(\kappa_n)$, it follows that
$$P(||\hat{\theta} - \theta_{0,n}||_1 + ||\hat{\eta} - \eta_{0,n}||_1 < \epsilon) \geq P(||\hat{\theta} - \theta_{0,n}||_1 + ||\hat{\eta} - \eta_{0,n}||_1 < \min\{\epsilon,\tau_n/2\})$$
$$\geq P(|f(\hat{\theta},\hat{\eta}) - f(\theta_{0,n},\eta_{0,n})| \leq 3/4\gamma_n ; d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) < \kappa_n).$$
\par 
Let $(\theta_p,\eta_p) = \argmin_{(\theta,\eta) \in \hat{S}_0^\zeta} ||\theta - \theta_{0,n}||_1 + ||\eta - \eta_{0,n}||_1$. If $d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) < \kappa_n$, then $||\theta_p - \theta_{0,n}||_1 + ||\eta_p - \eta_{0,n}||_1 < \kappa_n$ and therefore $f(\theta_p,\eta_p) < f(\theta_{0,n},\eta_{0,n}) + \gamma_n/4$. By definition of $\hat{\theta}$ and $\hat{\eta}$, $\hat{f}(\hat{\theta},\hat{\eta}) \leq \hat{f}(\theta_p,\eta_p)$. This implies $$f(\hat{\theta},\hat{\eta}) - f(\theta_p,\eta_p) \leq |\hat{f}(\hat{\theta},\hat{\eta}) - f(\hat{\theta},\hat{\eta})| + |\hat{f}(\theta_p,\eta_p) - f(\theta_p,\eta_p)|.$$
Thus $f(\theta_p,\eta_p) < f(\theta_{0,n},\eta_{0,n}) + \gamma_n/4$ and $|\hat{f}(\hat{\theta},\hat{\eta}) - f(\hat{\theta},\hat{\eta})| + |\hat{f}(\theta_p,\eta_p) - f(\theta_p,\eta_p)| < \gamma_n/4$ together imply $f(\hat{\theta},\hat{\eta}) - f(\theta_{0,n},\eta_{0,n}) < \gamma_n/2$. But since $d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) < \kappa_n$ implies $f(\theta_p,\eta_p) < f(\theta_{0,n},\eta_{0,n}) + \gamma_n/4$, we have that 
$$P(||\hat{\theta} - \theta_{0,n}||_1 + ||\hat{\eta} - \eta_{0,n}||_1 < \epsilon_n) $$
$$\geq P(|\hat{f}(\hat{\theta},\hat{\eta}) - f(\hat{\theta},\hat{\eta})| + |\hat{f}(\theta_p,\eta_p) - f(\theta_p,\eta_p)| < \gamma_n/4; d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) < \kappa_n).$$
$$\geq P(2 \sup_{(\theta,\eta) \in \hat{S}_0} |f(\theta,\eta) - \hat{f}(\theta,\eta)| < \gamma_n/4; d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) < \kappa_n).$$
By Assumption \hyperref[Ass3.1]{3.1.5}, for all $(\theta,\eta) \in S_{0,n}^\zeta$
$$|f(\theta,\eta) - f(\theta_{0,n})| \geq C_4 \min \{ (||\theta - \theta_{0,n}||_1 + ||\eta - \eta_{0,n}||_1)^{\gamma_1}, C_3 \},$$
and for sufficiently large $n$, $\epsilon_n^{\gamma_1} \leq C_3$. So for sufficiently large $n$, $\gamma_n \geq C_4 \epsilon_n^{\gamma_1}$. Since $\kappa_n = (\gamma_n/(4C_6))^{1/\gamma_2}$, this implies $\kappa_n^{\gamma_2}4C_6 \geq C_4 \epsilon_n^{\gamma_1}$ so $\kappa_n \geq \epsilon_n^{\gamma_1/\gamma_2} (C_4/(4C_6))^{1/\gamma_2} $. Therefore, for $n$ sufficiently large,
$$P(||\hat{\theta} - \theta_{0,n}||_1 + ||\hat{\eta} - \eta_{0,n}||_1 < \epsilon) $$
$$\geq P(2 \sup_{(\theta,\eta) \in \hat{S}_0} |f(\theta,\eta) - \hat{f}(\theta,\eta)| < C_4 \epsilon_n^{\gamma_1}/4; d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) < \epsilon_n^{\gamma_1/\gamma_2} (C_4/(4C_6))^{1/\gamma_2} ).$$

Then because $\sup_{(\theta,\eta) \in \hat{S}_0}|f(\theta,\eta) - \hat{f}(\theta,\eta)| = O_p(c_n)$ and $d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta,||\cdot||_1) = O_p(\max \{\lambda_\delta,\lambda_\eta,a_n \})$ by Lemma \hyperref[LB1]{B1}, for any decreasing sequence $\{\epsilon_n\}_{n \in \mathbb{N}}$ with $\epsilon_n > 0$, $\epsilon_n \rightarrow 0$, and $$\epsilon_n /(\max \{\lambda_\delta^{\gamma_2},\lambda_\eta^{\gamma_2},a_n^{\gamma_2},c_n\}^{1/\gamma_1}) \rightarrow \infty,$$ we have that $P(||\hat{\theta} - \theta_{0,n}||_1 < \epsilon_n) \rightarrow 1$ and $P(||\hat{\eta} - \eta_{0,n}||_1 < \epsilon_n ) \rightarrow 1$. Therefore, $$||\hat{\delta} - \delta_{0,n}||_1 + ||\hat{\eta}-\eta_{0,n}||_1 \leq ||\hat{\theta} - \theta_{0,n}||_1 + ||\hat{\eta}-\eta_{0,n}||_1 = O_p(\max \{\lambda_\delta^{\gamma_2},\lambda_\eta^{\gamma_2},a_n^{\gamma_2},c_n\}^{1/\gamma_1}).$$

\textbf{Proof of Lemma \hyperref[L2.1]{2.1}:} Let $\gamma = (\delta,\eta_q)$ and $\hat{\gamma} = (\hat{\delta},\hat{\eta}_q)$ where $\eta_q$ is the $q$-th row of $\eta$. Since the $q$-th element on the orthogonalized sample moment conditions $\hat{M}_q$ for $q \in \{1,...,m\}$ are twice continuously differentiable in $\gamma$, for each $q$ there exists $\Bar{\gamma}$ with $||\Bar{\gamma} - \gamma_{0,n}||_1 \leq ||\hat{\gamma} - \gamma_{0,n}||_1$ such that:
$$\sqrt{n}(\hat{M}_q(\beta_{0,n},\hat{\gamma}) - \hat{M}_q(\beta_{0,n}, \gamma_{0,n}))$$
$$ = \sqrt{n} \partial_\gamma \hat{M}_q(\beta_{0,n},\gamma_{0,n})(\hat{\gamma} - \gamma_{0,n}) + \sqrt{n}(\hat{\gamma} - \gamma_{0,n})'\partial^2_\gamma \hat{M}_q(\beta_{0,n},\Bar{\gamma})(\hat{\gamma} - \gamma_{0,n}).$$
The magnitude of the first term on the right-hand side is less than or equal to 
$$\sqrt{n} ||\partial_\gamma \hat{M}_q (\beta_{0,n},\gamma_{0,n})||_\infty ||\hat{\gamma} - \gamma_{0,n}||_1 \leq \sqrt{n} O_p(\log (J)/\sqrt{n})o_p(1/\log(J)) = o_p(1).$$
The second term on the right-hand side is equal to $$\sqrt{n}(\hat{\delta} - \delta_{0,n})'\partial_\delta^2 \hat{M}_q(\beta_{0,n},\Bar{\gamma})(\hat{\delta} - \delta_{0,n}) + 2\sqrt{n}(\hat{\eta}_q - \eta_{0,n,q})\partial_{\delta} \hat{g}(\beta_{0,n},\Bar{\delta})(\hat{\delta} - \delta_{0,n}).$$ In the linear case, $\sqrt{n}(\hat{\delta} - \delta_{0,n})'\partial_\delta^2 \hat{M}_q(\beta_{0,n},\Bar{\gamma})(\hat{\delta} - \delta_{0,n})  = 0$ and $\partial_\delta \hat{g}(\beta_{0,n},\Bar{\delta}) = \partial_\delta \hat{g}(\theta_{0,n}) = \partial_\delta \hat{g}(\hat{\theta})$. Therefore, 
$$|(\hat{\eta}_q - \eta_{0,n,q})\partial_\delta \hat{g}(\beta_{0,n},\Bar{\delta})(\hat{\delta} - \delta_{0,n})| = $$
$$|\hat{\eta}_q\partial_\delta \hat{g}(\hat{\theta})(\hat{\delta} - \delta_{0,n}) - \eta_{0,n,q} \partial_\delta \hat{g}(\theta_{0,n})(\hat{\delta} - \delta_{0,n})| \leq$$
$$(||\hat{\eta}_q\partial_\delta \hat{g}(\hat{\theta})||_\infty + ||\eta_{0,n,q} \partial_\delta \hat{g}(\theta_{0,n})||_\infty) ||\hat{\delta} - \delta_{0,n}||_1 = (||\hat{\eta}_q \partial_\delta \hat{g}(\hat{\theta})||_\infty + ||\partial_\delta \hat{M}_q(\theta_{0,n},\eta_{0,n})||_\infty) ||\hat{\delta} - \delta_{0,n}||_1$$
$$= (O_p(\log (J)\log(n)/\sqrt{n}) + O_p(\log (J)/\sqrt{n}))o_p(1/(\log (J)\log(n))) = o_p(1/\sqrt{n}).$$
Otherwise, for the non-linear case, there exists $\Bar{\delta}^*$ such that $||\Bar{\delta}^* - \delta_{0,n}||_1 \leq ||\hat{\delta} - \delta_{0,n}||_1$ and 
$$\partial_\delta \hat{g}(\beta_{0,n},\Bar{\delta}) = \partial_\delta \hat{g}(\theta_{0,n}) + (\Bar{\delta} - \delta_{0,n})' \partial_\delta^2 \hat{g}(\beta_{0,n},\Bar{\delta}^*).$$
Therefore, using Assumptions \hyperref[Ass2.1]{2.1.2} and \hyperref[Ass2.1]{2.1.4},
$$\sqrt{n}||(\hat{\eta}_q - \eta_{0,n,q})\partial_\delta \hat{g}(\beta_{0,n}, \Bar{\delta})(\hat{\delta} - \delta_{0,n})||_\infty \leq $$
$$\sqrt{n}||\hat{\eta}_q - \eta_{0,n,q}||_1( ||\partial_\delta \hat{g}(\theta_{0,n})||_\infty ||\hat{\delta} - \delta_{0,n}||_1$$
$$+   \max_{s \in \{1,...,Q\}}|(\Bar{\delta} - \delta_{0,n})'\partial_\delta^2 \hat{g}_s (\beta_{0,n},\Bar{\delta}^*)(\hat{\delta} - \delta_{0,n})|)$$
$$\leq \sqrt{n} o_p(n^{-1/4}/\sqrt{\log(J)}) O_p(\log(J))o_p(n^{-1/4}/\sqrt{\log(J)}) $$
$$+ \sqrt{n}o_p(n^{-1/4}/\sqrt{\log(J)}) ||\hat{\delta} - \delta_{0,n}||_2^2 \max_{s\in \{1,...,Q\}} \max eig(\partial_\delta^2 \hat{g}_s (\beta_{0,n},\Bar{\delta}^*)).$$
Then, using $\epsilon > 0$ defined by Assumption \hyperref[Ass2.1]{2.1.3}, because $||\Bar{\delta}^* - \delta_{0,n}||_1 \leq ||\hat{\delta} - \delta_{0,n}||_1 < \epsilon$ wpa1, then wpa1,
$$\max_{s\in \{1,...,Q\}} \max eig(\partial_\delta^2 \hat{g}_s (\beta_{0,n},\Bar{\delta}^*)) \leq \max_{s \in \{1,...,Q\}} \sup_{\delta: ||\delta - \delta_{0,n}||_1 < \epsilon} \max eig(\partial_\delta^2 \hat{g}_s(\beta_{0,n},\delta)) = O_p(\log(J)) \text{ and }$$
$$\max eig(\partial_\delta^2 \hat{M}_q (\beta_{0,n},\Bar{\gamma})) \leq \sup_{\gamma: ||\gamma-\gamma_{0,n}||_1 < \epsilon} \max eig(\partial_\delta^2 \hat{M}_q(\beta_{0,n},\gamma)) = O_p(\log(J)).$$
Hence,
$$\sqrt{n}||(\hat{\eta}_q - \eta_{0,n,q})\partial_\delta \hat{g}(\beta_{0,n}, \Bar{\delta})(\hat{\delta} - \delta_{0,n})||_\infty \leq $$
$$\leq \sqrt{n} o_p(n^{-1/4}/\sqrt{\log(J)}) O_p(\log(J))o_p(n^{-1/4}/\sqrt{\log(J)}) $$
$$+ \sqrt{n}o_p(n^{-1/4}/\log(J)) o_p(n^{-1/2}/\log(J))O_p(\log(J)) = o_p(1).$$
Also,
$$|\sqrt{n}(\hat{\delta} - \delta_{0,n})'\partial_\delta^2 \hat{M}_q(\beta_{0,n},\Bar{\gamma})(\hat{\delta} - \delta_{0,n})| \leq \sqrt{n}||\hat{\delta} - \delta_{0,n}||_2^2 \max eig(\partial_\delta^2 \hat{M}_q(\beta_{0,n},\Bar{\gamma}))$$
$$\leq \sqrt{n} o_p(n^{-1/2}/\log(J))O_p(\log(J)) = o_p(1).$$
Therefore, 
$$\sqrt{n}(\hat{M}_q(\beta_{0,n},\hat{\gamma}) - \hat{M}_q(\beta_{0,n}, \gamma_{0,n})) = o_p(1),$$
for each $q \in \{1,...,m\}$.

\textbf{Proof of Proposition \hyperref[P2.1]{2.1}:} I first show the consistency of $\Tilde{\beta}_{GMM}$. Note that $$||\hat{M}(\beta,\hat{\delta},\hat{\eta}) - \hat{M}(\beta,\delta_{0,n},\eta_{0,n})||_2 = ||\hat{\eta}\hat{g}(\beta,\hat{\delta}) - \eta_{0,n}\hat{g}(\beta,\delta_{0,n})||_2 \leq ||\hat{\eta}||_2 ||\hat{g}(\beta,\hat{\delta}) - g(\beta,\hat{\delta})||_2$$
$$+ ||\hat{\eta}||_2 ||g(\beta,\hat{\delta}) - g(\beta,\delta_{0,n})||_2 + ||\hat{\eta} - \eta_{0,n}||_2 ||g(\beta,\delta_{0,n}||_2 $$
$$+ ||\eta_{0,n}||_2 ||g(\beta,\delta_{0,n}) - \hat{g}(\beta,\delta_{0,n})||_2.$$
Note that since $||\eta_{0,n}||_2 = O(1)$ and $||\hat{\eta} - \eta_{0,n}||_2 = o_p(1)$, $||\hat{\eta}||_2 = O_p(1)$. Then $\sup_{\beta \in B}||g(\beta,\hat{\delta}) - g(\beta,\delta_{0,n})||_2 = o_p(1)$ by the continuous mapping theorem, and $\sup_{\beta \in B}||\hat{g}(\beta,\hat{\delta}) - g(\beta,\hat{\delta})||_2 = o_p(1)$ and $\sup_{\beta \in B}||g(\beta,\delta_{0,n}) - \hat{g}(\beta,\delta_{0,n})||_2 = o_p(1)$ by Assumption \hyperref[Ass2.1]{2.1.1}. Hence,
$$\sup_{\beta \in B} ||\hat{M}(\beta,\hat{\delta},\hat{\eta}) - \hat{M}(\beta,\delta_{0,n},\eta_{0,n})||_2 = o_p(1).$$
Therefore, since $W_n \overset{p}{\rightarrow} W$ where $W$ is positive definite, we have that $$\sup_{\beta \in B}|\hat{M}(\beta,\hat{\delta},\hat{\eta})'W_n\hat{M}(\beta,\hat{\delta},\hat{\eta}) - \hat{M}(\beta,\delta_{0,n},\eta_{0,n})'W_n\hat{M}(\beta,\delta_{0,n},\eta_{0,n})| = o_p(1).$$
Let $\hat{Q}(\beta)$ be equal to the objective function from equation \eqref{eq: GMM Estimator}. Combining this with Assumption \hyperref[Ass2.1]{2.1.1} and $W_n \overset{p}{\rightarrow} W$ gives $\sup_{\beta \in B} |\hat{Q}(\beta) - Q(\beta)| = o_p(1)$, where $$Q(\beta) = M(\beta,\delta_{0,n},\eta_{0,n})'W M(\beta,\delta_{0,n},\eta_{0,n}).$$ 
Let $\epsilon > 0$. By the definition of $\Tilde{\beta}_{GMM}$, $\hat{Q}(\Tilde{\beta}_{GMM}) < \hat{Q}(\beta_{0,n}) + \epsilon/3$. Then by the uniform convergence we have that $Q (\Tilde{\beta}_{GMM}) < \hat{Q}(\Tilde{\beta}_{GMM}) + \epsilon/3$ and $\hat{Q}(\beta_{0,n}) < Q(\beta_{0,n}) + \epsilon/3$ wpa1. Combining these inequalities gives $Q(\Tilde{\beta}_{GMM}) < Q(\beta_{0,n}) + \epsilon$ wpa1. By the strong identification condition of Assumption \hyperref[Ass2.2]{2.2.4} and $W$ being positive definite, for some $\Bar{C} > 0$, $||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2^2/\Tilde{C} \leq C^2 ||M (\Tilde{\beta}_{GMM},\delta_{0,n},\eta_{0,n})||_2^2/\Tilde{C} \leq  Q(\Tilde{\beta}_{GMM}) < \epsilon$ wpa1. So we have that $\Tilde{\beta}_{GMM} - \beta_{0,n} \overset{p}{\rightarrow} 0$.
\par 
By Assumption \hyperref[Ass2.2]{2.2.4}, $\partial_\beta^2 Q(\beta_{0,n}) = \partial_\beta M(\theta_{0,n},\eta_{0,n})'W \partial_\beta M(\theta_{0,n},\eta_{0,n}) \rightarrow M_\beta' W M_\beta$ and $M_\beta' W M_\beta$ is positive definite. Using Assumption \hyperref[Ass2.2]{2.2.2} and the consistency of $\hat{\delta}$ and $\hat{\eta}$, $$\partial_\beta^2 \hat{Q}(\beta_{0,n}) = \partial_\beta \hat{g}(\beta_{0,n},\hat{\delta})'\hat{\eta}'W_n \hat{\eta} \partial_\beta \hat{g}(\beta_{0,n},\hat{\delta}) - \partial_\beta M(\theta_{0,n},\eta_{0,n})'W \partial_\beta M(\theta_{0,n},\eta_{0,n}) \overset{p}{\rightarrow} 0.$$ So $\partial_\beta^2 \hat{Q}(\beta_{0,n}) \overset{p}{\rightarrow} M_\beta' W M_\beta$. Since $\hat{Q}(\beta)$ is twice continuously differentiable, 
$$\hat{Q}(\Tilde{\beta}_{GMM}) = \hat{Q}(\beta_{0,n}) + \partial_\beta \hat{Q}(\beta_{0,n})(\Tilde{\beta}_{GMM} - \beta_{0,n}) + (\Tilde{\beta}_{GMM} - \beta_{0,n})' \partial_\beta^2 \hat{Q}(\Bar{\beta}) (\Tilde{\beta}_{GMM} - \beta_{0,n})/2,$$
for some $\Tilde{\beta}$ with $||\Tilde{\beta} - \beta_{0,n}||_2 \leq ||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2$. Then since $\hat{Q}(\Tilde{\beta}_{GMM}) \leq \hat{Q}(\beta_{0,n})$, we have that
$$0 \geq \partial_\beta \hat{Q}(\beta_{0,n})(\Tilde{\beta}_{GMM} - \beta_{0,n}) + (\Tilde{\beta}_{GMM} - \beta_{0,n})' \partial_\beta^2 \hat{Q}(\Bar{\beta}) (\Tilde{\beta}_{GMM} - \beta_{0,n})/2.$$
Using Assumption \hyperref[Ass2.2]{2.2.2} and the consistency of $\Tilde{\beta}_{GMM}$, 
$$||\partial_\beta^2 \hat{Q}(\Bar{\beta}) - \partial_\beta^2 \hat{Q}(\beta_{0,n})||_2 \leq \sup_{\beta : ||\beta - \beta_{0,n}||_2 < ||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2} ||\partial_\beta^2 \hat{Q}(\beta) - \partial_\beta^2 \hat{Q}(\beta_{0,n})||_2 = o_p(1).$$
Then 
$$0 \geq \partial_\beta \hat{Q}(\beta_{0,n})(\Tilde{\beta}_{GMM} - \beta_{0,n}) + (\Tilde{\beta}_{GMM} - \beta_{0,n})' M_\beta' W M_\beta (\Tilde{\beta}_{GMM} - \beta_{0,n})/2 + o_p(||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2^2).$$
Multiplying both sides by $\frac{n}{(1 + \sqrt{n}||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2)^2}$ gives 
$$\frac{\sqrt{n}||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2}{(1 + \sqrt{n}||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2)^2} \sqrt{n} \partial_\beta \hat{Q}(\beta_{0,n}) $$
$$+ \sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n})'M_\beta'W M_\beta \sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n})/2 + o_p(1) \leq 0.$$
Then if $\sqrt{n}||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2 \rightarrow \infty$, $ \sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n})'M_\beta'W M_\beta \sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n})/2 \leq o_p(1)$. But since $'M_\beta'W M_\beta$ is positive definite, this implies that $\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) = o_p(1)$ which is a contradiction. Therefore, $\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) = O_p(1)$. 
\par
I now show that asymptotic normality of $\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n})$ when Assumption \hyperref[Ass2.2]{2.2.6} additionally holds. Since $\beta_{0,n}$ is bounded away from the boundary of $B$, wpa1 the first order condition is satisfied,
$$\hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})'W_n\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) = 0.$$
Using the Mean Value Theorem, for some $\Bar{\beta}$ such that $||\Bar{\beta} - \beta_{0,n}||_2 \leq ||\Tilde{\beta}_{GMM} - \beta_{0,n}||_2$, we have that
$$(\hat{M}(\beta_{0,n},\hat{\delta},\hat{\eta}) + \partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta})(\Tilde{\beta}_{GMM} - \beta_{0,n}))'W_n\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) = 0.$$
Therefore,
$$\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) = $$
$$(\partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta})'W_n\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}))^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})'W_n
\sqrt{n}\hat{M}(\beta_{0,n},\hat{\delta},\hat{\eta}).$$
Using the adaptivity condition of Lemma \hyperref[L2.1]{2.1},
$$\sqrt{n}\hat{M}(\beta_{0,n},\hat{\delta},\hat{\eta}) = \sqrt{n}\hat{M}(\theta_{0,n},\eta_{0,n}) + o_p(1) \overset{d}{\rightarrow} N(0, V_M).$$
Again using Assumption \hyperref[Ass2.2]{2.2.2}, $\partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta}) - \partial_\beta \hat{M}(\theta_{0,n},\eta_{0,n}) = o_p(1)$ and $\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) - \partial_\beta \hat{M}(\theta_{0,n},\eta_{0,n}) = o_p(1)$. Then since $\partial_\beta \hat{M}(\theta_{0,n},\eta_{0,n}) = \partial_\beta M(\theta_{0,n},\eta_{0,n}) + o_p(1) = M_\beta + o_p(1)$ and $W_n \overset{p}{\rightarrow} W$, we have that
$$\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) \overset{d}{\rightarrow} N(0,V),$$
where $(M_\beta' W M_\beta)^{-1} M_\beta' W V_M W M_\beta (M_\beta' W M_\beta)^{-1}$.

I now show the asymptotic normality of $\Tilde{\beta}_{OS}$. Because $\hat{M}$ is twice continuously differentiable, using the Mean Value Theorem,
$$\sqrt{n} (\Tilde{\beta}_{OS} - \beta_{0,n}) = $$
$$\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n} - (\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}))^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}))$$
$$ = \sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) $$
$$ + \sqrt{n}(\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}))^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \hat{M}(\beta_{0,n},\hat{\delta},\hat{\eta})$$
$$ - \sqrt{n}(\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}))^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n\partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta})(\Tilde{\beta}_{GMM} - \beta_{0,n}).$$
As shown above, $\partial_\beta \hat{M}(\beta_{0,n},\delta_{0,n},\eta_{0,n}) \overset{p}{\rightarrow} M_\beta$, $\partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta}) \overset{p}{\rightarrow} M_\beta$, and $\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) \overset{p}{\rightarrow} M_\beta$. Using this along with $W_n \overset{p}{\rightarrow} W$ and the adaptivity condition of Lemma \hyperref[L2.1]{2.1}, the second term is equal to 
$$(\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}))^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})' W_n \sqrt{n}\hat{M}(\theta_{0,n},\eta_{0,n}) + o_p(1) $$
$$ = (M_\beta' W M_\beta)^{-1} M_\beta' W \sqrt{n}\hat{M}(\theta_{0,n},\eta_{0,n}) + o_p(1)$$
and
$(\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})W_n \partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})')^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) W_n \partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta})' \overset{p}{\rightarrow} I_p.$
Then because $\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) = O_p(1)$, $\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n})$ multiplied by 
$$(I_p - (\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) W_n \partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta})')^{-1}\partial_\beta \hat{M}(\Tilde{\beta}_{GMM},\hat{\delta},\hat{\eta}) W_n \partial_\beta \hat{M}(\Bar{\beta},\hat{\delta},\hat{\eta})'),$$
is converging in probability to zero. Therefore, we have that 
$$\sqrt{n}(\Tilde{\beta}_{OS} - \beta_{0,n}) = $$
$$ (M_\beta' W M_\beta)^{-1} M_\beta' W \sqrt{n} \hat{M}(\theta_{0,n},\eta_{0,n}) + o_p(1) \overset{d}{\rightarrow} N(0,V).$$

\textbf{Proof of Proposition \hyperref[P3.1]{3.1}:} The proof proceeds by verifying Assumption 3.1 of \cite{Sun2013} and then replicating the argument in the proof of Theorem 3.1 of \cite{Sun2013} for the case with the sample moment conditions being $\hat{M}(\beta, \hat{\delta},\hat{\eta})$ and with drifting sequences of the true parameter $\beta_{0,n}$. Proposition \hyperref[P2.1]{2.1} holds so $\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) = O_p(1)$. Assumption \hyperref[Ass2.1]{2.2} imposes that $\beta_{0,n}$ is an interior point of $B$ bounded away from the boundary and Assumption \hyperref[Ass2.1]{2.1} imposes that $\hat{g}$ is twice continuously differentiable in $\theta$ which implies that $\hat{M}(\beta,\hat{\delta},\hat{\eta})$ is twice continuously differentiable in $\beta$. Then note that for $\lambda_n,r \in [0,1]$,
$$\sum_{i=1}^{\lfloor rn \rfloor} \partial_\beta \hat{M}_i(\beta_{0,n} + \lambda_n (\Tilde{\beta}_{GMM} - \beta_{0,n}),\hat{\delta},\hat{\eta})/n = \hat{\eta} (\sum_{i=1}^{\lfloor rn \rfloor}\partial_\beta g_i(\beta_{0,n} + \lambda_n(\Tilde{\beta}_{GMM} - \beta_{0,n}),\hat{\delta})/n - $$
$$\hat{\eta}\sum_{i=1}^{\lfloor rn \rfloor}\partial_\beta g_i(\beta_{0,n} + \lambda_n(\Tilde{\beta}_{GMM} - \beta_{0,n}),\delta_{0,n}))/n + \hat{\eta} \sum_{i=1}^{\lfloor rn \rfloor} \partial_\beta g_i(\beta_{0,n} + \lambda_n(\Tilde{\beta}_{GMM} - \beta_{0,n}),\delta_{0,n})/n.$$

The difference between the first and second terms is converging in probability to zero uniformly in $\lambda_n,r \in [0,1]$ by Assumption \hyperref[Ass3.2]{3.2.1}. Therefore, by Assumption \hyperref[Ass3.2]{3.2.3} and $||\hat{\eta} - \eta_{0,n}||_1 = o_p(1)$, we have that
$$\sum_{i=1}^{\lfloor rn \rfloor} \partial_\beta \hat{M}_i(\beta_{0,n} + \lambda_n (\Tilde{\beta}_{GMM} - \beta_{0,n}),\hat{\delta},\hat{\eta}) \overset{p}{\rightarrow} rM_\beta,$$
uniformly in $\lambda_n,r \in [0,1]$. Also, $M_\beta$ is full rank by Assumption \hyperref[Ass2.2]{2.2}. By Lemma \hyperref[L2.1]{2.1*} in Appendix \hyperref[ApB]{B} and Assumption \hyperref[Ass3.2]{3.2.4},
$$V_M^{-1/2} \sum_{t=1}^n \phi_k(\frac{t}{n}) \hat{\eta} g_t(\beta_{0,n},\hat{\delta})/\sqrt{n}$$
$$ = V_M^{-1/2} \sum_{t=1}^n (\phi_k(\frac{t}{n}) - \phi_k(\frac{t+1}{n}))(\sum_{i=1}^t \hat{\eta} g_i (\beta_{0,n},\hat{\delta})/\sqrt{n}) $$
$$V_M^{-1/2} \sum_{t=1}^n (\phi_k(\frac{t}{n}) - \phi_k(\frac{t+1}{n}))(\sum_{i=1}^t \eta_{0,n} g_i (\theta_{0,n})/\sqrt{n}) + o_p(1) $$
$$= V_M^{-1/2}\sum_{t=1}^n \phi_k(\frac{t}{n}) \eta_{0,n} g_t(\theta_{0,n})/\sqrt{n} + o_p(1) \overset{d}{\rightarrow} \xi_k,$$
for each $k \in \{0,...,K\}$, where I have normalized $\phi_k(\frac{n+1}{n}) = 0$. 
\par 
I now extend the proof of Theorem 3.1 of \cite{Sun2013}. Let $S_{t}(\beta) = \sum_{i=1}^t \hat{\eta} g_{i}(\beta,\hat{\delta})$. Then since the moment conditions are twice continuously differentiable in $\beta$, 
$$S_t(\Tilde{\beta}_{GMM})/\sqrt{n} = S_t(\beta_{0,n})/\sqrt{n} + (\sum_{i=1}^t \partial_\beta g_i(\Tilde{\beta}_t)/n) \sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}),$$
where $\Tilde{\beta}_{t} = \beta_{0,n} + \lambda_n \pdot (\Tilde{\beta}_{GMM} - \beta_{0,n})$ for some $\lambda_n \in [0,1]^p$ where $\pdot$ denotes the element-wise product. From Proposition \hyperref[P2.1]{2.1} and $W = I_m$, 
$$\sqrt{n}(\Tilde{\beta}_{GMM} - \beta_{0,n}) = \sqrt{n}(M_\beta' M_\beta)^{-1} M_\beta' \hat{M}(\beta_{0,n},\hat{\delta},\hat{\eta}) + o_p(1) = (M_\beta' M_\beta)^{-1} M_\beta' S_n(\beta_{0,n})/\sqrt{n} + o_p(1).$$
Therefore,
$$S_t(\Tilde{\beta}_{GMM})/\sqrt{n} = S_t(\beta_{0,n})/\sqrt{n} + (\sum_{i=1}^t \partial_\beta g_i(\Tilde{\beta}_t)/n) ((M_\beta'M_\beta)^{-1} M_\beta' S_n(\beta_{0,n}) + o_p(1))$$

$$ = S_t(\beta_{0,n})/\sqrt{n} - \frac{i}{n}S_n(\beta_{0,n})/\sqrt{n} + o_p(1),$$ uniformly over $t$. Then,
$$\sum_{i=1}^n \phi_k(\frac{i}{n}) \hat{\eta}g_i(\Tilde{\beta}_{GMM},\hat{\delta})/\sqrt{n} = \sum_{i=1}^n (\phi_k(\frac{i}{n}) - \phi_k(\frac{i+1}{n}))\frac{1}{\sqrt{n}} (S_i (\beta_{0,n}) - \frac{t}{n}S_n(\beta_{0,n})) + o_p(1)$$
$$= \frac{1}{\sqrt{n}}\sum_{i=1}^n \phi_k(\frac{i}{n}) (\hat{\eta} g_i (\beta_{0,n},\hat{\delta}) - \frac{1}{n}S_n(\beta_{0,n})) + o_p(1) = \frac{1}{\sqrt{n}}\sum_{i=1}^n \phi_k(\frac{i}{n}) \hat{\eta} g_i (\beta_{0,n},\hat{\delta}) + o_p(1).$$
Again, defining $\phi_k (\frac{n+1}{n}) = 0$. Then
$$V_M^{-1/2} \sum_{i=1}^n \hat{\eta} \phi_k (\frac{t}{n})g_i(\Tilde{\beta}_{GMM},\hat{\delta}) /\sqrt{n} \overset{d}{\rightarrow} \xi_k,$$
jointly for $k = 0,1,...,K$. Therefore,
$$\frac{K-p+1}{K}\mathbb{W}_n \overset{d}{\rightarrow} \frac{K-p+1}{K}\xi_0' (\sum_{k=1}^K \xi_k \xi_k'/K )^{-1}\xi_0 = F_{p,K-p+1}$$ and $$t_n \overset{d}{\rightarrow} \xi_0^2/\sqrt{\sum_{k=1}^K \xi_k^2/K} = t_K$$ when $p =1$.

\textbf{Proof of Proposition \hyperref[P4.1]{4.1}:} I first verify that Assumption \hyperref[Ass3.1]{3.1} holds when Assumptions \hyperref[Ass4.1]{4.1} and \hyperref[Ass4.2]{4.2} hold. Assumption \hyperref[Ass3.1]{3.1.1} holds because $D_n = \Delta^J$ is compact for all $J$, $f(\theta,\eta) = ||\delta||_2^2 + ||\eta||_2^2$, and $\hat{g}$ and $g$ are linear in $\delta$. For Assumption \hyperref[Ass3.1]{3.1.2}, note that for each $q \in 1,...,Q-1$,
$$\sup_{\delta \in \Delta^J}|Z_q^{pre}(Y_0^{pre'} - Y_{\mathcal{J}}^{pre'}\delta)/T_0 - E[Z_q^{pre}(Y_{0}^{pre'} - Y_{\mathcal{J}}^{pre'}\delta)/T_0]|
$$
$$ = \sup_{\delta \in \Delta^J}|Z_q^{pre}(Y_0^{pre'} - Y_{\mathcal{J}}^{pre'}\delta)/T_0 - E[Z_q^{pre} f^{pre}/T_0](\mu_0 - \mu_{\mathcal{J}}\delta)|$$
$$\leq 
\sup_{\delta \in \Delta^J} \{|(Z_q^{pre}f^{pre}/T_0 - E[Z_q^{pre}f^{pre}/T_0])(\mu_0 - \mu_{\mathcal{J}}\delta)' | $$
$$+ |Z_q^{pre}(\epsilon_0^{pre'} - \epsilon_{\mathcal{J}}^{pre'}\delta)/T_0|\} \leq $$
$$\max_{ 1 \leq j \leq J} ||\mu_0 - \mu_j||_2 ||Z_q^{pre}f^{pre}/T_0 - E[Z_q^{pre}f^{pre}/T_0]||_2 + 2\max_{0 \leq j \leq J} |Z_q^{pre}\epsilon_j^{pre'}/T_0|$$
$$ = O(1) O_p(1/\sqrt{T_0}) + O_p(\log(J)/\sqrt{T_0}).$$
Similarly, 
$$\sup_{\beta,\delta \in \Delta^J}| \sum_{t \in \mathcal{T}_1}(Y_{0t} - Y_{\mathcal{J},t}\delta)/T_1 - \beta - E[ \sum_{t \in \mathcal{T}_1}(Y_{0t} - Y_{\mathcal{J},t}\delta)/T_1 - \beta] | = $$ 
$$\sup_{\beta,\delta \in \Delta^J}| \sum_{t \in \mathcal{T}_1}(Y_{0t} - Y_{\mathcal{J},t}\delta)/T_1 - \beta - (E[\sum_{t\in\mathcal{T}_1 } f_t/T_1](\mu_0 - \mu_{\mathcal{J}}\delta) + \beta_{0,n} - \beta)| $$
$$\leq \max_{0 \leq j \leq J}||\sum_{t \in \mathcal{T}_1} f_t/T_1 - E[\sum_{t \in \mathcal{T}} f_t/T_1]||_2||\mu_0 - \mu_j||_2 + 2\max_{0 \leq j \leq J}|\sum_{t \in \mathcal{T}_1}\epsilon_{jt}/T_1|$$
$$= O_p(1/\sqrt{T_1})O(1) + O_p(\log(J)/\sqrt{T_1}).$$
Therefore, $\sup_{\theta \in\Theta_n} ||\hat{g}(\theta) - g(\theta)||_\infty = O_p(\log (J)/\sqrt{\min\{T_0,T_1\}})$. This also shows that $$\sup_{\theta \in\Theta_n} ||\partial_\delta \hat{g}(\theta) - \partial_\delta g(\theta)||_\infty = O_p(\log (J)/\sqrt{\min\{T_0,T_1\}}),$$ so Assumption \hyperref[Ass3.1]{3.1.2} holds with $a_n, b_n = \log (J)/\sqrt{\min \{T_0,T_1\}}$. Because $\hat{f}(\theta,\eta) = f(\theta,\eta)$, Assumption \hyperref[Ass3.1]{3.1.3} holds trivially with $c_n = 0$.
\par 
For Assumption \hyperref[Ass3.1]{3.1.4}, for any $\delta' \in D_n$, let $\delta^* = \argmin_{\delta \in D_{0,n}} ||\delta' - \delta||_2$. Provided that $||\delta' - \delta^*||_2 > 0$, $(\delta' - \delta^*)$ will be orthogonal to the hyperplane $\{ \delta : E[Z^{pre}f^{pre}/T_0]\mu_{\mathcal{J}}\delta = 0\} $ because $D_{0,n} = \{ \delta \in D_n : E[Z^{pre}f^{pre}/T_0]\mu_{\mathcal{J}}(\delta - \delta^*) = 0 \}$. Hence, because $ E[Z^{pre}f^{pre}/T_0]\mu_{\mathcal{J}}$ has non-zero rank,
$$||g(\theta)||_\infty \geq ||g(\theta)||_2/\sqrt{Q} \geq ||E[Z^{pre} f^{pre}/T_0] \mu_J(\delta' - \delta^*)||_2/\sqrt{Q} \geq \sqrt{C/Q} ||\delta' - \delta^*||_2/, $$
where $C$ is the minimum eigenvalue of $\mu_{\mathcal{J}}' E[Z^{pre} f^{pre}/T_0]'E[Z^{pre} f^{pre}/T_0] \mu_J$, which is bounded away from zero by Assumption \hyperref[Ass4.2]{4.2}. Then note that because $\delta^*$ only takes non-zero values for the elements in $\mathcal{P}$ and $||\delta'||_1 = ||\delta^*||_1 = 1$, so $$||\delta' - \delta^*||_1 = ||\delta_{\mathcal{P}}' - \delta_{\mathcal{P}}^*||_1 + ||\delta_{\mathcal{P}^c}'||_1 = ||\delta_{\mathcal{P}}' - \delta_{\mathcal{P}}^*||_1 + (1 - ||\delta_{\mathcal{P}}'||_1) $$
 $$= ||\delta_{\mathcal{P}}' - \delta_{\mathcal{P}}^*||_1 + (||\delta_{\mathcal{P}}^*||_1 - ||\delta_{\mathcal{P}}'||_1) \leq 2 ||\delta_{\mathcal{P}}' - \delta_{\mathcal{P}}^*||_1 \leq 2\sqrt{|\mathcal{P}|} ||\delta_{\mathcal{P}}' - \delta_{\mathcal{P}}^*||_2 \leq 2 \sqrt{|\mathcal{P}|} ||\delta' - \delta^*||_2.$$
For any $\eta \in H$, there exists a subset of $\mathcal{I}$ indices with $|\mathcal{I}| = R$ and the minimum singular value of $E[Z_{\mathcal{I}}^{pre}f^{pre}/T_0]$ is bounded below by some constant $C > 0$. Without loss of generality, assume that the row of $Z^{pre}$ are order so that the indices in $\mathcal{I}$ correspond to the first $R$ rows of $Z^{pre}$. Note that for any $\eta$, there exists $\Tilde{\eta}$ such that $\Tilde{\eta} \in H_{0,n} := \{\eta \in H: \partial_\delta M(\theta,\eta) = 0\}$ for all $n$ and  $\eta_q = \Tilde{\eta}_q$ for all $q > R$. Then $$||\eta \partial_\delta g(\delta)||_\infty
 = || (\eta_{-Q} - \Tilde{\eta}_{-Q})E[Z^{pre}F^{pre}/T_0]\mu_{\mathcal{J}}||_\infty $$
 $$\geq C ||(\eta_{-Q} - \Tilde{\eta}_{-Q} )E[Z_{\mathcal{I}}^{pre}f^{pre}/T_0]||_2 \geq C ||(\eta_{\mathcal{I}} - \Tilde{\eta}_{\mathcal{I}} )E[Z_{\mathcal{I}}^{pre}f^{pre}/T_0]||_2$$
 $$  \geq C'||\eta_{\mathcal{I}} - \Tilde{\eta}_{\mathcal{I}}||_2 \geq C/\sqrt{R} ||\eta_{\mathcal{I}} - \Tilde{\eta}_{\mathcal{I}}||_1 = C /\sqrt{R} ||\eta - \Tilde{\eta}||_1,$$
 for some $C,C' > 0$. Therefore, Assumption \hyperref[Ass3.1]{3.1.4} holds. 
\par 
Let $H_{0,n} := \{ \eta \in H : \eta g(\theta_{0,n}) \}$. For the first part of Assumption \hyperref[Ass3.1]{3.1.5}, note that, for each $n$, the identified set $D_{0,n} \times H_{0,n}$ and the set $$S = \{ (\delta,\eta) : ||\delta||_2^2 + ||\eta||_2^2 \leq ||\delta_{0,n}||_2^2 + ||\eta_{0,n}||_2^2 \}$$ are convex. By the separating hyperplane theorem, there exists a hyperplane described by the linear equations $Ax = b$ such that for all $\gamma = (\delta,\eta) \in S$ we have that $A\gamma \geq b$ and for all $\gamma \in D_{0,n} \times H_{0,n}$, $A\gamma \leq b$. Then since $(\delta_{0,n},\eta_{0,n}) \in S$ and $(\delta_{0,n},\eta_{0,n}) \in D_{0,n} \times H_{0,n}$,
 $A (\delta_{0,n},\eta_{0,n}) = b$ so $(\delta_{0,n},\eta_{0,n})' \gamma \geq 0$ for all $\gamma$ in the half space with $A \gamma \leq b$. Then it follows that $$||\gamma||_2^2 - ||(\delta_{0,n},\eta_{0,n})||_2^2 \geq ||\gamma - (\delta_{0,n},\eta_{0,n})||_2^2$$ for all $\gamma \in D_{0,n} \times H_{0,n}$. Because $\delta_{0,n}$ only takes non-zero values for the elements in $\mathcal{P}$ and $||\delta_{0,n}||_1 = ||\delta||_1 = 1$, so $$||\delta - \delta_{0,n}||_1 = ||\delta_{\mathcal{P}} - \delta_{0,n,\mathcal{P}}||_1 + ||\delta_{\mathcal{P}^c}||_1 = ||\delta_{\mathcal{P}} - \delta_{0,n,\mathcal{P}}||_1 + (1 - ||\delta_{\mathcal{P}}||_1) $$
 $$= ||\delta_{\mathcal{P}} - \delta_{0,n,\mathcal{P}}||_1 + (||\delta_{0,n,\mathcal{P}}||_1 - ||\delta_{\mathcal{P}}||_1) \leq 2 ||\delta_{\mathcal{P}} - \delta_{0,n,\mathcal{P}}||_1 \leq 2\sqrt{|\mathcal{P}|} ||\delta_{\mathcal{P}} - \delta_{0,n,\mathcal{P}}||_2,$$
 where $\delta_{\mathcal{P}}$ and $\delta_{\mathcal{P}^c}$ are vectors whose elements are the elements of $\delta$ with indices in $\mathcal{P}$ and $\mathcal{P}^c$ respectively. Since the dimension of $\eta$ is always equal to $Q$, $||\eta - \eta_{0,n}||_1 \leq \sqrt{Q} ||\eta - \eta_{0,n}||_2$. Therefore, $$||\gamma||_2^2 - ||(\delta_{0,n},\eta_{0,n})||_2^2 \geq ||\gamma - (\delta_{0,n},\eta_{0,n})||_2^2 \geq (2\sqrt{|\mathcal{P}|}||\delta  -\delta_{0,n}||_1 + \sqrt{Q}||\eta - \eta_{0,n}||_1)^2.$$ Therefore, we have that for all $n$, for all $\theta \in \Theta_{0,n}$ and $\eta \in H_{0,n}$, $$|f(\theta,\eta) - f(\theta_{0,n},\eta_{0,n})| \geq C_4 (||\delta - \delta_{0,n}||_1 + ||\eta - \eta_{0,n}||_1)^2 = C_4 (||\theta - \theta_{0,n}||_1 + ||\eta - \eta_{0,n}||_1)^2$$ for some constant $C_4 > 0$ which does not depend on $\theta$, $\eta$, or $n$.
 \par 
 For the second part of Assumption \hyperref[Ass3.1]{3.1.5}, note that for any $\delta_1,\delta_2 \in D_n$, $$2||\delta_1 - \delta_2||_1 \geq 2||\delta_1 - \delta_2||_2  \geq (||\delta_1||_2 + ||\delta_2||_2) |\;||\delta_1||_2 - ||\delta_2||_2| = 2 | \;||\delta_1||_2^2 - ||\delta_2||_2^2|.$$ Similarly, for any $\delta_1,\delta_2 \in D_n$ and $\eta_1,\eta_2 \in H$, if $C_5 \geq ||\delta_1||_2^2 + ||\eta_1||_2^2 \geq ||\eta_1||_2^2$  and $C_5 \geq ||\delta_2||_2^2 + ||\eta_2||_2^2 \geq ||\eta_2||_2^2$ for some $C_5 > 0$, then, $$ 2C_5 ||\eta_1 - \eta_2||_1 \geq 2 C_5 ||\eta_1 - \eta_2||_2 \geq (||\eta_1||_2 + ||\eta_2||_2)|\;||\eta_1||_2 - ||\eta_2||_2\;| = |\; ||\eta_1||_2^2 - ||\eta_2||_2^2\;|.$$ Then for any $n$ and any $\theta_1,\theta_2 \in \Theta_{n}$ and $\eta_1,\eta_2 \in H$ with $f(\theta_1,\eta_1),f(\theta_2,\eta_2) \leq C_5$, $$||\theta_1 - \theta_2||_1 + ||\eta_1 - \eta_2||_1 \geq ||\delta_1 - \delta_2||_1 + ||\eta_1 - \eta_2||_1 \geq |f(\theta_1,\eta_1) - f(\theta_2,\eta_2)|/\max \{2 C_5, 2\}.$$ Therefore, Assumption \hyperref[Ass3.1]{3.1.5} holds with $\gamma_1 = 2$ and $\gamma_2 = 1$.
\par 
I now verify the conditions of Assumption \hyperref[Ass2.1]{2.1}. Since Assumption \hyperref[Ass3.1]{3.1} holds, by Lemma \hyperref[L3.1]{3.1} we have that $$||\hat{\delta} - \delta_{0,n}||_1 = O_p(\max \{\log (J)/\sqrt{\min \{T_0,T_1\}},\lambda_\delta,\lambda_\eta\}^{\frac{1}{2}})= o_p(1/(\log(J)\log(\min \{T_0,T_1\}))).$$ For Assumption \hyperref[Ass2.1]{2.1.4}, $\hat{g}$ is linear in $\theta$ and $$||\hat{\eta}\partial_\delta \hat{g}(\theta)||_\infty \leq \lambda_\eta = O_p(\log (J)\log(\min\{T_0,T_1\})/\sqrt{\min\{T_0,T_1\}}).$$ Assumption \hyperref[Ass2.1]{2.1.3} holds trivially since $\hat{g}$ is linear in $\theta$ and Assumption \hyperref[Ass2.1]{2.1.2} is shown above. To verify Assumption \hyperref[Ass2.1*]{2.1*}, first note that $\eta_{0,n}$ satisfies,
$$\sum_{t \in \mathcal{T}_0} \sum_{q=1}^{Q-1} E[\eta_{0,n,q} Z_{qt} Y_{\mathcal{J},t}]/T_0 + \sum_{t \in \mathcal{T}_1} E[Y_{\mathcal{J},t}]/T_1 =  $$
$$(\sum_{t \in \mathcal{T}_0} \sum_{q=1}^{Q-1} E[\eta_{0,n,q} Z_{qt}f_t] /T_0 + \sum_{t \in \mathcal{T}_1} E[f_{t}]/T_1)\mu_{\mathcal{J}} = 0.$$
Therefore,
$$\sum_{t \in \mathcal{T}_0} \sum_{q=1}^{Q-1} E[\eta_{0,n,q} Z_{qt}f_t] /T_0 + \sum_{t \in \mathcal{T}_1} E[f_{t}]/T_1 = 0,$$
for each $\eta_{0,n}$. As a result, Assumption \hyperref[Ass4.2]{4.2.3} implies that $\eta_{0,n} \rightarrow \eta^*$ for some $\eta^*$. Without loss of generality, assume the time periods are indexed so that $\mathcal{T}_0 = \{ -T_0, ..., -1 \}$ and $\mathcal{T}_1 = \{0, ..., T_1 - 1\}$. Then for partial sums of the population moment conditions with pre-treatment time periods with indices $\{-t_0,...,-1\}$ and post-treatment time periods with indices $\{0,...,t_1-1\}$,
$$\sum_{i = -t_0}^{-1} \sum_{q=1}^{Q-1} E[\eta_{0,n,q} Z_{qi} Y_{\mathcal{J},i}]/T_0 + \sum_{i=0}^{t_1-1} E[Y_{\mathcal{J},i}]/T_1 \rightarrow 0$$
as $T_0,T_1 \rightarrow \infty$, uniformly over $1 \leq t_0 \leq T_0$ and $1 \leq t_1 \leq T_1$, so Assumption \hyperref[Ass2.1*]{2.1.1*} holds. For Assumption \hyperref[Ass2.1*]{2.1.2*},
 $$||\sum_{i=-t_0}^{-1} \sum_{q=1}^{Q-1} \eta_{0,n,q} Z_{qi} Y_{\mathcal{J},i}/T_0 + \sum_{i=0}^{t_1-1} Y_{\mathcal{J},i}/T_1- \sum_{i=-t_0}^{-1} \sum_{q=1}^{Q-1} E[\eta_{0,n,q} Z_{qi} Y_{\mathcal{J},i}]/T_0 - \sum_{i=0}^{t_1-1} E[Y_{\mathcal{J},i}]/T_1   ||_\infty \leq $$
$$||\eta_{0,n} ||_1 (|| \sum_{i=-t_0}^{-1} \sum_{q=1}^{Q-1} Z_{qi} \epsilon_{\mathcal{J},i}/T_0||_\infty + || \sum_{i=-t_0}^{-1} \sum_{q=1}^{Q-1} (E[Z_{qi}f_i] - Z_{qi}f_i)\mu_{\mathcal{J}}/T_0||_\infty $$
$$+ ||\sum_{i=0}^{t_1-1} (E[f_i] - f_i)\mu_{\mathcal{J}}/T_1||_\infty + ||\sum_{i=0}^{t_1-1} \epsilon_{\mathcal{J},i}/T_1||_\infty)  $$
$$ = O(1) O_p(\log (J)/\sqrt{T_0}) + O(1) O_p(\log (J)/\sqrt{T_1}) = O_p(\log(J)/\sqrt{\min \{T_0,T_1\}}) $$
uniformly over $1\leq t_0\leq T_0$ and $1\leq t_1 \leq T_1$ as $T_0,T_1 \rightarrow \infty$. Assumption \hyperref[Ass2.1*]{2.1.3*} holds trivially because $\hat{g}$ is linear in $\theta$. 
\par 
I now verify the conditions of Assumption \hyperref[Ass2.2]{2.2}.
 Since $$\sup_{\theta \in \Theta_n} ||\hat{g}(\theta) - g(\theta)||_2 = O_p(\log (J) /\sqrt{\min \{T_0,T_1\}})$$ and  $\log(J) /\sqrt{\min \{T_0,T_1\}} \rightarrow 0$, Assumption \hyperref[Ass2.2]{2.2.1} holds. Because $g(\theta)$ and $\hat{g}(\theta)$ are linear in $\theta$, Assumption \hyperref[Ass2.2]{2.2.2} holds. Also $\partial_\beta M(\beta_{0,n},\delta_{0,n},\eta_{0,n}) = -1 \ne 0$ and $||\beta_1 - \beta_2||_2 = ||M(\beta_1,\delta_{0,n},\eta_{0,n}) -M(\beta_2,\delta_{0,n},\eta_{0,n})||_2$ for all $\beta_1,\beta_2 \in B$ so Assumption \hyperref[Ass2.2]{2.2.4} holds. Then for Assumption \hyperref[Ass2.2]{2.2.5}, since there is single moment condition we can set $W_n = W = 1$ and $$\hat{M}(\beta , \delta_{0,n},\eta_{0,n}) - M(\beta,\delta_{0,n},\eta_{0,n}) = \eta_{0,n} (\hat{g}(0,\delta_{0,n}) - g(0,\delta_{0,n})) \overset{p}{\rightarrow} 0$$ as shown above.
\par 
I prove Assumption \hyperref[Ass2.2]{2.2.3} along with Assumption \hyperref[Ass3.2]{3.2}. Assumption \hyperref[Ass4.3]{4.3} directly guarantees that Assumption \hyperref[Ass3.2]{3.2.2} is satisfied. For Assumption \hyperref[Ass3.2]{3.2.1}, it holds trivially because $g_i(\theta)$ is linear in $\theta$. Assumption \hyperref[Ass3.2]{3.2.3} holds because $\partial_\beta \hat{M}(\beta,\delta,\eta) = \partial_\beta M(\beta,\delta,\eta) = 1$. Note that we can equivalently define the optimal control weights as 
 $$\delta_{0,n} = \argmin_{\delta \in \Delta^J: \mu_0 = \mu_{\mathcal{J}}\delta} ||\delta||_2^2.$$
 However, the elements of $\delta_{0,n}$ are only taking non-zero values for indices in $\mathcal{P}$ by Assumption \hyperref[Ass4.3]{4.3.3}, $\delta_{0,n}$ must also be equal to zero for all indices not in $\mathcal{P}$ and if $\mathcal{P} \subseteq \mathcal{J}$, then
 $$\delta_{0,n,\mathcal{P}} = \argmin_{\delta \in \Delta^{|\mathcal{P}|}: \mu_0 = \mu_{\mathcal{P}}\delta} ||\delta||_2^2.$$
 As a result, for sufficiently large $J$ so that $\mathcal{P} \subseteq \mathcal{J}$, $\delta_{0,n,\mathcal{P}}$ does not vary with $J$ or $n$. 
 \par 
Then for Assumption \hyperref[Ass3.2]{3.2.4} and \hyperlink{Ass2.2}{2.2.3}, first note that for $q \in \{1,..,Q-1\}$ and $k \in \{0,1,...,K\}$,
$$\sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) g_{q,t}(\theta_{0,n})/\sqrt{T_0} = \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) Z_{qt}(\epsilon_{0t} - \sum_{j \in \mathcal{P}} \delta_{0,n,j} \epsilon_{jt})/\sqrt{T_0},$$
$$= \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) Z_{qt} \epsilon_{0t}/\sqrt{T_0} + \sum_{j \in \mathcal{P}} \delta_{0,n,j} \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0})Z_{qt} \epsilon_{jt}/\sqrt{T_0}$$
and similarly for $q = Q$,
$$\sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1}) g_{q,t}(\theta_{0,n})/\sqrt{T_1} = \sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1})(\beta_t - \beta_{0,n}) + \sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1}) \epsilon_{0t} + \sum_{j \in \mathcal{P}} \delta_{0,n,j} \sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1}) \epsilon_{jt} /\sqrt{T_1}$$
because $\mu_0 = \mu_{\mathcal{J}}\delta_{0,n}$ and the sparsity of $\delta_{0,n}$. As noted earlier, for $T_0$ and $T_1$ sufficiently large, $\delta_{0,n}$ does not vary with $n$.  Therefore, the limit in equation \eqref{Asymptotic Variance of SCE} does exist and is equal to $V_g$, for some fixed positive definite matrix $V_g$. Then because of Assumption \hyperref[Ass4.3]{4.3.1} and $T_1/T_0 \rightarrow a > 0$, the conditions of Lemma \hyperref[LB3]{B3} are satisfied for the sequence of random vectors
\begin{equation*}
    \begin{pmatrix}
        \sqrt{\frac{\min \{T_0,T_1\}}{T_0}}g_{1t}(\theta_{0,n}) \\
        ... \\
        \sqrt{\frac{\min \{T_0,T_1\}}{T_0}}g_{q-1.t}(\theta_{0,n})        
    \end{pmatrix}
\end{equation*}
with $t \in \mathcal{T}_0$ and the sequence of random variables $\sqrt{\frac{\min \{T_0,T_1\}}{T_1}}g_{Qt}(\theta_{0,n})$ with $t \in \mathcal{T}_1$. Then, by Lemma \hyperref[LB3]{B3}, we have that 
$$V_g^{-1/2}\sqrt{\min \{T_0,T_1\}}\begin{pmatrix}
    \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) g_{1,t}(\theta_{0,n})/T_0 \\
    ... \\
    \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) g_{Q-1,t}(\theta_{0,n})/T_0 \\
    \sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1})  g_{Q,t}(\theta_{0,n})/T_1    
\end{pmatrix}$$
$$= V_g^{-1/2}\begin{pmatrix}
    \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) \sqrt{\frac{\min\{T_0,T_1\}}{T_0}} g_{1,t}(\theta_{0,n})/\sqrt{T_0} \\
    ... \\
    \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) \sqrt{\frac{\min\{T_0,T_1\}}{T_0}} g_{Q-1,t}(\theta_{0,n})/\sqrt{T_0} \\
    \sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1}) \sqrt{\frac{\min\{T_0,T_1\}}{T_1}} g_{Q,t}(\theta_{0,n})/\sqrt{T_1}    
\end{pmatrix} \overset{d}{\rightarrow} \zeta_k, $$
jointly for $k \in \{0,1,...,K\}$ with $\zeta_k \sim iid N(0,I_Q)$. Then since $V_M(\theta_{0,n},\eta_{0,n}) = \eta_{0,n}V_g(\theta_{0,n})\eta_{0,n}$ and $\hat{M}(\theta_{0,n},\eta_{0,n}) = \eta_{0,n}\hat{g}(\theta_{0,n})$ we also have that

$$V_M^{-1/2}\sqrt{\min \{T_0,T_1\}} \eta_{0,n} \begin{pmatrix}
    \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) g_{1,t}(\theta_{0,n})/T_0 \\  
    ...
    \\
     \sum_{t \in \mathcal{T}_0} \phi_k(\frac{t}{T_0}) g_{Q-1,t}(\theta_{0,n})/T_0 \\
     \sum_{t \in \mathcal{T}_1} \phi_k(\frac{t}{T_1}) g_{Q,t}(\theta_{0,n})/T_1
\end{pmatrix} \overset{d}{\rightarrow} \xi_k,$$
jointly for $k \in \{0,1,...,K\}$ with $\xi_k \sim iid N(0,1)$ so Assumptions \hyperref[Ass2.2]{2.2.3} and \hyperref[Ass3.2]{3.2.4} hold.




\section*{Appendix B}\phantomsection\label{ApB}

\textbf{Lemma B1 (Rate of Convergence of the Estimated Identified Set)}\phantomsection\label{LB1} Suppose that the conditions of Lemma \hyperref[L3.1]{3.1} hold. Then for any $\zeta > 0$, $d_H(\hat{S}_0^\zeta,S_{0,n}^\zeta, ||\cdot||_1) = O_p(\max \{ a_n \lambda_\delta, \lambda_\eta \})$ where $\hat{S}_0^\zeta = \{ (\theta,\eta) \in \hat{S}_0 : f(\theta,\eta) \leq f(\theta_{0,n},\eta_{0,n}) + \zeta\}$.

\textbf{Proof:}

Note that by the identification condition on $g$ in Assumption \hyperref[Ass3.1]{3.1.4}, for any $(\theta,\eta) \in \hat{S}_0^\zeta$,

$$C_2 \min \{ ||(\theta,\eta) - S_{0,n}^\zeta , C_1 \} \leq ||g(\theta)||_\infty + ||\eta \partial_\delta g(\theta)||_\infty \leq $$
$$||\hat{g}(\theta)||_\infty + ||g(\theta) - \hat{g}(\theta)||_\infty + ||\eta \partial_\delta \hat{g}(\theta)||_\infty + ||\eta (\partial_\delta g(\theta) - \partial_\delta \hat{g}(\theta))||_\infty$$
$$\leq \lambda_\delta + ||g(\theta) - \hat{g}(\theta)||_\infty + \lambda_\eta +  ||\eta||_1 \sum_{q=1}^Q ||\partial_\delta g_q(\theta) - \partial_\delta \hat{g}_q(\theta)||_\infty.$$
By Assumption \hyperref[Ass3.1]{3.1.1}, $\sup_{(\theta,\eta) \in \hat{S}_0^\zeta} ||\eta||_1 \leq \sup_{(\theta,\eta) \in S_n^\zeta} ||\eta||_1 = O(1)$. Then because $\lambda_\delta,\lambda_\eta, \sup_{\theta \in\Theta_n} ||g(\theta) - \hat{g}(\theta)||_\infty,\sup_{\theta \in\Theta_n} ||\partial_\delta g(\theta) - \partial_\delta \hat{g}(\theta)||_\infty = o_p(1) $, this implies that $\sup_{(\theta, \eta) \in \hat{S}_0^\zeta} ||(\theta,\eta) - S_{0,n}||_1  < C_1$ wpa1. Then wpa1, 
$$\sup_{(\theta,\eta) \in \hat{S}_0^\zeta} ||(\theta,\eta) -S_{0,n}^\zeta ||_1 \leq $$
$$\lambda_\delta + \lambda_\eta + \sup_{\theta \in \Theta_n} ||g(\theta) - \hat{g}(\theta)||_\infty + \sup_{(\theta, \eta) \in \hat{S}_0^\zeta }||\eta\|_1 ||\partial_\delta g(\theta) - \partial_\delta \hat{g}(\theta)||_\infty$$
$$ = \lambda_\delta + \lambda_\eta + O_p(a_n) + O(1)O_p(a_n) = O_p(\max \{\lambda_\delta,\lambda_\eta,a_n\}).$$
Also note that since $\sup_{(\theta,\eta) \in S_{0,n}^\zeta} ||\hat{g}(\theta)||_\infty \leq \sup_{\theta \in \Theta_{0,n}} ||\hat{g}(\theta)||_\infty = O_p(b_n)$, 
$$\sup_{(\theta,\eta) \in S_{0,n}^\zeta} ||\partial_\delta \eta g(\theta)||_\infty \leq \sup_{(\theta,\eta) \in S_{0,n}^\zeta} ||\eta||_1 ||\partial_\delta \hat{g}(\theta) - \partial_\delta g(\theta)||_\infty \ = O(1) O_p(b_n) = O_p(b_n),$$ 
and $ b_n/\min \{ \lambda_\delta, \lambda_\eta \} \overset{p}{\rightarrow} 0$, we have that $\sup_{(\theta,\eta) \in S_{0,n}^\zeta} ||\hat{g}(\theta)||_\infty < \lambda_\delta$ and $\sup_{(\theta,\eta) \in S_{0,n}^\zeta} ||\partial_\delta \eta \hat{g}(\theta) ||_\infty < \lambda_\eta$ wpa1. Hence, $S_{0,n}^\zeta \subset \hat{S}_0^\zeta$ wpa1. Therefore, $d_H(S_{0,n}^\zeta , \hat{S}_0^\zeta,||\cdot||_1) = O_p( \max \{a_n, \lambda_\delta,\lambda_\eta\})$.


\textbf{Lemma B2 (Convergence of Maximum of Averages)}\label{LB2} For random vectors $\{X_i\}_{i \in \mathbb{N}}$ with $X_i$ is taking values in $\mathbb{R}^J$ where $J$ is growing with $n$, suppose that $\{ X_i \}_{i \in \mathbb{N}}$ is $\alpha$-mixing with exponentially decaying mixing coefficients, mean-zero, bounded four moments, and there exists constants $C_1,C_2, q > 0$ such that $\sup_i P(|Z_{ji}| > a) \leq c_1 exp(-c_2 a^q)) $ for all $a > 0$. Then if $J = o(n^\zeta)$ for some $\zeta > 0$ as $n,J \rightarrow \infty$, $\max_{1 \leq j \leq J} |\sum_{i=1}^n X_{jt}/n| = O_p(\log(J)/\sqrt{n})$.

\textbf{Proof:} By Lemma 1 of \cite{Dendramis2021},
$$P(|\frac{1}{\sqrt{n}} \sum_{i=1}^n X_{ji}| > a) \leq c_3 [\exp(-c_4 a^2) + \exp(-c_5 (\frac{a\sqrt{T_0}}{\log^2 T_0})^{q/(q+1)})]$$
for all $a >0$ where $c_3$, $c_4$, and $c_5$ do not depend on $i$ and $j$. Then let $a = \kappa \log J/2$ for some $\kappa$ so that,
$$P(\max_{i \in \{1,...,J\}} |\frac{1}{n} \sum_{i=1}^n X_{ji}| > \kappa \log J/2) \leq $$
$$\sum_{j=1}^J P(|\frac{1}{\sqrt{n}} \sum_{i=1}^n X_{ji}| > \kappa \log J/2 \sqrt{n}) \leq $$
$$J c_3 \exp(-c_4 (\kappa/2)^2 \log J ) + J c_3 \exp(-c_5 (\frac{\kappa \log J /2\sqrt{n}}{\log^2 n})^{q/(q+1)}) := r_J + r_{J,n}.$$
First consider the case where $J \rightarrow \infty$. Let $\gamma >0$. Then we can choose $\kappa$ such that $c_4 (\kappa/2)^2 > 1 + \gamma$. Then
$r_J \leq J\exp(-(1+\gamma) \log J) = c_3 J^{-\gamma} \rightarrow 0$ as $J \rightarrow \infty$. Furthermore, since $J = o(n^\zeta)$, we have $n^{\frac{1}{4}} \geq J^{\frac{1}{4 \zeta}}$ and $n^{\frac{1}{4}} > 2\log^2(n)$ as $n \rightarrow \infty$. Then 
$$c_5 (\frac{\kappa \log J /2\sqrt{n}}{\log^2 n})^{q/(q+1)} \geq c_5 (\kappa(J^{\frac{1}{4\zeta}} \sqrt{\log J})^{q/(q+1)} > (1 + \gamma) \log J$$
as $J \rightarrow \infty$. Therefore, $ 0 \leq r_{J,n} \leq r_J \rightarrow 0$ as $n,J \rightarrow \infty$. Hence $\max_{j \geq 1} |\frac{1}{n} \sum_{i=1}^n X_{ji}| = o_p(1)$. 

\textbf{Applying Lemma B2 for Assumption 4.2:} Suppose $J = o(T_0^\zeta)$ for some $\zeta > 0$, $(Z_t, \epsilon_t)_{t \in \mathbb{Z}}$ is $\alpha$-mixing with exponentially decaying mixing coefficients, $E[\epsilon_{jt}|Z_{qt}] = 0$ for all $q \in \{1,...,Q-1\}$, $j \in \{1,...,J\}$, $\sup_{i,t} E[\epsilon_{it}^4] < \infty$ and $\sup_{q,t} E[Z_{qt}^4] < \infty$, and
$$\sup_{i,t} P(|\epsilon_{it}| > a) \leq c_1 \exp(-c_2 a^{q_1}) \text{ and } \sup_{f,t} P(|Z_{qt}| > a) \leq c_1 \exp(-c_2 a^{q_2})$$
for all $a > 0$ for some $q_1,q_2 > 0$ and $c_1,c_2 > 0$ which do not depend on $i,t$ and $q$. By Lemma A4 in \cite{Dendramis2021}, an exponential tail bound also holds for products of the idiosyncratic shocks and factors so, for example, 
$\sup_{i,t,k} P(|Z_{qt}\epsilon_{it}| > a) \leq c_1 exp(-c_2 a^{q})$ for all $a > 0$ where $q = q_1 q_2/(q_1 + q_2)$. Also $\sup_{q,j,t} E[(Z_{qt}\epsilon_{jt})^4] = \sup_{k,j,t} E[Z_{kt}^4]^{\frac{1}{2}} E[\epsilon_{jt}^4]^{\frac{1}{2}} < \infty$, $E[\epsilon_{jt} Z_{qt}] = E[\epsilon_{jt}|Z_{qt}]E[Z_{qt}] = 0$. As a result, the conditions of Lemma \hyperref[LB2]{B2} is satisfied so $\max_{1 \leq j \leq J} |\sum_{t \in \mathcal{T}_0} Z_{qt}\epsilon_{jt}/T_0| = O_p(\log(J)/\sqrt{T_0})$ for each $q \in \{1,...,Q-1\}$. The same reasoning can be applied to show that $\max_{1 \leq j \leq J} |\sum_{t \in \mathcal{T}_1} \epsilon_{jt}/T_1| = O_p(\log(J)/\sqrt{T_1})$.

\textbf{Lemma B3 (Applying a Functional Central Limit Theorem)}\phantomsection\label{LB3} Suppose $\{ \phi_k(x)\}_{k=0}^K$ satisfies Assumption \hyperref[Ass3.2]{3.2.2} and there is a stochastic process $\{X_i \}_{i \in \mathcal{N}}$ with $E[X_i] = 0$, $E[X_i^2] < \infty$ for all $i \in \mathbb{N}$, and $E[(\sum_{i=1}^n X_i)^2/n] \rightarrow \sigma^2$ for some $\sigma^2 > 0$. Further suppose that the sequence is $\alpha$-mixing with mixing coefficients $\alpha(k)$ and there exists $\gamma > 2$ such that $\sup_{i \in \mathbb{N}} E[|X_i|^\gamma] < \infty$ and $\sum_{k=1}^\infty \alpha(k)^{1- 2/\gamma} < \infty$. Then 
$$\sigma^{-1/2} \sum_{i=1}^n \phi_k(\frac{i}{n}) X_i/\sqrt{n} \overset{d}{\rightarrow} \xi_k,$$
jointly for $k \in \{0,1,...,K\}$ with $\xi_k \sim iid N(0,1)$.

\textbf{Proof:} The conditions of Theorem 0 of \cite{Herrndorf1985} are satisfied, which provides a Functional Central Limit Theorem for partial sums for $\alpha$-mixing processes. Therefore, the partial sums function $\hat{B}(r) = \sum_{i=1}^{\lfloor rn \rfloor} X_i/(\sigma \sqrt{n})$ converges weakly to the standard Wiener measure.
\par 
As pointed out by \cite{Phillips_2005} (see page 119), when Assumption \hyperref[Ass3.2]{3.2.2} holds and $\hat{B}(r)$ is converging weakly to the standard Wiener measure, then standard functional limit arguments and Wiener integration show that
$$\sigma^{-1/2} \sum_{i=1}^n \phi_k(\frac{i}{n}) X_i/\sqrt{n} \overset{d}{\rightarrow} \int_0^1 \phi_k(r)dB(r) = \xi_k,$$
where $\xi_k \sim N(0, 1)$, jointly for $k \in \{0,1,...,K\}$. Then, due to the orthogonality property of the basis functions, these $\xi_k$ are uncorrelated and since they are jointly normal this also means that they are independent. 

\textbf{Lemma 2.1* (Partial Sums Adaptivity Condition)}  Suppose $(\beta_{0,n},\delta_{0,n}) \in  \Theta_{0,n}$, $\eta_{0,n}$ satisfies equation \eqref{eq: Orthogonality Condition}, and Assumptions \hyperref[Ass2.1]{2.1} and \hyperref[Ass2.1*]{2.1*} hold. Then, uniformly over $t$ with $1 \leq t \leq n$, 
$$\sqrt{n}(\sum_{i=1}^t \hat{\eta} g_{i}(\beta_{0,n}, \hat{\delta})/n - \sum_{i=1}^t \eta_{0,n} g_i (\beta_{0,n},\delta_{0,n})/n) = o_p(1).$$

\textbf{Proof:} Let $\gamma = (\delta,\eta_q)$ and $\hat{\gamma} = (\hat{\delta},\hat{\eta}_q)$ where $\eta_q$ is the $q$-th row of $\eta$. Since the $q$-th element on the orthogonalized sample moment conditions $\hat{M}_q$ for $q \in \{1,...,m\}$ are twice continuously differentiable in $\gamma$, for each $q$ there exists $\Bar{\gamma}_t$ for each $t$ with $1 \leq t \leq n$ and $||\Bar{\gamma}_t - \gamma_0||_1 \leq ||\hat{\gamma} - \gamma_0||_1$ such that:
$$\sqrt{n}(\sum_{i=1}^t M_{qi}(\beta_{0,n},\hat{\gamma})/n - \sum_{i=1}^t M_{qi}(\beta_{0,n}, \gamma_0)/n) = \sqrt{n} \partial_\gamma \sum_{i=1}^t M_{qi}(\beta_{0,n},\gamma_0)/n(\hat{\gamma} - \gamma_0) $$
$$+ \sqrt{n}(\hat{\gamma} - \gamma_0)'\partial^2_\gamma \sum_{i=1}^t M_{qi}(\beta_{0,n},\Bar{\gamma}_t)/n(\hat{\gamma} - \gamma_0).$$
The magnitude of the first term on the right-hand side is less than or equal to 
$$\sqrt{n} ||\partial_\gamma \sum_{i=1}^t M_{qi} (\beta_{0,n},\gamma_0)/n||_\infty ||\hat{\gamma} - \gamma_0||_1 \leq \sqrt{n} O_p(\log (J)/\sqrt{n})o_p(1/\log(J)) = o_p(1).$$
The second term on the right-hand side is equal to $$\sqrt{n}(\hat{\delta} - \delta_{0,n})'\partial_\delta^2 \hat{M}_q(\beta_{0,n},\Bar{\gamma}_t)(\hat{\delta} - \delta_{0,n}) + 2\sqrt{n}(\hat{\eta}_q - \eta_{0,n,q})\partial_{\delta} \sum_{i=1}^t g_i (\beta_{0,n},\Bar{\delta})/n(\hat{\delta} - \delta_{0,n}).$$ In the linear case, $\sqrt{n}(\hat{\delta} - \delta_{0,n})'\partial_\delta^2 \sum_{i=1}^t M_{qi}(\beta_{0,n},\Bar{\gamma}_t)/n(\hat{\delta} - \delta_{0,n})  = 0$ and $$\partial_\delta \sum_{i=1}^t g_i (\beta_{0,n},\Bar{\delta})/n = \partial_\delta \sum_{i=1}^t g_i (\theta_{0,n})/n = \partial_\delta \sum_{i=1}^t g_i (\hat{\theta})/n.$$ Therefore, 
$$|(\hat{\eta}_q - \eta_{0,n,q})\partial_\delta \sum_{i=1}^t g_i (\beta_{0,n},\Bar{\delta})/n(\hat{\delta} - \delta_{0,n})| = $$
$$|\hat{\eta}_q\partial_\delta \sum_{i=1}^t g_i(\hat{\theta})(\hat{\delta} - \delta_{0,n})/n - \eta_{0,n,q} \partial_\delta \sum_{i=1}^t g_i (\theta_{0,n})(\hat{\delta} - \delta_{0,n})/n| \leq$$
$$(||\hat{\eta}_q\partial_\delta \sum_{i=1}^t g_i (\hat{\theta})/n||_\infty + ||\eta_{0,n,q} \partial_\delta \sum_{i=1}^t g_i (\theta_{0,n})/n||_\infty) ||\hat{\delta} - \delta_{0,n}||_1 $$
$$= (||\hat{\eta}_q \partial_\delta \sum_{i=1}^t g_i (\hat{\theta})/n||_\infty + ||\partial_\delta \sum_{i=1}^t M_{qi}(\theta_{0,n},\eta_{0,n})/n||_\infty) ||\hat{\delta} - \delta_{0,n}||_1$$
$$= (O_p(\log (J)\log(n)/\sqrt{n}) + O_p(\log (J)/\sqrt{n}))o_p(1/(\log (J)\log(n))) = o_p(1/\sqrt{n}).$$
Otherwise, for the non-linear case, there exists $\Bar{\delta}_t^*$ for each $t$ with $1 \leq t \leq n$, such that $||\Bar{\delta}_t^* - \delta_{0,n}||_1 \leq ||\hat{\delta} - \delta_{0,n}||_1$ and 
$$\partial_\delta \sum_{i=1}^t g_i (\beta_{0,n},\Bar{\delta})/n = \partial_\delta \sum_{i=1}^t g_i (\theta_{0,n})/n + (\Bar{\delta} - \delta_{0,n})' \partial_\delta^2 \sum_{i=1}^t g_i (\beta_{0,n},\Bar{\delta}_t^*)/n.$$
Therefore, using Assumptions \hyperref[Ass2.1]{2.1.2} and \hyperref[Ass2.1]{2.1.4},
$$\sqrt{n}||(\hat{\eta}_q - \eta_{0,n,q})\partial_\delta \sum_{i=1}^t g_i (\beta_{0,n}, \Bar{\delta})/n(\hat{\delta} - \delta_{0,n})||_\infty \leq $$
$$\sqrt{n}||\hat{\eta}_q - \eta_{0,n,q}||_1( ||\partial_\delta \sum_{i=1}^t g_i (\theta_{0,n})/n||_\infty ||\hat{\delta} - \delta_{0,n}||_1$$
$$+   \max_{s \in \{1,...,Q\}}|(\Bar{\delta} - \delta_{0,n})'\partial_\delta^2 \sum_{i=1}^t g_{si} (\beta_{0,n},\Bar{\delta}_t^*)/n(\hat{\delta} - \delta_{0,n})|)$$
$$\leq \sqrt{n} o_p(n^{-1/4}/\sqrt{\log(J)}) O_p(\log(J))o_p(n^{-1/4}/\sqrt{\log(J)}) $$
$$+ \sqrt{n}o_p(n^{-1/4}/\sqrt{\log(J)}) ||\hat{\delta} - \delta_{0,n}||_2^2 \max_{s\in \{1,...,Q\}} \max eig(\partial_\delta^2 \sum_{i=1}^t g_{si} (\beta_{0,n},\Bar{\delta}_t^*)/n).$$
\par 
Then, using $\epsilon > 0$ defined by Assumption \hyperref[Ass2.1]{2.1.4}, because $||\Bar{\delta}_t^* - \delta_{0,n}||_1 \leq ||\hat{\delta} - \delta_{0,n}||_1 + ||\hat{\eta}_q - \eta_{0,n,q}||_1 < \epsilon$ wpa1, then wpa1 
$$\max_{s\in \{1,...,Q\}} \max eig(\partial_\delta^2 \sum_{i=1}^t g_{si} (\beta_{0,n},\Bar{\delta}_t^*)/n) $$
$$\leq \max_{s \in \{1,...,Q\}} \sup_{\delta: ||\delta - \delta_{0,n}||_1 < \epsilon} \max eig(\partial_\delta^2 \sum_{i=1}^t g_{si} (\beta_{0,n},\delta)/n) = O_p(\log(J)) \text{ and }$$
$$\max eig(\partial_\gamma^2 \sum_{i=1}^t M_{qi}(\beta_{0,n},\Bar{\gamma}_t)/n) \leq \sup_{\gamma: ||\gamma-\gamma_0||_1 < \epsilon} \max eig(\partial_\gamma^2 \sum_{i=1}^t M_{qi}(\beta_{0,n},\gamma)/n) = O_p(\log(J)).$$
Hence,
$$\sqrt{n}||(\hat{\eta}_q - \eta_{0,n,q})\partial_\delta \sum_{i=1}^t g_i (\beta_{0,n}, \Bar{\delta})/n(\hat{\delta} - \delta_{0,n})||_\infty \leq $$
$$\leq \sqrt{n} o_p(n^{-1/4}/\sqrt{\log(J)}) O_p(\log(J))o_p(n^{-1/4}/\sqrt{\log(J)}) $$
$$+ \sqrt{n}o_p(n^{-1/4}/\log(J)) o_p(n^{-1/2}/\log(J))O_p(\log(J)) = o_p(1).$$
Also,
$$|\sqrt{n}(\hat{\delta} - \delta_{0,n})'\partial_\delta^2 \sum_{i=1}^t M_{qi} (\beta_{0,n},\Bar{\gamma}_t)/n(\hat{\delta} - \delta_{0,n})/n| $$
$$\leq \sqrt{n}||\hat{\delta} - \delta_{0,n}||_2^2 \max eig(\partial_\delta^2 \sum_{i=1}^t M_{qi} (\beta_{0,n},\Bar{\gamma}_t)/n)$$
$$\leq \sqrt{n}O_p(\log(J)) o_p(n^{-1/2}/\log(J)) = o_p(1).$$
Therefore, uniformly over $t$ with $1 \leq t \leq n$,
$$(\sum_{i=1}^t M_{qi}(\beta_{0,n},\hat{\gamma}) - \hat{M}_{qi}(\beta_{0,n}, \gamma_0))/\sqrt{n} = o_p(1),$$
for each $q \in \{1,...,m\}$.

\textbf{Sufficient Condition for Assumption \hyperref[Ass2.2]{2.2.2}: } Suppose that $J$ is fixed, $\Theta_n$ is fixed and compact, $\hat{g}(\theta) - g(\theta) \overset{p}{\rightarrow} 0$ point-wise in $\theta$, and there exists $\alpha > 0$ and $B_n = O_p(1)$ such that for all $\theta_1,\theta_2 \in \Theta_n$, $\sup_{\theta \in \Theta_n} ||\hat{g}(\theta_1) - \hat{g}(\theta_2)||_2 \leq B_n ||\theta_1 - \theta_2||_2^\alpha$. Then since $g$ is continuous, the conditions of Lemma 2.9 of \cite{Newey-McFadden} are satisfied when $J$ is fixed, so $\sup_{\theta \in \Theta_n} |\hat{g}(\theta) - g(\theta)| \overset{p}{\rightarrow} 0$ as $n \rightarrow \infty$.

