\section*{Appendix}

In this appendix, we take the Green-function method to study the Casimir effect on the network. For simplicity, we focus on the conformal scalar in the $d$-dimensional Euclidean spacetime $M=R^{d-1}\times N^1$. Here $R^{d-1}$ is the $(d-1)$-dimensional flat space, and $N^1$ denotes the one-dimensional network with n edges linked by one node (Fig. \ref{CrossLine}). The coordinates on the edge $E_i$ are $(x_i, y^a)$ with $i=1,2,...,n$ and $a=1,2,..,d-1$. We have $0\le x_i\le L_i$ with the node at $x_i=0$. We take $x_{\mu}$ to label the coordinates on the whole space $M=R^{d-1}\times N^1$.  

Let us start with the heat kernel obeying EOM
 \begin{eqnarray}\label{app: EOM heat kernel}
(\partial_s -\Box) K(s,x_{\mu},x'_{\mu})=0,
\end{eqnarray}
and the limit
 \begin{eqnarray}\label{app: BC heat kernel}
\lim_{s\to 0} K(s,x_{\mu},x'_{\mu})=\delta^{(d)}(x_{\mu}-x'_{\mu}). 
\end{eqnarray}
Here $\Box=\partial_{\mu}\partial_{\mu}$ is the D'Alembert operator, and $\delta^{(d)}(x_{\mu}-x'_{\mu})$ is the $d$-dimensional delta function. From the heat kernel, we can derive the Green function as \cite{Vassilevich:2003xt}
 \begin{eqnarray}\label{app: Greenfunction}
G(x_{\mu},x'_{\mu})=\int_0^{\infty} ds K(s,x_{\mu},x'_{\mu}),
\end{eqnarray}
and then derive the renormalized stress tensor by \cite{Miao:2024ddp}
\begin{eqnarray}\label{app: Tij}
\langle T_{\mu\nu} \rangle=\lim_{x'_{\mu}\to x_{\mu}} \left[  (1-2\xi) \partial_{\mu}\partial_{\nu'}-2\xi \partial_{\mu} \partial_{\nu} +(2\xi -\frac{1}{2})\delta_{\mu\nu} \partial_{\alpha} \partial_{\alpha'}  \right] \hat{G}(x_{\mu},x'_{\mu}),
\end{eqnarray}
where $\xi=\frac{d-2}{4(d-1)}$ and $\hat{G}=G-G_0$ with $G_0$ the Green function in the free space.

For the space $R^{d-1}\times N^1$, the heat kernel is given by 
\begin{eqnarray}\label{app: heat kernel 1}
K=K_{R^{d-1}} K_{N^1},
\end{eqnarray}
where \cite{Vassilevich:2003xt}
\begin{eqnarray}\label{app: heat kernel R}
K_{R^{d-1}}=\frac{1}{(4\pi s)^{\frac{d-1}{2}}} \exp(-\frac{\sum_{a=1}^{d-1} (y_{a}-y'_{a})^2}{4s}),
\end{eqnarray}
and $K_{N^1}$ can be obtained by 
\begin{eqnarray}\label{app: heat kernel N}
K_{N^1}=\sum_m e^{-\lambda_m s}\varphi_m(x_i) \varphi_m(x'_j),
\end{eqnarray}
where $\lambda_m$ and $\varphi_m(x_i)$ are the eigenvalues and eigenfunctions of D'Alembert operator on $N^1$
\begin{eqnarray}\label{app: eigenfunctions}
\partial^2_{x_i}\varphi_m(x_i)=-\lambda_m \varphi_m(x_i). 
\end{eqnarray}
Note that $\varphi_m(x_i)$ obeys the junction condition (\ref{sect2: junction condition}) on the node and either DBC (\ref{sect3: DBC}) or NBC (\ref{sect3: NBC}) on the boundaries. As a result, we have from sect. 3 that 
\begin{eqnarray}\label{app: eigenfunctions 1}
\varphi_m(x_i)=a_{m (i)}\begin{cases}
 \sin\Big( k_{m} (x_i-L_i) \Big),\ \ \ \ \ \text{for DBC} ,\\
\cos\Big( k_{m}  (x_i-L_i) \Big),\  \ \ \ \ \text{for NBC},
\end{cases} 
\end{eqnarray}
and $\lambda_m=k_m^2$ with $k_m$ obeying the spectrum $\Delta(k_m)=0$
\begin{eqnarray}\label{app: spectrum}
\Delta(k)=\begin{cases}
\sum_{i=1}^n \cot(k L_i),\ \ \ \ \ \text{for DBC} ,\\
\sum_{i=1}^n \tan(k L_i),\  \ \ \ \ \text{for NBC}.
\end{cases} 
\end{eqnarray}
We normalize the eigenfunctions as
\begin{eqnarray}\label{app: eigenfunctions normalize}
\sum_{i=1}^n\int_0^{L_i} \varphi_m(x_i)\varphi_n(x_i) dx_i=\delta_{mn},
\end{eqnarray}
which fixes the coefficients
\begin{eqnarray}\label{app: coefficients}
a_{m (i)}=\begin{cases}
\frac{\sqrt{2} \csc \left(L_i k_m\right)}{\sqrt{\sum _{j=1}^n L_j \csc ^2\left(L_j k_m\right)}},\ \ \ \ \ \text{for DBC} ,\\
\frac{\sqrt{2} \sec \left(L_i k_m\right)}{\sqrt{\sum _{j=1}^n L_j \sec ^2\left(L_j k_m\right)}},\  \ \ \ \ \text{for NBC}.
\end{cases} 
\end{eqnarray}
From (\ref{app: heat kernel 1},\ref{app: heat kernel R},\ref{app: heat kernel N},\ref{app: eigenfunctions 1},\ref{app: coefficients}), we obtain the heat kernel and then can derive the renormalized stress tensor from (\ref{app: Greenfunction},\ref{app: Tij}). For the conformal scalar, we have $T_{xx}=-(d-1) T_{y_ay_a}$ so that $\langle T^{\mu}_{\ \mu} \rangle=0$. Without loss of generality, we focus on the pressure $T_{xx}$ below. 

From (\ref{app: Tij}), we obtain the pressure on the edge $E_i$
\begin{eqnarray}\label{app: Pi}
P^i=\langle T_{xx} \rangle|_{E_i}=2^{1-d} \pi ^{\frac{1}{2}-\frac{d}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right) 
\begin{cases}
\sum_{m}  \frac{k_m^{d-1} \csc^2\left(L_i k_m\right)}{\sum _{j=1}^n L_j \csc ^2\left(L_j k_m\right)},\ \ \ \ \ \text{for DBC} ,\\
\sum_{m}  \frac{k_m^{d-1} \sec^2\left(L_i k_m\right)}{\sum _{j=1}^n L_j \sec ^2\left(L_j k_m\right)},\  \ \ \ \ \text{for NBC},
\end{cases} 
\end{eqnarray}
 where $k_m$ are zeros of (\ref{app: spectrum}). In the above derivations, we first take the limit $x'_{\mu}\to x_{\mu}$, and then do the integral of $s$ for suitable dimension $d$. Finally, we analytically continue the results to general even $d$ and get the above result. Note that, for odd $d$, (\ref{app: Pi}) is divergent and we need further regularizations. For simplicity, we focus on even $d$ below. 

We take the following formula to compute (\ref{app: Pi})
\begin{eqnarray} \label{app: key trick}
P^i=\sum_n f(\omega_n)=\sum_m f(p_m)+\frac{1}{2\pi i}\oint f(\omega) d \ln \Delta(\omega),
\end{eqnarray} 
where $\omega_n$ and $p_m$ are zeros and poles of $\Delta(k)$ (\ref{app: spectrum}).  The poles of (\ref{app: spectrum}) are given by
\begin{eqnarray}\label{app: poles}
p_{m}=\begin{cases}
\frac{m \pi}{L_i},\ \ \ \ \ \ \ \ \ \  \text{for DBC} ,\\
\frac{(\frac{1}{2}+m) \pi}{L_i},\  \ \ \ \ \text{for NBC}.
\end{cases} 
\end{eqnarray}
Thus, the pole contributions to the pressure (\ref{app: key trick}) is 
\begin{eqnarray} \label{app: pole contribution}
\sum_m f(p_m)&=&2^{1-d} \pi ^{\frac{1}{2}-\frac{d}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right) \begin{cases}
\sum_{m}\frac{(m \pi)^{d-1} }{ L_i^d},\ \ \ \ \ \ \ \text{for DBC} ,\\
\sum_{m} \frac{(\frac{1}{2}\pi+m \pi)^{d-1} }{ L_i^d},\  \ \ \text{for NBC},
\end{cases} \nonumber\\
&=&2^{1-d} \pi ^{\frac{d}{2}-\frac{1}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right)\frac{1}{L_i^d} \begin{cases}
\zeta(1-d) ,\ \ \ \ \ \ \ \text{for DBC} ,\\
\zeta(1-d,\frac{1}{2}),\  \ \ \ \text{for NBC},
\end{cases}
\end{eqnarray} 
which agrees with the first line of (\ref{sect3.2: Pi DBC},\ref{sect3.2: Pi NBC}). The integral contribution to the pressure (\ref{app: key trick}) is
\begin{eqnarray} \label{app: integral contribution}
\frac{1}{2\pi i}\oint f(\omega) d \ln \Delta(\omega)=(-1)^{\frac{d}{2}} 2^{1-d} \pi ^{-\frac{d}{2}-\frac{1}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right)\begin{cases}
-\int_0^{\infty} d\omega \frac{\omega ^{d-1} \text{csch}^2\left(\omega  L_i\right)}{\sum _{j=1}^n \coth \left(\omega  L_j\right)},\  \text{for DBC} ,\\
\int_0^{\infty} d\omega\frac{\omega ^{d-1} \text{sech}^2\left(\omega  L_i\right)}{\sum _{j=1}^n \tanh \left(\omega  L_j\right)},\  \ \ \ \text{for NBC},
\end{cases} 
\end{eqnarray} 
Now we obtain the total pressure for DBC
\begin{eqnarray}\label{app: Pi DBC}
P^i_{\text{DBC}}&=&2^{1-d} \pi ^{\frac{d}{2}-\frac{1}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right)\zeta(1-d)\sum_{i=1}^n\frac{1}{L_i^d} \nonumber\\
&&-(-1)^{\frac{d}{2}} 2^{1-d} \pi ^{-\frac{d}{2}-\frac{1}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right)\int_0^{\infty} d\omega \frac{\omega ^{d-1} \text{csch}^2\left(\omega  L_i\right)}{\sum _{j=1}^n \coth \left(\omega  L_j\right)},
\end{eqnarray}
and for NBC
\begin{eqnarray}\label{app: Pi NBC}
P^i_{\text{NBC}}&=&2^{1-d} \pi ^{\frac{d}{2}-\frac{1}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right)\zeta(1-d,\frac{1}{2})\sum_{i=1}^n\frac{1}{L_i^d} \nonumber\\
&&+(-1)^{\frac{d}{2}} 2^{1-d} \pi ^{-\frac{d}{2}-\frac{1}{2}} \Gamma \left(\frac{3}{2}-\frac{d}{2}\right)\int_0^{\infty} d\omega \frac{\omega ^{d-1} \text{sech}^2\left(\omega  L_i\right)}{\sum _{j=1}^n \tanh \left(\omega  L_j\right)}.
\end{eqnarray}
Recall that the above formulas work only for even $d$. For $d=2$ and $n=3$, the pressures (\ref{app: Pi DBC},\ref{app: Pi NBC}) reduces to (\ref{sect3: Casimir force DBC},\ref{sect3: Casimir force NBC}) of sect. 3.1. For general even $d$,  the pressures (\ref{app: Pi DBC},\ref{app: Pi NBC}) also agree with those of sect. 3.2. We now complete the discussion of the network Casimir effect by applying the Green-function method. 


