\begin{document}
\title{Largest zero-dimensional intersection of $r$ degree $d$ hypersurfaces}
\author{Deepesh Singhal, Yuxin Lin}



\begin{abstract}
Suppose we have $r$ hypersurfaces in $\mathbb{P}^m$ of degree $d$, whose defining polynomials are linearly independent and their intersection is zero-dimensional. Then what is the maximum number of points in the intersection of the $r$ hypersurfaces?
We conjecture an exact formula for this problem and prove it when $m=2$.

We show that this can be used to compute the generalized Hamming weights of the projective Reed-Muller code $\operatorname{PRM}_q(d,2)$ and hence settle a conjecture of Beelen, Datta, and Ghorpade for $m=2$.
\end{abstract}

\maketitle









\section{introduction}

Let $\fq$ be the finite field of size $q$.
Let $S(m,\fq)=\fq[x_0,\dots,x_m]$ and $S_d(m,\fq)$ be its $d^{th}$ graded component. Given a positive integer $r \leq \binom{m+d}{d}=\dim_{\fq}(S_d(m,\fq))$, Beelen, Datta and Ghorpade in \cite{beelen2018maximum} define
$$e_r(d,m;q)=\max\{|V(W)(\fq)| : W\subseteq S_d(m,\fq), \dim(W)=r\}.$$
We would like to note that the problem of computing $e_r(d,m;q)$, is equivalent to computing the $r^{th}$ generalized Hamming weight of the projective Reed-Muller code $PRM_q(d,m)$.
Beelen, Datta and Ghorpade have conjectured an exact formula for $e_r(d,m;q)$. We will introduce some notations to state their conjecture.

Let $\N$ be the set of non-negative integers. Beelen, Datta and Ghorpade in \cite{beelen2018maximum} define
$$\Omega(d,m)=\Big\{(\gamma_1,\dots,\gamma_{m+1})\in \N^{m+1}: \sum_{i=1}^{m+1} \gamma_i=d\Big\}.$$
For $1\leq r\leq |\Omega(d,m)|=\binom{m+d}{d}$, let $\omega_r(d,m)=(\beta_1,\dots,\beta_{m+1})$ be its $r^{th}$ largest element under lexicographical ordering. Then, they define
$$H_r(d,m;q)=\sum_{i=1}^m \beta_iq^{m-i}.$$
%For $r>\binom{m+d}{d}$, set $H_r(d,m;q)=0$ and $H_0(d,m;q)=q^m$.
Let $\pi_m(q)=|\pmfq|=\frac{q^{m+1}-1}{q-1}$. If $m<0$, we set $\pi_m(q)=0$.

\begin{conjecture}[Beelen-Datta-Ghorpade Conjecture]\label{Conj: complete GDC}\cite{beelen2022combinatorial}
Suppose $m,d,r$ are positive integers that satisfy $1 \leq r \leq \binom{m+d}{d}$. Pick the unique $1\leq l\leq m+1$, for which
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d}.$$
Let $j=r-\binom{m+d}{d}+\binom{m+d+1-l}{d}$, so $0< j\leq \binom{m+d-l}{d-1}$.
Then for $q\geq d+1$ we have
$$e_r(d,m;q)=H_j(d-1,m-l+1;q) +\pi_{m-l}(q).$$
\end{conjecture}
We denote this conjectured formula as
\[f_r(d,m;q)=H_j(d-1,m-l+1;q) +\pi_{m-l}(q).\]
For fixed $m$, $d$ and $r$, it is a polynomial in $q$.
We show that there is a simpler way of describing this polynomial.
\begin{proposition}\label{Prop: simple expression frdm}
Given positive integers $m,d,r$ that satisfy $1\leq r\leq \binom{m+d}{d}$. Suppose $w_r(d,m)=(\beta_1,\dots,\beta_{m+1})$. Let $l$ be the smallest index for which $\beta_l\neq 0$. Then we have
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d},$$
and
\[f_r(d,m;q)=H_r(d,m;q)+\pi_{m-l-1}(q).\]
\end{proposition}


We would like to note that certain special cases of Conjecture~\ref{Conj: complete GDC} have been proven.
\begin{enumerate}
    \item The case $r=1$ was shown by Serre in \cite{serre1991lettre} and S{\o}rensen in \cite{sorensen1991projective}.
    \item The case $r=2$ was proven by Boguslavsky in \cite{boguslavsky1997number}.
    \item The case $d=2$ was proven by Zanella in \cite{zanella1998linear}.
    \item The case $r\leq m+1$, the case $d=1$ and the case $m=1$ were proven by Datta and Ghorpade in \cite{datta2017number}.
    \item The case $r\leq \binom{m+2}{2}$ was proven by Beelen, Datta and Ghorpade in \cite{beelen2018maximum}.
    \item The case $\binom{m+d}{d}-d\leq r\leq \binom{m+d}{d}$ was proven by Datta and Ghorpade in \cite{datta2017remarks}. This range of $r$ corresponds to $l\in \{m,m+1\}$.
\end{enumerate}
All of these cases involved specific ranges of $r$ or special values of $m,d$, but allowed for any $q\geq d+1$.
In \cite{singhal2025conjecturebeelendattaghorpade}, we show that Conjecture~\ref{Conj: complete GDC} is true for any $m$, $d$ and $r$ when $q$ is sufficiently large.

\begin{theorem}\cite[Theorem 1.11]{singhal2025conjecturebeelendattaghorpade}
Suppose we are given positive integers $m,d,r$ such that $1 \leq r \leq \binom{m+d}{d}$. Pick the unique $1\leq l\leq m+1$ and $1\leq c\leq d$ for which
\[\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d}+\tbinom{m+d-l-c}{d-c-1} <r 
\leq \tbinom{m+d}{d}-\tbinom{m+d+1-l}{d}+\tbinom{m+d+1-l-c}{d-c}.\]
If
$$q\geq \max\Big\{2(m-l+1)c^2+1,\;8\frac{d^{l+1}}{c},\; 164 c^{14/3}\Big\},$$
then we have
$$e_r(d,m;q)= f_r(d,m;q).$$
\end{theorem}

\begin{theorem}\cite[Theorem 1.12]{singhal2025conjecturebeelendattaghorpade}\label{Thm l=1 with e}
Suppose $m\geq 2$, $d\geq 2$, $0\leq e\leq d-2$ and $\binom{m+e}{e}< r \leq \binom{m+e+1}{e+1}$.
If $q\geq \max\{d+e+\frac{e^2-1}{d-(e+1)}, d-1+e^2-e\}$, then we have
$$e_r(d,m;q)= f_r(d,m;q).$$
\end{theorem}


%\begin{corollary}\cite[Corollary 1.12.1]{singhal2023conjectureghorpadedattabeelen}
%Suppose we are given $m,d\geq 1$, $1\leq r\leq \binom{m+d-1}{d-1}$. Then for $q\geq (d-1)^2$, we have
%$$e_r(d,m;q)=f_r(d,m;q).$$    
%\end{corollary}

In summary, when $m=2$, Conjecture~\ref{Conj: complete GDC} holds in the following cases:
\begin{enumerate}
    \item $1\leq r\leq \binom{2+2}{2}=6$ and $q\geq d+1$;
    \item $\binom{d+1}{2}< r\leq \binom{d+2}{2}$ and $q\geq d+1$;
    \item For $2\leq e\leq d-2$ with
    \begin{align*}
    &\tbinom{e+2}{2}<r\leq \tbinom{e+3}{2},
    &
    q&\geq \max\{d+e+\frac{e^2-1}{d-(e+1)}, d-1+e^2-e\}.
    \end{align*}
\end{enumerate}

One of our main results is to show that when $m=2$, Conjecture~\ref{Conj: complete GDC} is true for any $q\geq d+1$.
\begin{theorem}\label{GDC for m=2}
Given positive integers $d,r$ such that $r\leq \binom{d+2}{2}$ and $q\geq d+1$. We have
\[e_r(d,2;q)=f_r(d,2;q).\]
\end{theorem}






Let $\kappa$ be an algebraically closed field.
Let $S_{d}(m,\kappa)$ be the $d^{th}$ graded component of $\kappa[x_0,\dots,x_m]$.
For $m\leq r\leq \binom{m+d}{d}$, denote
\[u_r(d,m)=\max\{|V(W)| : W\subseteq S_d(m,\kappa), \dim(W)=r,\dim(V(W))=0\}.\]
This definition is similar to $e_r(d,m;q)$, except for the requirement that $V(W)$ be of dimension zero. We need $r\geq m$, as otherwise the vanishing set of $r$ polynomials cannot be of dimension~$0$.
Also note that because $V(W)$ is zero-dimensional, we can directly take the cardinality of $V(W)$, without reference to a finite field $\fq$. In fact, we allow for $\kappa$ to be of characteristic $0$.

We will introduce some notations to state our conjecture for an exact formula of $u_r(d,m)$.
Let
\[\Omega'(d,m)=\Big\{(\alpha_1,\alpha_{2},\dots,\alpha_{m+1})\in \N_0^{m+1}\mid \sum_{i=1}^{m+1}\alpha_i=d, d\notin\{\alpha_2,\dots,\alpha_{m}\}  \Big\}.\]
So $\Omega'(d,m)$ is obtained from $\Omega(d,m)$ by dropping $m-1$ tuples that have $d$ at the $j^{th}$ spot and $0$ everywhere else for $2\leq j\leq m$. See Example\ref{Eg: lower bound} for the motivation behind why these tuples are dropped.
Hence $|\Omega'(d,m)|=\binom{m+d}{d}-(m-1)$. Order $\Omega'(d,m)$ by lexicographical ordering.
Let $\omega'_r(d,m)$ be its $r^{th}$ largest element. If $\omega'_r(d,m)=(\alpha_1,\dots,\alpha_{m+1})$, we define
\[H'_{r}(d,m)=\alpha_1 d^{m-1}+\dots+\alpha_m.\]
Note that $H'_r(d,m)$ does not refer to any $q$.
\begin{conjecture}\label{Conjecture urdm}
Given $d,m\geq 1$ and $m\leq r\leq \binom{d+m}{m}$, we have
\[u_r(d,m)=H_{r-(m-1)}'(d,m).\]
\end{conjecture}

We show that our conjectured formula is a lower bound $u_r(d,m)$.
\begin{proposition}\label{Prop: lower bound urdm}
For positive integers $m,d,r$ with $m\leq r\leq \binom{d+m}{m}$, we have
\[u_r(d,m)\geq H_{r-(m-1)}'(d,m).\]
\end{proposition}

Moreover, we prove the following special cases of Conjecture~\ref{Conjecture urdm}.

\begin{theorem}\label{thm: cases of urdm}
Given positive integers $d,m,r$ with $m\leq r\leq \binom{d+m}{m}$, if we have at least one of the following:
\begin{enumerate}
    \item $d=1$;
    \item $m=1$;
    \item $m=2$;
    \item $r=m$;
    \item $\binom{m+d}{d}-d\leq r\leq \binom{m+d}{d}$,
\end{enumerate}
then we have
\[u_r(d,m)=H_{r-(m-1)}'(d,m).\]
\end{theorem}


This paper is organized as follows. We introduce some preliminaries in Section~\ref{Sec: Prelim}. In Section~\ref{Sec: lower bound}, we show that our conjectured formula is a lower bound for $u_r(d,m)$, proving Proposition~\ref{Prop: lower bound urdm}.
In Section~\ref{Sec: special cases}, we prove all parts of Theorem~\ref{thm: cases of urdm} except $m=2$. In Section~\ref{Sec: m=2 urdm} we prove the $m=2$ part of Theorem~\ref{thm: cases of urdm}. In Section~\ref{Sec: m=2 erdm} we prove Theorem~\ref{GDC for m=2}.
The proofs of some technical lemmas are deferred to Appendix~\ref{Appendix}.













