\section{Preliminaries}\label{Sec: Prelim}

\subsection{Cayley-Bacharach Theorem}
Let $\kappa$ be an algebraically closed field.
\begin{definition}
Let $\Gamma$ be a zero-dimensional subscheme of $\Pt(\kappa)$. We denote its length as $|\Gamma|_{\mm}$ (the subscript $\mm$ indicates that the points are counted with multiplicity). We denote the number of points counted without multiplicity as $|\Gamma|$.
We denote the ideal of $\Gamma$ as $I(\Gamma)$. We denote the graded coordinate ring as $S(\Gamma)=\kappa[x_0,x_1,x_2]/I(\Gamma)$ and its $k^{th}$ homogeneous piece as $S_k(\Gamma)$.

Suppose that $\Gamma'\subseteq \Gamma$ are subschemes of $\Pt(\kappa)$. Then the residual subscheme of $\Gamma'$ in $\Gamma$ is the scheme whose ideal is
\[I(\Gamma'') = \Ann(I(\Gamma')/I(\Gamma)).\]
\end{definition}

Note that while we can define this in general, this notion is well behaved only when $\Gamma$ is a complete intersection.
For example, we have $|\Gamma|_{\mm}= |\Gamma'|_{\mm}+|\Gamma''|_{\mm}$ when $\Gamma$ is a complete intersection (see \cite{eisenbud1996cayley}).

\begin{example}
\begin{enumerate}
    \item Suppose $I(\Gamma)=(x^2,xy,y^2)$, so it is not a complete intersection. Take $I(\Gamma')=(x,y)$. Then, we have $I(\Gamma'')=(x,y)$. Note that $|\Gamma|_{\mm}=3$, $|\Gamma'|_{\mm}=1$ and $|\Gamma''|_{\mm}=1$, so $|\Gamma|_{\mm}\neq |\Gamma'|_{\mm}+|\Gamma''|_{\mm}$.
    \item Suppose $I(\Gamma)=(x^2,y^2)$, so it is a complete intersection. Take $I(\Gamma')=(x,y)$. Then, we have $I(\Gamma'')=(xy,x^2,y^2)$. Note that $|\Gamma|_{\mm}=4$, $|\Gamma'|_{\mm}=1$ and $|\Gamma''|_{\mm}=3$, so $|\Gamma|_{\mm}= |\Gamma'|_{\mm}+|\Gamma''|_{\mm}$.
\end{enumerate}
\end{example}

For a zero-dimensional subscheme $\Gamma$ of $\Pt(\kappa)$, and nonnegative integer $k$, we denote
\[g_{\Gamma}(k)=|\Gamma|_{\mm}-\dim(S_k(\Gamma)) =\dim(I_{k}(\Gamma))-\tbinom{m+k}{k}+|\Gamma|_{\mm}.\]
Note that $I_{k}(\Gamma)$ is the vector space of degree $k$ polynomials that vanish on $\Gamma$. Next, $\dim(S_k(\Gamma))$ is the Hilbert function, giving us the dimension of the $k^{th}$ homogeneous piece of the coordinate ring, and it can also be viewed as the number of independent conditions imposed by $\Gamma$ on degree $k$ polynomials. Finally, $g_{\Gamma}(k)$ is the failure of the points in $\Gamma$ to impose independent conditions on polynomials of degree $k$.


Noether computed the Hilbert function for the zero-dimensional subschemes of $\Pt$ that are obtained as the intersection of two curves.
\begin{proposition}\label{prop: intersection of two plane curves} \cite{noether1873ueber,eisenbud1996cayley}
Suppose $X_1$ and $X_2$ are curves of degrees $a$ and $b$ with no common components. Consider the zero-dimensional scheme $\Gamma=X_1\cap X_2$. Then for any $k$, the Hilbert function of the scheme $\Gamma$ can be written as
\[\dim(S_k(\Gamma))=\tbinom{k+2}{2}-\tbinom{k-a+2}{2}-\tbinom{k-b+2}{2}+ \tbinom{k-a-b+2}{2}.\]
\end{proposition}
\begin{corollary}\label{cor: g gamma curve a,b}
If we assume $1\leq a\leq b=k$, then we have
\[g_{\Gamma}(k)=\tbinom{a-1}{2}.\]
\end{corollary}


Cayley and Bacharach consider such a $\Gamma$, they further consider a subscheme $\Gamma'$ and its residual subscheme $\Gamma''$. Since $\Gamma$ is a complete intersection, we know that $ab=|\Gamma|_{\mm}=|\Gamma'|_{\mm}+|\Gamma''|_{\mm}$. Their result relates the dimension of the space of degree $k$ polynomials passing through $\Gamma'$ to the failure of $\Gamma''$ to impose independent conditions on polynomials of degree $a+b-3-k$.

\begin{theorem}\label{Thm: CB7}(Cayley-Bacharach)
Let $X_1, X_2 \subset \Pt$ be plane curves of degrees $a$, $b$, respectively, such that $\Gamma=X_1 \cap X_2$ is zero-dimensional.  Let $\Gamma'$ and $\Gamma''$ be subschemes of $\Gamma$ residual to each other in $\Gamma$. % That is, $\Gamma' \cup \Gamma''=\Gamma$ set theoratically, and $I_{\Gamma''}= \Ann(I_{\Gamma'}/I_\Gamma)$.
Set $s = a+b-3$. Then, we have
%the dimension of the vector space of forms of degree $k$ vanishing on $\Gamma'$ (modulo those containing all of $\Gamma$) is equal to the failure of $\Gamma''$ to impose independent conditions on forms of degree $s-k$. In other words,
\begin{equation}\label{Eq: CB5}
\dim(I_k(\Gamma')-\dim(I_k(\Gamma))
= g_{\Gamma''}(s-k).
\end{equation}
\end{theorem}


