\subsection{Relationships between conjectured polynomials}

In this subsection we consider the relationship between $H'_{r-(m-1)}(d,m)$ and polynomials $f_r(d,m;q)$ and $H_r(d,m;q)$. In particular, in we will prove Proposition~\ref{Prop: simple expression frdm}. We will also show that $H'_{r-(m-1)}(d,m)\leq H_r(d,m;d+1)$, but the proof is deferred to Appendix~\ref{Appendix}.


Given $1\leq r\leq \binom{m+d}{d}$, Conjecture~\ref{Conj: complete GDC} picks the unique $1\leq l\leq m+1$ for which
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d}.$$
In \cite[Proposition 4]{singhal2025conjecturebeelendattaghorpade}, the authors show that this $l$ has the property that for any $W\subseteq S_d(m)$ with $\dim(W)=r$, we have $\dim(V(W))\leq m-l$.
We will show that another way of picking the same $l$ is by looking at $w_r(d,m)=(\beta_1,\dots,\beta_{m+1})$ and finding the index of the first nonzero term. In order to show this we recall the relation between $r$ and the tuple $w_r(d,m)$.









\begin{lemma}\label{r as function of alpha}\cite[Lemma 32]{singhal2025conjecturebeelendattaghorpade}
If $w_r(d,m)=(\beta_1, \dots, \beta_{m+1})$, then
\begin{align*}
    r&=1+\sum_{k=1}^m \tbinom{m-k+d-\sum_{j=1}^k \beta_j}{m-k+1}.
\end{align*}
\end{lemma}

\begin{corollary}\label{Cor: index of d,000}
For $1\leq l\leq m+1$, take $r=\binom{m+d}{d}-\binom{m+d-l+1}{d}+1$, then we have $w_r(d,m)=(0,\dots,0,d,0,\dots,0)$, the $d$ is in the $l^{th}$ index.
\end{corollary}
\begin{proof}
Pick the $r'$ for which $w_{r'}(d,m)=(0,\dots,0,d,0,\dots,0)$ where $d$ is in the $l^{th}$ index. Then by Lemma~\ref{r as function of alpha} we have
\begin{align*}
r'&=1+\tbinom{m-1+d}{m}+\dots +\tbinom{m-(l-1)+d}{m-l+2}+ \tbinom{m-l+d-d}{m-l+1}+\dots +\tbinom{m-m+d-d}{m-m+1}\\
&=1+\tbinom{m-1+d}{d-1}+\dots +\tbinom{m-(l-1)+d}{d-1}\\
&=1+\tbinom{m+d}{d}-\tbinom{m-l+1+d}{d}=r. \qedhere
\end{align*}
\end{proof}


\begin{lemma}\label{Lem: first non-zero index}
Suppose $w_{s}(d,m)=(\alpha_1,\dots,\alpha_{m+1})$. Let $l$ be the smallest index for which $\alpha_l\neq 0$. Then we have
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <s \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d}.$$
\end{lemma}
\begin{proof}
Since $l$ be the smallest index for which $\alpha_l\neq 0$, we know that $w_{s}(d,m)$ is $\leq_{lex}$ to the tuple with $d$ on $l^{th}$ index and zero elsewhere. Also $w_{s}(d,m)$ is $>_{lex}$ to the tuple with $d$ on $(l+1)^{th}$ index and zero elsewhere. The result follows from Corollary~\ref{Cor: index of d,000}.
\end{proof}

\begin{corollary}\label{Cor: l,c}
Suppose $w_{s}(d,m)=(\alpha_1,\dots,\alpha_{m+1})$. Let $l$ be the smallest index for which $\alpha_l\neq 0$ and denote $\alpha_l=c$. Then we have
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d}+\tbinom{m+d-l-c}{d-c-1} <s \leq \tbinom{m+d}{d}-\tbinom{m+d+1-l}{d}+\tbinom{m+d-l-c+1}{d-c}.$$
\end{corollary}
\begin{proof}
Follows similarly from Lemma~\ref{r as function of alpha}.
\end{proof}

Now, we can prove Proposition~\ref{Prop: simple expression frdm}, which gives a simpler expression for $f_r(d,m;q)$.

\begin{customprop}{\ref{Prop: simple expression frdm}}
Given $1\leq r\leq \binom{m+d}{d}$, suppose $w_r(d,m)=(\beta_1,\dots,\beta_{m+1})$. Let $l$ be the smallest index for which $\beta_l\neq 0$. Then we have
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d},$$
and
\[f_r(d,m;q)=H_r(d,m;q)+\pi_{m-l-1}(q).\]
\end{customprop}
\begin{proof}
By Lemma~\ref{Lem: first non-zero index}, we know that $\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d}$.
Let $j=r-\binom{m+d}{d}+\binom{m+d+1-l}{d}$. By definition, we have
$$f_r(d,m;q)=H_j(d-1,m-l+1;q) +\pi_{m-l}(q).$$
Now consider the following injective map
\[\phi:\Omega(d-1,m-l+1)\to \Omega(d,m),\]
\[\phi(\gamma_1,\dots,\gamma_{m-l+2})=(0,\dots,0,1+\gamma_1,\gamma_2,\dots,\gamma_{m-l+2}).\]
There are $l-1$ zeros on the left, so the map actually lands in $\Omega(d,m)$. Corollary~\ref{Cor: index of d,000} implies that
\[\phi(w_{a}(d-1,m-l+1))=w_{\binom{m+d}{d}-\binom{m+d-l+1}{d}+a} (d,m).\]
In particular, this means $\phi(w_j(d-1,m-l+1))=w_{r}(d,m)$. Thus,
\[H_r(d,m;q)=H_{j}(d-1,m-l+1;q) +q^{m-l}.\]
We conclude that
\begin{align*}
f_r(d,m;q)
&=H_j(d-1,m-l+1;q) +\pi_{m-l}(q)\\
&=H_r(d,m;q) -q^{m-l}+\pi_{m-l}(q)\\
&=H_r(d,m;q) +\pi_{m-l-1}(q).\qedhere
\end{align*}
\end{proof}

Next, we want to show that $H'_{r-(m-1)}(d,m)\leq H_r(d,m;d+1)$. We start by understanding the relation between the tuples $w_r(d,m)$ and $w'_{r-(m-1)(d,m)}$.


\begin{lemma}\label{Lem: w and w'}
Consider some $m\leq r< \binom{m+d}{d}$. Denote $w'_{r-(m-1)}(d,m)=(\alpha_1,\dots,\alpha_{m+1})$.
Pick the $s$ for which $(\alpha_1,\dots,\alpha_{m+1})=w_{s}(d,m)$. Let $l$ be the smallest index for which $\alpha_l\neq 0$.
Then we have $s=r-(m-l)$. If $r=\binom{m+d}{d}$, then we have $s=r$.
\end{lemma}
\begin{proof}
Note that
\[s=\#\{u\in \Omega(d,m): u\geq_{lex} (\alpha_1,\dots,\alpha_{m+1})\},\]
\[r-(m-1)=\#\{u\in \Omega'(d,m): u\geq_{lex} (\alpha_1,\dots,\alpha_{m+1})\}.\]
Therefore,
\[s-r+(m-1)=\#\{u\in \Omega(d,m)\setminus \Omega'(d,m): u\geq_{lex} (\alpha_1,\dots,\alpha_{m+1})\}.\]
The tuples in this set are precisely $(0,\dots,0,d,0,\dots,0)$ with $d$ in the $t^{th}$ index for $2\leq t\leq \min(l,m)$. Since $r\neq \binom{m+d}{d}$, we have $l\leq m$, and therefore the set has size $l-1$. This means that $s-r+(m-1)=l-1$, that is, $s=r-(m-l)$.

If $r=\binom{m+d}{d}$, then $l=m+1$. In this case $\min(l,m)=m$, so the set has size $m-1$. This means  $s-r+(m-1)=m-1$, that is, $s=r$.
\end{proof}


\begin{proposition}\label{Prop: H' smaller than H}
Given $m\leq r\leq \binom{m+d}{d}$, for every $q\geq d+1$, we have
\[H'_{r-(m-1)}(d,m)\leq H_r(d,m;q).\]
\end{proposition}
\begin{proof}
See the end of Appendix~\ref{Appendix}.
\end{proof}







