\subsection{Explicit polynomials when $m=2$}




In Conjecture~\ref{Conjecture urdm}, for $m=2$, $r$ is in the range $2\leq r\leq \binom{d+2}{2}$. This range can be subdivided as 
\[\left[2,\tbinom{d+2}{2}\right]
=\bigcup_{t=3}^{d}\left(1+\tbinom{d-t+1}{2}, 1+\tbinom{d-t+2}{2}\right] 
\bigcup (1+\tbinom{d-1}{2},\tbinom{d+2}{2}].\]

\begin{lemma}\label{Lem: formula for H' m=2}
We have
\begin{equation*}
H'_{r-1}(d,2)=\begin{cases}
    td+\binom{d-t+2}{2}-r+1 &\text{ if } \binom{d-t+1}{2}<r-1\leq \binom{d-t+2}{2}, 1\leq t\leq d\\
    \binom{d+2}{2}-r &\text{ if } \binom{d-1}{2}<r-1\leq \binom{d+2}{2}-1.
\end{cases}
\end{equation*}    
\end{lemma}
Note that, if $t\in \{1,2\}$ and $ \binom{d-t+1}{2}<r-1\leq \binom{d-t+2}{2}$, then both formulae are valid
\[H'_{r-1}(d,2) =td+\tbinom{d-t+2}{2}-r+1=\tbinom{d+2}{2}-r.\]

\begin{proof}
By Lemma~\ref{Lem: w and w'}, we see that for $1\leq r-1\leq \binom{d+2}{2}-1$, we have
\begin{equation*}
H'_{r-1}(d,2)=\begin{cases}
    H_{r-1}(d,2;d) &\text{ if } 1\leq r-1\leq \binom{d+1}{2}\\
    H_{r}(d,2;d) &\text{ if } \binom{d+1}{2}<r-1\leq \binom{d+2}{2}-1.
\end{cases}
\end{equation*}
Now consider some $0\leq t\leq d$ and $\binom{d-t+1}{2}<r-1\leq \binom{d-t+2}{2}$. Let $a_1=t$ and $a_2=\binom{d-t+2}{2}-r+1$, so $0\leq a_1,a_2$ and
\[a_1+a_2=t+\tbinom{d-t+2}{2}-(r-1)\leq t+\tbinom{d-t+2}{2}- (\tbinom{d-t+1}{2}+1)=d.\]
Thus $a_3=d-a_1-a_2\geq 0$. This means that $(a_1,a_2,a_3)\in\Omega(d,2)$ and $(a_1,a_2,a_3)=\omega_s(d,2)$ for some $s$. By Lemma~\ref{r as function of alpha}, we have
\[s=1+\tbinom{1+d-a_1}{2}+\tbinom{d-a_1-a_2}{1}
=1+\tbinom{1+d-t}{2}+(d-t-\tbinom{d-t+2}{2}+r-1) =r-1.\]

Now if $t\geq 1$, then $r-1\leq \binom{d-t+2}{2}\leq \binom{d+1}{2}$, so
\[H'_{r-1}(d,2)=H_{r-1}(d,2;d)= a_1d+a_2= td+\tbinom{d-t+2}{2}-r+1.\]
Note that if $t=1$, then this simplifies as
\[H'_{r-1}(d,2)= d+\tbinom{d+1}{2}-r+1 =\tbinom{d+2}{2}-r.\]
Similarly, if $t=2$, then this simplifies as
\[H'_{r-1}(d,2)= 2d+\tbinom{d}{2}-r+1 =\tbinom{d+2}{2}-r.\]

Finally if $t=0$, then $r-1>\binom{d-t+1}{2}=\binom{d+1}{2}$, so $H'_{r-1}(d,2)=H_{r}(d,2;d)$.
Moreover,
\[w_{r-1}(d,2)=(t,\tbinom{d-t+2}{2}-r+1,d-t-\tbinom{d-t+2}{2}+r-1)=(0,\tbinom{d+2}{2}-r+1,d-\tbinom{d+2}{2}+r-1),\]
so
\[w_{r}(d,2)=(0,\tbinom{d+2}{2}-r,d-\tbinom{d+2}{2}+r).\]
We conclude that
\[H'_{r-1}(d,2)=H_{r}(d,2;d)= \tbinom{d+2}{2}-r. \qedhere\]
\end{proof}














\section{Lower bound}\label{Sec: lower bound}

In this section, we will prove Proposition~\ref{Prop: lower bound urdm}, which shows that our conjectured formula for $u_r(d,m)$ is at least a lower bound. We will do this by explicitly constructing $r$ linearly independent polynomials whose vanishing set has size at least $H'_{r-(m-1)}(d,m)$.

We give an example of our construction before getting to the general proof.
\begin{example}\label{Eg: lower bound}
Suppose $m=3$ and $w'_{r-2}(d,m)=(\alpha_1,\alpha_2,\alpha_3,\alpha_4)$.
Pick distinct $a_1,\dots,a_d\in\kappa$.
Then we take
\begin{align*}
Y_1&=\{a_1,\dots,a_{\alpha_1}\}\times \{a_1,\dots,a_{d}\} \times \{a_1,\dots,a_{d}\},\\
Y_2&= \{a_d\}\times\{a_1,\dots,a_{\alpha_2}\}\times \{a_1,\dots,a_{d}\},\\
Y_3&= \{a_d\}\times \{a_d\}\times \{a_1,\dots,a_{\alpha_3}\}\},
\end{align*}
and $Y=Y_1\cup Y_2\cup Y_3$. It is clear that $|Y|=H'_{r-2}(d,m)$. We will show that there are $r$ linearly independent polynomials of degree $d$ that vanish on $Y$ and their vanishing set has dimension $0$. This will establish the lower bound.

Moreover, this construction motivates the construction of $\Omega'(d,3)$, which leaves out the tuples $(0,d,0,0)$ and $(0,0,d,0)$. Note that the tuple $(0,d,0,0)$ would lead to the same $Y$ (up to relabeling) as the tuple $(1,0,0,d-1)$. Similarly, the tuple $(0,0,d,0)$ would lead to the same $Y$ as the tuple $(0,1,0,d-1)$.
\end{example}

We now prove Proposition~\ref{Prop: lower bound urdm}. We introduce a notation that if $R$ is a ring of polynomials in some variables, then $R_d$ will be the subspace of homogeneous degree $d$ polynomials.

\begin{customprop}{\ref{Prop: lower bound urdm}}
For $m\leq r\leq \binom{m+d}{d}$, we have
\[u_r(d,m)\geq H_{r-(m-1)}'(d,m).\]
\end{customprop}
\begin{proof}
First consider the case $r=\binom{m+d}{d}$. Then $H_{r-(m-1)}'(d,m)=0$ so the result is trivially true. Now suppose $m\leq r< \binom{m+d}{d}$.

Pick distinct $a_1,\dots,a_d\in \kappa$, with $a_d=0$. Suppose $w'_{r-(m-1)}(d,m)=(\alpha_1,\dots,\alpha_{m+1})$. Let $l$ be the smallest index for which $\alpha_l\neq 0$. Let $s=r-(m-l)$. So Lemma~\ref{Lem: w and w'} tells us that $(\alpha_1,\dots,\alpha_{m+1})=w_s(d,m)$. For $1\leq i\leq m$ denote
\begin{align*}
F_i&=\prod_{j=1}^{d}(x_i-a_jx_0),
&
\text{and}
&
&g_i=\prod_{j=1}^{\alpha_i}(x_i-a_jx_0).
\end{align*}
If $\alpha_i=0$, then $g_i=1$.

Next, consider the case $r=m$, so $(\alpha_1,\dots,\alpha_{m+1})=(d,0,\dots,0)$ and $l=1$. Then $F_1,\dots,F_m$ are linearly independent, $\dim(V(F_1,\dots,F_m))=0$ and
$$|V(F_1,\dots,F_m)|=d^m=H'_1(d,m).$$
This shows that $u_{m}(d,m)\geq H_{m-(m-1)}'(d,m)$.

For the rest of the proof, suppose $m<r<\binom{m+d}{d}$. This means $\alpha_1\neq d$ and hence $d\notin \{\alpha_1,\dots,\alpha_{m}\}$. Thus, $x_i|F_i$ and $x_i\nmid g_i$.
For $l\leq i\leq m$, denote
\begin{align*}
Y_i&=V(x_1,\dots,x_{i-1}, g_i,F_{i+1},\dots, F_{m}),
&
\text{and}
&
&Y=\bigcup_{i=l}^{m}Y_i.
\end{align*}
Notice that $|Y_i|=\alpha_i d^{m-i}$ and $|Y|=\sum_{i=l}^{m}\alpha_i d^{m-i}=H'_{r-(m-1)}(d,m)$.
%Also note that $\dim (Y_i)=0$ and hence $\dim(Y)=0$.
Next, for $1\leq i\leq m-1$, denote
\[W_i=g_l g_{l+1}\dots g_{i}x_i \kappa[x_0,x_i,\dots,x_{m}]_{d-1-\alpha_l-\dots-\alpha_{i}}.\]
Notice that if $i<l$, then this simplifies to $W_i=x_i \kappa[x_0,x_i,\dots,x_{m}]_{d-1}$.
Also denote
\[W_m=g_l\dots g_{m} \kappa[x_0,x_{m}]_{d-\alpha_l-\dots-\alpha_{m}}.\]
Let $W=W_1+\dots+W_m+\langle F_{l+1},\dots,F_{m}\rangle$. It is clear that $Y\subseteq V(W)$, so
\[|V(W)|\geq |Y|=H'_{r-(m-1)}(d,m).\]
Moreover, $V(W)\subseteq V(F_1,\dots,F_m)$, so $\dim(V(W))=0$.
We want to compute $\dim(W)$, for this we want to show that the sum used to define $W$ is a direct sum.

Suppose for $1\leq i\leq m-1$, we have $h_i\in \kappa[x_0,x_i,\dots,x_{m}]_{d-1-\alpha_1-\dots-\alpha_i}$ and $h_m\in \kappa[x_0,x_m]_{d-\alpha_1-\dots-\alpha_m}$ and $u_{l+1},\dots,u_m\in \kappa$ such that
\[\sum_{i=1}^{l}\Big( x_i\prod_{j=1}^{i}g_j\Big)h_i+
\sum_{i=l+1}^{m-1}\Big(\Big( x_i\prod_{j=1}^{i}g_j\Big)h_i +u_{i}F_i\Big) +\Big(\prod_{j=1}^{m}g_j\Big)h_m +u_{m}F_m=0.\]
We will show that all $h_i$ and $u_i$ are zero, which will show that it is a direct sum.
Assume for the sake of contradiction that some $h_i$ or $u_i$ is non-zero. Consider the smallest such index, denote it as $i_0$.
\begin{enumerate}
    \item Case 1: $1\leq i_0\leq l$. We know that
    \[\sum_{i=i_0}^{l}\Big( x_i\prod_{j=1}^{i}g_j\Big)h_i+
\sum_{i=l+1}^{m-1}\Big(\Big( x_i\prod_{j=1}^{i}g_j\Big)h_i +u_{i}F_i\Big) +\Big(\prod_{j=1}^{m}g_j\Big)h_m +u_{m}F_m=0.\]
Note that for $i>i_0$, the terms do not involve $x_{i_0}$. Therefore if we plug in $x_{i_0}=0$ and subtract the resulting equation from the equation above, it implies that $( x_{i_0}\prod_{j=1}^{i_0}g_j)h_{i_0} =0$. This means $h_{i_0}=0$ which is a contradiction.

\item Case $2$: $l+1\leq i_0\leq m-1$. We know that
    \[
\sum_{i=i_0}^{m-1}\Big(\Big( x_i\prod_{j=1}^{i}g_j\Big)h_i +u_{i}F_i\Big) +\Big(\prod_{j=1}^{m}g_j\Big)h_m +u_{m}F_m=0.\]
Again note that for $i>i_0$, the terms do not involve $x_{i_0}$. Therefore if we plug in $x_{i_0}=0$ and subtract the resulting equation from the equation above, it implies that $( x_i\prod_{j=1}^{i_0}g_j)h_{i_0} +u_{i_0}F_{i_0} =0$.
Since at least one of $h_{i_0}$ or $u_{i_0}$ is nonzero, it follows that they both must be nonzero.
Now $\alpha_l>0$ and $i_0>l$ imply that
\begin{align*}
&(x_l-a_1 x_0)\mid g_l,
&
&g_l\mid \prod_{j=1}^{i_0} g_j,
&
&\prod_{j=1}^{i_0} g_j \mid F_{i_0}.
\end{align*}
This means $(x_l-a_1 x_0)\mid F_{i_0}$. Since $i_0>l$, this contradicts the definition of $F_{i_0}$.

\item Case 3: $i_0>l$ and $i_0=m$. We know that
    \[ \Big(\prod_{j=1}^{m}g_j\Big)h_m +u_{m}F_m=0.\]
    Since at least one of $h_{m}$ and $u_{m}$ is nonzero, it follows that they both must be nonzero. Arguing as in Case 2, we see that $(x_l-a_1 x_0)\mid F_{m}$. Since $m>l$, this contradicts the definition of $F_{m}$.
\end{enumerate}
It follows that
\[W=W_1\oplus\dots\oplus W_m\oplus\langle F_{l+1},\dots,F_{m}\rangle.\]
Note that for $1\leq i\leq m-1$, $\dim(W_i)=\binom{m-(i-1)+d-1-\sum_{j=1}^{i}\alpha_j}{m-(i-1)}$ and $\dim(W_m)=\binom{1+d-\sum_{j=1}^{m}\alpha_j}{1}$.
Therefore, by Lemma~\ref{r as function of alpha}, we have
\begin{align*}
\dim(W)
&=(m-l)+\sum_{i=1}^{m-1} \tbinom{m-(i-1)+d-1-\sum_{j=1}^{i}\alpha_j}{m-(i-1)} +\tbinom{1+d-\sum_{j=1}^{m}\alpha_j}{1}\\
&=1+(m-l)+\sum_{i=1}^{m} \tbinom{m-i+d-\sum_{j=1}^{i}\alpha_j}{m-(i-1)}
=(m-l)+s
=r.
\end{align*}
We have shown that $\dim(W)=r$, $\dim(V(W))=0$ and $|V(W)|\geq H'_{r-(m-1)}(d,m)$. It follows that $u_r(d,m)\geq H'_{r-(m-1)}(d,m)$.
\end{proof}




