\begin{align*}
r\leq &\dim(I_{d}(X)) \leq \dim(I_d(X_1))
=\tbinom{d+2}{2} -|X_1|_{\mm} +g_{X_1}(d)\\
&\leq \tbinom{d+2}{2} -\big(td+2+\tbinom{d-t+2}{2}-r\big) +\tbinom{t-1}{2}\\
&=r-1.
\end{align*}
This is a contradiction.
\end{proof}

We will now prove by induction on $d$ that if $|X|_{\mm}\leq td+d-t+1$, then $g_X(d)\leq \binom{t-1}{2}$. By the induction hypothesis, we know that this holds for $d'<d$. Hence, by Lemma~\ref{Lem: cond on gx implies udr} and Proposition~\ref{Prop: udr Case 2}, we know that $u_{r'}(d',2)\leq H'_{r'-1}(d',2)$.



\begin{proposition}\label{Prop: cond on gx udr}
Consider positive integers $t$, $d$ satisfying $3\leq t\leq d$.
Given coprime polynomials $G_1$, $G_2$ in $S_d(2,\kappa)$ and a subscheme $X\subseteq V(G_1,G_2)$, with $|X|_{\mm}\leq td+d-t+1$, we have
\[g_X(d)\leq \tbinom{t-1}{2}.\]
\end{proposition}
\begin{proof}
We prove this by induction on $d$, assume that the statement is known for smaller values of $d$. % The existence of such $t$ implies that $d\geq 3$.
Let $\Gamma=V(G_1,G_2)$. First, if $t=d$, then it follows from Corollary~\ref{cor: g gamma curve a,b} that
\[g_{X}(d)\leq g_{\Gamma}(d)=\tbinom{d-1}{2}.\]
Now suppose $3\leq t\leq d-1$, so $d\geq 4$.
Let $X'$ be the residual subscheme of $X$ in $\Gamma$. So
\[|X'|_{\mm}=d^2-|X|_{\mm}\geq d^2-dt -d+t-1.\]
Pick $Y\subseteq X'$ such that $|Y|_{\mm}= d^2-dt-d+t-1$.
Corollary~\ref{Cor: g gamma' OP2 gamma''} implies that $g_{X}(d)=\dim(I_{d-3}(X'))$. This means $g_{X}(d)\leq \dim(I_{d-3}(Y))$.
%If $d=3$, then $t=3$ and $g_{\Gamma}(3)=1$, hence $g_X(d)\leq 1=\binom{3-1}{2}$. Now assume $d\geq 4$.

Assume for the sake of contradiction that $g_{X}(d)\geq \tbinom{t-1}{2}+1$.
This implies
\[\dim(I_{d-3}(Y))\geq \tbinom{t-1}{2}+1.\]
From here we want to bound $|Y|_{\mm}$ and derive a contradiction.
Denote
\begin{align*}
r_1&=\dim(I_{d-3}(Y)),
&
g&=\gcd(I_{d-3}(Y)),
&
e&=\deg(g).
\end{align*}
It is possible that $e=0$ if $g=1$. Say $I_{d-3}(Y)=gW$, so
\[\dim(W)=\dim(I_{d-3}(Y))=r_1\geq \tbinom{t-1}{2}+1.\]
Let $d_1=d-3-e$, so the polynomials in $W$ are of degree $d_1$.

Now $I_{d-3}(Y)=gW$, so $Y\subseteq V(g)\cup V(W)$, and hence
\[Y\subseteq \big(V(g)\cap \Gamma \big)\cup V(W).\]
We will bound $|Y|_{\mm}$ by bounding $|V(g)\cap \Gamma|_{\mm}$ and $|V(W)|_{\mm}$ separately.
Notice that
\[d(d-t)-d+t-1 = |Y|_{\mm} \leq |V(g)\cap \Gamma|_{\mm} + |V(W)|_{\mm}\leq |V(g)\cap \Gamma|_{\mm} +u_{r_1}(d_1,2).\]

We first bound $|V(g)\cap \Gamma|_{\mm}$.
Suppose, $g$ factors as $g=g_1\dots g_u$. Then for each $g_i$, it does not divide at least one of $G_1$ or $G_2$ (since $\gcd(G_1,G_2)=1$). Thus, $|V(g_i)\cap V(G_1,G_2)|_{\mm}\leq \deg(g_i)d$. It follows that $|V(g)\cap \Gamma|_{\mm}\leq ed$.

Next, we will bound $u_{r_1}(d_1,2)$. We will use the induction hypothesis as $d_1<d$.
Note that
\[1+\tbinom{t-1}{2}\leq r_1=\dim(I_{d-3}(Y)) =\dim(W)\leq \dim(\kappa[x_0,x_1,x_2]_{d-3-e}).\]
This implies $1+\tbinom{t-1}{2}\leq \binom{d-1-e}{2}$ and hence $e<d-t$.
Next,
\[|V(W)|_{\mm}\leq u_{r_1}(d_1,2)\leq u_{\binom{t-1}{2}+1}(d_1,2).\]
Let $t_1=d_1-t+3=d-e-t$, so $t-1= d_1-t_1+2$ and
\[1+\tbinom{d_1-t_1+1}{2}< \tbinom{t-1}{2}+1 =\tbinom{d_1-t_1+2}{2}+1.\]
The condition $e<d-t$ means $t_1>0$.


\begin{enumerate}
    \item Case 1: $e\leq d-t-3$. This means $t_1\geq 3$.
    We know that $d_1<d$, so the statement is known for $d_1$ by the induction hypothesis. Then Lemma \ref{Lem: cond on gx implies udr} says that
    \[u_{\binom{t-1}{2}+1}(d_1,2) \leq t_1 d_1+1+\tbinom{d_1-t_1+2}{2} -(\tbinom{t-1}{2}+1)=t_1d_1.\]

    \item Case 2: $d-t-2 \leq e\leq d-t-1$, so $1\leq t_1\leq 2$. Then Proposition~\ref{Prop: udr Case 2} implies that
    \[u_{\binom{t-1}{2}+1}(d_1,2)=\tbinom{d_1+2}{2}-\tbinom{t-1}{2}-1 = \tbinom{d_1+2}{2}-\tbinom{d_1-t_1+2}{2}-1.\]
    Since $t_1\in\{1,2\}$, this simplifies to $t_1d_1$.
\end{enumerate}
Therefore in both cases we have 
\[u_{\binom{t-1}{2}+1}(d_1,2)\leq t_1d_1.\]
We see that
\begin{align*}
d^2-dt-d+t-1 &= |Y|_{\mm} \leq ed+ |V(W)|_{\mm}\\
&\leq ed+ (d-e-t) (d-e-3)\\
&= e^2 -(d-t-3)e +(d-t)(d-3).
\end{align*}
Since $0\leq e\leq  d-t-1$, by the shape of the parabola, we see that 
\[e^2 -(d-t-3)e\leq 2(d-t-1).\]
and hence
\[d^2-dt-d+t-1\leq 2(d-t-1) +(d-t)(d-3).\]
This simplifies to 
\[d^2-dt-d+t-1\leq d^2-dt-d+t-2.\]
which is a contradiction.
\end{proof}

\begin{theorem}\label{Thm: urd2}
Given $d\geq 1$ and $2\leq r\leq \binom{d+2}{2}$, we have
\[u_r(d,2)=H_{r-1}'(d,2).\]
\end{theorem}
\begin{proof}
This follows from Proposition~\ref{Prop: udr Case 2}, Proposition~\ref{Prop: lower bound urdm}, Lemma~\ref{Lem: formula for H' m=2}, Lemma~\ref{Lem: cond on gx implies udr} and Proposition~\ref{Prop: cond on gx udr}.
\end{proof}

This completes the proof of Theorem~\ref{thm: cases of urdm}.


\section{Computing $e_r(d,2;q)$}\label{Sec: m=2 erdm}







In this section, our goal is to prove Theorem~\ref{GDC for m=2}. First we recall a result of Beelen, Datta, and Ghorpade \cite{beelen2022combinatorial} which states that their conjectured formula $f_r(d,m;q)$ is at least a lower bound for $e_r(d,m;q)$.
\begin{proposition}\cite[Theorem 2.3]{beelen2022combinatorial}\label{Lower bound for erdm}\\
Suppose we are given $1 \leq r \leq \binom{m+d}{d}$ and $q\geq d+1$. Say
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d},$$
and $j=r-\binom{m+d}{d}+\binom{m+d+1-l}{d}$. Then we have
$$e_r(d,m;q)\geq f_r(d,m;q).$$
\end{proposition}

Therefore, we only need to prove that $e_r(d,2;q)\leq f_r(d,2;q)$. This means given a subspace $W$ of $S_d(2,\fq)$ of dimension $r$, we want to show that $|V(W)(\fq)|\leq f_r(d,2;q)$.
We decompose $V(W)$ into $X_1$, $X_0$, where $X_1$ has all the one-dimensional components of $V(W)$ and $X_0$ has the zero-dimensional components. Then $X_1=V(g)$ where $g=\gcd(W)$, so
\[|X_1(\fq)|\leq e_1(\deg(g),2)=f_1(\deg(g),2).\]
Moreover, we can bound $|X_0|$ using Theorem~\ref{Thm: urd2}. We recall a lemma from \cite{singhal2025conjecturebeelendattaghorpade}, which allows us to combine the two bounds.


\begin{lemma}\cite[Lemma 6.8]{singhal2025conjecturebeelendattaghorpade}\label{Lem d-c to d}
Given $m\geq 1$, $1\leq c\leq d-1$ and $1\leq r\leq \binom{m+d-c}{d-c}$, we have
$$H_r(d-c,m;q)+cq^{m-1}\leq H_r(d,m;q).$$
\end{lemma}

We are now ready to prove Theorem~\ref{GDC for m=2}.


\begin{customthm}{\ref{GDC for m=2}}
For $d\geq 1$, $1\leq r\leq \binom{d+2}{2}$ and $q\geq d+1$, we have
\[e_r(d,2;q)=f_r(d,2;q).\]
\end{customthm}
\begin{proof}
By Proposition \ref{Lower bound for erdm}, it is already known that $e_r(d,2;q)\geq f_r(d,2;q)$. Now consider $W\subseteq S_d(m)$ of dimension $r$. Say $\gcd(W)=g$ and $W=gW_1$.
\begin{enumerate}
    \item Case 1: $\deg(g)=0$, that is, $\gcd(W)=1$. Then it follows from Theorem~\ref{Thm: urd2}, Proposition~\ref{Prop: simple expression frdm} and Proposition~\ref{Prop: H' smaller than H} that
    \[|V(W)|_{\mm}\leq H'_{r-1}(d,2)\leq H_{r}(d,2;q)\leq f_r(d,2;q).\]
    \item Case 2: $\deg(g)\geq 1$. Say $e=\deg(g)$. We still have $\gcd(W_1)=1$, so Theorem~\ref{Thm: urd2} and Proposition~\ref{Prop: H' smaller than H} imply that
    \[|V(W_1)|_{\mm}\leq H'_{r-1}(d-e,2)\leq H_r(d-e,2;q).\]
    Moreover, $|V(g)(\fq)|\leq e_1(e,2)=eq+1$.
    Since $\dim(W_1)=r$ and $W_1\subseteq \fq[x_0,x_2,x_2]_{d-e}$, we know that $r\leq \binom{d-e+2}{2}$.
    Also note that $r\leq \binom{d-1+2}{2}$, so $l=1$.
    Thus, Lemma \ref{Lem d-c to d} implies that
    \begin{align*}
    |V(W)(\fq)|
    &\leq |V(W_1)|+|V(g)(\fq)|
    \leq H_r(d-e,2;q) +eq +1\\
    &\leq H_r(d,2;q)+1
    =H_r(d,2;q)+\pi_{m-l}(q)
    =f_r(d,2;q). \qedhere
    \end{align*}
\end{enumerate}
\end{proof}


