\section{Conjecture of Bogulavsky}

We start by recalling a conjecture of Bogulavsky regarding the degrees in different dimensions of $V(W)$.

\begin{conjecture}\cite[Conjecture 2]{boguslavsky1997number}\label{Conj: Bogulavsky}
Suppose we have $m,d\geq 1$ and $1\leq r\leq \tbinom{m+d}{d}$. Denote $w_r(d,m)=(\beta_1,\dots,\beta_{m+1})$. Then given a subspace $W$ of $S_d(m,\fq)$, we have
\[\Big(\deg_{m-1}(V(W)),\dots,\deg_0(V(W)),d-\sum_{i=0}^{m-1} \deg_i(V(W))\Big) \leq_{\text{lex}} (\beta_1,\dots,\beta_{m+1}). \]
Moreover, equality holds for some $W$.
\end{conjecture}


Note that we consider the first nonzero index of $w_r(d,m)$, that is, $l=\min\{i: \beta_i\neq 0\}$, then Conjecture~\ref{Conj: Bogulavsky} says that $\dim(V(W))\leq m-l$. By Lemma~\ref{Lem: first non-zero index}, this $l$ is determined by the range of $r$
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d} <r \leq \tbinom{m+d}{d}-\tbinom{m+d-l}{d}.$$
Thus, this part of Conjecture~\ref{Conj: Bogulavsky} follows from the following result of \cite{singhal2025conjecturebeelendattaghorpade}.

\begin{proposition}\cite[Proposition 4]{singhal2025conjecturebeelendattaghorpade}\label{dimension}
Suppose that we have $1\leq l\leq m$ and $\binom{m+d}{d}-\binom{m+d+1-l}{d} <r \leq \binom{m+d}{d}$. Given $F_1, \dots, F_r \in S_d(m)$ that are linearly independent, we have
$$\dim(V(F_1, \dots, F_r)) \leq m-l.$$
\end{proposition}

Moreover, for the same choice of $l$, Conjecture~\ref{Conj: Bogulavsky} is saying that $\deg_{m-l}(V(W))\leq \beta_l$.
This follows from Corollary~\ref{Cor: l,c} and the following result of \cite{singhal2025conjecturebeelendattaghorpade}.

\begin{proposition}\cite[Proposition 5]{singhal2025conjecturebeelendattaghorpade}\label{degree}
Suppose that we have $1\leq l\leq m$, $1\leq c\leq d$ and
$$\tbinom{m+d}{d}-\tbinom{m+d+1-l}{d}+\tbinom{m+d-l-c}{d-c-1} <r \leq \tbinom{m+d}{d}.$$
Then given $F_1, \dots, F_r \in S_d(m)$ that are linearly independent, we have:
$$\deg_{m-l}(V(F_1, \dots, F_r)) \leq c.$$
\end{proposition}

Now, let us restrict ourselves to the case $m=2$ and suppose $w_r(d,2)=(\beta_1,\beta_2,\beta_3)$. If $\beta_1=0$, then the previous two propositions prove Conjecture~\ref{Conj: Bogulavsky} for this $r$.
On the other hand, if $\beta_1>0$, then they say that $\dim_1(V(W))\leq \beta_1$. It remains to be shown that if $\deg_1(V(W))= \beta_1$, then $\deg_0(V(W))\leq \beta_2$. We prove this in the next lemma.

\begin{lemma}
Suppose $w_r(d,2)=(\beta_1,\beta_2,\beta_3)$ with $\beta_1>0$.
For subspaces $W$ of $S_d(2,\fq)$ of dimension $r$, if $\deg_1(V(W))= \beta_1$, then $\deg_0(V(W))\leq \beta_2$.
\end{lemma}
\begin{proof}
Consider a subspace $W$ of $S_d(2,\fq)$ of dimension $r$ with $\deg_1(V(W))= \beta_1$.
Denote $g=\gcd(W)$. Then we have $\deg(g)=\deg_1(V(W))=\beta_1$. Suppose $W=g W_1$, so $W_1$ consists of polynomials of degree $d-\beta_1$ and $\gcd(W_1)=1$. Note that
\[\deg_0(V(W)) =\deg(V(W_1)) =|V(W_1)|_{\mm}\leq u_{r} (d-\beta_1,2).\]
Therefore, Theorem~\ref{Thm: urd2} implies that $u_{r} (d-\beta_1,2)=H'_{r-1}(d-\beta_1,2)$. By Lemma~\ref{r as function of alpha}, we see that
\[r=1+\tbinom{1+d-\beta_1}{2} +\tbinom{d-\beta_1-\beta_2}{1}.\]
Consider the $s$ for which $w_s(d-\beta_1,2)=(0,\beta_2,\beta_3)$. By Lemma~\ref{r as function of alpha}, we see that
\[s=1+\tbinom{1+(d-\beta_1) -0}{2} +\tbinom{(d-\beta_1)-0-\beta_2}{1}.\]
This means that $s=r$. By Lemma~\ref{Lem: w and w'}, we see that $w'_{r-1}(d-\beta_1,2)=(0,\beta_2,\beta_3)$, that is, $H'_{r-1}(d,2)=\beta_2$. This completes the proof.
\end{proof}


The discussion in this section proves the following.

\begin{theorem}
Conjecture~\ref{Conj: Bogulavsky} is true when $m=2$.
\end{theorem}








