\section{Technical Lemmas}\label{Appendix}

In this appendix, our goal is to prove Proposition~\ref{Prop: H' smaller than H}.


\begin{lemma}\label{Lem: diff ws}
Suppose $w_{s}(d,m)=(\beta_1,\dots,\beta_{m+1})$ and
\[k=\max\{1\leq k\leq m: \beta_k\neq 0\}.\]
Denote $\sigma=\sum_{i=1}^m\beta_i =d-\beta_{m+1}$.
Then for $1\leq j\leq m+1-k$, we have
\[H_s(d,m;d+1)-H_{s+j}(d,m;d+1)=(\sigma+1) (d+1)^{m-k-1} -\lfloor(d+1)^{m-k-j}\rfloor.\]
\end{lemma}
\begin{proof}
Note that $w_{s+j}(d,m)=(\beta_1,\dots,\beta_{k-1},\beta_k-1,d-\sigma,0,\dots,0,1,0,\dots,0)$.
Thus,
\[H_s(d,m;d+1)=\sum_{i=1}^{k}\beta_i (d+1)^{m-i},\]
\[H_{s+j}(d,m;d+1)=\sum_{i=1}^{k}\beta_i (d+1)^{m-i} -(d+1)^{m-k} +(d-\sigma)(d+1)^{m-k-1}+\lfloor(d+1)^{m-k-j}\rfloor.\]
The result follows.
\end{proof}

\begin{lemma}\label{lem:}
Given $a,b\geq 1$, we have
\[(d+1)^{a-1}+(d+1)^{b-1}\leq (d+1)^{a+b-1}.\]
\end{lemma}
\begin{proof}
Assume $a\leq b$. Then we have
\[(d+1)^{a-1}+(d+1)^{b-1}\leq 2 (d+1)^{b-1} \leq (d+1)^b \leq (d+1)^{a+b-1}.\qedhere\]
\end{proof}


\begin{lemma}\label{lem2:}
Given $1\leq c\leq a,b$, we have
\[(d+1)^{a-1}+(d+1)^{b-1}-(d+1)^{c-1}\leq (d+1)^{a+b-c-1}.\]
\end{lemma}
\begin{proof}
Assume $a\leq b$. If $c=a$, then equality holds so assume $c\leq a-1$.
Then we have
\[(d+1)^{a-1}+(d+1)^{b-1}\leq 2 (d+1)^{b-1} \leq (d+1)^b \leq (d+1)^{a+b-c-1}.\qedhere\]
\end{proof}


\begin{lemma}
Suppose $w_s(d,m)=(\beta_1,\dots,\beta_{m+1})$ and $l$ is the smallest index for which $\beta_l\neq 0$. Assuming $l<m$, we have
\[H_s(d,m;d+1)-H_{s+(m-l)}(d,m;d+1)\leq (\beta_{l}+1) (d+1)^{m-l-1}-1.\]
\end{lemma}
\begin{proof}
We will break the difference $H_s(d,m;d+1)-H_{s+(m-l)}(d,m;d+1)$ into parts $\sum_i H_{s_{i-1}}(d,m;d+1)-H_{s_i}(d,m;d+1)$, such that each part $H_{s_{i-1}}(d,m;d+1)-H_{s_i}(d,m;d+1)$ can be obtained from Lemma~\ref{Lem: diff ws}.
For this we will construct a sequence $s=s_0<s_1<\dots<s_t=s+(m-l)$. We will denote
\begin{align*}
\delta_i&= s_i-s_{i-1},\\
\Delta_i&= H_{s_{i-1}}(d,m;d+1)-H_{s_i}(d,m;d+1),\\
w_{s_{i-1}}(d,m)&= (\gamma_{i-1,1},\dots,\gamma_{i-1,m+1}),\\
k_i &= \max\{1\leq k\leq m\mid \gamma_{i-1,k}\neq 0\},\\
\sigma_i &= \sum_{j=1}^{m} \gamma_{i-1,j}= d-\gamma_{i-1,m+1}.
\end{align*}
In order to apply Lemma~\ref{Lem: diff ws}, we need $\delta_i\leq m+1-k_i$. Denote
\[u_i=m+1-k_i.\]

We start with $s_0=s$. Suppose $s_0,\dots,s_{i-1}$ have been constructed. Using these we can compute $k_i$, $\sigma_i$ and $u_i$. Take
\[s_i=s_{i-1}+\min\big(u_i, s_0+(m-l)-s_{i-1}\big).\]
Thus, $\delta_i\leq u_i$. This will terminate at some $t$ with $s_t=s_0+(m-l)$.

Now, Lemma~\ref{Lem: diff ws} says that for $1\leq i\leq t$ we have
\begin{align*}
\Delta_i= \begin{cases}
    (\sigma_i+1)(d+1)^{u_i-2} -(d+1)^{u_i-1-\delta_i} &\text{ if } \delta_i<u_i\\
    (\sigma_i+1)(d+1)^{u_i-2} &\text{ if } \delta_i=u_i.
\end{cases}
\end{align*}
Note that for $1\leq i\leq t-1$, we have $\delta_i=u_i$ and hence
\[\Delta_i= (\sigma_i+1)(d+1)^{u_i-2} \leq (d+1)\times (d+1)^{u_i-2} =(d+1)^{\delta_i-1}.\]
Notice that $\sum_{i=1}^{t-1} \delta_i= (m-l)-\delta_t$.
Therefore, by Lemma~\ref{lem:} we have
\[\sum_{i=1}^{t-1} \Delta_i
\leq \sum_{i=1}^{t-1} (d+1)^{\delta_i-1}
\leq (d+1)^{m-l-\delta_t-1}.\]
Note that if $t=1$, then the sum on the left is $0$, so the inequality still holds.

For $i=t$, there are there are three possibilities:
\begin{enumerate}
\item Case 1: $\delta_t=u_t$. In this case $\Delta_t\leq (d+1)^{\delta_t-1}$. Thus, by Lemma~\ref{lem:} we have
\begin{align*}
&H_{s}(d,m;d+1)-H_{s+(m-l)}(d,m;d+1)\\
&=\sum_{i=1}^t \Delta_i
\leq (d+1)^{(m-l-\delta_t)-1} +(d+1)^{\delta_t-1}\\
&\leq (d+1)^{m-l-1}
\leq (\beta_{l}+1) (d+1)^{m-l-1}-1.
\end{align*}

\item Case 2: $\delta_t<u_t$ and $k_{t}>l$.
In this case
\[\Delta_t= (\sigma_t+1)(d+1)^{u_t-2} -(d+1)^{u_t-1-\delta_t} \leq (d+1)^{u_t-1} -(d+1)^{u_t-1-\delta_t}.\]
Since $k_t>l$, we have $u_t=m+1-k_t\leq m-l$.
Therefore, by Lemma~\ref{lem2:} we have
\begin{align*}
&H_{s}(d,m;d+1)-H_{s+(m-l)}(d,m;d+1)
=\sum_{i=1}^t \Delta_i\\
&\leq  (d+1)^{m-l-\delta_t-1} +(d+1)^{u_t-1} -(d+1)^{u_t-\delta_t-1}\\
&\leq (d+1)^{m-l-1}
\leq (\beta_{l}+1) (d+1)^{m-l-1}-1.
\end{align*}

\item Case 3: $\delta_t<u_t$ and $k_{t}=l$.
In this case
\[\Delta_t=(\sigma_t+1)(d+1)^{u_t-2} -(d+1)^{u_t-1-\delta_t} = (\beta_l+1) (d+1)^{u_t-2} -(d+1)^{u_t-1-\delta_t}.\]
Notice that $k_t=l$ means $u_t=m+1-k_t=m-l+1$.
Now, if $t=1$, then $\delta_t=m-l$, hence
\[H_{s}(d,m;d+1)-H_{s+(m-l)}(d,m;d+1)
=\Delta_t = (\beta_l+1) (d+1)^{m-l-1} -1.\]
If $t\geq 2$, then $\delta_t\leq (m-l)-\delta_{t-1}\leq m-l-1$, so
\begin{align*}
&H_{s}(d,m;d+1)-H_{s+(m-l)}(d,m;d+1)
=\sum_{i=1}^t \Delta_i\\
&\leq (d+1)^{m-l-\delta_t-1} +(\beta_l+1)(d+1)^{m-l-1} -(d+1)^{m-l-\delta_t}\\
&=(\beta_l+1)(d+1)^{m-l-1} -d(d+1)^{m-l-1-\delta_t}\\
&\leq (\beta_l+1)(d+1)^{m-l-1} -1.\qedhere
\end{align*} 
\end{enumerate}
\end{proof}




\begin{lemma}\label{lem:3}
Given $d,k\geq 1$, we have
\[d^k\leq 1+(d-1)(d+1)^{k-1}.\]
\end{lemma}
\begin{proof}
The case $d=1$ and the cases $k\in \{1,2,3\}$ are easy to verify directly. Now assume $d\geq 2$ and $k\geq 4$. It is enough to show that
\[1\leq \Big(1-\frac{1}{d}\Big)\Big(1+\frac{1}{d}\Big)^{k-1}.\]
Consider the function $f(x)=(1-x)(1+x)^{k-1}$, it is easy to see that $f'(x)\geq 0$ for $0\leq x\leq \frac{k-2}{k}$. Since $d\geq 2$ and $k\geq 4$, we know that $\frac{1}{d}\leq \frac{1}{2}\leq \frac{k-2}{k}$. Thus, $f(0)\leq f(\frac{1}{d})$. The result follows.
\end{proof}

\begin{corollary}
Given $\beta,k,d\geq 1$, we have
\[(\beta+1) (d+1)^{k-1} -1\leq \beta \big( (d+1)^k -d^k\big).\]
\end{corollary}
\begin{proof}
Lemma~\ref{lem:3} can be restated as
\[(d+1)^{k-1} -1\leq d(d+1)^{k-1}-d^k.\]
Therefore,
\[(d+1)^{k-1} -1 \leq d(d+1)^{k-1}-d^k \leq \beta (d(d+1)^{k-1}-d^k)
=\beta ((d+1)^{k}-d^k-(d+1)^{k-1}).\]
The result follows.
\end{proof}

\begin{customprop}{\ref{Prop: H' smaller than H}}
Given $m\leq r\leq \binom{m+d}{d}$, for every $q\geq d+1$, we have
\[H'_{r-(m-1)}(d,m)\leq H_r(d,m;q).\]
\end{customprop}
\begin{proof}
Suppose $w'_{r-(m-1)}(d,m)=(\beta_1,\dots,\beta_{m+1})=w_s(d,m)$. Let $l$ be the smallest index for which $\beta_l\neq 0$. Then we know that $r=s+(m-l)$.

If $l=m$, then $r=s$ and hence
\[H'_{r-(m-1)}(d,m)=\beta_{m}= H_r(d,m;q).\]

Next, if $l<m$, then we have
\begin{align*}
&H_s(d,m;d+1)- H_{s+(m-l)}(d,m;d+1)\\
&\leq (\beta_l+1) (d+1)^{m-l-1} -1\\
&\leq \beta_l ((d+1)^{m-l}- d^{m-l})\\
&\leq H_s(d,m;d+1) -H_s(d,m;d).
\end{align*}
This means $H_s(d,m;d)\leq H_{s+(m-l)}(d,m;d+1)$. We conclude that
\[H'_{r-(m-1)}(d,m) =H_s(d,m;d)\leq H_{s+(m-l)}(d,m;d+1)= H_r(d,m;d+1)\leq H_r(d,m;q).\]
\end{proof}















