We will apply the asymptotic analysis method described in \cite{Li} to explore the asymptotic behavior of the double-pole anti-dark soliton. For convenience, assume $c=1,c_1=c_2=2,\lambda_1=\alpha_1+\mathrm{i}\beta_1$ that under the corresponding state transition conditions, we can obtain $a=\alpha_1^2-\beta_1^2+\frac{4\delta+1}{2},\delta=-\frac{3\alpha_1^2}{2}+\frac{3\beta_1^2}{2}$ and $4\beta_1^2>1$. Hence, the double-pole anti-dark soliton solution is
\begin{align}\label{sj}
    q_d=\dfrac{3072e^{\mathrm{i}D_1}(E_1e^{\frac{D_2\Delta}{8}}+E_2e^{\frac{3D_2\Delta}{8}}+E_3e^{\frac{D_2\Delta}{2}}-\frac{1}{2}E_4e^{\frac{D_2\Delta}{4}}-E_5)}{G_1e^{\frac{D_2\Delta}{2}}+G_2e^{\frac{D_2\Delta}{4}}+384\beta(G_3e^{\frac{D_2\Delta}{8}}+G_4e^{\frac{3D_2\Delta}{8}}-G_5)},
\end{align}
where 
\begin{align*}
    D_1&=\frac{25(\beta_1 - \alpha_1)^3(\beta_1 + \alpha_1)^3t}{4} + 2\left(\beta_1^2 - \alpha_1^2 + \frac{1}{4}\right)x,\\
    D_2&=\left(6\beta_1^4 + 4(5\alpha_1^2 - 1)\beta_1^2 + 6\alpha_1^4 + 4\alpha_1^2 + 1\right)t - 4x, ~\Delta=\sqrt{(4\beta_1^2-1)(4\alpha_1^2+1)},  
\end{align*}
and $E_j,j=1,\cdots,5$ and $G_j,j=1,\cdots,5$ are too long to be included here, so we omit them.

Subsequently, we substitute $x = \frac{\left(6\beta_1^4 + 4(5\alpha_1^2 - 1)\beta_1^2 + 6\alpha_1^4 + 4\alpha_1^2 + 1\right)t - D_2}{4}$ into Eq.\eqref{sj} so that the double-pole solution is only related to $D_2$ and $t$. Numerous articles about the asymptotic analysis method have illustrated that the characteristic line of the double-pole solution is curved\cite{zxf,wu,he}. Therefore, according to the relation $e^{D_2}\geq D_2(D_2\to+\infty)$ and $e^{D_2}\leq D_2(D_2\to-\infty)$, there must exist an asymptotic balance relation between $e^{D_2}$ and $t$. The explicit expressions of the asymptotic solitons are exhibited as follows.

$\bullet$~~When $e^{D_2}\sim t$, $D_2\to+\infty$,
\begin{align}\label{as1}
    [u]_{\mathrm{I}}^{\pm}\to e^{D_1}\Bigg[1+\frac{K_1}{2K_2\cosh\Big(\frac{D_2\Delta}{8}+\ln K_3\Big)+384\beta_1 K_4}\Bigg],~~t\to\pm\infty,
\end{align}
where
\begin{align*}
    K_1&=32t \cdot (2\beta_1 + 1)^2(2\beta_1 - 1)^2(4\alpha_1^2 + 1)^2(\alpha_1^2 + \beta_1^2)\beta_1^3,\\&\quad\cdot\left(4i\beta_1^2 - i - \sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}\right),\\
    K_2&=32\sqrt{2}\sqrt{-\beta_1^8\left(\sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}i + 2\beta_1^2 - 2\alpha_1^2 - 1\right)}\\&\quad\cdot\sqrt{(\alpha_1^2 + \beta_1^2)^3t^2(2\beta_1 + 1)^3(2\beta_1 - 1)^3(4\alpha_1^2 + 1)^3},\\
    K_3&=\frac{\beta_1^4 \left(\sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}i + 2\beta_1^2 - 2\alpha_1^2 - 1\right)(\alpha_1^2 + \beta_1^2)\sqrt{2}}{2\sqrt{-\beta_1^8\left(\sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}i + 2\beta_1^2 - 2\alpha_1^2 - 1\right)}}\\
&\quad\cdot\frac{1}{\sqrt{(\alpha_1^2 + \beta_1^2)^3 t^2 (2\beta_1 + 1)^3 (2\beta_1 - 1)^3 (4\alpha_1^2 + 1)^3}},\\
    K_4&=\frac{t(2\beta_1 + 1)(2\beta_1 - 1)(4\alpha_1^2 + 1)^2(\alpha_1^2 + \beta_1^2)\beta_1^2}{24}\\
&\quad\cdot\left(4i\beta_1^2 - i - \sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}\right).
    \end{align*}

$\bullet$~~When $e^{D_2}\sim t$, $D_2\to-\infty$,
\begin{align}\label{as2}
     [u]_{\mathrm{II}}^{\pm}\to e^{D_1}\Bigg[1+\frac{L_1}{2L_2\cosh\Big(\frac{D_2\Delta}{8}+\ln L_3\Big)+384\beta_1 L_4}\Bigg],~~t\to\pm\infty,
\end{align}
where 
    \begin{align*}
    L_1&=32t(2\beta_1 + 1)^2(2\beta_1 - 1)^2(4\alpha_1^2 + 1)^2(\alpha_1^2 + \beta_1^2)\beta_1^3\\
&\quad\cdot\left(4i\beta_1^2 - i + \sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}\right),\\
L_2&=32\sqrt{2}\sqrt{t^2(2\beta_1 + 1)^3(2\beta_1 - 1)^3(4\alpha_1^2 + 1)^3(\alpha_1^2 + \beta_1^2)^3\beta_1^8}\\
&\quad\cdot\sqrt{\left(\sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}i - 2\beta_1^2 + 2\alpha_1^2 + 1\right)},\\
L_3&=-\frac{t^2(2\beta_1 + 1)^3(2\beta_1 - 1)^3(4\alpha_1^2 + 1)^3(\alpha_1^2 + \beta_1^2)^2\beta_1^4\sqrt{2}}{\sqrt{t^2(2\beta_1 + 1)^3(2\beta_1 - 1)^3(4\alpha_1^2 + 1)^3(\alpha_1^2 + \beta_1^2)^3\beta_1^8}},\\
&\quad\cdot\frac{1}{\sqrt{\left(\sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}i - 2\beta_1^2 + 2\alpha_1^2 + 1\right)}},\\
L_4&=\frac{t(2\beta_1 + 1)(2\beta_1 - 1)(4\alpha_1^2 + 1)^2(\alpha_1^2 + \beta_1^2)\beta_1^2}{24}\\
&\quad\cdot\left(4i\beta_1^2 - i + \sqrt{(4\beta_1^2 - 1)(4\alpha_1^2 + 1)}\right).
    \end{align*}

We can find that the characteristic lines of the asymptotic solitons above are $\frac{D_2\Delta}{8}+\ln K_3=0$ and $\frac{D_2\Delta}{8}+\ln L_3=0$, both contain the  logarithmic terms which can reflect the double-pole properties.
When $a = \frac{3}{10}, c = 1, \delta=-\frac{3}{20},\lambda_1=\frac{7}{10}+\frac{\sqrt{39}}{10}\mathrm{i}$ are taken, we can find that the characteristic trajectories of the corresponding asymptotic solitons in Fig.\ref{fg} fit perfectly with the contour plot of Fig.\ref{fg10}. Furthermore, we compare the asymptotic solitons \eqref{as1}, \eqref{as2} and the exact solution \eqref{dou} when 
the parameters are given. We can find that the asymptotic soliton perfectly matches the exact solution in the far-field region as is shown in Fig.\ref{com}. This demonstrates the validity of our asymptotic analysis.
