\begin{appendix}
\section{Proofs for cyclic transitions}\label{sec:appendix}
\subsection{Preliminaries}\label{sec:pre}
\begin{lemma}[upper bound on \(x\) after stage rXd]\label{lem:up_bound1}
Suppose that the previous stage was rxd. Suppose that the stage rXd finishes by transitioning to stage rXD. The maximal value variable \(x\) can assume is
\begin{equation*}
    \overline{x} := \frac{\sqrt{\beta^2 d^{*2} + 2Hd^*} - \beta d^*}{H} ,
\end{equation*}
where \(H = 1 - \epsilon d^*\).
\end{lemma}
\begin{proof}
\(x\) crosses 0 during the transition rxd \(\rightarrow\) rXd. We can therefore calculate an upper bound on \(x\) at the end of stage rXd. In order to do this, we need to find an upper bound on the time it takes for \(d\) to reach its threshold since this marks the end of the stage.
\begin{align*}
    \dot{x} &\geq 1 - \epsilon \sup d = 1 - \epsilon d^* \\
    & \Rightarrow x(t) \geq (1 - \epsilon d^*)t \\\\
    \dot{d} &\geq x - \beta \sup d = (1 - \epsilon d^*)t - \beta d^* \\
    &\Rightarrow d(t) \geq \frac{1}{2} (1  - \epsilon d^*)t^2 - \beta d^* t
\end{align*}
We used \(\sup d = d^*\) because we are in stage rXd. Inserting the time \(\tau_d\) when \(d\) reaches its threshold \(d^*\), we get an upper bound for it:
\begin{align*}
    d(\tau_d) &= d^* \geq \frac{1}{2} (1 - \epsilon d^*)\tau_d^2 - \beta d^* \tau_d\\
    0 &\geq \frac{1}{2} \underbrace{(1 - \epsilon d^*)}_{H}\tau_d^2 - \beta d^*\tau_d - d^*\\
    \tau_d &\leq \frac{\sqrt{\beta^2 d^{*2} + 2Hd^*} - \beta d^*}{H} \ .
\end{align*}
Note, that \(\dot{x} \leq 1 - \epsilon \inf d = 1 \).
This can be used to calculate a maximal value of \(d\) at the end of the stage:
\begin{equation*}
    x(\tau_d) \leq \tau_d \leq \frac{\sqrt{\beta^2 d^{*2} + 2Hd^*} - \beta d^*}{H} =: \overline{x} \ .
\end{equation*}
\end{proof}


\begin{lemma}[lower bound on \(x\) after stage rXd]\label{lem:low_bound1}
Suppose that the previous stage was \bs{rxd}. Suppose that the stage \bs{rXd} finishes by transitioning to stage \bs{rXD}. The minimal value variable \(x\) can assume is
\begin{equation*}
    \underline{x} :=  H \sqrt{d^*} \ ,
\end{equation*}
where \(H = 1 - \epsilon d^*\).
\end{lemma}
\begin{proof}
\(x\) crosses 0 during the transition \bs{rxd} \(\rightarrow\) \bs{rXd}. We can therefore calculate a lower bound on \(x\) at the end of stage \bs{rXd}. In order to do this, we need to find a lower bound on the time it takes for \(d\) to reach its threshold since this marks the end of the stage.
\begin{align*}
    \dot{x} &\leq 1 - \epsilon \inf d = 1 \\
    & \Rightarrow x(t) \leq t \\\\
    \dot{d} &\leq x - \beta \inf d = t \\
    &\Rightarrow d(t) \leq \frac{1}{2} t^2
\end{align*}
Using the time \(\tau_d\) when \(d\) reaches its threshold \(d^*\):
\begin{align*}
    d(\tau_d) &= d^* \leq \frac{1}{2} \tau_d^2\\
    \tau_d &\geq \sqrt{d^*} \ .
\end{align*}
Note, that \(\dot{x} \geq 1 - \epsilon \sup d = 1 - \epsilon d^*\).
This can be used to calculate a lower bound of \(x\) at the end of the stage:
\begin{equation*}
    x(\tau_d) \geq (1 - \epsilon d^*) \tau_d \geq (1 - \epsilon d^*) \sqrt{d^*} =: \underline{x} \ .
\end{equation*}
\end{proof}


\begin{assumption} \label{bounds_check}
    Assume $\overline{x} > \underline{x}$.
\end{assumption}

\begin{remark}
\cref{bounds_check} implies that the upper bound on \(x\) is greater than the lower bound on \(x\) in stage \bs{rXD}, since \(\overline{x}' > \overline{x}\). The bounds on X are therefore \(\underline{x} \leq x \leq \overline{x}\) after stage \bs{rXd} and \(\underline{x} \leq x \leq \overline{x}'\) after stage \bs{rXD}.
\end{remark}

\subsection{Transition rXD to RXD}
\begin{lemma}[threshold conditions \bs{rXD}]\label{lem:vrvd_app}
Suppose stage \bs{rXD} was reached from stage \bs{rXd}. The condition \(d=1/\epsilon\) must be fulfilled before either \(d\) or \(x\) reach their respective threshold.
\end{lemma}
\begin{proof}
The trajectory has crossed the threshold \(d=d^*\) from below. Since stages \bs{rXd} and \bs{rXD} are governed by the same equations, condition \(\dot{d} > 0\) holds on both sides of the transition, which implies \(x > \beta \delta/\gamma\). We also know, that \(\dot{x} > 1 - \epsilon d^* > 0\). In summary, \(\dot{d}>0, \dot{x}>0 \) at the time of threshold crossing. This holds true at least until \( d = 1/\epsilon\) at which point \( \dot{x} = 0\) and a subsequent decrease in \(x\) is followed by decreasing \(d\).
\end{proof}

\begin{theorem}
Suppose the stage \bs{rXD} was reached by stage \bs{rXd}. If the following inequality is fulfilled, the system can only transition to stage \bs{RXD}:
\begin{equation*}
    \sqrt{\frac{2}{\gamma (\underline{x} - \beta /\epsilon)}} < \frac{\sqrt{G^2 + 2H^2/\epsilon}-G}{H} \ .
\end{equation*}
\end{theorem}
\begin{proof}
By lemma \ref{lem:tr}, the time it takes to reach \(r\)'s threshold is bounded from above by
\[T_r = \sqrt{\frac{2}{\gamma (\underline{x} - \beta /\epsilon)}} \ .\]
Lemma \ref{lem:vrvd} shows that the threshold \(d=1/\epsilon\) must be crossed before the system reaches either \(d\)'s or \(x\)'s threshold.
By lemma \ref{lem:td}, the time it takes to reach \(d=1/\epsilon\) is bounded from below by
\[ T_d = \frac{\sqrt{G^2 + 2H^2/\epsilon}-G}{H} \ .\]
If \(T_r < T_d\), the only possible transition is \bs{rXD}  \(\rightarrow\) \bs{RXD}.
\end{proof}



\subsection{Transition RXD to RxD}
\begin{lemma}[initial condition]\label{lem:ic}
Suppose that a trajectory followed the stage progression \bs{rXd, RXD} and is now in stage \bs{RXD}.The trajectory traversing stage \bs{RXD} is bounded from below by the trajectory starting with the initial condition $x=\underline{x}, d=d^*$.
\end{lemma}
\begin{proof}
In stage \bs{rXD}, the following holds by \autoref{lem:vrvd}: \(\dot{x}>0, \dot{d}>0\). Any initial condition in \bs{RXD}, will therefore have an initial condition $(x_{IC}, d_{IC}) \geq (\underline{x}, d^*)$, where equality is attained only if $T_r = 0$. Since the dynamics are linear and trajectories in 2-d cannot cross because of uniqueness, the real trajectory is bounded from below by the one starting from $(\underline{x}, d^*)$.
\end{proof}

\begin{theorem}[final condition]\label{lem:curve_end_app}
Under the following conditions, the bounding Jordan curve $\mathcal{J}$ will terminate at a point $O = (x=0, d>d^*)$:
\begin{align}\label{eq:cond2_app}
x_m(t_1) \left( \frac{1}{\beta} - \frac{1}{2 \epsilon d^*} x_m(t_1) \right) &> d^*
\end{align}
where
\begin{align*}
x_m(t_1) &= \underline{x} \exp\left(-\frac{\epsilon}{\beta^2 - \epsilon}\ln\left( \beta\frac{d^* + F}{\underline{x} + \beta F}\right) \right) \\
F &= \frac{\beta \underline{x}}{\epsilon - \beta^2} \ .
\end{align*}
\end{theorem}

\begin{proof}
The curve $\mathcal{J}$ is described in \autoref{lem:jordancurve}. It is produced by the trajectory of the system:
\begin{align*}
  \left\lbrace
  \begin{array}{l@{}l}
    (x_m, d_m) & \ \text{if }\ (x, d) \in \mathcal{A}\\
    (x_p, d_p) & \ \text{if }\ (x, d) \in \mathcal{B}
  \end{array}
  \right.
\end{align*}
with
\begin{align*}
\dot{x}_m &= -\frac{\epsilon}{\beta} x_m\\
\dot{d}_m &= x_m - \beta d_m\\
\dot{x}_p &= -\epsilon d^*\\
\dot{d}_p &= x_p - \beta d_p \ .
\end{align*}
First, We will integrate the trajectory starting from $(\underline{x}, d^*)$ and reaching $x=\beta d$.
\begin{align*}
x_m(t) &= \underline{x} \exp\left(-\frac{\epsilon}{\beta}t\right)\\
d_m(t) &= -F \exp\left(-\frac{\epsilon}{\beta}t \right) + (d^*+F) \exp(-\beta t)\\
\text{where} \ F &= \frac{\beta \underline{x}}{\epsilon - \beta^2} \ .
\end{align*}
Using the ending condition $x(t_1)=\beta d(t_1)$:
\begin{align*}
\left( F + \frac{\underline{x}}{\beta} \right) \exp\left(-\frac{\epsilon}{\beta}t_1 \right) &= (d^* + F) \exp(-\beta t_1)\\
t_1 = \frac{1}{\beta - \epsilon/\beta}&\ln\left(\frac{d^* + F}{\underline{x}/\beta + F}\right) \ .
\end{align*}
Second, we will integrate the trajectory starting from $(x_p(0)=x_m(t_1), d_p(0)=d_m(t_1))$ and reaching \mbox{$x_p(t_2)=0$}:
\begin{align}
x_p(t) &= x_m(t_1) - \epsilon d^* t \nonumber \\
d_p(t) &= b_0 + b_1t + b_2\exp(-\beta t) \\
\text{where} \ b_0 &= \frac{x_m(t_1)}{\beta} + \frac{\epsilon d^*}{\beta^2} \nonumber\\
b_1 &= \frac{\epsilon d^*}{\beta} \nonumber\\
b_2 &= -\frac{\epsilon d^*}{\beta^2} \ . \nonumber
\end{align}
The final condition yields:
\begin{align}
x_p(t_2) &= x_m(t_1) - \epsilon d^* t_2 = 0 \nonumber\\
\Rightarrow t_2 &= \frac{x_m(t_1)}{\epsilon d^*} \ . \label{eq:t2_app}
\end{align}
Last, we need to show that $d_p(t_2) > d^*$. Keeping in mind that $\exp(-x) < (1-x+x^2/2) \quad \forall x>0$ and $b_2<0$, we can calculate a lower bound:
\begin{align*}
d_p(t_2) &= b_0 + b_1 t_2 + b_2 \exp(-\beta t_2) \\
 &> b_0 + b_1 t_2 + b_2 \left(1-\beta t_2+\frac{\beta^2 t_2^2}{2}\right)\\
 &=  \frac{x_m(t_1)}{\beta} + t_2(b_1 - \beta b_2) + t_2^2 \left(\frac{1}{2}\beta^2 b_2 \right) \\
&>  \frac{x_m(t_1)}{\beta} - \frac{1}{2} \epsilon d^* t_2^2\\
&= x_m(t_1) \left(\frac{1}{\beta} - \frac{x_m(t_1)}{2\epsilon d^*}\right)
\end{align*}

where
\begin{align*}
x_m(t_1) &= \underline{x} \exp\left(-\frac{\epsilon}{\beta^2 - \epsilon}\ln\left( \beta\frac{d^* + F}{\underline{x} + \beta F}\right) \right) \ .
\end{align*}
Now, if
\begin{align} \label{eq:jc2}
x_m(t_1) \left(\frac{1}{\beta} - \frac{x_m(t_1)}{2\epsilon d^*}\right) > d^*
\end{align}
it follows that $d_p(t_2) > d^*$. Therefore if a set of parameters fulfills \eqref{eq:jc2}, the jordan curve will terminate at $O = (x_p=0, d_p(t_2)>d^*)$.

\end{proof}

\end{appendix}
\end{document}

