\section{Preliminaries}\label{sec:notation}
Throughout the paper, we use regular lowercase letters for scalars (e.g., $d$), bold lowercase letters for vectors (e.g., $\bm{v}$), and bold capital letters for matrices (e.g., $\bm{A}$). The notation $[d]$ denotes the set $\{1, 2, \dots, d\}$ for any positive integer $d$. Given a vector $\bm{v}$, $\|\bm{v}\|_0$, $\|\bm{v}\|_2$, and $\|\bm{v}\|_\infty$ represent its $\ell_0$-, $\ell_2$-, and $\ell_\infty$-norms, respectively. For a matrix $\bm{M}$, $\sigma_i(\bm{M})$ denotes the $i$-th singular value. For simplicity, we denote $\sigmas_i$ as the $i$-th singular value of the unknown density matrix $\brhos$ and define $\kappa = \sigmas_1 / \sigmas_r$ as its condition number. $\Tr(\bm{M})$ denotes the trace of $\bm{M}$. We use $\lV\bm{M}\rV$ to represent the  spectral norm of $\bm{M}$ and $\lV\bm{M}\rV_F=\sqrt{\Tr(\bm{M}^\dagger\bm{M})}$ to represent the Frobenius norm of $\bm{M}$. $\lV\bm{M}\rV_{*}$ denotes the nuclear norm (or trace norm) of $\bm{M}$, given by $\lV\bm{M}\rV_{*}:=\Tr\left(\sqrt{\bm{M}^{\dag}\bm{M}}\right)$.

Consider a quantum system with $n$ qubits, where the associated density matrix $\brhos \in \mathbb{C}^{d\times d}$ is a positive semidefinite matrix of order $d = 2^n$ with trace unity. For the ease of presentation, we renormalize $\brhos$ such that $\lV\brhos\rV=1$, thus $\sigmas_r=\frac{1}{\kappa}$. Any such density matrix can be expressed as a linear combination of local Pauli observables $\mathbb{W}=\{\bA_i \mid i \in [d^2]\}$, where each Pauli observable is a tensor product of $n$ Pauli matrices $\bm{P}_1 \otimes \bm{P}_2 \otimes \cdots \otimes \bm{P}_n$, with each $\bm{P}_i$ selected from the set of $2 \times 2$ Pauli matrices $\{I_{2 \times 2}, X, Y, Z\}$. In fact, $\mathbb{W}$ form a complete orthogonal set in $\bC^{d\times d}$, satisfying the relation:
$
\langle\bW_j,\bW_i\rangle=\Tr(\bW_i^\dagger \bW_j) = d \cdot \delta_{i,j} 
$
for all $i,j\in[d^2]$, where $\langle\cdot,\cdot\rangle$ denotes the Frobenius inner-product on $\bC^{d\times d}$ and $\delta_{i,j}$ is the Kronecker delta. This orthogonality allows any matrix $\bm{X} \in \mathbb{C}^{d \times d}$ to be uniquely represented as a linear combination of the Pauli observables:
$
\bm{X} = \frac{1}{d} \sum_{i=1}^{d^2} \langle \bm{X}, \bW_i \rangle \bW_i.
$
For the underlying density matrix $\brhos$, this expansion implies that each Pauli operator $\bW_i$ is associated with the coefficient $\frac{1}{d} \Tr(\bW_i \brhos)$ in the Pauli basis representation.


\section{Non-convex Mini-batch SGD for Online QST}\label{sec:non_convex_mini_batch_sgd_for_online_qst}
In this section, we present the mini-batch SGD algorithm for online low-rank QST in more detail. Recall that online low-rank QST aims to reconstruct an unknown rank-$r$ quantum state \(\brhos \in \mathbb{C}^{d \times d}\) of an \(n\)-qubit system (\(d=2^n\)) from sequentially performed measurement statistics. More precisely, within each round, we receive \(B\) measurement outcomes of the form
\begin{align}\label{eq:minibatchmodel}
    y_{t,k} = \Tr(\bm{A}_{t,k} \brhos))+z_{t,k},~ k\in [B],
\end{align}
where each $\bm{A}_{t,k}$ is sampled uniformly at random from $\mathbb{W}$ and $z_{t,k}$ denotes the statistical noise incurred from the finite repetitions of the measurements. For a rank-\(r\) density matrix $\brho=\bU\bU^\dagger\in\bC^{d\times d}$, where $\bU\in\bC^{d\times r}$ is the parameter matrix,  the instantaneous loss $\ell_t(\bU)$ of $\bU$ and the squared loss $\hat{\ell}_t(\brho)$ of $\brho$ at the $t$-th round is defined as
 \begin{align}\label{eq:batchloss}
    &~\ell_t(\bU):=\frac{1}{4}\sum_{k=1}^B \left( y_{t,k} - \Tr(\bm{A}_{t,k} \bU \bU^{\dag}) \right)^2\cr
    =&~\frac{1}{4}\sum_{k=1}^B \left( y_{t,k} - \Tr(\bm{A}_{t,k} \brho) \right)^2
    =:\hat{\ell}_t(\brho).  
 \end{align}
We shall work with the instantaneous loss $\ell_t(\bU)$ and update the parameter matrix $\bU$. Similar to the case of $B=1$, to update $\bU_t$ at round $t$, we use the previous estimation $\bU_{t-1}$ to reduce the loss $\ell_t(\bU_t)$. We follow the gradient descent update:
 \begin{align}\label{eq:minibatchGD}
    \bU_{t} = \bU_{t-1}- \eta \nabla_{\bU}\ell_t(\bU_{t-1}),\quad t\in[T],
 \end{align}
where $\eta>0$ denotes the learning rate, which will be chosen explicitly from the analysis. By a direct computation, the gradient term $\nabla_{\bU}\ell_t(\bU_{t-1})$ at the $t$-th round is given by
\begin{align*}
  \nabla_{\bU}\ell_t(\bU_{t-1})
  =\sum_{k=1}^B\left[ \Tr(\bm{A}_{t,k} \bU_{t-1} \bU_{t-1}^{\dag})-y_{t,k} \right]\bm{A}_{t,k}\bU_{t-1}.
\end{align*}
The proposed algorithm is formalized in \Cref{algo:minibatchGD}. The rest of this paper will focus on the convergence analysis of the algorithm: Assuming the initial guess of the state is sufficiently close to the target unknown state~\footnote{The initial guess can be computed by \Cref{algo:iniSGD} or off-the-shelf spectral method. Spectral method yield an $\O(\sigmas_r)$-close approximation using $\O(\kappa^2r^2d\log^6 d)$ random Pauli measurements; see \cite[Lemma 4]{kyrillidis2018provable} or \cite[Lemma 2 in supplementary material]{hsu2024quantum} for details). More discussions on the initialization can be found in Appendix~\ref{appendix:numerical_simulation}, with numerical simulations.}, we shall provide bounds on the number of rounds $T$, the learning rate $\eta$ and the batch size $B$ such that the output state $\brho_T=\bU_T\bU_T^\dagger$ is $\epsilon$-close to the unknown state $\brhos$ with respect to the Frobenius norm. Note that the update can be computed in $\O(Brd\log d)$ FLOPs.
 \begin{algorithm}[htbp!]
\caption{Mini-batch SGD for Online QST}
\label{algo:minibatchGD}
\begin{algorithmic}[1]
\STATE \textbf{Input:} $T$, learning rate $\eta$, batch size $B$, Measurements $A_{t,k}$ and outcomes $y_{t,k}$ 
\STATE Initialize $\bU_0$  
\FOR{$t = 1, \ldots, T$}
    \STATE Let each $\bA_{t,k}$, $k \in [B]$, be chosen from the set of local Pauli measurements $\mathbb{W}$ uniformly at random, update: 
    \begin{align*}
      \bU_{t} =&~ \bU_{t-1} - \eta \sum_{k=1}^B\Big[ \Tr(\bm{A}_{t,k} \bU_{t-1} \bU_{t-1}^{\dag}) \cr
               &~ -y_{t,k} \Big]\bm{A}_{t,k}\bU_{t-1}
    \end{align*}
\ENDFOR
\STATE \textbf{Output:} $\brho_T = \bU_T \bU_T^{\dagger}$.
\end{algorithmic}
\end{algorithm}

\subsection{Expectation convergence}\label{sec:theory}
We first define the local contraction region, a crucial subset of the parameter space where the algorithm exhibits desirable convergence behavior. Formally, this region is defined as
\begin{align*}
    \mathcal{E}(\brho_\star,\delta ):=\left\{\bU: \lV \bU\bU^{\dag}-\brhos\rV_\fro\le \delta  \right\},
\end{align*} 
where $\delta\in [0, 1)$ is the diameter which will be chosen later. 
We shall consider the distance between the current estimate $\brho_t=\bU_t\bU_t^\dagger$ and the unknown quantum state $\brhos$. Define the learning error at $t$-th round of \Cref{algo:minibatchGD} as 
\begin{align}\label{def:error}
  e_t&=\mathrm{dist}(\brho_t,\brhos):=\lV\brho_t-\brhos \rV_{\fro} \cr
  &=\lV \bU_t\bU_t^{\dag}-\brhos\rV_\fro.
\end{align}

We first analyze the statistical error incurred by the finite repetitions of measurements. 
We demonstrate that the measurement error introduced by the shots in each round has a variance with zero mean and is well-bounded as long as the number of shots is sufficiently large.
\begin{lemma}\label{lemma:Eerror}
    At any round $t$, we have
     \begin{align}\label{eq:EztAt}
        \E[z_{t,k}\bA_{t,k}]=\bm{0},~\forall k\in [B] .
    \end{align}
    Moreover,  $\forall \varepsilon_0\in (0,1)$, provided $\ell \ge 112\varepsilon_0^{-2} d\log d$, it holds that
    \begin{align}\label{ineq:boundzt}
      \lv z_{t,k}\rv\le \frac{\varepsilon_0}{\sqrt{d}},~\forall k\in [B] 
    \end{align}
    with probability at least $1-2d^{-10}$. 
\end{lemma}
\begin{proof}
The proof is deferred to \Cref{sec:proofoferror}.
\end{proof}

Now we present the local contraction property in expectation. Specifically, for iterates within the defined contraction region, the algorithm achieves a linear rate of error reduction per iteration in expectation, provided the learning rate is sufficiently small.  Let the filtration $\mathcal{F}_t := \sigma\{\nabla_{\bU}\ell_1(\bU_0), \nabla_{\bU}\ell_2(\bU_1), \ldots, \nabla_{\bU}\ell_t(\bU_{t-1})\}$, where \(\sigma\{\cdot\}\) represents the sigma field.
\begin{theorem}\label{thm:Econtraction}
Assume $B\le d$, $\kappa\le \sqrt{dr}$. Under event \eqref{ineq:boundzt}, for $\bU_t\in\mathcal{E}(\brhos,\frac{\sigmas_r}{3})$, there exists numerical constant $c_1>0$ such that 
\begin{align*}
\E[e_{t+1}^2|\mathcal{F}_t]\le (1-\frac{\eta B}{2\kappa d})e_t^2 +\frac{\eta B \varepsilon_0^2}{8\kappa d}
\end{align*} 
provided $\eta \le \frac{c_1}{\kappa r}$ and $B\le 40 \kappa^2$. Moreover, for $B\ge 40 \kappa^2$, \eqref{eq:contra} also holds provided $\eta \le \frac{\kappa}{5B r}$.
\end{theorem}
\begin{proof}
    The proof is deferred to \Cref{proofofEcontraction}
\end{proof}   
In the noiseless case, \Cref{thm:Econtraction} shows that the expected number of iterations is $T=\mathcal{O}(B^{-1}\kappa^2 r d \log \frac{1}{\epsilon})$ to achieve $\epsilon$-accuracy for small $B$, provided the iterates remain in the $\mathcal{O}(\sigma_r^*)$-neighborhood of $\brhos$. 
\begin{remark}\label{remark:propconvergence}
In \Cref{thm:Econtraction}, we demonstrated that the mini-batch version of SGD achieves an iteration complexity that is $B$ times faster than standard SGD, provided the batch size $B$ is not excessively large. Notably, our convergence analysis holds for all values of $B\le d$. Specifically, for $\bU_t\in\mathcal{E}(\brhos,\frac{\sigmas_r}{3})$, we always have
\begin{align}
    \E[e_{t+1}^2|\mathcal{F}_t]\le (1-\frac{\eta B}{2\kappa d})e_t^2 +\frac{\eta B \varepsilon_0^2}{8\kappa d}
\end{align} 
provided $\eta \le \O(\min\{\frac{\kappa}{B r},\frac{1}{\kappa r}\})$.
\end{remark}

\subsection{Probabilistic convergence}\label{sec:theory p}
We now convert the expectation convergence into a probabilistic convergence guarantee, showing that the algorithm achieves geometric convergence with high probability under practical conditions, including sufficient shots and appropriately chosen learning rates.
\begin{theorem}[Formal statement of \Cref{thm:informal}]\label{thm:propconvergence}
Assume  $\ell \ge 112\varepsilon_0^{-2}d\log d$, $\varepsilon_{0}\in (0,1)$, and $\kappa\le \sqrt{dr}$. There exist numerical constant $c_2>0$ satisfying: For $\bU_0\in\mathcal{E}(\brhos,\frac{\sigmas_r}{3})$ and all $t\in [T]$, it holds
\begin{align*}
  e_{t}^2\le 2\left(1-\frac{\eta B}{4\kappa d}\right)^t e_0^2+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]\varepsilon_0^2  
\end{align*} 
with probability at least $1-\frac{3T}{d^{10}}$, provided $\eta \le \frac{c_2}{\kappa r\log d}$ and $B\le \min\{40 \kappa^{2/3},d\}$. 
\end{theorem}
\begin{proof}
The proof is deferred to \Cref{subsec:proofofprobconvergence}
\end{proof}



This leads to the iteration complexity estimates for achieving a target accuracy $\epsilon$. 
\begin{corollary}\label{col:esterror}
For $e_0 \le \frac{1}{3}\sigmas_r$, we have    
\begin{align}
    e_T^2 \le \O\left(\frac{\epsilon}{9}(\sigmas_r)^2+ \varepsilon_0^2\right)
\end{align}
with probability at least $1-\frac{3T}{d^{10}}$, provided 
$$T\ge \frac{1}{B}\kappa^2 rd\log d\log\frac{1}{\epsilon}$$
and $\eta = \frac{c_2}{\kappa r\log d}$, $B\le \min\{40 \kappa^{2/3},d\}$, $\ell \ge 112\varepsilon_0^{-2}d\log d$.
\end{corollary}

For the spectral initialization in~\cite[Lemma 4]{kyrillidis2018provable} or \cite[Lemma 2 in supplementary material]{hsu2024quantum} guarantees that $e_0 \le \frac{1}{3}\sigmas_r$. Thus, it implies  $ \O\left(\max\{\kappa^2 rd\log d\log\frac{1}{\epsilon},\kappa^2r^2d\log^6 d\}\right)$ Pauli measurements is required to achieve an $\epsilon$-approximation of the unknown state $\brhos$, provided that $\varepsilon_0$ sufficiently small. 

