\section{Proofs}
In this section, we provide comprehensive proofs of the main theoretical results. We begin with the proof of \Cref{lemma:Eerror} in \Cref{sec:proofoferror}, followed by the proof of \Cref{thm:onlineIni} in \Cref{sec:proofofini}. To establish \Cref{thm:Econtraction}, we first develop several key lemmas that establish the necessary local regularity and smoothness properties; these are presented in \Cref{subsec:keylemmas}. With these foundational results in place, we proceed to the full proof of \Cref{thm:Econtraction} in \Cref{proofofEcontraction}. Finally, \Cref{thm:propconvergence} is proven in \Cref{subsec:proofofprobconvergence} by applying the Azuma–Bernstein inequality.

\subsection{Proof of Lemma~\ref{lemma:Eerror}}\label{sec:proofoferror}
\begin{proof}
At round $t$, once each $\bA_{t,k} \in \{\bW_1, \bW_2, \dots, \bW_{d^2}\}$ is sampled to be $\bW_i$, the approximated coefficient $\Tr(\bW_i \brhos)$ is obtained from a 2-outcome measurement $\left\{\frac{I + \bW_i}{2}, \frac{I - \bW_i}{2}\right\}$ as in \eqref{eq:minibatchmodel}, with error $z_{t,k} = \hat{z}_{t,k,i}$. The outcome is a random variable $G_{t,k,i}$, where the subscript $i$ corresponds to the Pauli matrix $\bW_i$. Each instance of the random variable $G_{t,k,i}$ is denoted by $G_{t,k,i}^j$, with $j \in [\ell]$ referring to the $j$-th instance, and we perform $\ell$ measurements for each $\bW_i$. The instance $G_{t,k,i}^j = 1$ occurs with probability $\Tr\left(\frac{I + \bW_i}{2} \brhos\right)$, while $G_{t,k,i}^j = -1$ occurs with probability $\Tr\left(\frac{I - \bW_i}{2} \brhos\right)$. Thus, we obtain the measurement outcomes as

  $$\hat{y}_{t,k,i}=\frac{1}{\ell}\sum_{j=1}^{\ell}G_{t,k,i}^{j},~i\in [d^2].$$
 Therefore, 
  \begin{align}\label{eq:EzA}
\E[z_{t,k}\bA_{t,k}]&=\frac{1}{d^2}\sum_{i=1}^{d^2}\E[\hat{z}_{t,k,i}|\bW_i] \bW_i\cr
&=\frac{1}{d^2}\sum_{i=1}^{d^2}\E\left[\hat{y}_{t,k,i}-\Tr(\bW_i\brhos) |\bW_i\right] \bW_i\cr
&=\frac{1}{d^2}\sum_{i=1}^{d^2}\sum_{j=1}^{\ell}\frac{1}{\ell}\E\left[G_{t,k,i}^{j}-\Tr(\bW_i\brhos)|\bW_i\right] \bW_i\cr
&= \frac{1}{d^2}\sum_{i=1}^{d^2}\sum_{j=1}^{\ell}\frac{1}{\ell}\left[\Tr\left(\frac{I+\bW_i}{2}\brhos\right)-\Tr\left(\frac{I-\bW_i}{2}\brhos\right)-\Tr(\bW_i\brhos)\right]\bW_i\cr
&= \bm{0}.
  \end{align}
Now we prove the second statement. By definition we have
  $$\hat{z}_{t,k,i}=\sum_{j=1}^{\ell}\frac{1}{\ell}\left(G_{t,k,i}^{j}-\Tr(\bW_i\brhos)\right) :=\sum_{i=1}^{\ell}\frac{1}{\ell} \mathcal{Z}_{t,k,i}^{j}$$
where $\mathcal{Z}_{t,k,i}^{j}:=G_{t,k,i}^{j}-\Tr(\bW_i\brhos)$. Noticing $\E\left[\mathcal{Z}_{t,i}^{j}\right]=0$ and $\lv\mathcal{Z}_{t,i}^{j}\rv\le 2$, then by the Hoeffding's bound we have
\begin{align*}
    \P\left(\lv\sum_{j=1}^{\ell}\frac{1}{\ell} \mathcal{Z}_{t,k,i}^{j}\rv\ge \frac{\varepsilon_0}{\sqrt{d}} \right)\le 2e^{-\ell \varepsilon_0^2/(8d)}.
\end{align*}
By a union bound and the fact that $B\le d^2$, it then implies 
$$\P\left(\lv\sum_{j=1}^{\ell}\frac{1}{\ell} \mathcal{Z}_{t,k,i}^{j}\rv< \frac{\varepsilon_0}{\sqrt{d}},~\forall i\in [d^2], \forall k\in [B] \right)\ge 1-  2B d^{-12}\ge 1-2d^{-10}$$ 
provided $\ell \ge 112\varepsilon_0^{-2}d\log d$.  
\end{proof}

\subsection{Proof of Theorem~\ref{thm:onlineIni}}\label{sec:proofofini}
\begin{proof}
 The proof is based on \cite[Theorem 3]{jain2016streaming}.   Noticing that $\{d y_t\bA_t\}_{t=1}^{T_0}$ is a sequence of matrices sampled independently from a distribution that satisfies 
    \begin{align}
        \E[d y_t\bA_t] = \frac{1}{d^2}\sum_{i=1}^{d^2}d \E[y_i|\bW_i]\bW_i=\frac{1}{d}\sum_{i=1}^{d^2}\Tr(\bW_i \brhos)\bW_i+\frac{1}{d}\sum_{i=1}^{d^2}\E\left[z_{i}|\bW_i\right]\bW_i=\brhos,
    \end{align}
    where the last equation follows from~\eqref{eq:EzA} and the fact that $\frac{1}{d}\sum_{k=1}^{d^2}\Tr(\bW_i \brhos)\bW_i=\brhos$. Moreover, as $0\le y_t\le 1$ we have
     \begin{align}
     \lV d y_t\bA_t-\brhos \rV_2\le d\lV\bA_t\rV_2+\lV\brhos\rV_2 \le d+1, 
    \end{align}
    and 
    \begin{align}
        &~\lV\E[(d y_t\bA_t-\brhos)(d y_t\bA_t-\brhos)^{\dag}]\rV_2 
        = \lV\E[d^2y_t^2\bA_t\bA_t^{\dag}]-\E[dy_t\bA_t\brhos^{\dag}+d\brhos y_t\bA_t^{\dag}]+\brhos\brhos^{\dag}\rV_2 \cr 
        =&~\lV\sum_{i=1}^{d^2}\E\left[y_i^2|\bW_i\right]\bW_i\bW_i^{\dag}-\brhos\brhos^{\dag}\rV_2 \cr
    =&~\lV\sum_{i=1}^{d^2}\left(\Tr(\bW_i \brhos)^2+2\Tr(\bW_i \brhos)\E\left[z_i|\bW_i\right]+\E\left[z_i^2|\bW_i\right]\right)\bW_i\bW_i^{\dag}-\brhos\brhos^{\dag}\rV_2 \cr
         =&~\lV\sum_{i=1}^{d^2}\Tr(\bW_i \brhos)^2\bW_i\bW_i^{\dag}
         +\sum_{i=1}^{d^2}\E\left[z_i^2|\bW_i\right]\bW_i\bW_i^{\dag}-\brhos\brhos^{\dag}\rV_2 \cr
         \le &~\lV\sum_{i=1}^{d^2}\Tr(\bW_i \brhos)^2\bW_i\bW_i^{\dag}\rV_2
+\lV\sum_{i=1}^{d^2}\E\left[z_i^2|\bW_i\right]\bW_i\bW_i^{\dag}\rV_2+\lV\brhos\brhos^{\dag}\rV_2 \cr
\le &~ d+\frac{\varepsilon_0^2}{d}d^2+1=(\varepsilon_0^2+1)d+1,
    \end{align}
where the inequality follows from \Cref{lemma:Eerror}, $\lV \brhos\rV_{2}=1$ and 
    \begin{align*}
        \lV\sum_{i=1}^{d^2}\Tr(\bW_i \brhos)^2\bW_i\bW_i^{\dag}\rV_2
        \le \sum_{i=1}^{d^2}\Tr(\bW_i \brhos)^2\lV\bW_i\rV_2\lV\bW_i^{\dag}\rV_2\le d\sum_{i=1}^{d^2}\frac{1}{d}\Tr(\bW_i \brhos)^2\le d\lV \brhos\rV_{\fro}^2\le d.
        % &=\sup_{\lV \bm{a}\rV_2=1,\lV \bm{b}\rV_2=1} \sum_{i=1}^{d^2}\Tr(\bW_i \brhos)^2\bm{a}^{\dag}\bW_i\bW_i^{\dag}\bm{b}\cr
        % &\le \sup_{\lV \bm{a}\rV_2=1,\lV \bm{b}\rV_2=1} \sum_{i=1}^{d^2}\lV\bm{a}^{\dag}\bW_i\rV_{2}\lV\bW_i^{\dag}\bm{b}\rV_{2}
    \end{align*}
Therefore, letting the step size $\eta_t=\frac{\log d}{80d\log^2 d+t}$, by \cite[Theorem 3]{jain2016streaming} we have   
\begin{equation}\label{eq:uinierror}
    1-\lv \bu_{T_0}^{\dag}\bu_{\star} \rv^2\le C\left(\frac{2d\log d}{T_0}+\left(\frac{160d\log^2 d}{T_0}\right)^{2\log d}\right)\le \frac{\delta^2}{2}
\end{equation}
with probability at least $\frac{3}{4}$, provided $T_0\ge \max\{8C\delta^{-2} d\log d,160 C\delta^{-\frac{1}{\log d}} d\log^2 d\}$ for some universal constant $C>0$. Then, we have
\begin{align*}
\lVert\brho_0-\brhos \rVert_{\fro}^2 
&=\lVert\brho_0 \rVert_{\fro}^2+\lVert\brhos \rVert_{\fro}^2-2\Re\l\bu_{\star}\bu_{\star}^{\dag},\bu_{T_0}\bu_{T_0}^{\dag}\r \cr
&=2\left(1-\l\bu_{T_0}^{\dag}\bu_{\star},\bu_{T_0}^{\dag}\bu_{\star}\r\right)
=2\left(1-\lv \bu_{T_0}^{\dag}\bu_{\star} \rv^2\right) \le \delta^2,
\end{align*}
which completes the proof.
\end{proof}

\subsection{Proof of Corollary~\ref{col:onlineIni}}\label{sec:proofofinihp}
\begin{proof}
Denote $$\mathcal{S}:=\{j:  \lVert\brho_{T_0,j} -\brhos \rVert_{\fro}> \frac{\delta}{4}\}.$$ 
We first show that w.h.p. we have $|\mathcal{S}|\le \frac{J}{3}$. \par
Letting $T_0\ge C_0 \left(\frac{\delta}{4}\right)^{-2}d\log^2 d$. Then, for any fixed $j\in [J]$, by \Cref{thm:onlineIni}, it holds 
$$\lVert\brho_{T_0,j}-\brhos \rVert_{\fro}\le \frac{\delta}{4}$$
with probability at least $\frac{3}{4}$. We define the independent random variables
\begin{align*}
    \xi_{j}:=\mathbb{I}_{\{\lVert\brho_{T_0,j}-\brhos \rVert_{\fro}\le \frac{\delta}{4}\}},~j\in [J],
\end{align*}
where $\mathbb{I}_{\{\cdot\}}$ is the indicator function and $\mathbb{I}_{\{\mathbb{A}\}}=1$ if $\mathbb{A}$ is true, $\mathbb{I}_{\{\mathbb{A}\}}=0$ otherwise. Noticing that 
$\mathbb{E}[\xi_{j}]\ge\frac{3}{4}$, $j\in [J]$. By Hoeffding's inequality, we have
\begin{align*}
    \mathbb{P}\left(\frac{1}{J}\sum_{i=1}^{J}\xi_{j}-\E\left[\frac{1}{J}\sum_{i=1}^{J}\xi_{j}\right] \le -\varepsilon\right)\le e^{-2J\varepsilon^2},
\end{align*}
which implies
\begin{align*}
&~\mathbb{P}\left(\frac{1}{J}\sum_{i=1}^{J}\xi_{j}\le -\varepsilon+\frac{3}{4}\right) \cr
\le&~\mathbb{P}\left(\frac{1}{J}\sum_{i=1}^{J}\xi_{j}\le -\varepsilon+\E\left[\frac{1}{J}\sum_{i=1}^{J}\xi_{j}\right] \right)\cr
\le&~ e^{-2J\varepsilon^2}.
\end{align*}
By letting $\varepsilon=\frac{1}{12}$ and $J\ge 72\log d$, we have
\begin{align*}
    \mathbb{P}\left(\sum_{i=1}^{J}\xi_{j}> \frac{2J}{3}\right)>1- \frac{1}{d}.
\end{align*}
Therefore,
 \begin{align*}
    \mathbb{P}\left( |\mathcal{S}|\le \frac{J}{3}\right)
   & =\mathbb{P}\left(\sum_{j=1}^J \mathbb{I}_{\{\lVert\brho_{T_0,j}-\brhos \rVert_{\fro}\le \frac{\delta}{4}\}}\ge \frac{2J}{3}\right)\cr
    &=  \mathbb{P}\left(\sum_{i=1}^{J}\xi_{j}\ge \frac{2J}{3}\right)\ge 1-\frac{1}{d}.
\end{align*}
Now we prove the statement by the properties of the geometric median. Let $\mathrm{vec}(\cdot)$ be the vectorization operator. Noticing that 
$$\lV \brho-\brho_{T_0,j}\rV_{\fro}=\lV \mathrm{vec}(\brho)-\mathrm{vec}(\brho_{T_0,j})\rV_{2}$$
for all $j$, we know $\mathrm{vec}(\brho_{T_0})$ is the geometric median of $\{\mathrm{vec}(\brho_{T_0,j})\}_{j=1}^{J}$.
According to \cite[Lemma 24]{cohen2016geometric}, for $|\mathcal{S}|\le \frac{J}{3}$ we have
\begin{align*}
&~\lV\mathrm{vec}(\brho_{T_0})-\mathrm{vec}(\brhos)\rV_{2}\cr
\le&~ \frac{2J- |\mathcal{S}|}{J- 2|\mathcal{S}|}\max_{j\notin J}\lV\mathrm{vec}(\brho_{T_0,j})-\mathrm{vec}(\brhos)\rV_{2} \cr
\le&~ 4\max_{j\notin \mathcal{S}}\lV\brho_{T_0,j}-\brhos\rV_{\fro}\le \delta.
\end{align*}
Thus $\lV\brho_{T_0}-\brhos\rV_{\fro}\le\delta$. This completes the proof.
\end{proof}


\subsection{Key lemmas}\label{subsec:keylemmas}
Before we present the proof of \Cref{thm:Econtraction}, we first provide some technical lemmas.   Following the analysis illustrated in \Cref{sec:overview}, we examine the local smoothness of the squared distance function $\mathrm{dist}^2(\brho,\brhos)=\lV \bU\bU^{\dag}-\brhos\rV_\fro^2$, where $\brho=\bU\bU^{\dag}$.  
\begin{lemma}\label{lemma:Lip}
 The function $f(\bU)=\lV \bU\bU^{\dag}-\brhos\rV_\fro^2$ satisfies 
\begin{align*}
    \lv f(\bU+\bV)-f(\bU)-\Re\l\nabla f(\bU),\bV \r \rv\le L_C\lV \bV\rV_{\fro}^2
\end{align*}  
for all $\bU\in \mathcal{E}(\brho_\star,\delta\sigmas_r)$ and all $\lV\bV \rV_{\fro}\le C\sqrt{\sigmas_r}$, $C>0$. Here, $ L_C= (4\kappa+6\delta +2C\sqrt{\kappa+\delta}+C^2)\sigmas_r$.
\end{lemma} 
\begin{proof}
Through direct expansion, we have
 \begin{align*}
    &~\lv f(\bU+\bV)-f(\bU)-\Re\l\nabla f(\bU),\bV \r\rv\cr
    =&~\lv 2\Re\l \bU\bU^{\dag}-\brhos,\bV\bV^{\dag} \r+2\Re\l \bU\bV^{\dag}+\bV\bU^{\dag},\bV\bV^{\dag} \r+\lV \bU\bV^{\dag}+\bV\bU^{\dag} \rV_{\fro}^2+ \lV\bV\bV^{\dag} \rV_{\fro}^2\rv\cr
    \le &~2\lV\bU\bU^{\dag}-\brhos\rV_{\fro}\lV\bV\bV^{\dag} \rV_{\fro}
    +2\lV \bU\bV^{\dag}+\bV\bU^{\dag}\rV_{\fro}\lV \bV\bV^{\dag}\rV_{\fro}
    +\lV \bU\bV^{\dag}+\bV\bU^{\dag} \rV_{\fro}^2+ \lV\bV\bV^{\dag} \rV_{\fro}^2\cr
    \le &~ 2\lV\bU\bU^{\dag}-\brhos\rV_{\fro}\lV\bV \rV_{\fro}^2
    +2\lV \bU\rV\lV \bV\rV_{\fro}^3+4\lV \bU\rV^2\lV \bV\rV_{\fro}^2+\lV \bV\rV_{\fro}^4\cr
    =&~\left(2\lV\bU\bU^{\dag}-\brhos\rV_{\fro}
    +2\lV \bU\rV\lV \bV\rV_{\fro}+4\lV \bU\rV^2 +\lV \bV\rV_{\fro}^2\right)\lV \bV\rV_{\fro}^2,
 \end{align*}
where the first inequality follows from the Cauchy-Schwarz inequality, the second inequality follows from $\lV\bV\bV^{\dag} \rV_{\fro}\le \lV \bV\rV_{\fro}^2$. By Weyl's inequality, for all $\bU\in \mathcal{E}(\brho_\star,\delta)$  we have
\begin{align}\label{ineq:Uopup}
\lV \bU\rV^2=  \lV \bU\bU^{\dag}\rV \le \sigmas_1+\lV \bU\bU^{\dag}-\brhos\rV\le \sigmas_1+\lV \bU\bU^{\dag}-\brhos\rV_{\fro}\le \sigmas_1+ \delta\sigmas_r=(\kappa+\delta)\sigmas_r.
\end{align}
Therefore, 
\begin{align*}
   \lv f(\bU+\bV)-f(\bU)-\Re\l\nabla f(\bU),\bV \r\rv\le \left(2\delta\sigmas_r
    +2C\sqrt{\kappa+\delta}\sigmas_r+4(\kappa+\delta)\sigmas_r +C^2\sigmas_r\right)\lV \bV\rV_{\fro}^2,
 %L_C \lV \bV\rV_{\fro}^2,
\end{align*}
which completes the proof.
\end{proof}

\begin{lemma}\label{lemma:boundEGDnorm}
    For all $\bU\in \mathcal{E}(\brho_\star,\delta\sigmas_r)$, we have
    \begin{equation}
        \Re\l \left( \bU \bU^{\dag}- \brhos\right)\bU\bU^{\dag},\left( \bU \bU^{\dag}- \brhos\right)\r \ge \frac{1}{2}(1-\delta)^2\sigmas_r\lV\bU \bU^{\dag}- \brhos \rV_{\fro}^2.
    \end{equation}
\end{lemma}
\begin{proof}
    Let $\brhos$ and $\bU\bU^{\dag}$ has the compact SVD $\brhos=\bV_{\star}\bSigma_{\star}\bV_{\star}^{\dag}$, $\bSigma_{\star}\in \mathbb{C}^{r\times r}$, $\bV_{\star}\in \mathbb{C}^{d\times r}$, and $\bU\bU^{\dag}=\bV\bSigma\bV^{\dag}$, $\bSigma\in \mathbb{C}^{r\times r}$, $\bV\in \mathbb{C}^{d\times r}$.  We first notice that  
\begin{align*}
 \lV\bV_{\star,\perp}^{\dag}\bV \rV^2
 &\le \frac{1}{\sigma_r(\bSigma)}\lV\bV_{\star,\perp}^{\dag}\bV\bSigma^{1/2} \rV^2
 =\frac{1}{\sigma_r(\bSigma)}\lV\bV_{\star,\perp}^{\dag}\bV\bSigma\bV^{\dag}\bV_{\star,\perp} \rV\cr
 &\le\frac{1}{\sigma_r(\bSigma)}\lV\bV_{\star,\perp}^{\dag}(\bU\bU^{\dag}-\brhos)\bV_{\star,\perp} \rV_{\fro}\cr
 &\le \frac{1}{\sigma_r(\bSigma)}\lV\bU\bU^{\dag}-\brhos\rV_{\fro}\le \delta,
\end{align*}
where the second line follows from $\bV_{\star,\perp}^{\dag}\brhos=\bV_{\star,\perp}^{\dag}\bV_{\star}\bSigma_{\star}\bV_{\star}^{\dag}=\bm{0} $.Let $\theta$ be the  principal angle between $\bV_{\star}$ and $\bV$. Then $\sin^2\theta=\lV\bV_{\star,\perp}^{\dag}\bV \rV^2\le \delta$. Therefore, by \cite[Theorem 2.1]{zhu2013angles}, we have
\begin{equation}\label{ineq:boundVsVsig}
  \sigma_r^2(\bV_{\star}^{\dag}\bV)=\cos^2\theta=1-\sin^2\theta\ge 1-\delta.
\end{equation} 
Then, we have
\begin{align*}
%\lV(\bU \bU^{\dag}- \brhos)\bU\rV_{\fro}^2
%&=\lV\bV\bV^{\dag}(\bU \bU^{\dag}- \brhos)\bU\rV_{\fro}^2+\lV(\bI-\bV\bV^{\dag})(\bU \bU^{\dag}-\brhos)\bU\rV_{\fro}^2\cr
&~\Re\l \left( \bU \bU^{\dag}- \brhos\right)\bU\bU^{\dag}, \bU \bU^{\dag}- \brhos\r\cr
=&~ \Re\l \bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)\bV\bSigma\bV^{\dag}, \bU \bU^{\dag}- \brhos\r\cr
&~+\Re\l (\bI-\bV\bV^{\dag})\left( \bU \bU^{\dag}- \brhos\right)\bV\bSigma, (\bI-\bV\bV^{\dag})(\bU \bU^{\dag}- \brhos)\bV\r\cr
=&~ \Re\l \bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)\bV\bSigma, \bV\bV^{\dag}(\bU \bU^{\dag}- \brhos)\bV\r+\Re\l (\bI-\bV\bV^{\dag}) \brhos\bV\bSigma, (\bI-\bV\bV^{\dag}) \brhos\bV\r\cr
\ge &~ \sigma_r(\bSigma)\lV\bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)\bV\bV^{\dag}\rV_{\fro}^2+\sigma_r(\bSigma)\lV(\bI-\bV\bV^{\dag}) \bV_{\star}\bSigma_{\star}\bV_{\star}^{\dag}\bV \rV_{\fro}^2\cr
\ge&~ \sigma_r(\bSigma)\lV\bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)\bV\bV^{\dag}\rV_{\fro}^2+\sigma_r(\bSigma)\sigma_r^2(\bV_{\star}^{\dag}\bV)\lV(\bI-\bV\bV^{\dag}) \bV_{\star}\bSigma_{\star} \rV_{\fro}^2\cr
\ge&~ \sigma_r(\bSigma)\lV\bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)\bV\bV^{\dag}\rV_{\fro}^2+(1-\delta)\sigma_r(\bSigma)\lV(\bI-\bV\bV^{\dag}) \bV_{\star}\bSigma_{\star} \bV_{\star}^{\dag}\rV_{\fro}^2
\end{align*} 
where the first inequality follows from the fact that: for positive semidefinite matrices $\bm{C}$, $\bm{D}$, we have  $\mathrm{tr}(\bm{C}\bm{D})\ge \sigma_{\min}(\bm{C})\mathrm{tr}(\bm{D})$. The last inequality follows from \eqref{ineq:boundVsVsig}. By noticing that 
\begin{align*}
    &~\lV(\bI-\bV\bV^{\dag}) \bV_{\star}\bSigma_{\star} \bV_{\star}^{\dag}\rV_{\fro}^2
    =\frac{1}{2}\left(\lV(\bI-\bV\bV^{\dag}) \brhos\rV_{\fro}^2+\lV\brhos(\bI-\bV\bV^{\dag}) \rV_{\fro}^2\right)\cr
    =&~\frac{1}{2}\left(\lV(\bI-\bV\bV^{\dag}) \brhos \bV\bV^{\dag}\rV_{\fro}^2 +\lV \bV\bV^{\dag}\brhos(\bI-\bV\bV^{\dag}) \rV_{\fro}^2+2\lV (\bI-\bV\bV^{\dag})\brhos(\bI-\bV\bV^{\dag}) \rV_{\fro}^2 \right),
\end{align*}
we have
\begin{align*}
&~\Re\l \left( \bU \bU^{\dag}- \brhos\right)\bU\bU^{\dag}, \bU \bU^{\dag}- \brhos\r\cr
\ge &~ \frac{(1-\delta)\sigma_r(\bSigma)}{2}\Big(\lV\bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)\bV\bV^{\dag}\rV_{\fro}^2+ \lV(\bI-\bV\bV^{\dag}) \left( \bU \bU^{\dag}- \brhos\right) \bV\bV^{\dag}\rV_{\fro}^2 \cr
 &~+\lV \bV\bV^{\dag}\left( \bU \bU^{\dag}- \brhos\right)(\bI-\bV\bV^{\dag}) \rV_{\fro}^2+\lV (\bI-\bV\bV^{\dag})\left( \bU \bU^{\dag}- \brhos\right)(\bI-\bV\bV^{\dag}) \rV_{\fro}^2\Big)\cr
 \ge &~ \frac{(1-\delta)^2\sigmas_r}{2}\lV\bU \bU^{\dag}- \brhos \rV_{\fro}^2
\end{align*} 
where the second inequality follows from $(\bI-\bV\bV^{\dag})\bU \bU^{\dag}=0$, the last inequality follows from the Weyl's inequality, which gives for all $\bU\in \mathcal{E}(\brho_\star,\delta\sigmas_r)$, $\delta \in (0,1)$, we have
\begin{align}\label{ineq:Uopdw}
\sigma_r(\bSigma)=\sigma_r(\bU\bU^{\dag})\ge \sigmas_r-\lV \bU\bU^{\dag}-\brhos\rV\ge \sigmas_r-\lV \bU\bU^{\dag}-\brhos\rV_{\fro}\ge (1-\delta)\sigmas_r.
\end{align}
This completes the proof.
% For $\sigma_r(\bV_{\star}^{\dag}\bV)$, we consider the angle of its orthogonal complement 
% \begin{align}
%  \lV\bV_{\star,\perp}^{\dag}\bV \rV^2
%  &\le \frac{1}{\sigma_r(\bSigma)}\lV\bV_{\star,\perp}^{\dag}\bV\bSigma^{1/2} \rV^2
%  =\frac{1}{\sigma_r(\bSigma)}\lV\bV_{\star,\perp}^{\dag}\bV\bSigma\bV^{\dag}\bV_{\star,\perp} \rV\cr
%  &\le\frac{1}{\sigma_r(\bSigma)}\lV\bV_{\star,\perp}^{\dag}(\bU\bU^{\dag}-\brhos)\bV_{\star,\perp} \rV_{\fro}\cr
%  &\le \frac{1}{\sigma_r(\bSigma)}\lV\bU\bU^{\dag}-\brhos\rV_{\fro}\le \delta,
% \end{align}
% where the second line follows from $\bV_{\star,\perp}^{\dag}\brhos=\bV_{\star,\perp}^{\dag}\bV_{\star}\bSigma_{\star}\bV_{\star}^{\dag}=0 $. Let $\theta$ be the  principal angle between $\bV_{\star}$ and $\bV$. Then $\sin^2\theta=\lV\bV_{\star,\perp}^{\dag}\bV \rV^2\le \delta$. Therefore, by \cite[Theorem 2.1]{zhu2013angles}, we have
% \begin{equation*}
%   \sigma_r^2(\bV_{\star}^{\dag}\bV)=\cos^2\theta=1-\sin^2\theta\ge 1-\delta.
% \end{equation*} 
\end{proof}
We then obtain the following estimates, which include a perturbation bound as well as the regularity and smoothness conditions for the loss $\ell_t(\bU)$:
\begin{lemma}\label{lemma:boundSG}
For all $\bU\in \mathcal{E}(\brhos,\delta\sigmas_r)$,  under event \eqref{ineq:boundzt} it holds for all $t\ge 0$ that
    \begin{align}
\lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^2&\le 2 B^2\left(2r\lV\bU\bU^{\dag}-\brhos\rV_{\fro}^2+ \frac{\varepsilon_0^2}{d}\right)r(\kappa+\delta)\sigmas_r, \label{ineq:boundgd} \\
   \Re\l \nabla  f(\bU),\E[\nabla_{\bU}\ell_t(\bU)]\r&\ge\frac{2B}{d}  (1-\delta)^2\sigmas_r\lV\bU \bU^{\dag}- \brhos\rV_{\fro}^2,\label{ineq:boundEgd}\\
   \E[\lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^2] 
     &\le  \left[\frac{3B\max\{d,B\}}{d^2}\lV  \bU \bU^{\dag}- \brhos\rV_{\fro}^2+\frac{2B\varepsilon_0^2}{d}\right] r(\kappa+\delta)\sigmas_r, \label{ineq:Egrad2}\\
\E[\lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^4] 
    &\le 8 B^4\left(\frac{2re_t^4}{d}+\frac{\varepsilon_0^4}{d^2 }\right)r^2(\kappa+\delta)^2(\sigmas_r)^2.  \label{ineq:Egrad4}
\end{align}
\end{lemma}
\begin{proof}
We first prove \eqref{ineq:boundgd}. For all $\bU\in \mathcal{E}(\brho_\star,\delta\sigmas_r)$, we have
\begin{align}\label{ineq:proveboundgd}
   \lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^2
   &=\lV\sum_{k=1}^B \left[ \Tr(\bm{A}_{t,k} \bU \bU^{\dag})-y_{t,k} \right]\bm{A}_{t,k}\bU\rV_{\fro}^2\cr
   &\le \left(\sum_{k=1}^B \lv \Tr(\bm{A}_{t,k} \bU \bU^{\dag})-y_{t,k} \rv\lV\bm{A}_{t,k}\bU\rV_{\fro}\right)^2\cr
   &\le \left(\sum_{k=1}^B \lv \Tr(\bm{A}_{t,k}) \bU \bU^{\dag})-y_{t,k} \rv^2\right)\left(\sum_{k=1}^B\lV\bm{A}_{t,k}\bU\rV_{\fro}^2\right)\cr
   &\le 2\left( \sum_{k=1}^B \lv\l\bm{A}_{t,k}, \bU \bU^{\dag}-\brhos\r\rv^2+ \sum_{k=1}^B z_{t,k}^2 \right)\left(\sum_{k=1}^B\lV \bA_{t,k}\rV^2\lV\bU\bU^{\dag}\rV_{*}\right)\cr
   &\le 2\left(\sum_{k=1}^B\lV \bA_{t,k}\rV^2\lV\bU\bU^{\dag}-\brhos\rV_{*}^2+ \sum_{k=1}^B \frac{\varepsilon_0^2}{d}\right)B\lV\bU\bU^{\dag}\rV_{*}  \cr
   &\le 2 B^2\left(2r\lV\bU\bU^{\dag}-\brhos\rV_{\fro}^2+ \frac{\varepsilon_0^2}{d}\right)r(\kappa+\delta)\sigmas_r, 
\end{align}
where the second inequality follows from the Cauchy-Schwarz inequality, the third inequality follows from the inequality $\lV \bA_t\bU\rV_{\fro}^2=\l \bA_t\bA_t^{\dag},\bU\bU^{\dag} \r\le \lV\bA_t\rV^2\lV\bU\bU^{\dag}\rV_{*}$, the fourth inequality follows from the fact that $\bA_t$ is drawn from the set of standard Pauli matrices and thus $\lV\bA_t\rV\le 1$ (see \cite{liu2011universal}), the last inequality follows from~\eqref{ineq:Uopup} and the fact that 
\begin{align}
    \lV\bU\bU^{\dag}-\brhos\rV_{*}\le \sqrt{2r}\lV\bU\bU^{\dag}-\brhos\rV_{\fro},~\lV\bU\bU^{\dag}\rV_{*}\le r\lV\bU\rV^2.
\end{align}
Next, we prove \eqref{ineq:boundEgd}. For each $\bA_{t,k}$, $k\in [B]$ we have 
$$\E\left[\left( \Tr(\bm{A}_{t,k} \bU \bU^{\dag})-\Tr(\bW_i \brhos) \right)\bm{A}_{t,k}\bU\right]=\frac{1}{d^2} \sum_{i=1}^{d^2} \left[ \Tr(\bW_i \bU \bU^{\dag})-\Tr(\bW_i \brhos)\right]\bW_i\bU.$$
Thus,  by Lemma~\ref{lemma:Eerror} we have
  \begin{align}\label{eq:Egrad}
      \E[\nabla_{\bU}\ell_t(\bU)] 
      &=\frac{B}{d^2} \sum_{i=1}^{d^2} \left[ \Tr(\bW_i \bU \bU^{\dag})-\Tr(\bW_i \brhos)\right]\bW_i\bU - \sum_{k=1}^{B} \E[ z_{t,k} \bm{A}_{t,k}\bU]\cr
      &=\frac{B}{d}\left(\frac{1}{d}\sum_{i=1}^{d^2}\l \bU \bU^{\dag}- \brhos,\bW_i\r \bW_i \right)\bU-\sum_{k=1}^{B} \E[ z_{t,k} \bm{A}_{t,k}]\bU\cr
      &=\frac{B}{d}\left( \bU \bU^{\dag}- \brhos\right)\bU,
  \end{align}
and thus by \Cref{lemma:boundEGDnorm} we have
\begin{align*}
  \Re \l \nabla f(\bU),\E[\nabla_{\bU}\ell_t(\bU)]\r
   =&~ \Re\l 4\left( \bU \bU^{\dag}- \brhos\right)\bU,\frac{B}{d}\left( \bU \bU^{\dag}- \brhos\right)\bU\r \cr
   =&~\frac{4B}{2d}\Re\l \left( \bU \bU^{\dag}- \brhos\right)\bU\bU^{\dag},\bU \bU^{\dag}- \brhos \r\cr
    %\ge&~ \frac{B}{d}  \sigma_r(\bU\bU^{\dag})\lV\bU \bU^{\dag}- \brhos\rV_{\fro}^2\cr
   \ge&~ \frac{2B}{d}  (1-\delta)^2\sigmas_r\lV\bU \bU^{\dag}- \brhos\rV_{\fro}^2.
 \end{align*}
Now we prove \eqref{ineq:Egrad2}. Similar to \eqref{ineq:proveboundgd}, noticing that
for $\bU\in \mathcal{E}(\brho_\star,\delta)$, we have
\begin{align} \label{ineq:boundEgd2}
     &~\E\lV  \left[ \Tr(\bA_{t,k} \bU \bU^{\dag})-\Tr(\bA_{t,k} \brhos) -z_{t,k}\right]\bA_{t,k}\bU\rV_{\fro}^2\cr
      \le&~ \E \left[ \left(2\l\bA_{t,k}, \bU \bU^{\dag}- \brhos\r^2 +2 z_{t,k}^2\right)\lV\bA_{t,k}\bU\rV_{\fro}^2\right]\cr
      \le &~\left[\frac{2}{d^2}\sum_{i=1}^{d^2} \lv\l\bW_i, \bU \bU^{\dag}-\brhos\r \rv^2+\frac{2\varepsilon_0^2}{d}\right]\lV\bU\bU^{\dag}\rV_{*}\cr
      \le &~\left[\frac{2}{d}\sum_{i=1}^{d^2} \frac{1}{d}\lv\l\bW_i, \bU \bU^{\dag}-\brhos\r \rv^2+\frac{2\varepsilon_0^2}{d}\right]r\lV\bU\rV^2\cr
      \le&~ \left[\frac{2}{d}\lV  \bU \bU^{\dag}- \brhos\rV_{\fro}^2+\frac{2\varepsilon_0^2}{d}\right]r(\kappa+\delta)\sigmas_r,~ k\in [B] 
  \end{align}
where the last inequality follows from~\eqref{ineq:Uopup}. Thus, we have
 \begin{align} \label{ineq:sumEgrad2}
      &~\E[\lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^2] \cr
      = &~\E\lV  \sum_{k=1}^B \left[ \Tr(\bm{A}_{t,k} \bU \bU^{\dag})-y_{t,k} \right]\bm{A}_{t,k}\bU\rV_{\fro}^2\cr
      = &~ \sum_{k=1}^B\E\lV  \left[ \Tr(\bm{A}_{t,k} \bU \bU^{\dag})-y_{t,k} \right]\bm{A}_{t,k}\bU\rV_{\fro}^2\cr
      &~+\sum_{k_1\neq k_2}\l \E\left[ (\Tr(\bm{A}_{t,k_1} \bU \bU^{\dag})-y_{t,k_1}) \bm{A}_{t,k_1}\bU\right],\E\left[ (\Tr(\bm{A}_{t,k_2} \bU \bU^{\dag})-y_{t,k_2}) \bm{A}_{t,k_2}\bU\right] \r\cr
      =&~  \sum_{k=1}^B\E\lV  \left[ \Tr(\bm{A}_{t,k} \bU \bU^{\dag})-\Tr(\bA_{t,k} \brhos) -z_{t,k} \right]\bm{A}_{t,k}\bU\rV_{\fro}^2\cr
      &~+\sum_{k_1\neq k_2}\frac{1}{d^2}\l \left( \bU \bU^{\dag}- \brhos\right)\bU,\left( \bU \bU^{\dag}- \brhos\right)\bU\r\cr
       \le&~ B\left[\frac{2}{d}\lV  \bU \bU^{\dag}- \brhos\rV_{\fro}^2+\frac{2\varepsilon_0^2}{d}\right] r(\kappa+\delta)\sigmas_r+\frac{B^2-B}{d^2}\lV  \bU \bU^{\dag}- \brhos\rV_{\fro}^2(\kappa+\delta)\sigmas_r\cr
    = &~ \left[\frac{2dB+B^2-B}{d^2}\lV  \bU \bU^{\dag}- \brhos\rV_{\fro}^2+\frac{2B\varepsilon_0^2}{d}\right] r(\kappa+\delta)\sigmas_r\cr
      \le&~  \left[\frac{3B\max\{d,B\}}{d^2}\lV  \bU \bU^{\dag}- \brhos\rV_{\fro}^2+\frac{2B\varepsilon_0^2}{d}\right] r(\kappa+\delta)\sigmas_r,
  \end{align}
    where the first inequality follows from \eqref{ineq:Uopup} and~\eqref{ineq:boundEgd2}. 

    Finally, we prove \eqref{ineq:Egrad4}. By \eqref{ineq:Egrad2} and Cauchy-Schwarz inequality we have
\begin{align*}
\E[\lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^4] 
      &= \E\lV \sum_{k=1}^B \left[ \Tr(\bA_{t,k} \bU \bU^{\dag})-\Tr(\bA_{t,k} \brhos) -z_{t,k}\right]\bA_{t,k}\bU\rV_{\fro}^4\cr
      &\le\E \left[ \left(\sum_{k=1}^B\left( \Tr(\bA_{t,k} \bU \bU^{\dag})-\Tr(\bA_{t,k} \brhos) -z_{t,k}\right)^2\right)\left(\sum_{k=1}^B\lV\bA_{t,k}\bU\rV_{\fro}^2\right)\right]^2\cr
      &\le \E \left[ \sum_{k=1}^B\left(2\l\bA_{t,k}, \bU \bU^{\dag}- \brhos\r^2 +\frac{2\varepsilon_0^2}{d}\right) B\lV\bU\bU^{\dag}\rV_{*}\right]^2\cr
      &\le 8B \E \left[ \sum_{k=1}^B\left(\l\bA_{t,k}, \bU \bU^{\dag}- \brhos\r^4 +\frac{\varepsilon_0^4}{d^2}\right) \right] B^2\lV\bU\bU^{\dag}\rV_{*}^2\cr
      &\le 8B^3 \E \left[ \sum_{k=1}^B\left(2r e_t^2\l\bA_{t,k}, \bU \bU^{\dag}- \brhos\r^2 +\frac{\varepsilon_0^4}{d^2}\right) \right] \lV\bU\bU^{\dag}\rV_{*}^2\cr
      &\le 8B^4\left[\frac{2re_t^2}{d^2}\sum_{i=1}^{d^2} \lv\l\bW_i, \bU \bU^{\dag}-\brhos\r \rv^2+\frac{\varepsilon_0^4}{d^2}\right]r^2\lV\bU_t\rV^4\cr
      &\le 8 B^4\left(\frac{2re_t^4}{d}+\frac{\varepsilon_0^4}{d^2 }\right)r^2(\kappa+\delta)^2(\sigmas_r)^2,
  \end{align*}
where the fourth inequality follows from the fact that
$$\l\bA_{t,k}, \bU \bU^{\dag}- \brhos\r^4 \le \lV\bA_{t,k} \rV^2\lV \bU \bU^{\dag}- \brhos\rV_{*}^2\l\bA_{t,k}, \bU \bU^{\dag}- \brhos\r^2.$$
This completes the proof.
\end{proof}
\subsection{Proof of \Cref{thm:Econtraction}}\label{proofofEcontraction}
The estimations in \Cref{subsec:keylemmas} allow us to prove the local contraction property in expectation, and we present the proof of \Cref{thm:Econtraction} in the following.
\begin{proof}
We mainly use the local smoothness of $f(\bU)=\lV \bU\bU^{\dag}-\brhos\rV_\fro^2$ to derive the local contraction property. 
Let $C(\eta):=\eta B\sqrt{2\left(2r\delta^2(\sigmas_r)^2+ \frac{\varepsilon_0^2}{d}\right)(\kappa+\delta)r}$ and
\begin{align}\label{def:CLC}
 L_{C,\eta}:= (4\kappa+6\delta +2C(\eta)\sqrt{\kappa+\delta}+C^2(\eta))\sigmas_r.    
\end{align}
 For $\bU_t\in\mathcal{E}(\brhos,\delta\sigmas_r)$, by \eqref{ineq:boundgd} we know
$$\lV\eta\nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}\le  C(\eta)\sqrt{\sigmas_r}.$$
 Then, by the local smoothness of $f(\bU)$ (cf.~Lemma~\ref{lemma:Lip}) and the update rule~\eqref{eq:minibatchGD}, we have
  \begin{align*}
      \E[e_{t+1}^2|\mathcal{F}_t]&=\E\left[\lV \bU_{t+1}\bU_{t+1}^{\dag}-\brhos\rV_\fro^2\right]\cr
      &=\E\left[\lV (\bU_{t}- \eta \nabla_{\bU}\ell_{t+1}(\bU_t))(\bU_{t}- \eta \nabla_{\bU}\ell_{t+1}(\bU_t))^{\dag}-\brhos\rV_\fro^2\right]\cr
      &\le \lV \bU_t\bU_t^{\dag}-\brhos\rV_\fro^2-\eta \Re\l \nabla f(\bU_t),\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]\r+ L_{C,\eta}\eta^2\E\left[\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2\right]
  \end{align*}
Let $\delta=\frac{1}{3}$ and $B\le d$. Recall that $\lV\brhos\rV=1$,  $\sigmas_r=\frac{1}{\kappa}$. Then, provided $\eta \le \frac{1}{24\kappa r L_{C,\eta} }$,  by Lemma~\ref{lemma:boundSG} we have 
\begin{align*}
      \E[e_{t+1}^2|\mathcal{F}_t]
      \le&~ \lV \bU_t\bU_t^{\dag}-\brhos\rV_\fro^2- \frac{2\eta B}{d}  (1-\delta)^2\sigmas_r\lV\bU_t \bU_t^{\dag}- \brhos\rV_{\fro}^2 +\frac{3\eta^2 L_{C,\eta}B r(\kappa+\delta)\sigmas_r}{d}\lV  \bU_t \bU_t^{\dag}- \brhos\rV_{\fro}^2\cr
&~+\frac{2\eta^2B r L_{C,\eta}\varepsilon_0^2(\kappa+\delta)\sigmas_r}{d}  \le~(1-\frac{\eta B}{2\kappa d})e_t^2+\frac{\eta B\varepsilon_0^2}{8\kappa d}.
  \end{align*}
By the definition of $L_{C,\eta}$ in \eqref{def:CLC}, we have $L_{C,\eta}\le 7$ provided $\eta \le \frac{\kappa}{4B r}$. Therefore, for $B\le 40\kappa^2$, we let $\eta \le \frac{1}{168\kappa r}$, then $\eta \le \frac{\kappa}{4B r}$ and $\eta\le \frac{1}{24\kappa r L_{C,\eta} }$ hold simultaneously. For $B\ge 40\kappa^2$, we let $\eta \le \frac{\kappa}{5B r}$,  then $\eta\le \frac{1}{200\kappa r}\le \frac{1}{24\kappa r L_{C,\eta} }$ also holds. This completes the proof.
\end{proof}   
