\subsection{Proof of \Cref{thm:propconvergence}}\label{subsec:proofofprobconvergence}
The proof of \Cref{thm:propconvergence} follows from the standard Azuma-Bernstein inequality. Define the event
\begin{align}
    \mathfrak{E}_t := \left\{ e_{\tau}^2 \le \left(1 - \frac{\eta B}{4d\kappa}\right)^{\tau} 2e_0^2 + \left[ 1 - \left(1 - \frac{\eta B}{4d\kappa}\right)^{\tau} \right] \frac{\varepsilon_0^2 }{2}, \quad \forall \tau \le t \right\}.
\end{align}
First, we have the following results, Lemma~\ref{lemma:supermart} and Lemma~\ref{lemma:boundvar}, for supermartingale, which are crucial for the proof of \Cref{thm:propconvergence} due to the Azuma-Bernstein inequality.

\begin{lemma}\label{lemma:supermart}
Let  $\eta \le \frac{c_1}{\kappa r}$ and $B\le 10\kappa^2$. Define
\begin{align}
    F_t:= \left(1-\frac{\eta B}{2d\kappa}\right)^{-t}\max\left\{e_t^2 \cdot 1_{\mathfrak{E}_{t-1}}-\frac{\varepsilon_0^2}{4},0\right\},~t=0,1,2,\cdots.
\end{align}
Then, $F_t$ is a supermartingale, i.e., 
\begin{align*}
    \E\left[F_{t+1}|\mathcal{F}_t\right]&\le F_t, ~t=0,1,2,\cdots.
\end{align*} 
\end{lemma}
\begin{proof}
By the definition of $F_{t}$ we have
\begin{align}
    \E\left[F_{t+1}|\mathcal{F}_t\right]&= \left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\E\left[\max\left\{e_{t+1}^2 \cdot 1_{\mathfrak{E}_t}-\frac{\varepsilon_0^2}{4},0\right\}\Bigg|\mathcal{F}_t\right]\cr
    &\le \left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\max\left\{ \left(1-\frac{\eta B}{2d\kappa}\right)e_{t}^2\cdot 1_{\mathfrak{E}_t}-\left(\frac{\varepsilon_0^2}{4}-\frac{\eta B\varepsilon_0^2}{8\kappa d}\right),0\right\}\cr
    &\le \left(1-\frac{\eta B}{2d\kappa}\right)^{-t}\max\left\{  e_{t}^2\cdot 1_{\mathfrak{E}_{t-1}} -\frac{\varepsilon_0^2}{4},0\right\}=F_{t},
\end{align}
where the first inequality follows from the \Cref{thm:Econtraction}, the second inequality from $1_{\mathfrak{E}_t}\le 1_{\mathfrak{E}_{t-1}}$.
\end{proof}


\begin{lemma}\label{lemma:boundvar}
 Let  $\eta \le \frac{c_1}{\kappa r}$ and $B\le \min\{40\kappa^{2/3},d\}$, we have
\begin{align*}
    \lv\E\left[F_{t}|\mathcal{F}_{t-1}\right]- F_t\rv &\le c_3\eta \kappa r\left(1-\frac{\eta B}{2d\kappa}\right)^{-t}\left( \left(1- \frac{\eta B}{4d\kappa}\right)^{t}2e_0^2+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]\varepsilon_0^2\right),\cr
    \mathrm{Var}\left[F_{t}|\mathcal{F}_{t-1}\right]&\le \frac{c_4\eta^2B r}{d}\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t}\left( \left(1-\frac{\eta B}{4d\kappa}\right)^{2t}2e_0^4+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]^2 \varepsilon_0^4 \right),
\end{align*} 
for $t=0,1,2,\cdots$, where $c_3$, $c_4$ are positive numerical constants.
\end{lemma}

\begin{proof}
By~\eqref{ineq:boundgd} and~Lemma~\ref{lemma:Lip} we have
\begin{align*}
      \lv \E[e_{t+1}^2|\mathcal{F}_t]-e_t^2+\eta\Re \l \nabla f(\bU_t),\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]\r \rv
    \le \eta^2 L_{C,\eta}\E\left[\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2\right]
  \end{align*}
and
\begin{align*}
      \lv e_{t+1}^2-e_t^2+\eta \Re\l \nabla f(\bU_t),\nabla_{\bU}\ell_{t+1}(\bU_t)\r \rv
    \le \eta^2 L_{C,\eta}\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2,
  \end{align*}
thus,
\begin{align}\label{ineq:EF-F}
     \lv \E\left[F_{t+1}|\mathcal{F}_{t}\right]- F_{t+1}\rv
    & \le \left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\lv\E\left[e_{t+1}^2 \cdot 1_{\mathfrak{E}_t}\big|\mathcal{F}_t\right] -e_{t+1}^2 \cdot 1_{\mathfrak{E}_t} \rv\cr
    &\le\left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\Big( \lv\eta \Re\l \nabla f(\bU_t),-\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]+\nabla_{\bU}\ell_{t+1}(\bU_t)\r\rv\cr
    &\quad + \eta^2L_{C,\eta}\E\left[\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2\right]+\eta^2L_{C,\eta}\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2\Big)\cdot 1_{\mathfrak{E}_t}.
 \end{align}  
For the linear term, by \eqref{ineq:boundEgd} we have
\begin{align*}
  -\Re \l \nabla f(\bU_t),\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]\r\le - \frac{B}{2d}  (1-\delta)^2\sigma_r e_t^2,
\end{align*}
and
\begin{align*}
   &~\lv\Re\l \nabla f(\bU_t),\nabla_{\bU}\ell_{t+1}(\bU_t)\r \rv\cr
   =&~\lv\Re \l \left( \bU_{t} \bU_{t}^{\dag}- \brhos\right)\bU_{t}, \sum_{k=1}^B\left[ \Tr(\bm{A}_{t+1,k} \bU_{t} \bU_{t}^{\dag})-y_{t+1,k} \right]\bm{A}_{t+1,k}\bU_{t}\r\rv \cr
   \le&~\sum_{k=1}^B\lv\left[ \Tr(\bm{A}_{t+1,k} \bU_{t} \bU_{t}^{\dag})-\Tr(\bm{A}_{t+1,k} \brhos) -z_{t+1,k}\right]\rv\cdot\lv \l ( \bU_{t} \bU_{t}^{\dag}- \brhos)\bU_{t} \bU_{t}^{\dag},\bm{A}_{t+1,k}\r\rv\cr
   \le&~ \sum_{k=1}^B\left(\lV\bm{A}_{t+1,k}\rV\lV\bU_{t} \bU_{t}^{\dag}- \brhos\rV_{*}+\frac{\varepsilon_0}{\sqrt{d }}\right)\lV\bm{A}_{t+1,k}\rV\lV\left( \bU_{t} \bU_{t}^{\dag}- \brhos\right)\bU_{t} \bU_{t}^{\dag}\rV_{*}\cr
   \le&~ B\left(\sqrt{2r}\lV\bU_{t} \bU_{t}^{\dag}- \brhos\rV_{\fro}+\frac{\varepsilon_0}{\sqrt{d }}\right)\sqrt{r}\lV\bU_{t} \bU_{t}^{\dag}\rV\lV\bU_{t} \bU_{t}^{\dag}- \brhos\rV_{\fro}\cr
   \le&~ \sqrt{2}B(\kappa+\delta)\sigmas_r r e_t^2+\frac{\varepsilon_0 B(\kappa+\delta)\sigmas_r\sqrt{r}}{\sqrt{d}}e_t,
\end{align*}
where the third inequality follows from the fact that $\lV\left( \bU_{t} \bU_{t}^{\dag}- \brhos\right)\bU_{t} \bU_{t}^{\dag}\rV_{*}\le \sqrt{r}\lV\left( \bU_{t} \bU_{t}^{\dag}- \brhos\right)\bU_{t} \bU_{t}^{\dag}\rV_{\fro}$. For the quadratic term, by \eqref{ineq:boundgd} we have
  \begin{align*}
      \lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^2
      \le  B^2\left(4r e_t^2+ \frac{2\varepsilon_0^2}{d}\right)r(\kappa+\delta)\sigmas_r.
  \end{align*}
Therefore, together with \eqref{ineq:Egrad2} and \eqref{ineq:EF-F} we have
\begin{align*}%\label{ineq:EF-Fbound}
     \lv\E\left[F_{t+1}|\mathcal{F}_{t}\right]- F_{t+1}\rv 
   % \le&~\left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\Bigg( \Big|- \frac{\eta B}{d}  (1-\delta)\sigma_r e_t^2
   % +\sqrt{2}\eta B(\kappa+\delta)\sigmas_r r e_t^2+\frac{\eta B\varepsilon_0(\kappa+\delta)\delta(\sigmas_r)^2\sqrt{r}}{\sqrt{d}}\Big|\cr
    %&~ +  \frac{3\eta^2 B L_{C,\eta} r(\kappa+\delta)\sigmas_r e_t^2}{d} +\frac{2 \eta^2 B L_{C,\eta}\varepsilon_0^2(\kappa+\delta)\sigmas_r r}{d} 
    %+\eta^2 B^2 L_{C,\eta}\left(4r e_t^2 + \frac{2\varepsilon_0^2}{rd}\right) r(\kappa+\delta)\sigmas_r\Bigg)\cdot 1_{\mathfrak{E}_t}\cr
    \le&~ \tilde{c}_3\left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}(\eta^2 \kappa^2r^2e_t^2+\eta\kappa re_t^2+\frac{\eta^2\varepsilon_0^2\kappa^2 r^2}{d}+\frac{\eta\varepsilon_0\kappa \sqrt{r}}{\sqrt{d}}e_t)\cdot 1_{\mathfrak{E}_t} \cr
\le&~ \frac{c_3\eta\kappa r}{4} \left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\left(e_t+\frac{\varepsilon_0}{\sqrt{d}}\right)^2\cdot 1_{\mathfrak{E}_t}\cr
\le&~ \frac{c_3\eta\kappa r}{2}\left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\left( e_t^2+\frac{\varepsilon_0^2}{d}\right)\cdot 1_{\mathfrak{E}_t}\cr
\le&~ c_3\eta\kappa r\left(1-\frac{\eta B}{2d\kappa}\right)^{-t-1}\left( \left(1- \frac{\eta B}{4d\kappa}\right)^{t+1}2e_0^2+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t+1}\right]\varepsilon_0^2\right),
 \end{align*}   
for some universal constants $\tilde{c}_3, c_3>0$, provided $\eta\le\frac{c_1}{\kappa r}$, $B\le \min\{40\kappa^2, d\}$, and $\varepsilon_0\in (0,1)$.   In the last inequality, we have used the fact that $\left(1-\frac{\eta B}{4d\kappa}\right)^{-1}<\sqrt{2}$ as $c_1$ is sufficiently small, and $\frac{\varepsilon_0^2}{d}\le \frac{\varepsilon_0^2}{2}$.
By \eqref{ineq:Egrad2} and \eqref{eq:Egrad}, we have
\begin{align}\label{ineq:EgradEG}
   &~\E\left[\eta \Re\l \nabla f(\bU_t),\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]-\nabla_{\bU}\ell_{t+1}(\bU_t)\r\cdot 1_{\mathfrak{E}_t}\right]^2\cr
   \le &~\eta^2\lV \nabla f(\bU_t)\rV_{\fro}^2 \E\lV \E[\nabla_{\bU}\ell_{t+1}(\bU_t)]-\nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2\cdot 1_{\mathfrak{E}_t}\cr
   = &~\eta^2\lV \nabla f(\bU_t)\rV_{\fro}^2\left( \E\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2-\lV\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]\rV_{\fro}^2\right)\cdot 1_{\mathfrak{E}_t}\cr
   \le&~  4\eta^2  \lV\left( \bU_{t} \bU_{t}^{\dag}- \brhos\right)\bU_{t}\rV_{\fro}^2    \Bigg(\frac{3Br(\kappa+\delta)\sigmas_r}{d}\lV  \bU_{t} \bU_{t}^{\dag}- \brhos\rV_{\fro}^2+\frac{2Br\varepsilon_0^2(\kappa+\delta)\sigmas_r}{d} \cr
   &~-\frac{B^2}{d^2}\lV\left( \bU_{t} \bU_{t}^{\dag}- \brhos\right)\bU_{t}\rV_{\fro}^2\Bigg)\cdot 1_{\mathfrak{E}_t}\cr
   \le&~4\eta^2 (\kappa+\delta)\sigmas_r e_t^2\left( \frac{3Br(\kappa+\delta)\sigmas_r}{d} e_t^2+\frac{2Br\varepsilon_0^2 (\kappa+\delta)\sigmas_r}{d} \right)\cdot 1_{\mathfrak{E}_t}.
\end{align}

By \eqref{ineq:Egrad2}, we have 
\begin{align}\label{ineq:Egrad22}
\left(\E[\lV\nabla_{\bU}\ell_t(\bU)\rV_{\fro}^2]\right)^2 
      \le  \left[\frac{6B^2}{d^2}e_t^4+\frac{4B^2\varepsilon_0^4}{d^2}\right] r^2(\kappa+\delta)^2(\sigmas_r)^2. 
\end{align}
Thus, by \eqref{ineq:EF-F} and Cauchy-Schwarz inequality we have
  \begin{align*}
\mathrm{Var}\left[F_{t+1}|\mathcal{F}_{t}\right] 
=&~\E\left[\left(F_{t+1}-\E\left[F_{t+1}|\mathcal{F}_{t}\right]\right)^2\big|\mathcal{F}_{t}\right]\cr
\le&~  2\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\E\left[\eta \Re\l \nabla f(\bU_t),\E[\nabla_{\bU}\ell_{t+1}(\bU_t)]-\nabla_{\bU}\ell_{t+1}(\bU_t)\r\cdot 1_{\mathfrak{E}_t}\right]^2\cr
&~+2\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\eta^4\E\left[L_{C,\eta}\E\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2+L_{C,\eta}\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2
   \right]^2\cdot 1_{\mathfrak{E}_t}\cr
%\le&~\tilde{c}_4\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\left(\frac{\eta^2Br e_t^4}{d}+\frac{\eta^4 B^4r^3e_t^4}{d}+\frac{\eta^4\varepsilon_0^4B^4r^2}{d^2} +\frac{\eta^2\varepsilon_0^2Bre_t^2}{d}\right)\cr
\le&~\tilde{c}_4\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\frac{\eta^2 B r}{d}\left(e_t^4+\eta^2 B^3r^2e_t^4+\frac{\eta^2\varepsilon_0^4 B^3 r}{d}+\varepsilon_0^2e_t^2\right)\cdot 1_{\mathfrak{E}_t}\cr
\le&~\frac{c_4\eta^2Br}{8d}\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\left( e_t^2+\frac{\varepsilon_0^2}{2}\right)^2\cdot 1_{\mathfrak{E}_t}\cr
\le &~\frac{c_4\eta^2Br}{4d}\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\left( e_t^4+\frac{\varepsilon_0^4}{4}\right)\cdot 1_{\mathfrak{E}_t}\cr
\le &~\frac{c_4\eta^2Br}{d}\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\left( \left(1-\frac{\eta B}{4d\kappa}\right)^{2t+2}2e_0^4+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t+1}\right]^2 \varepsilon_0^4\right)
%\le &~\frac{c_4\eta^2\kappa^2r}{d}\left(1-\frac{\eta B}{2d\kappa}\right)^{-2t-2}\left( \left(1-\frac{\eta B}{4d\kappa}\right)^{2t}e_0^4+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]4\varepsilon_0^2 +\frac{\varepsilon_0^4}{r^2}\right),
  \end{align*}
for some universal constants $\tilde{c}_4, c_4>0$, provided $\eta\le\frac{c_1}{\kappa r}$, $B\le \min\{40\kappa^{2/3}, d\}$, and $\varepsilon_0\in (0,1)$. In the second inequality, we have used \eqref{ineq:EgradEG}, \eqref{ineq:Egrad4}, \eqref{ineq:Egrad22} and the fact 
\begin{align*}
   &~\E\left[L_{C,\eta}\E\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2+L_{C,\eta}\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2
   \right]^2\cdot 1_{\mathfrak{E}_t}\cr
   =&~L_{C,\eta}^2\E\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^4\cdot 1_{\mathfrak{E}_t}+3L_{C,\eta}^2\left[\E\lV \nabla_{\bU}\ell_{t+1}(\bU_t)\rV_{\fro}^2
   \right]^2\cdot 1_{\mathfrak{E}_t},
\end{align*}
and in the last inequality, we have used the fact that $\left(1-\frac{\eta B}{4d\kappa}\right)^{-2}<2$ as $c_1$ is sufficiently small.
\end{proof}

\begin{lemma}\label{lemma:propconverge}
   Let $\bU_0\in \mathcal{E}(\brho_\star,\delta)$. It holds
    \begin{align}\label{event:propconverge}
        \P\left(e_{t}^2\cdot 1_{\mathfrak{E}_{t-1}}>\left(1-\frac{\eta B}{4\kappa d}\right)^t 2e_0^2+\left[1-\left(1-\frac{\eta B}{2d\kappa}\right)^{t}\right]\frac{\varepsilon_0^2}{2}\right)\le d^{-10}.
    \end{align}  
provided $\eta \le \frac{c_2}{\kappa r\log d}$ and $B\le 40\kappa^{2/3}$ for some sufficiently small numerical constant $c_2>0$. 
\end{lemma}
\begin{proof}
  Let $\sigma^2 = \sum_{\tau=1}^t \mathrm{Var}\left[F_{\tau}|\mathcal{F}_{\tau-1}\right]$ and let $R$ satisfies  $ \lv\E\left[F_{\tau}|\mathcal{F}_{\tau-1}\right]-F_{\tau}\rv\le R$ almost surely for all $\tau\in [t]$.  By the standard Azuma-Bernstein inequality for supermartingales, we have
  \begin{align*}
      \P\left(F_t\ge F_0+\beta\right)\le \exp\left(\frac{-\beta^2/2}{\sigma^2+R\beta/3}\right),
  \end{align*} 
which implies
\begin{align*}
      \P\left[\max\left\{e_t^2\cdot 1_{\mathfrak{E}_{t-1}}-\frac{\varepsilon_0^2}{4},0\right\} \ge \left(1-\frac{\eta B}{2d\kappa}\right)^{t}\max\left\{e_0^2-\frac{\varepsilon_0^2}{4},0\right\}+\left(1-\frac{\eta B}{2d\kappa}\right)^{t}\beta\right]\le \exp\left(\frac{-\beta^2/2}{\sigma^2+R\beta/3}\right).
  \end{align*}
We consider only the non-trivial case. For $\beta= \sqrt{10\sigma^2\log d+\frac{100}{36}R^2\log^2 d}$, we have
  \begin{align*}
      \P\left[e_t^2 \cdot 1_{\mathfrak{E}_{t-1}}\ge \left(1-\frac{\eta B}{2d\kappa}\right)^{t}e_0^2+\left(1-\left(1-\frac{\eta B}{2d\kappa}\right)^{t}\right)\frac{\varepsilon_0^2}{4}+\left(1-\frac{\eta B}{2d\kappa}\right)^{t}\beta\right]\le d^{-10}.
  \end{align*}
As $\left(1-\frac{\eta B}{2d\kappa}\right)^{t}e_0^2\le \left(1-\frac{\eta B}{4d\kappa}\right)^{t}e_0^2$,  we only need to show that $\left(1-\frac{\eta B}{2d\kappa}\right)^{t}\beta \le \left(1-\frac{\eta}{4d\kappa}\right)^{t}e_0^2+  \left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]\frac{\varepsilon_0^2}{4}$ in the following.
In fact, provided $\eta\le \frac{c_2}{\kappa r \log d}$ with $c_2$ sufficiently small, by Lemma~\ref{lemma:boundvar} we have 
\begin{align*}
\left(1-\frac{\eta B}{2d\kappa}\right)^{2t}\sigma^2 
=&~ \left(1-\frac{\eta B}{2d\kappa}\right)^{2t}\sum_{\tau=1}^t \mathrm{Var}\left[F_{\tau}|\mathcal{F}_{\tau-1}\right]  \cr
\le&~ \sum_{\tau=1}^t \frac{c_4\eta^2Br}{d}\left(1-\frac{\eta B}{2d\kappa}\right)^{2t-2\tau}\left( \left(1-\frac{\eta B}{4d\kappa}\right)^{2\tau}2e_0^4+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{\tau}\right]^2 \varepsilon_0^4\right)\cr
\le&~  \left(1-\frac{\eta B}{4d\kappa}\right)^{2t}\sum_{\tau=1}^t \frac{c_4\eta^2Br}{d}\left(\frac{1-\frac{\eta B}{2d\kappa}}{1-\frac{\eta B}{4d\kappa}}\right)^{2t-2\tau}2e_0^4\cr
&~+\sum_{\tau=1}^t\left(1-\frac{\eta B}{2d\kappa}\right)^{2t-2\tau}\frac{c_4\eta^2Br}{d}\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]^2 \varepsilon_0^4 \cr
<&~ \frac{4c_2c_4}{\log d}\left(\left(1-\frac{\eta B}{4d\kappa}\right)^{2t}e_0^4+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]^2 \frac{\varepsilon_0^4}{2}\right),
\end{align*}
where the second inequality follows from $\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{\tau}\right]^2\le \left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]^2$ for $\tau \le t$, the last inequality follows from the fact that $\sum_{\tau =1}^{t}a^{2t-2\tau}=\frac{1-a^{2t}}{1-a^2}< \frac{1}{1-a^2}$ and hence $\sum_{\tau=1}^t\left(\frac{1-\frac{\eta B}{2d\kappa}}{1-\frac{\eta B}{4d\kappa}}\right)^{2t-2\tau}<\frac{2d\kappa}{\eta B}$, $\sum_{\tau=1}^t\left(1-\frac{\eta B}{2d\kappa}\right)^{2t-2\tau}<\frac{2d\kappa}{\eta B}$. Also, by Lemma~\ref{lemma:boundvar} we have
\begin{align*}
  \left(1-\frac{\eta B}{2d\kappa}\right)^{t}R < \frac{c_2c_3}{\log d}\left( \left(1- \frac{\eta B}{4d\kappa}\right)^{t}2e_0^2+\left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t+1}\right]\varepsilon_0^2\right). 
 \end{align*}
Noticing that $\beta\le \sqrt{10\sigma^2\log d}+\frac{10}{6}R\log d$, then for sufficiently small $c_2$ we have
 \begin{align*}
  \left(1-\frac{\eta B}{2d\kappa}\right)^{t}\beta \le \left(1-\frac{\eta B}{4d\kappa}\right)^{t}e_0^2+  \left[1-\left(1-\frac{\eta B}{4d\kappa}\right)^{t}\right]\frac{\varepsilon_0^2}{4}, 
 \end{align*}
 which completes the proof.
\end{proof}
\begin{proof}[Proof of \Cref{thm:propconvergence}]
By Lemma~\ref{lemma:propconverge}, we have for $\bU_0\in \mathcal{E}(\brho_\star,\delta)$ and any $t\ge 1$, it holds
 \begin{align*}
 \P\left(\mathfrak{E}_{t-1} \cap \mathfrak{E}_{t}^c\right) =      \P\left(\mathfrak{E}_{t-1} \cap \left\{e_{t}^2>\left(1-\frac{\eta B}{4\kappa d}\right)^t 2e_0^2+\left[1-\left(1-\frac{\eta B}{2d\kappa}\right)^{t}\right]\frac{\varepsilon_0^2}{2}\right\}\right)\le d^{-10}.
 \end{align*}
Thus, we have
\begin{align*}
 \P\left(\mathfrak{E}_{T}^c \right)\le \sum_{t=1}^T\P\left(\mathfrak{E}_{t-1} \cap \mathfrak{E}_{t}^c\right)\le \frac{T}{d^{10}}.
 \end{align*}
Finally, by a union bound together with event \eqref{ineq:boundzt}  for $t\in[T]$, we complete the proof. 
\end{proof}


