\title{When Does Diversity Matter? A Unified Framework for Binary-Choice Dynamics} 

\author{Arkadiusz J\k{e}drzejewski}
\email{arkadiusz.jedrzejewski@ua.pt}
\affiliation{Department of Physics \& I3N, University of Aveiro, 3810-193 Aveiro, Portugal}

