In order to gain intuition behind the extent of conservativeness incurred by the DRO formulation with a $\phi-$divergence based uncertainty set, we analyze what all distributions are included $\Dphi(P_0)$. A crucial difference is that, unlike the previous case, \textit{both} the tail strength of $P_0$ as well as the rate of increase of $\phi(\cdot)$ influence whether or not a distribution lies in $\Dphi(P_0)$. We point out that a similar result has been established in \cite{kruse2019joint} (see Proposition 4 therein). However, our  result is derived under significantly milder assumptions: we do not require the existence of densities for the reference model, nor do we place any asymptotic restriction of the tail cdf beyond that imposed by regular variation. 
In addition, we provide a constructive proof to showcase how the reference model may be exponentially twisted by a suitable amount
to arrive at distributions with heavier tails. 
\begin{proposition}\label{prop:f_div_contents}
    Suppose Assumption~\ref{assume:f-assume} holds. 
    \begin{enumerate}
        \item[(i)] There exists $P_1\in \Dphi(P_0)$ with $E_{P_1}[X] =\infty$, if $\phi(x) \sim x\log x$ and either Assumption~\ref{assume:heavy_tailed_data} holds, or Assumption~\ref{assume:weibullian_tails} holds with $\gamma< 1$. If instead $\phi\in \RV(p)$ and $P_0$ satisfies Assumption~\ref{assume:heavy_tailed_data} 
        with $\gamma< \frac{p}{p-1}$, there exists $P_1\in \Dphi(P_0)$ with $E_{P_1}[X]=\infty$. 
        \item[(ii)] Suppose that for some $p>1$, $\phi\in \RV(p)$, and let $P_0$ satisfy Assumption~\ref{assume:heavy_tailed_data}. Then, for any $\gamma^\prime > \frac{p-1}{p}\gamma$ there exists $\tilde P\in \Dphi(P_0)$ for which $\bar F_{\tilde P}\in \RV(-\gamma^\prime)$.
    \item[(iii)] Suppose the setup of part (ii) holds, but instead
    $P_0$ satisfies Assumption~\ref{assume:weibullian_tails}. Then, for any $\kappa>0$ there exists $\tilde P \in\Dphi(P_0)$ such that 
    \[
   \lim_{t\to \infty} \frac{\Lambda_{\tilde P}(t)}{\Lambda_{P_0}(t)}  = \left(\frac{p-1}{p}\right)+\kappa.
    \]
    % \item[(iv)] Conversely, any distribution whose density, call it $g(\cdot)$ satisfies  
    % \[
    % \limsup_{x\to\infty}\frac{g(x)}{[f(x)]^{\gamma_0}} >0
    % \]
    % for some $\gamma_0 > \frac{p-1}{p}$ does not
    % lie in $\Dphi(P_0)$ if $P_0$ satisfies Assumption~\ref{assume:heavy_tailed_data}. Any distribution whose density, call it $g(\cdot)$ satisfies
    % \[
    % \limsup_{x\to\infty }\frac{\log f(x)}{\log g(x)} > \frac{p-1}{p}
    % \]
    % does not lie in $\Dphi(P_0)$ if $P_0$ satisfies Assumption~\ref{assume:weibullian_tails}.
    \end{enumerate}
\end{proposition}
Note that whenever $\tilde P\in\Dphi(P_0)$, $C_{1-\beta}(\Dphi(P_0)) \geq C_{1-\beta}(\tilde P)$.
Proposition~\ref{prop:f_div_contents} can therefore be used to lower bound the worst case risk as follows:

\noindent \textbf{i)} First, suppose that $\phi(x) = x\log x-x+1$ (corresponding to Kullback-Liebler divergence). Since $C_{1-\beta}(P) \geq E_{P}[Z]$ for all $\beta>0$, part (i) of the above result suggests that $C_{1-\beta}(\Dphi(P_0)) = \infty$ when either (a) the distribution $P_0$ is heavy tailed, or (b) it is Weibullian with tails decaying slower than exponential. Similarly, if $P_0$ had sufficiently heavy tails (that is $\gamma$ is smaller than a threshold), $C_{1-\beta}(\Dphi(P_0))=\infty$.
The above observation echos the findings in \cite{jin2024constructing}, who argue that KL (or) polynomial divergences may not suited for DRO involving tail-risks, since these may lead to unreasonably large worst-case evaluations.  

\noindent \textbf{ii)} Next, suppose that $\phi\in \RV(p)$ (this class includes all polynomial divergences) and $P_0$ is heavy tailed, such that (ii) above holds. Then, there exists $P_1\in\Dphi(P_0)$ with $\bar F_{P_1}\in \RV(\gamma^\prime)$ for $\gamma^\prime = \frac{p}{p-1}\gamma - \kappa$. Then, $C_{\beta}(\Dphi(P_0)) \geq C_{1-\beta}(P_1)$. Since $\gamma^\prime<\gamma$ for all small enough choices of $\kappa$, Lemma~\ref{lem:CVaR_regularity} suggests that the worst case CVaR is orders of magnitude greater than $C_{1-\beta}(P_0)$.

\noindent \textbf{iii)} Suppose now that $P_0$ is light tailed, so that (iii) above holds.
Then, fixing a $\varepsilon>0$, note that there exists a distribution $\tilde P\in \Dphi(P_0)$  for which
\[
 \frac{\Lambda_{\tilde P}(t)}{\Lambda_{P_0}(t)} < \frac{p-1}{p} + \varepsilon , \ \forall t>t_0.
\]
Suppose $\beta$ is chosen small enough such that  $t_1=\Lambda_{\tilde P}^{\leftarrow}\log(1/\beta)>t_0$. Then, $\log(1/\beta) < \Lambda_{P_0}(t_1)(\frac{p-1}{p}+\varepsilon)$. Further, since $\Lambda_{P_0}\in \RV(1/\gamma)$ and is increasing, given any $\delta>0$, whenever $\beta$ is sufficiently small,
\[
v_{1-\beta}(\tilde P)>\left(\left(\frac{p}{p-1}\right) - \delta  \right)^{1/\gamma} v_{1-\beta}(P_0). 
\]
With $C_{1-\beta}(P_0) \sim v_{1-\beta}(P_0)$ (resp. $C_{1-\beta}(\tilde P) \sim v_{1-\beta}(\tilde P)$),   Lemma~\ref{lem:CVaR_regularity_Weibull} implies the following: for every $\kappa>0$, there exists a $\beta_0$ such that for all $\beta<\beta_0$,
\[
C_{1-\beta}(\Dphi(P_0)) >  \left(\left(\frac{p}{p-1}\right) - \kappa \right)^{1/\gamma}  C_{1-\beta}(P_0).
\]
Therefore if nominal distribution had light tails, $C_{1-\beta}(\Dphi(P_0))$ is (at least) a constant away from the evaluation under the nominal distribution. Further, this constant critically depends on both $p$ as well as the tail index of $P_0$.

% \noindent\textbf{iv)} Finally, part (iv) of Proposition~\ref{prop:f_div_contents} suggests that 
% when the tail of $P_1$ is heavier than that of $P_0$ to the extent that $F_{P_1}(x) = \omega([F_{P_0}(x)]^{p/(p-1)})$, then $P_1\not\in \Dphi(P_0)$. 

The next (somewhat technical) result which follows from a representation of CVaR due to \cite{acerbi2002coherence} helps derive a matching upper bound:
\begin{lemma}\label{lem:cvar_upper}
    For any uncertainty set $\mathcal P$ and $\beta>0$,
\begin{equation}\label{eqn:acerbi_characterisation}
    C_{1-\beta}(\mathcal P) \leq \beta^{-1}\int_{0}^\beta v_{1-t}(\mathcal P) dt.
\end{equation}
\end{lemma}
Lemma~\ref{lem:cvar_upper} suggests that the tail behavior of worst-case VaR influences the upper bound on worst case CVaR. In turn, evaluation of worst case VaR for $\phi-$divergence based uncertainty sets has been well studied (see \cite{glasserman2014robust,blanchet2020distributionally}). Applying these results leads to the following asymptotic characterization of worst case CVaR:

\begin{theorem}\label{thm:poly_divergence}
    Suppose Assumption~\ref{assume:f-assume} holds, and further $\phi\in \RV(p)$ for some $p>1$. 
    \begin{enumerate}
        \item[(i)]  If in addition Assumption~\ref{assume:heavy_tailed_data} holds with $\gamma > \frac{p}{p-1}$, then 
        \[
        \log C_{1-\beta}(\Dphi(P_0)) \sim \frac{p}{p-1} \log C_{1-\beta}(P_0) \text{ as $\beta\to 0$}.
        \]
        \item[(ii)] If Assumption \ref{assume:weibullian_tails} holds, then
        \[
        C_{1-\beta}(\Dphi(P_0)) \sim \left(\frac{p}{p-1}\right)^{1/\gamma} C_{1-\beta}(P_0) \text{ as $\beta\to 0$}.
        \]
    \end{enumerate}
\end{theorem}

Let us use Theorem~\ref{thm:poly_divergence} to compare the worst case and nominal evaluations of CVaR.
Consider two separate cases:

\noindent \textbf{i) When $P_0$ is heavy tailed:} Theorem~\ref{thm:poly_divergence} implies that $C_{1-\beta}(\Dphi(P_0)) =[C_{1-\beta}(P_0)]^{p/(p-1) +o(1)}$. This suggests that the worst case CVaR grows at a significantly faster rate than $C_{1-\beta}(P_0)$. 
A crucial difference from the case where uncertainty sets are defined using Wasserstein distance is that rate at which $C_{1-\beta}(\Dphi(P_0))$ grows depends on the tail of $P_0$ via $C_{1-\beta}(P_0)$. The intuition here is that the contents of $\phi-$divergence based uncertainty sets critically depend on both the tail of $P_0$, and as a result, so does the rate at which the worst case evaluation grows. 

\noindent \textbf{ii) When $P_0$ is Weibullian:} Here, $C_{1-\beta}(\Dphi(P_0))  =(p/(p-1) + o(1))^{1/\gamma} C_{1-\beta}(P_0)$. This suggests that the worst case CVaR is a constant times $C_{1-\beta}(P_0)$.
The reason is that when $P_0$ is Weibullian, $\phi$-divergence balls only contain distributions whose hazard functions are at most a constant away from the hazard function of $P_0$. This implies that while the  
 tail of the worst-case distribution $\Dphi(P_0)$ and that of $P_0$ decay at the same rate, albeit differing by a constant.
Note also how $\gamma$ influences the extent of conservativeness: the fatter the tail (small $\gamma$) the larger the gap between CVaR evaluation under the nominal and worst case distributions.


\begin{illustration}\label{illustrate:poly_div}\em
    In order to show the implications of the asymptotics from Theorem~\ref{thm:poly_divergence}, we numerically compute $C_{1-\beta}(\Dphi(P_0))$ and compare it with $C_{1-\beta}(P_0)$. The following duality result from \cite{shapiro2017distributionally} (see Section 3.2 therein) is useful to this end:
    \begin{equation*}
       \sup_{P\in \Dphi(P_0)} E[Z-u]^+ = \inf_{\lambda \geq 0,\eta } \left\{\eta+ \delta \lambda + \lambda E_{P_0}\left[\phi^*\left(\frac{(Z-u)^+-\eta}{\lambda}\right)\right]\right\},
    \end{equation*}
   where $\phi^*(s) = \sup_{t}\{st-\phi(t)\}$. Therefore, from \eqref{eqn:wc_cvar},
    \begin{equation}\label{eqn:phi_div_dual}
        C_{1-\beta}(\Dphi(P_0)) = \inf_{(u,\lambda) \geq 0,\eta } \left\{u+ \beta^{-1}\left(\eta+ \delta \lambda + \lambda E_{P_{0}}\left[\phi^*\left(\frac{(Z-u)^+-\eta}{\lambda}\right)\right]\right)\right\}.
    \end{equation}
The expectation above can be evaluated using a Monte-Carlo simulation, since $P_0$ is a known distribution. In Figure~\ref{fig:WC_evals}, we compare the worst case evaluation against CVaR evaluated at the nominal model. We set $\phi(t) = \frac{1}{2}(t-1)^2$, which corresponds to the $\chi^2-$divergence. The nominal distribution $P_0$ and budget parameter $\delta$ are as indicated in the respective sub-figure; the parameters of each distribution are as in Numerical Illustration~\ref{illustrate:wass_dro}.
 When $P_0$ is heavy tailed, observe that $C_{1-\beta}(\Dphi(P_0))$ grows polynomially in $(1/\beta)$ but a rate orders of magnitude larger than $C_{1-\beta}(P_0)$. Conversely, if $P_0$ is of a Weibullian type, then \textit{both} $C_{1-\beta}(\Dphi(P_0))$ and $C_{1-\beta}(P_0)$ appear to grow at the same rate, differing instead by a constant.

