\subsection{Data Driven Implementation} While the nominal distribution in \eqref{eqn:nominal_dist} leads to formulations which are $Q$-rate preserving, the quantities
$v_{1-\beta_0}(Q)$ and $\gamma$ still need to be estimated from data. 
Suppose $(Z_1,\ldots,Z_n)\sim Q$ are available
data samples 
from which $C_{1-\beta}(\Dphi(Q_\beta))$ has to be estimated. Let $ v_{1-\beta_0}(\hat Q^{(n)}) = Z_{(\lfloor n\beta_0\rfloor)}$, where $z_{(i)}$ is used henceforth to denote the $i$th largest element of the collection $\{z_1,\ldots,z_n\}$. 
\begin{lemma}\label{lem:intermidiate_var}
    Suppose  $\bar F_Q\in \RV$ (or) $\Lambda_Q\in \RV$ and let $\beta_0 = n^{-\kappa}$ for $\kappa\in (0,1)$. Then,
    \[
    \frac{ v_{1-\beta_0}(\hat Q^{(n)})}{v_{1-\beta_0}(Q)}\xrightarrow{a.s.} 1 \text{ as }  n\to\infty.
    \]
\end{lemma}
The intuition behind Lemma~\ref{lem:intermidiate_var} is that since $n\beta_0 \to \infty$, there are sufficient samples from which $v_{1-\beta_0}(Q)$ is estimated, even as $\beta_0\to 0$. Therefore the statistical errors associated in estimation of  are small. With the VaR at risk level $\beta_0$ estimated, the next task is to estimate the tail index.
Note that the choice of $\beta_0$ in Lemma~\ref{lem:intermidiate_var} satisfies $\beta_0\to 0$ as $n\to\infty$. Therefore, samples in excess of $v_{1-\beta_0}(\hat Q^{(n)})$ are representative of the distribution tail, and may be used in estimation of $\gamma$. 
When $\bar F_Q\in \RV$,  the Hill estimator (\cite{deHaan}, Chapter 3) can be used to this end:
\begin{equation}\label{eqn:hill_est}
    \hat\gamma_n = \left(\frac{1}{\lfloor n\beta_0 \rfloor} \sum_{i=1}^{\lfloor n\beta_0 \rfloor}\left(\frac{\log Z_{(i)}}{\log Z_{(\lfloor n\beta_0\rfloor+1)}}\right)\right)^{-1}. 
\end{equation}
 In case $\Lambda_Q\in \RV$, we estimate $\gamma $ as follows: 
\begin{equation}\label{eqn:lambda_lt}
    \hat \gamma_n = \frac{\log (1/\kappa)}{\log \left(\frac{Z_{(\lfloor n\beta_0(n)\rfloor)}}{Z_{(\lfloor n\beta_1(n)\rfloor)}}\right)}, \text{ where } \beta_1(n) = [\beta_0(n)]^{\kappa_1} \text{ for some }\kappa_1<1.
\end{equation}
In what follows, for ease of analysis, we assume that $n\beta_i$ is an integer for $i\in\{0,1\}$. We point out that the subsequent results go through even if this is not the case, but require more extensive notation.
With $v_{1-\beta_0}(Q)$ and $\gamma$ estimated, define  
\begin{equation}\label{eqn:sampled_measure}
d\hat Q_\beta^{(n)}(t)  = d\hat Q^{(n)}(t) \mv{1}(t\leq  v_{1-\beta_0}(\hat Q^{(n)})) +d\hat G_\beta^{(n)}(t)  \mv{1}(t> v_{1-\beta_0}(\hat Q^{(n)})),
\end{equation}
where $\hat Q^{(n)}$ is the empirical distribution of data and $\hat G_\beta^{(n)}$ as in \eqref{eqn:nominal_dist}, but with $\gamma$ and $v_{1-\beta_0}(Q)$ replaced by $\hat\gamma_n$ and $v_{1-\beta_0}(\hat Q^{(n)})$, respectively.
\begin{theorem}{\textbf{(Consistency of Data Driven DRO)}}\label{thm:consistency_of_dro}
        Suppose the data generating distribution $Q$ satisfies $\bar F_Q\in \RV$ (resp. $\Lambda_Q\in \RV$). Let $\hat Q_{\beta}^{(n)}$ be defined as in \eqref{eqn:sampled_measure}. Suppose that the target
        risk level 
        $\beta(n)\sim  c_0  n^{-q}$ for $c_0>0$, $q\geq 1$, and $\beta_0 = n^{-\kappa}$ for some $\kappa\in(0,1)$. Then if $\phi(\cdot)$ satisfies \eqref{eqn:phi_growth}, 
        % the sequence of ambiguity sets $\mathcal D_{\phi}(\hat P_{0,\beta_0}^{(n)})$ is $Q$-weakly (resp. strongly) rate preserving almost surely. In particular, this implies that
        in the statistically challenging regime where $\beta(n) \in O(1/n)$, $C_{1-\beta}(\Dphi (\hat Q_{\beta}^{(n)})) = [C_{1-\beta}(Q)]^{1+o(1)} $ (resp. $C_{1-\beta}(\Dphi(\hat Q_{\beta}^{(n)})) = (1+o(1)) C_{1-\beta}(Q)$) almost surely as $n\to\infty$. 
        % Finally if \eqref{eqn:second_order} holds, then even in the case where $Q$ is heavy tailed, we have $C_{1-\beta(n)}(\Dphi(\hat P_{0,\beta_0}^{(n)})) = (1+o_p(1))C_{1-\beta(n)}(Q)$.
\end{theorem}

\begin{algorithm}[h!] 
  \caption{Data-Driven Distributionally Robust CVaR Evalution}\label{alg:robust_cvar_estimation}
  % \DontPrintSemicolon
  \ \vspace{-2pt}\\
  \KwIn{Intermediate risk level $\beta_0,$ target level $\beta$, data samples
    $Z_1,\ldots,Z_n$}
      \noindent \textbf{1. Estimate tail Index and baseline VaR: }

      \noindent Estimate $\hat \gamma_n$ using \eqref{eqn:hill_est} if $\bar F_{Q}\in \RV$, and \eqref{eqn:lambda_lt} if  $\Lambda_Q\in \RV $. Set $ v_{1-\beta}(\hat Q^{(n)}) = Z_{(\lfloor n\beta_0\rfloor)}$.\\

       \noindent \textbf{2. Generate tail samples from nominal distribution: } 

        \noindent Draw samples $U_{1},\ldots U_{N}$ from the uniform distribution on $[1-\beta_0,1]$. For $i\in[N]$ set 
        \begin{equation}\label{eqn:inverse_samples}
            \tilde Z_i = \begin{cases}
         v_{1-\beta_0}(\hat Q^{(n)}) \left(\frac{1-U_i}{\beta_0}\right)^{-1/\hat \gamma_n} \quad\quad\quad\quad \ \ \text{ if $\bar F_{Q}\in \RV$}\\
         v_{1-\beta_0}(\hat Q^{(n)}) \left(\frac{\log(1-U_i)}{\log(\beta_0)}\right)^{1/\hat \gamma_n} \quad \quad\quad\quad\text{ if $\Lambda_{Q}\in \RV$}.
        \end{cases}
        \end{equation}
\ \\ 
\noindent \textbf{3. Evaluate Robust CVaR: } Return:
       \begin{align}\label{eqn:dro_estimate}
 \hat C_{1-\beta}^{(N)}(\Dphi(\hat{Q}_{\beta}^{(n)})) = \inf_{(u,\lambda) \geq 0,\eta } \Bigg\{u+ \beta^{-1}\Bigg(\eta+ \delta \lambda &+ \frac{\lambda}{n}\sum_{i=1}^{n} \phi^*\left(\frac{(Z_{i}-u)^+-\eta}{\lambda}\right)\mv{1}(Z_i\leq v_{1-\beta_0}(\hat Q^{(n)})) \nonumber\\
 &+  \frac{\beta_0\lambda }{N} \sum_{i=1}^N \phi^*\left(\frac{(\tilde Z_{i}-u)^+-\eta}{\lambda}\right)\Bigg)\Bigg\}.          
       \end{align}
    \end{algorithm}


While sample average approximation (SAA) does not rely on any parametric assumptions to define the nominal distribution, in order to 
estimate $C_{1-\beta}(Q)$ to within a relative error of $\varepsilon$ with at least $(1-\delta) \times 100\%$ confidence, order $\beta^{-1}\varepsilon^{-2}\delta^{-1} $ samples are required. Therefore  
SAA has a vanishing relative error only when $\beta(n) \in \omega (1/n)$. 
On the other hand, the proposed DRO is able to  produce an approximation which is representative of the true risk even for $\beta(n) \in O(1/n)$, despite the fact that the additional assumptions required to make it work are non-parametric in nature.


Algorithm~\ref{alg:robust_cvar_estimation}
implements our DRO formulation.
Recall that from the duality result \eqref{eqn:phi_div_dual},
\[
C_{1-\beta}(\Dphi(\hat Q_{\beta}^{(n)})) = \inf_{(u,\lambda)\geq 0,\eta} \left\{u+ \beta^{-1} \left( \eta+ \delta\lambda+  \lambda E_{\hat Q_{\beta}^{(n)}}\left[\phi^*\left(\frac{(Z- u)^+-\eta}{\lambda}\right)\right)\right]\right\}.
\]
The expression in \eqref{eqn:dro_estimate} aims to approximate the expectation in the display above using Monte-Carlo simulation.  
\begin{proposition}\label{prop:correctness_of_algo}
For any given problem instance (that is $n$, $\beta$ and $\beta_0$ fixed),  the output of Algorithm~\ref{alg:robust_cvar_estimation} is consistent in that $\hat C_{1-\beta}^{(N)}(\Dphi(\hat Q_{\beta}^{(n)})) \to C_{1-\beta}(\Dphi(\hat Q_{\beta}^{(n)}))$ as $N\to\infty$.
\end{proposition}
\begin{remark}\label{rem:IS}\em Proposition~\ref{prop:correctness_of_algo} demonstrates
that it is possible to approximate $C_{1-\beta}(\Dphi(\hat Q_\beta^{(n)}))$ to any degree of accuracy. 
To reduce the computational burden, one can use variance reduction techniques such as importance sampling  to solve the stochastic program \eqref{eqn:dro_estimate} (see \cite{deo2021efficient} for one potential implementation).
\end{remark}


