\section{Robust evaluation of distortion risk measures} \label{sec:distortion}
Consider risk measures $\rho_{g, 1-\beta}:\mathcal M(\R) \to \mathbb [0,\infty]$ defined as in \eqref{eqn:distortion_risk_measure}. Using integration by parts,
\begin{align}\label{eqn:rep_for_distortion_tail_risk}
    \rho_{g,1-\beta}(P) = \int_{0}^\infty g_{\beta}(\bar F_P(x))dx
    & = \beta^{-1}\int_{0}^\beta g^{\prime}(t/\beta) v_{1-t}(P) dt.
\end{align}
Setting the weighing function $g(x) =x^k$ allows a modeler to capture 
non-linearity in the perception of  tail risk through the choice of $k$. As a baseline, note that
$k=1$ corresponds to $\rho_{g,1-\beta} = C_{1-\beta}$ where an agent whose risk appetite  being modeled is neutral to tail risks (that is the weighing function in \eqref{eqn:rep_for_distortion_tail_risk} is constant).
% Suppose first that $k>1$. Here, $g^\prime$ is a \textit{increasing} function and therefore weighs regions deep into the tail less. This captures a risk seeking agent, whose evaluation of risk posed by tail events is less than the baseline case. If $k<1$, then $g^\prime $ is 
% a \textit{decreasing} function, and therefore weighs regions deep into the distribution tail more than the region around $t=\beta$. 
% This captures a risk averse modeler, whose evaluation of risk posed by tail events is larger than the baseline case. This is corroborated by the evaluation of the corresponding distortion risk measure which is less (resp. greater) 
% than CVaR for $k> 1$ (resp. $k<1$). 
By changing the value of $k$ and allowing for non-linear weights to be assigned to the tail quantiles in \eqref{eqn:rep_for_distortion_tail_risk}, one can capture either a risk seeking $(k>1)$ or risk averse $(k<1)$ behavior. 
In what follows, we demonstrate that the tail asymptotics for worst-case evaluation can be readily extended  
to this more general setup. As before, the first step is to understand the asymptotic behavior of $\rho_{g,1-\beta}$ as $\beta\to 0$ for a given $P_0$.
\begin{lemma}\label{lem:distortion_asymptotics}
    Suppose a distribution $P$ satisfies Assumption~\ref{assume:heavy_tailed_data} and $g(x) =x^k$ for some $k>1/\gamma$, $\rho_{g,1-\beta}(P)  \sim \frac{k\gamma}{k\gamma-1} U_P(1/\beta)$.
    If $\gamma>1$ in addition, we have that $\rho_{g,1-\beta}(P) \sim \frac{k(\gamma-1)}{\gamma k- 1} C_{1-\beta}(P)$. If instead $P$ satisfies Assumption~\ref{assume:weibullian_tails}, $\rho_{g,1-\beta}(P) \sim C_{1-\beta}(P)$.
\end{lemma}
\subsection{Asymptotics for worst-case risk} As a first step towards understand the behavior of distributionally robust distortion risk measures, we derive the asymptotic behavior of $\rho_{g,1-\beta}(\mathcal P)$. We consider two cases:

\noindent\textbf{Wasserstein Ambiguity:} When $\mathcal P =\mathcal W_{p,\delta}$, it turns out that the worst case risk has the following representation whenever $g(\cdot)$ is convex (see  \cite{wu2022generalization}, Proposition 2):
\[
\rho_{g,1-\beta}(\mathcal W_{p,\delta}) = \rho_{g,1-\beta}(P_0) + \delta \|g^\prime_\beta\|_{q} 
\]
where $1/p+1/q=1$ and if $p=1$, $q=\infty$,  and  $\|h\|_q = (\int_{0}^1 |h(x)|^q dx)^{1/q}$ is the $q-$norm of the function $h$.
This leads to the following bounds on the conservativeness of $\rho_{g,1-\beta}(\mathcal P)$:
\begin{proposition}\label{prop:Robust_distortion_measures}
 Suppose $g(x) = x^k$ for some $k\geq 1$. Then,
 \begin{enumerate}
     \item[(i)]  if in addition $P_0$ satisfies Assumption~\ref{assume:heavy_tailed_data} with $k>1/(p\gamma)$, 
     \[
 \lim_{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\mathcal W_{p,\delta})}{\log \rho_{g,1-\beta}(P_0)} = \frac{p}{\gamma}.
 \]
 \item[(ii)] If instead if in addition $P_0$ satisfies Assumption~\ref{assume:weibullian_tails}  
  \[
 \liminf_{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\mathcal W_{p,\delta})}{\log \rho_{g,1-\beta}(P_0)} = \infty.
 \]
 \end{enumerate}
  \end{proposition}



\noindent\textbf{$\phi-$divergence ambiguity:} Unfortunately, when $\mathcal P=\Dphi(P_0)$ it is not as straightforward to derive an exact characterization of $\rho_{g,1-\beta}(\mathcal P)$. However, note that paralleling Lemma~\ref{lem:cvar_upper}, the following bound holds:
\begin{equation}\label{eqn:ub_risk_measure}
    \rho_{g,1-\beta}(\mathcal P) \leq  \beta^{-1 }\int_{0}^\beta g^\prime(x/\beta) v_{1-t}(\mathcal P) dt.
\end{equation}
Since $v_{1-\beta}(\mathcal P)$ is relatively easy to characterize, a 
 lower bound to match
 \eqref{eqn:ub_risk_measure} can be derived as in Section~\ref{sec:divergence_dro} to yield the following asymptotic for worst case risk measure:
 \begin{proposition}\label{prop:Robust_distortion_measures_poly_divergence}
     In the setup of Proposition~\ref{prop:Robust_distortion_measures} let $\phi\in \RV(p)$ for some $p>0$. Then,
  \item[(i)]  if in addition $\bar F_Q\in \RV$,
        \[
        \log \rho_{g,1-\beta}(\Dphi(Q)) \sim \frac{p}{p-1} \log \rho_{g,1-\beta}(Q) \text{ as $\beta\to 0$}.
        \]
        \item[(ii)] If instead $\Lambda_Q\in \RV$,
        \[
        \rho_{g, 1-\beta}(\Dphi(Q)) \sim \left(\frac{p}{p-1}\right)^{1/\gamma}\rho_{g, 1-\beta}(Q) \text{ as $\beta\to 0$}.
        \]
\end{proposition}


