\subsection{Proofs From Section~\ref{sec:wass_dro}}
\noindent \textbf{Proof of Proposition~\ref{prop:wass_maximal}: }Note that the Wasserstein ball $\mathcal W_{p,\delta} \subset \mathcal M_p(\mathbb R)$, the set of distributions with finite $p-$th moment. The condition,
\[
\liminf_{x\to\infty} x^p \bar F_P([x,\infty)) > 0 
\]
implies that $\exists \varepsilon >0$ such that $\bar F_p(x) > \varepsilon x^{-p}$ for all large enough $x$. Then, note that the $p$-th moment of such a distribution is given by
\[
\int_{x} x^p dP(x) = \int_{x}x^{p-1} \bar F_P(x) dx > \int_{x>x_0}\varepsilon x^{-1}dx =\infty. 
\]
Therefore, $P\not\in \mathcal M_p(\mathbb R)$ and is therefore not in $\mathcal W_{p,\delta}$.

For the second part, fix a $\delta$, and suppose $\tilde P$ is a distribution with cdf $F_{\tilde P} = p_0 F_{P_0} + (1-p_0) F_{P_1}$, where $\bar F_{P_1}(x) = x^{-(p+\kappa)}$ for all $x>1$. 
Observe now that since $\bar F_{\tilde P}$ is the sum of two regularly varying functions, it too is regularly varying, with index $\max\{-\gamma, -(p+\kappa)\}$ (refer to \cite{deHaan}, Proposition B.1.9), where $\gamma$ is understood to be $+\infty$ if $\Lambda_{P_0}\in \RV$. 
Since $(p+\kappa)<\gamma$, the previous maximum equals $-(p+\kappa)$.

Next, notice that a coupling between $\tilde P$ and $P_0$ can be constructed by letting
$\tilde Z =  B Z + (1-B)Y$, where  $Y\sim P_1$, $Z\sim P$ and  $B$ is Bernoulli distributed with $P(B=1) = p_0$ 
and $Y$, $Z$ and $B$ are independent. Denoting this coupling by $\pi_0$, 
\begin{align*}
\inf_{\pi\in \Pi} E_{\pi}[d^p(\tilde Z,Z)]  & \leq   E_{\pi_0}\left[|Z-\tilde Z|^p\right]\\
& = E\left[E\left[|Z-\tilde Z|^p\mid B\right]\right] = (1-p_0)E[|Z-Y|^p].
\end{align*}
Since both $(Y,Z)$ have tail cdfs that are regularly varying with indices less than $-p$, they have finite $p$th order moments (see \cite{deHaan}, Exercise 16). The last expectation is hence finite. Thus, by choosing $p_0$ such that $(1-p_0)E[|Z-Y|^p]<\delta^p$, we have that $\tilde P\in \mathcal W_{p,\delta}$ and $F_{\tilde P}\in\RV(-(p+\kappa))$ which concludes the proof.\qed



\noindent\textbf{Proof of Proposition~\ref{prop:Dual_Mult}:} We complete the proof in two steps.

\noindent \textbf{Part 1 - $p>1$:} Fix $z$ and note that the first order condition implies that any maximizer of $g_{\lambda}(y) = (y-u)^+ -\lambda |y-z|^p$ satisfies
\begin{equation}\label{eqn:foc}
\mv{1}(y^*\geq u) = \lambda p |y^*-z|^{p-1} {\tt sgn}(y^*-z),    
\end{equation}
where ${\tt sgn}(x)$ is the sign function which takes the value $1$ if $x\geq0 $ and $-1$ otherwise.
Note that to solve \eqref{eqn:foc}, either $y^*<u$ and $y^* =z$ (so that both sides of \eqref{eqn:foc} equal $0$), or one must have that $y^*\geq u$, and
\begin{equation}\label{eqn:case_2}
    |y^*-z|^{p-1}{\tt sgn}(y^*-z) = \frac{1}{\lambda p}  \implies y^* = z+  (\lambda p )^{\frac{-1}{p-1}}.
\end{equation}
Let us analyze the solution case by case. 

\noindent \textbf{Case 1:} Let us first suppose that $z<\vartheta(u,\lambda)$. Then, if in addition, $z< u - (\lambda p)^{-\frac{1}{1-p}}$, $y_1^*= z$ is the only solution to \eqref{eqn:foc}, since then $ z+ (\lambda p )^{\frac{-1}{p-1}} < u$ and so \eqref{eqn:case_2} cannot hold. Next, suppose $z>u- (\lambda p )^{\frac{-1}{p-1}}$. In this case, both $y_1^*=z$ and $y_2^*=z+ (\lambda p )^{\frac{-1}{p-1}}$ solve \eqref{eqn:foc}. To evaluate the maximizer, we find that $g_\lambda(y_1^*)=0$ and 
\begin{align*}
    g_\lambda(y_2^*) &= \left(z-u +(\lambda p)^{\frac{-1}{p-1}}\right)^+  + \lambda (\lambda p )^{-\frac{p}{p-1}}\\
    & <  \left(\frac{1}{(\lambda p)^{\frac{1}{p-1}}} - \frac{1-1/p}{(\lambda p)^{\frac{1}{p-1}}}\right) - \frac{1}{p (\lambda p)^{\frac{1}{p-1}}} < 0
\end{align*}
where the last statement follows, since additionally $z< \vartheta(u,\lambda)$.
Thus  $y^*=z$ if $z<\vartheta(u,\lambda)$. Therefore, when $z<\vartheta(u,\lambda)$, $g(y^*)=0$.

\noindent \textbf{Case 2:} Now, suppose that $z> \vartheta(u,\lambda)$. Suppose in addition, $z\geq u$. Then the only solution to \eqref{eqn:foc} is $y^* = z+ {(\lambda p)^{-\frac{1}{p-1}}}$, since both
$y^*<u$ and $y^*=z$ is cannot hold. 
Finally, suppose $z< u$. In this case $y^*_1=z$ and $y^*_2 =z + (\lambda p)^{\frac{-1}{p-1}}$ \textit{both} satisfy \eqref{eqn:foc}. To find the supremum, we compare the function evaluation at each of
these values. Note that $g_\lambda(y_1^*) =0$ and 
 \begin{align*}
      g_{\lambda}(y^*_2) &= (z-u+(\lambda p)^{\frac{-1}{p-1}})^+ + \lambda(\lambda p)^{\frac{-p}{p-1}}\\
      & = z -\left(u - \frac{1-1/p}{(\lambda p)^{\frac{1}{p-1}}}\right) = (z-\vartheta(u,\lambda)) > 0
 \end{align*}
Therefore, $g(y^*) = (z-\vartheta(u,\lambda))$ when $z>\vartheta(u,\lambda)$.

\noindent  \textbf{Case 3:} Finally, suppose that $z =\vartheta(u,\lambda)$. Then, one can check that both $y^*_1 =z$ and $y_2^* = z+(\lambda p)^\frac{-1}{p-1}$ are optimal since $g(y^*_1) = g(y_2^*) = 0$.\\

Putting the above three cases together, $g(y^*) = (z-\vartheta(u,\lambda))^+$ 
\[
E_{P_0}\left[\sup_y\left\{(y-u)^+ -\lambda |y-Z|^p\right\}\right] = E_{P_0}\left[Z-\vartheta(u,\lambda)\right]^+.
\]
Substituting the above expression into \eqref{eqn:wass_duality},
\begin{align}\label{eqn:cvar_wass_expansion}
    C_{1-\beta}(\mathcal W_{p,\delta}) &= \inf_u\left\{u+ \beta^{-1}\inf_{\lambda}\left\{\lambda\delta^p + E_{P_0}[Z-\vartheta(u,\lambda)]^+ \right\} \right\}\nonumber\\
    & = \inf_{u,\lambda}\left\{u+ \beta^{-1}\lambda\delta^p + \beta^{-1} E_{P_0}[Z-\vartheta(u,\lambda)]^+\right\},
\end{align}
which concludes the proof.

\noindent \textbf{Part - II:} Suppose now $p=1$. Here, the inner optimization problem becomes 
\[
\sup_{y}\left\{(y-u)^+ - \lambda |y-z|\right\} =\sup_{y}g_\lambda(y).
\]
First, suppose that $\lambda<1$. Then for every large enough $y$, $(y-u)^+ -|y-z| = (1-\lambda)y -(u+\lambda z)$, and so the supremum above is $+\infty$. Next, let $\lambda > 1 $. Then observe that the only maximizer of $g_\lambda$ is $y^*=z$, since for $y\neq z$, one can verify that $g_\lambda(y) < g_\lambda(z)$. If instead $\lambda=1$, note that for any $c$, $y^* = z + c$ is a maximizer so long as $z>u$, else the above expression gets maximized at $y^*=z$. Putting all of the previous observations together, for $\lambda\geq 1$, $g_\lambda(y^*) = [z-u]^+$. Substituting this information into \eqref{eqn:cvar_wass_expansion} and recalling that $\vartheta(u,\lambda)=u$ if $\lambda>1$ and $-\infty$ otherwise,
\[
\sup_{y}\left\{(y-u) - \lambda |z-y|\right\} = [z-\vartheta(u,\lambda)]^+.
\]
Repeating the steps leading up to \eqref{eqn:cvar_wass_expansion} completes the proof.\qed



\noindent\textbf{Proof of Theorem~\ref{thm:wass_exact_characterisation}: }As before, we complete the proof in two parts

\noindent \textbf{Part 1 - } Suppose that $p>1$. Differentiate \eqref{eqn:cvar_wass_expansion} and set derivatives to $0$ to obtain that the optimal $(u^*,\lambda^*)$:
\begin{align*}
    \frac{\partial \varphi_\beta(u,\lambda)}{\partial u} = 0 &\implies \beta = \bar F_{P_0}(\vartheta(u^*,\lambda^*)), \\
    \frac{\partial \varphi_\beta(u,\lambda)}{\partial \lambda} = 0&\implies \beta^{-1} \delta^p = \beta^{-1}\bar F_{P_0}(\vartheta(u^*,\lambda^*))\left(\frac{1}{\lambda p}\right)^{p/(1-p)}.
\end{align*}
The first of the above equations implies that $\vartheta(u^*,\lambda^*) = v_{1-\beta}(P_0)$. The second hence implies 
\begin{align*}
    \lambda^* = \frac{1}{p}\left(\frac{\delta^p}{\beta}\right)^{(1-p)/p} \implies u^* +\lambda^* \delta^p \beta^{-1}& = u^* + 1/p \times (\delta/\beta^{1/p}) \\
    &= \vartheta(u^*,\lambda^*) + (\delta/\beta^{1/p}).
\end{align*}
Substituting $\vartheta(u^*,\lambda^*) = v_{1-\beta}(P_0)$,
\begin{align*}
    C_{1-\beta}(\mathcal W_{p,\delta}) &= v_{1-\beta}(P_0) + \beta^{-1}[Z-v_{1-\beta}(P_0)]^+  + (\delta^p/\beta)^{1/p}\\
    & = C_{1-\beta}(P_0) + (\delta/\beta^{1/p}). 
\end{align*}
\noindent \textbf{Part 2 -} Next, suppose that $p=1$. Here, 
note that $\nu(u,\lambda) = u$ if $\lambda\geq 1$ and equals $-\infty$ otherwise. Thus $E_{P_0}[Z-\vartheta(u,\lambda)]^+ = \infty$ whenever $\lambda<1$. As a consequence, $\lambda^*=1$  and $u^* =v_{1-\beta}(P_0)$. Plugging these values into \eqref{eqn:cvar_wass_expansion}
\[
C_{1-\beta}(\mathcal W_{p,\delta}) = C_{1-\beta}(P_0) + (\beta/\delta)^{-1},
\]
thereby completing the first part of the proof. 

To conclude recall that from Lemmas~\ref{lem:CVaR_regularity}-\ref{lem:CVaR_regularity_Weibull}, $C_{1-\beta}(P_0) = \beta^{-1/\gamma+o(1)}$ if $P_0$  satisfies Assumption~\ref{assume:heavy_tailed_data} and $C_{1-\beta}(P_0) = (\log(1/\beta))^{1/\gamma+o(1)}$ if $P_0$ satisfies Assumption~\ref{assume:weibullian_tails}. With $\gamma>p$ when Assumption~\ref{assume:heavy_tailed_data} holds, this further implies that $C_{1-\beta}(\mathcal W_{p,\delta})\sim (\delta/\beta^{1/p})$. Therefore,
\begin{align*}
   \lim_{\beta\to 0}\frac{\log C_{1-\beta}(\mathcal W_{p,\delta})}{\log C_{1-\beta}(P_0)} &=\frac{\gamma}{p} \quad\quad \text{ if $P_0$ satisfies Assumption~\ref{assume:heavy_tailed_data} and }\\
      \lim_{\beta\to 0}\frac{\log C_{1-\beta}(\mathcal W_{p,\delta})}{\log C_{1-\beta}(P_0)} &=\infty \quad\quad \text{ if $P_0$ satisfies Assumption~\ref{assume:weibullian_tails} }.
\end{align*}
\qed



\noindent \textbf{Proof of Proposition~\ref{prop:wc_transport_map}: }First suppose that $p>1$.
Fix $u$, and consider evaluation of the worst case expectation 
\[
\sup_{P\in \mathcal W_{p,\delta}} E_P[Z-u]^+ = \inf_{\lambda}\left\{\lambda\delta^p + E_{P_0}\left[\sup_{y}(y-u)^+-\lambda|Z-y|\right]\right\}.
\]
The supremum above is attained by a distribution supported on the set $\{(x,y): y\in\arg\max\{(y-u)^+-\lambda^*|y-x|^p\} $ where $\lambda^*=\lambda^*(u)$ solves the infimum on the right hand side above
(see \cite{blanchet2019quantifying}, Remark 2). From the proof of Proposition~\ref{prop:Dual_Mult}, the previous
arg-max is attained at 
\begin{equation}\label{eqn:wc_map_wass}
    y^* = 
z \mv{1}( z<\vartheta(u,\lambda^*)) +  
(z+ (\lambda^* p)^{\frac{-1}{1-p}} )\mv{1}(z\geq \vartheta(u,\lambda^*))
\end{equation}
if $p>1$.
Recall that from \eqref{eqn:wc_cvar},
\[
C_{1-\beta}(\mathcal W_{p,\delta}) = u^* + \beta^{-1}\sup_{P\in\mathcal W_{p,\delta}}E_{P}[Z-u^*]^+
\]
where $u^*$ is as defined in Theorem~\ref{thm:wass_exact_characterisation}.
Thus, distribution which attains the worst case CVaR is the one where $u$ in \eqref{eqn:wc_map_wass} is replaced by $u^*$. However from the proof of Theorem~\ref{thm:wass_exact_characterisation}, $\vartheta(u^*,\lambda^*) = v_{1-\beta}(P_0)$ and $(\lambda^* p)^{-1/(p-1)} = \delta/\beta^{1/p}$. Plugging these values above completes the proof when $p>1$.

When $p=1$, one instead has that $\lambda^*=1$, $u^*=v_{1-\beta}(P_0)$. Recall that from the proof of Proposition~\ref{prop:Dual_Mult}, the for $\lambda=1$, that worst-case transport map concentrates mass on the set
\[
    \bigcup_{c\geq 0}\left\{(x,y): y = x \mv{1}(x\leq u) + (x+c)\mv{1}(x>u)\right\}.
    \]
Substituting $u^*=v_{1-\beta}(P_0)$ completes the proof.\qed


\subsection{Proofs from Section~\ref{sec:divergence_dro}} 

The following technical result is key to the proofs in this section. Let $\bar F_{\tt wc}(x) = \sup\{\bar F_P(x) : P\in \Dphi(P_0)\}$.
\begin{proposition}{(\textbf{Proposition 3.3 from \cite{birghila2021distributionally}})}\label{prop:sol_of_inverse}
  Let the function $\phi(\cdot)$ satisfy Assumption~\ref{assume:f-assume}. Then the worst case tail-cdf satisfies
  \[
  \bar F_{\tt wc}(x) \sim \phi^{\leftarrow}(\delta/\bar F_{P_0}(x)) \bar F_{P_0}(x) \ \ \ \ \ \text{ as }x\to\infty
  \]
\end{proposition}
We also give Karamata's theorem below for reference: this result will be useful going ahead in evaluating integrals of regularly varying functions:

\begin{theorem}{\textbf{(Karamata's Theorem (\cite{deHaan}, Theorem B.1.5))}}\label{thm:Karamata}
  Let $f\in \RV(\rho)$ for some $\rho<-1$. Then, 
  \[
  \int_{x}^\infty f(t) dt \sim \frac{xf(x)}{-\rho-1}.
  \]
\end{theorem}
\noindent \textbf{Proof of Proposition~\ref{prop:f_div_contents}: } Let $\tilde P$ be a distribution whose likelihood with the nominal distribution $\mathcal L(x) = \frac{d\tilde P(x)}{dP_0}$ satsifies
which satisfies
\begin{equation}\label{eqn:tilde_f}
   \mathcal L(x) =  \mv{1}(x\leq m) + \psi(x)\mv{1}(x\geq m)
\end{equation}
where $\psi(\cdot)$ is a differentiable function.  
For each part, we demonstrate that an appropriate choice of $\psi$ and $m$ leads to the desired conclusion

\noindent \textbf{i) } Suppose that $\phi(x) \sim x\log x$, and suppose first that Assumption~\ref{assume:heavy_tailed_data} holds. Note that  
\begin{align*}
    E_{\tilde P}[X] &= \int_{0}^\infty F_{\tilde P}(x) dx = \int_0^\infty E_{P_0}\left[\mathcal L(Z) ; Z\geq x\right]dx \\
    &=\int_{0}^\infty \left[ \int_{x}^\infty \mathcal L^\prime(t) \bar F_{P_0}(t) dt  + \bar F(x)\mathcal L(x)\right]dx \geq \int_{0}^\infty \left[ \int_{x}^\infty \mathcal L^\prime(t) \bar F_{P_0}(t) dt\right]dx,
\end{align*}
where the third display above is the result of integrating by parts.
In the region $x<m$, $\mathcal L(x) =1$. 
Then, setting for $x>m$,
\[
\int_{x}^\infty \psi^\prime(t) \bar F_{P_0}(t) dt = \frac{c_0}{x \log x},
\]
$E_{\tilde P}[X]=\infty$. Here the constant $c_0>0$ is meant to ensure that $\mathcal L$ is a valid likelihood function.
Without loss of generality, we shall henceforth set $c_0=1$. Differentiating the above implies that 
\[
\psi^\prime(x) \bar F(x) = \frac{\log x+1}{x^2\log^2x} .
\]
Choose $m_0$ so large that $\phi(x) \leq (1+\varepsilon) x
\log x$ for all $m>m_0$. Now,
\begin{align*}
    \int_{x} \phi(\mathcal L(x)) dP_0(x) &\leq (1+\varepsilon) \int_{x>m} \psi(x) \log(\psi(x)) dP_0(x) \\
    & = (1+\varepsilon) \int_{x>m} \psi^\prime(x) \bar F_{P_0}(x) (\log \psi(x)+1)dx\\
    & =  (1+\varepsilon) \int_{x>m} \left(\frac{\log x+1}{x^2\log ^2x}\right)(\log \psi(x) +1)dx.
\end{align*}
where the last line above follows upon substituting the value of $\psi^\prime(x) \bar F_P(x) $. Now, notice that
since $\bar F_P \in \RV(-\gamma)$, dominated convergence implies that as $t\to\infty$,
\[
\psi(t) = \int \frac{\log t+1}{t^2 \bar F(t) \log^2 t} dt = \int \frac{1}{t^{2-\gamma+o(1)}} dt = t^{\gamma-1+o(1)}
\]
Then, whenever $t>m_1$, $\psi(t) \leq t^{\gamma-1+\varepsilon}$.
Consequently, for all $m>\max\{m_0,m_1\}$
\[
 \int_{x} \phi(\mathcal L(x)) dP_0(x) \leq (1+\varepsilon)\int_{x>m}\left(\frac{\log x+1}{x^2\log^2 x}\right)(\gamma+\varepsilon)\log(x)dx <\delta 
\]
This implies that $\tilde P\in \Dphi(P_0)$.

Next suppose that Assumption~\ref{assume:weibullian_tails} holds with $\gamma< 1$. Then, we have that $\bar F_P(t) = \exp(-t^{\gamma+o(1)})$ and $\psi(t) = \exp(t^{\gamma+o(1)})$, or $\log \psi(t) = t^{\gamma+o(1)}$. Then,
\[
 \int_{x} \phi(\mathcal L(x)) dP_0(x) \leq (1+\varepsilon) \int_{x>m} \left(\frac{\log x+1}{x^{2-\gamma-\varepsilon}\log^2x} \right) 
\]
Since $\gamma<1$, it is possible to choose $\varepsilon>0$ such that $2-\gamma-\varepsilon>1$. Therefore, the integral above can be made arbitrarily small by an appropriate choice of $m$, and $\tilde P\in\Dphi(P_0)$.\qed

% Set $f_1(x)  =  c_0 x^{-1} (\log x)^{-r}$ for some $r>1$. Note that a random variable with density $\tilde f$ as in \eqref{eqn:tilde_f} has infinite mean, since $x^{-1}\tilde f(x) \to \infty$ as $x\to\infty$ for any choice of $m$. Fix $\eta>0$, and observe that for any fixed $\varepsilon>0$, there exists an $x_0$ such that $\forall x>x_0$, $\phi(x) \leq (1+\varepsilon) x\log x$. Therefore,
% \begin{align*}
%     \int_{x} \phi(x) f_0(x) dx &\leq c_1 (1+\varepsilon) \int_{x>m} f_1(x) \log\left(\frac{f_1(x)}{f_0(x)}\right) dx \\
%     & = k(1+\varepsilon) \int_{x>m} x^{-1} (\log x)^{-r} \log\left(x^{\gamma}(\log x)^{-r} \right)dx
% \end{align*}
% Note that since $r>1$, we have that $(\log x)^{-r} \log\left(x^{\gamma}(\log x)^{-r} \right) = o((\log x)^{-1})$, which suggests that the last integral above can be made as small as desired upon setting $m$ sufficiently large. 

% Next, suppose that Assumption~\ref{assume:densities}(ii) holds, with $\gamma<1$. Then, choose any $f_1 \in \RV(-(\gamma+1))$, and note that here
% \begin{align*}
%     \int_{x} \phi(x) f_0(x) dx & \leq \int_{x} x^{-(\gamma+1)}s(x) \log(\exp(x^\gamma s_1(x))x^{-(\gamma+1)}s(x) )dx
% \end{align*} 
% Since $\gamma>0$, the above integral can be made as small as desired upon a suitable choice of $m$.
% Observing also that any distribution with density $\tilde f$ with $f_1$ as defined above has infinite mean completes the proof.

\noindent \textbf{ii) }
First, note that for every $t>m$ in \eqref{eqn:tilde_f}, integrating by parts,
\[
\tilde P(Z>t) = \int_{t}^\infty \mathcal L(x) dP_0(x) = \int_{t}^\infty \psi^\prime(x) \bar F_{P_0}(x) dx  + \psi(t) \bar F_{P_0}(t).
\]
Fix $\gamma^\prime$, and set $\psi^\prime(x) = c x^{\gamma-\gamma^\prime-1}$, where $c$ is an appropriate normalizing constant. Then with $\bar F_{P_0}\in \RV(-\gamma)$, $\psi^\prime F_{\bar P_0}\in \RV(-\gamma^\prime -1)$. Apply Karamata's theorem
to infer that $\tilde P(Z>t) \sim (\gamma^\prime-1)^{-1} t \psi^\prime(t) \bar F_{P_0}(t) + \psi(t) \bar F_{P_0}(t)$. Therefore $F_{\tilde P }\in \RV(-\gamma^\prime)$.   

Further, for any $\varepsilon>0$, for all $m$ large enough 
\begin{align*}
\int_x \phi\left(\mathcal{L}(x)\right) dP_0(x) dx &\leq  \int_{x>m} \psi^{p+\varepsilon}(x) dP_0(x)\\
    & =(p+\varepsilon) \int_{x>m} \psi^\prime(x) \psi^{p-1+\varepsilon}(x) \bar F_{P_0}(x)dx + \psi^{p+\varepsilon}(m)\bar F_{P_0}(m),
\end{align*}
where the second expression above is obtained by following the steps from part (i). 
By construction, $\psi(x) = c_1 x^{\gamma-\gamma^\prime}$. Substituting this in the last equation above:
\[
\int_x \phi\left(\mathcal{L}(x)\right) dP_0(x) dx \leq c_1(1+\varepsilon)\int_{x>m} x^{(p+\varepsilon)(\gamma-\gamma^\prime)-1}\bar F_{P_0}(x)+ m^{(\gamma-\gamma^\prime)(p+\varepsilon)}\bar F_{P_0}(m) dx. 
\]
Note that the  $x^{(p+\varepsilon)(\gamma-\gamma^\prime)-1}\bar F_{P_0}(x)$ is regularly varying with index $\theta=(p+\varepsilon-1)\gamma -(p+\varepsilon)\gamma^\prime-1$.
Note that for any $\gamma^\prime>\frac{p-1}{p}\gamma$, $\theta<-1$ whenever $\varepsilon$ is chosen small enough. Once again using Karamata's theorem,
\[
\int_{x>m} x^{(p+\varepsilon)(\gamma-\gamma^\prime)-1}\bar F_{P_0}(x) \sim  m^{(p+\varepsilon)(\gamma-\gamma^\prime)}\bar F_{P_0}(m) =o(m^{\theta+1}) \to 0 \text{ as }m\to\infty
\]
Hence, there exists $m$ large enough such that $\int_x \phi\left(\mathcal{L}(x)\right) dP_0(x)\leq \delta$, and $\tilde P \in \Dphi(P_0)$.\qed

\noindent \textbf{iii)} Here, for a large enough $t$, write
\[
\Lambda_{\tilde P}(x) = -\log \left(\int_{x>t} \psi^\prime(t)  e^{-\Lambda_{P_0}(x)}dx + \psi(t) e^{-\Lambda_{P_0}(t)}\right).
\]
Set $\psi^\prime(t) =  e^{-(c-1)\Lambda_{P_0}(x)}$ for some $c\in (0,1)$, which we will decide later. Then, 
\[
\Lambda_{\tilde P}(x) = -\log \left(\int_{x>t}   e^{-c\Lambda_{P_0}(x)} dx  + e^{-c\Lambda_{P_0}(t)} \right).
\]
Since $\Lambda_{P_0}\in \RV$, we may write the above using the Laplace principle as $\Lambda_{\tilde P}(x) \sim c \Lambda_{P_0}(x)$ as $x\to\infty$. 

Next, recall that from the previous part
\begin{align}
\int_x \phi\left(\mathcal{L}(x)\right) dP_0(x) dx 
    & =p(1+\varepsilon) \int_{x>m} \psi^\prime(x) \psi^{p-1}(x) \bar F_{P_0}(x) dx\nonumber\\
    & = p(1+\varepsilon)\int_{x>m}\psi^{p-1}(x) e^{-c\Lambda_{P_0}(x)} dx\label{eqn:divergence_ub}.
\end{align}
Now, observe that 
\[
\log \psi(x) = \log \int e^{-(c-1)\Lambda_P(t)} dt.
\]
With $c\in(0,1)$, the exponent above is dominated by $-(c-1)\Lambda(x)$ in the region $t\in[0,1]$. The following upper bound holds as a consequence:
\[
\log \psi(x)  \leq \log (c-1)^{-1} e^{-(c-1)\Lambda_{P}(x)} \sim (c-1)\Lambda_{P_0}(x) \quad \text{ as }x\to\infty .
 \]
Substituting the above in \eqref{eqn:divergence_ub},
\[
\int_x \phi\left(\mathcal{L}(x)\right) dP_0(x) dx \leq p(1+\varepsilon)\int_{x>m}  e^{-((c-1)(p-1)-c)\Lambda_{P_0}(x)}dx.
\]
If $(c-1)(p-1)-c >0$ then the above exponent can be made arbitrarily small by choosing $m$ sufficiently large. This in turn holds for any that $c> (p-1)/p$. This further implies that given any $\kappa>0$, there exists some $\tilde P$ with 
\[
\frac{\Lambda_{\tilde P}(x)}{\Lambda_{P_0}(x)} \sim \frac{p-1}{p}+\kappa.
\]\qed

\noindent \textbf{Proof of Lemma~\ref{lem:cvar_upper}: }Note that for any measure $P$, the following holds due to \cite{artzner1999coherent}:
\[
C_{1-\beta}(P) = \beta^{-1}\int_{0}^\beta v_{1-t}(P) dt.
\]
By definition, for any $P\in \mathcal P$ and $t\in(0,1]$, $v_{1-t}(P)\leq v_{1-t}(\mathcal P)$. Therefore,
\[
C_{1-\beta}(P) \leq \beta^{-1}\int_{0}^\beta v_{1-t}(\mathcal P) dt  \ \ \ \ \ \text{ for all } P\in\mathcal P.
\]
Since the right hand side above is a constant, taking the supremum over all $P\in \mathcal P$ yields $C_{1-\beta}(\mathcal P) \leq \beta^{-1}\int_{0}^\beta v_{1-t}(\mathcal P) dt$.\qed



\noindent \textbf{Proof of Theorem~\ref{thm:poly_divergence}:} \textbf{Upper Bound:} From \eqref{eqn:acerbi_characterisation},  
\[
C_{1-\beta}(\Dphi(P_0)) \leq \beta^{-1} \int_0^\beta v_{1-t}(\Dphi(P_0)) dt.
\]
Lemma~1 of \cite{blanchet2020optimal} implies that the worst-case quantile satisfies
\[
v_{1-t}(\Dphi(P_0)) = \bar F_{\tt wc}^{\leftarrow}(t),
\]
where $\bar F_{\tt wc}(x) = \sup_{P\in\Dphi(P_0)}P(Z>x)$.
 Applying Proposition~\ref{prop:sol_of_inverse},
\begin{equation}\label{eqn:wc_prob_asymptotics}
    \bar F_{\tt wc}(x) \sim \bar F_{P_0}(x)\phi^{\leftarrow}(\delta/\bar F_{P_0}(x)) =  \delta^{1/p} [\bar F_{P_0}(x)]^{1-1/p+o(1)}
\end{equation}
where the last statement follows since $\phi^\leftarrow\in \RV(1/p)$.

\noindent \textbf{i) }First, suppose that $\bar F_{P_0} \in \RV(-\gamma)$, and therefore, $\bar F_{\tt wc}\in \RV(-\gamma(1-1/p))$. Consequently, $v_{1-1/t}(\Dphi(P_0))$ is regularly varying with tail index $\gamma^\prime = \frac{p}{\gamma(p-1)}$. Changing variables as $r=1/t$, $dr = -t^{-2}dt$ and thus,
\[
\beta^{-1}\int_{0}^\beta v_{1-r}(\Dphi(P_0))dt  = \beta^{-1}\int_{1/\beta}^\infty t^{-2} v_{1-1/t}(\Dphi(P_0))dt.
\]
Note that $t^{-2}v_{1-1/t}(Q)$ is regularly varying with index $\gamma^\prime-2$. 
Since $\gamma > p/(p-1)$, $\gamma^\prime <1$  and $\gamma^\prime-2<-1$. Thus,  Karamata's Theorem shows that $\beta^{-1}\int_{0}^\beta v_{1-r}(\Dphi(P_0))dr$
is asymptotically equivalent to 
$\gamma^\prime/(1-\gamma^{\prime}) \times v_{1-\beta}(\Dphi(P_0))= (1/\beta)^{1/\gamma^\prime+o(1)}$.
Further, note that from Lemma~\ref{lem:CVaR_regularity}, $C_{1-\beta}(P_0) = (1/\beta)^{1/\gamma+o(1)}$. Using Lemma~\ref{lem:cvar_upper}, $C_{1-\beta}(\Dphi(P_0))$ is upper bounded by $(1/\beta)^{\gamma^\prime+o(1)}$. Therefore,
\begin{equation}\label{eqn:robust_ht_ub}
    \limsup_{\beta\to0 }\frac{\log C_{1-\beta}(\Dphi(P_0))}{\log C_{1-\beta}(P_0)}\leq \frac{p}{p-1}
\end{equation}



\noindent \textbf{ii) }Next suppose that $P_0$ satisfies Assumption~\ref{assume:weibullian_tails}. Then, $\Lambda_{P_0} \in \RV(\gamma)$, and \eqref{eqn:wc_prob_asymptotics} implies that 
\[
\log \bar F_{\tt wc}(x) \sim  \log \bar F_{P_{0}}(x) + \log  \phi^{\leftarrow}(\delta/\bar F_{P_0})  \implies  - \log \bar F_{\tt wc}(x) \sim \frac{p-1}{p}\Lambda_{P_0}(x).
\]
Let $x = v_{1-\beta}(\Dphi(P_0))$. Note that as $\beta\to 0$, $x\to \infty$, since $v_{1-\beta}(\Dphi(P_0)) \geq v_{1-\beta}(P_0) \to \infty$. Therefore,
\[
\frac{p}{p-1} \log(1/\beta) \sim \Lambda_{P_0}( v_{1-\beta}(\Dphi(P_0))).
\]
Since $\Lambda^{\leftarrow}_{P_0}\in \RV(1/\gamma)$, the above asymptotic results further in 
\[
\Lambda_{P_0} \left(\frac{p}{p-1} \log(1/\beta) \right) \sim v_{1-\beta_0}(\Dphi(P_0)) \implies \left(\frac{p}{p-1}\right)^{1/\gamma} v_{1-\beta}(P_0) \sim v_{1-\beta}(\Dphi(P_0)).
\]
where the implication follows as $\Lambda^{\leftarrow}(\log(1/\beta)) = v_{1-\beta}(P_0)$.
Then, using dominated convergence theorem, 
\[
\beta^{-1}\int_{0}^\beta v_{1-t}(\Dphi(P_0)) dt\sim  \left(\frac{p}{p-1}\right)^{1/\gamma} \beta^{-1}\int_{0}^\beta  v_{1-t}(P_0)dt =\left(\frac{p}{p-1}\right)^{1/\gamma}  C_{1-\beta}(P_0).
\]
Therefore
\begin{equation}\label{eqn:robust_lt_ub}
    \limsup_{\beta\to0 }\frac{C_{1-\beta}(\Dphi(P_0))}{C_{1-\beta}(P_0)}\leq \left(\frac{p}{p-1}\right)^{1/\gamma}.
\end{equation}

\noindent \textbf{Lower bound: }To prove the matching lower bound, fix a $\kappa>0$. First suppose that $P_0$ satisfies Assumption~\ref{assume:heavy_tailed_data}. Note that for the distribution $\tilde P$ constructed in the proof of Proposition~\ref{prop:f_div_contents}(ii),
$\bar F_{\tilde P}\in \RV(\gamma^\prime)$, where $\gamma^\prime = (\frac{p-1}{p}\gamma+\kappa)$. Thus, 
\[
\liminf_{\beta\to 0} \frac{\log C_{1-\beta}(\Dphi(P_0))}{\log C_{1-\beta}(P_0)} \geq \liminf_{\beta\to 0}\frac{\log C_{1-\beta}(Q_0)}{\log C_{1-\beta}(P_0)} = \frac{p}{p-1} - \kappa/\gamma.
\]
Since $\kappa$ was arbitrary, we have that
\begin{equation}\label{eqn:robust_ht_lb}
    \liminf_{\beta\to 0} \frac{\log C_{1-\beta}(\Dphi(P_0))}{\log C_{1-\beta}(P_0)} \geq \frac{p}{p-1}.
\end{equation}
Next, suppose that $P_0$ satisfies Assumption~\ref{assume:weibullian_tails}. Then for the distribution 
$\tilde P$ constructed in the proof of Proposition~\ref{prop:f_div_contents}(iii), for all $\beta<\beta_0$
\[
\frac{v_{1-\beta}(\tilde P)}{v_{1-\beta}(P_0)} \geq \left(\frac{p}{p-1}\right)^{1/\gamma} - \varepsilon
\]
Further, whenever $\Lambda_{Q}\in \RV$, $C_{1-\beta}(Q) \sim v_{1-\beta}(Q)$. Then, for all $\beta<\beta_0$,
\[
\frac{C_{1-\beta}(\tilde P)}{C_{1-\beta}(P_0)} \geq \left(\frac{p}{p-1}\right)^{1/\gamma} - 2\varepsilon.
\]
This implies that
\begin{equation}\label{eqn:robust_lt_lb}
    \liminf_{\beta\to 0} \frac{ C_{1-\beta}(\Dphi(P_0))}{ C_{1-\beta}(P_0)} \geq \left(\frac{p}{p-1}\right)^{1/\gamma} - 2\varepsilon.
\end{equation}
Since $\varepsilon$ was arbitrary,  combining \eqref{eqn:robust_ht_ub} and \eqref{eqn:robust_ht_lb} (resp. \eqref{eqn:robust_ht_ub} and \eqref{eqn:robust_lt_lb}) completes the proof. \qed



\subsection{Proofs from Section~\ref{sec:calib_uncert}} \
The following technical results are needed for proofs in this section: 

\begin{lemma}\label{lem:RVs_ht}
    Let $\log\beta_0 = c\log \beta$, and $\bar F_Q\in\RV(-\gamma)$. Then, for all $t\in(0,\beta]$, 
    \begin{equation}\label{eqn:RVs_ht}
        v_{1-t}(Q_{\beta}) = v_{1-\beta_0}(Q) \left(\frac{t}{\beta_0}\right)^{-1/\gamma}.
    \end{equation}
\end{lemma}

\begin{lemma}\label{lem:RVs_lt}
    Let $\log\beta_0 = c\log \beta$, and $\Lambda_Q\in \RV(\gamma)$. Then, for all $t\in(0,\beta]$, 
    \begin{equation}\label{eqn:RVs_lt}
        v_{1-t}(Q_{\beta}) = v_{1-\beta_0}(Q) \left( \frac{\log (1/t)}{\log(1/\beta_0)}\right)^{1/\gamma}.
    \end{equation}
\end{lemma}

\begin{lemma}\label{lem:consistency_of_gamma}
    Suppose that $\hat\gamma_n$ is given by \eqref{eqn:hill_est} if $\bar F_Q\in \RV(\gamma)$ and by \eqref{eqn:lambda_lt} if $\Lambda_Q\in \RV(\gamma)$. Then $\gamma$ is consistent, in that $\hat \gamma_n \xrightarrow{a.s.} \gamma$.
\end{lemma}

In addition, we need the following uniform version of Proposition~\ref{prop:sol_of_inverse} since in what follows, the nominal distribution is a function of the risk level $\beta$.
\begin{proposition}\label{prop:sol_of_inverse_unif}
    Let the conditions of Proposition~\ref{prop:sol_of_inverse} hold, and let $Q_\beta$ be given by \eqref{eqn:nominal_dist}. Then 
    \begin{equation}\label{eqn:sol_of_inverse_unif}
        \lim_{\beta\to 0}\sup_{x\geq v_{1-\beta_0}(Q)}\left\vert \frac{\bar F_{{\tt wc},\beta}(x) }{\phi^\leftarrow\left(\frac{\delta}{\bar F_{Q_\beta}(x)}\right)\bar F_{Q_\beta}(x)}  -1\right\vert =0
\end{equation}
where $\bar F_{{\tt wc},\beta}(x) = \sup\{ \bar F_P(x): {P\in \mathcal \Dphi(Q_\beta)}\}$ is the worst-case cdf.
\end{proposition}

