\noindent \textbf{Proof of Proposition~\ref{prop:rate_preserving_suffcient}: }  
Let us first suppose that $\bar F_Q\in \RV$

\noindent \textbf{i) Lower Bound:} Given $\varepsilon>0$, there exists $\beta_1$ such that
\begin{align}\label{eqn:lb_robust}
    \liminf_{\beta\to 0}\inf_{t\in(0,\beta]} \frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq 1 &\implies  \inf_{t\in(0,\beta]}  \frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq 1-\varepsilon, \quad \forall \beta<\beta_1\nonumber\\
\end{align}
This implies that for any such $\beta$, $\log v_{1-t}(Q_\beta) \geq (1-\varepsilon) \log v_{1-t}(Q)$ for all $ t\in (0,\beta]$.
Since $Q_\beta\in\mathcal Q_\beta$, $C_{1-\beta}(\mathcal Q_\beta) \geq C_{1-\beta}(Q_\beta)$. Therefore, 
\begin{align*}
    C_{1-\beta}(\mathcal Q_\beta)  &\geq \beta^{-1}\int_{0}^\beta v_{1-t}(Q_\beta)dt \geq \beta^{-1}\int_{0}^\beta [v_{1-t}(Q)]^{1-\varepsilon}dt\\
    &=\beta^{-1}\int_{(1/\beta)}^\infty r^{-2}[v_{1-1/r}(Q)]^{1-\varepsilon}dr.
\end{align*}
In the second inequality above $\beta$ is chosen to be smaller that $\beta_1$ defined in \eqref{eqn:lb_robust}. Now, note that $[v_{1-1/r}(Q)]^{1-\varepsilon}$ is regularly varying with tail index $(1-\varepsilon)/\gamma$. With $\gamma>1$, Karamata's theorem applies to yield that 
\[
\beta^{-1}\int_{0}^\beta r^{-2}[v_{1-1/r}(Q)]^{1-\varepsilon}dr \sim \frac{\gamma/(1-\varepsilon)}{\gamma/(1-\varepsilon)-1} [v_{1-\beta}(Q)]^{1-\varepsilon} \sim K [C_{1-\beta}(Q)]^{1-\varepsilon} 
\]
for some suitable constant $K$. Then, $\log C_{1-\beta}(\mathcal Q_\beta) \geq (1-\varepsilon)\log C_{1-\beta}(Q)$ for all $\beta$ sufficiently small, yielding that 
\[
\liminf_{\beta\to 0}\frac{\log C_{1-\beta}(\mathcal Q_\beta)}{\log C_{1-\beta}(Q)}\geq 1.
\]

\noindent \textbf{ii) Upper Bound: }
We get the following bound, similar to \eqref{eqn:lb_robust}: for any $\varepsilon>0$, there exists a $\beta_2$ such that for all $\beta<\beta_2$, 
\[
\log v_{1-t}(\mathcal Q_\beta) \leq (1+\varepsilon) \log v_{1-t}(Q).
\]
Recall that from Lemma~\ref{lem:cvar_upper}, $C_{1-\beta}(\mathcal Q_\beta) \leq \beta^{-1}\int_{0}^\beta v_{1-t}(\mathcal Q_{\beta})dt$. Consequently,
\begin{align*}
     C_{1-\beta}(\mathcal Q_\beta)  \leq \beta^{-1}\int_{(1/\beta)}^\infty r^{-2}[v_{1-1/r}(Q)]^{1+\varepsilon}dr.
\end{align*}
Once again  $[v_{1-1/r}(Q)]^{1+\varepsilon}$ is regularly varying with parameter $(1+\varepsilon)/\gamma <1$ (since $\gamma<1$ and $\varepsilon>0$ is arbitrarily small). 
Applying Karamata's theorem further yields $ \beta^{-1}\int_{(1/\beta)}^\infty r^{-2}[v_{1-1/r}(Q)]^{1+\varepsilon} \sim [v_{1-\beta}(Q)]^{1+\varepsilon} $. Lemma~\ref{lem:CVaR_regularity} now implies 
\[
C_{1-\beta}(\mathcal Q_\beta) \leq K_1 [C_{1-\beta}(Q)]^{1+\varepsilon} \text{ for all $\beta<\beta_0$}.
\]
Since $\varepsilon>0$ was arbitrary, it follows that
\[
\limsup_{\beta\to 0}\frac{\log C_{1-\beta}(\mathcal Q_\beta)}{\log C_{1-\beta}(Q)} \leq 1.
\]
Combining the two bounds $\log C_{1-\beta}(\mathcal Q_\beta) \sim \log C_{1-\beta}(Q)$.

\noindent \textbf{Case ii) $\Lambda_Q\in \RV$:} \noindent\textbf{i) Lower Bound} The first inequality in \eqref{eqn:suff_cond_lt} states that for every $\kappa>1$, there exists $\beta_2$ such that for all $\beta<\beta_2$,
$v_{1-t}(Q_\beta) \geq (1-\varepsilon)v_{1-t}(Q)$ 
for all $t\in (\beta^{\kappa},\beta]$. Therefore, 
\[
C_{1-\beta}(\mathcal Q_\beta) \geq \beta^{-1}\int_{0}^\beta v_{1-t}(Q_\beta) dt \geq (1-\varepsilon)\beta^{-1}\int_{\beta^{\kappa}}^\beta v_{1-t}(Q) dt.
\]
Write $v_{1-t}(Q) = \Lambda^{\leftarrow}(\log(1/t))$ above to get
\[
\beta^{-1} \int_{\beta^{\kappa}}^\beta v_{1-t}(Q) dt  =\beta^{-1}\int_{\beta^\kappa}^\beta \Lambda_Q^{\leftarrow}\left(\frac{\log(1/t)}{\log(1/\beta)}\log(1/\beta)\right)dt.
\]
Since $\Lambda^\leftarrow_Q\in \RV(1/\gamma)$, one has that $\Lambda^{\leftarrow}_Q(tx) \sim x^{1/\gamma}\Lambda^\leftarrow_Q(t)$ uniformly over $x\in[1,\kappa]$. Therefore,
\[
\beta^{-1}\int_{\beta^\kappa}^\beta  \Lambda_Q^{\leftarrow}\left(\frac{\log(1/t)}{\log(1/\beta)}\log(1/\beta)\right)dt \sim \beta^{-1}\int_{\beta^\kappa}^{\beta} \Lambda^{\leftarrow}_Q(\log(1/\beta)) \left(\frac{\log(1/t)}{\log(1/\beta)}\right)^{1/\gamma}dt .
\]
Change variables to $p=\log(1/t)$ in the integral above and evaluate it to 
\[
\beta^{-1}\frac{v_{1-\beta}(Q)}{\log^{1/\gamma}(1/\beta)} \left(\Gamma\left( \frac{1}{\gamma}+1,\log(1/\beta)\right) - \Gamma\left(\frac{1}{\gamma}+1, \kappa\log(1/\beta)\right)\right).
\]
Here $\Gamma(t,x)$ is the incomplete gamma function. Using the asymptotic $\Gamma(t,x) \sim x^{t-1}e^{-x}$ the above expression further simplifies to
$v_{1-\beta}(Q) \left(1-\beta^{\kappa-1}\right)$. Putting everything together, for all $\beta$ sufficiently small, 
\[
C_{1-\beta}(Q_\beta) \geq (1-\varepsilon) C_{1-\beta}(Q) 
\]
This suggests the lower bound 
\begin{equation}\label{eqn:lb_lt_suff}
    \liminf_{\beta\to 0}\frac{C_{1-\beta}(Q_\beta)}{C_{1-\beta}(Q)} \geq 1.
\end{equation}

\noindent \textbf{ii) Upper Bound} First recall that from Lemma~\ref{lem:ub_for_risk_measures}, $C_{1-\beta}(\mathcal Q_\beta) \leq\beta^{-1}\int_0^\beta v_{1-t}(\mathcal Q_\beta) dt$. Split the above integral as
\[
\int_0^\beta v_{1-t}(\mathcal Q_\beta) dt = \underbrace{\int_{\beta^\kappa}^\beta v_{1-t}(\mathcal Q_\beta) dt}_{(\textbf{a)}} +  \underbrace{\int_0^{\beta^\kappa} v_{1-t}(\mathcal Q_\beta) dt}_{(\textbf{b)}}  
\]
Let's analyze $\textbf{(a)}$ first. For this, we note that given $\varepsilon>0$, under the proposition assumptions, there exists $\beta_4$ such that for all $\beta<\beta_4$, 
\[
\sup_{t\in [\beta^\kappa,\beta]} \frac{v_{1-t}(\mathcal Q_\beta)}{v_{1-t}(Q)}\leq (1+\varepsilon).
\]
Therefore,  \textbf{(a)} above can be bounded for all $\beta<\beta_0$ by 
$(1+\varepsilon)\int_{0}^\beta \Lambda_Q^{\leftarrow}(\log(1/t)) dt$. As in the proof of the lower bound, the previous integral becomes 
\[
\frac{v_{1-\beta}(Q)}{\log^{1/\gamma}(1/\beta)} \Gamma\left( \frac{1}{\gamma}+1,\log(1/\beta)\right) \sim \beta v_{1-\beta}(Q).
\]
Then with $v_{1-\beta}(Q)\sim C_{1-\beta}(Q)$, for 
all $\beta<\beta_0$,
\[
\beta^{-1}\int_{\beta^\kappa}^\beta v_{1-t}(\mathcal Q_\beta) dt \leq (1+\varepsilon)v_{1-\beta}(Q)  \leq (1+\varepsilon)^2 C_{1-\beta}(Q)
\]
To handle \textbf{(b)}, note that 
under the assumptions of the proposition,
for all $\varepsilon>0$, there exists a $\beta_5$ such that for all $\beta<\beta_5$, $v_{1-t}(\mathcal Q_\beta) \leq  [v_{1-t}(Q)]^{1+\varepsilon}$ for all $t<\beta^\kappa$. Then, \textbf{(b)} can be upper bounded by 
\[
\int_0^{\beta^\kappa} (\log(1/t))^{1/\gamma+2\varepsilon} dt = \Gamma\left(\frac{1}{\gamma}+2\varepsilon , \kappa \log(1/\beta)\right).
\]
The incomplete gamma function above is asymptotically equivalent to $\beta^{\kappa} [\log(1/\beta)]^{1/\gamma+2\varepsilon}$. Putting this together with the bound in \textbf{(a)}, we have that 
\[
C_{1-\beta}(\mathcal Q_\beta) \leq (1+\varepsilon)^2 C_{1-\beta}(Q) + \beta^{\kappa-1}[\log(1/\beta)]^{{1/\gamma+2\varepsilon}} \leq ((1+\varepsilon)^2+\varepsilon)C_{1-\beta}(Q).
\]
Note that the latter bound above follows from Lemma~\ref{lem:CVaR_regularity_Weibull} which implies that $C_{1-\beta}(Q) = [  \log(1/\beta)]^{1/\gamma+o(1)}$. Since $\varepsilon$  was arbitrary, this implies that 
\[
\limsup_{\beta\to 0}\frac{C_{1-\beta}(\mathcal Q_\beta)}{C_{1-\beta}(Q)}\leq 1.
\]
Combining the upper bound above with \eqref{eqn:lb_lt_suff} completes the proof of the result.\qed




\noindent \textbf{Proof of Lemma~\ref{lem:lb_suff}: }\textbf{Case i) $\bar F_{Q}\in \RV$: }From Lemma~\ref{lem:cvar_upper}, $v_{1-t}(Q_\beta)= v_{1-\beta_0}(Q)(t/\beta_0)^{-1/\gamma}$. Since $\beta_0 = \beta^{c}$ for some $c\in (0,1)$ and $\bar F_{Q}\in \RV(-\gamma)$, $v_{1-\beta}(Q) = \beta^{1/\gamma+o(1)}_0$. Now
simplify the previous expression to $\beta_0^{o(1)}t^{-1/\gamma}$. 
This implies that for any $\varepsilon>0$, there exists a $\beta_1>0$ such that for all $t<\beta_1$, $v_{1-t}(Q_\beta) \geq t^{-1/\gamma+\varepsilon}$. Similarly, for all $t<\beta_2$, we have that $v_{1-\beta}(Q) \leq t^{1/\gamma+\varepsilon}$. Putting these two together,
\[
\frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq \frac{1-\gamma \varepsilon}{1+\gamma\varepsilon} .
\]
Owing to the uniformity of the above display over $t\leq  \min\{\beta_1,\beta_2\}$,
\[
\inf_{t\in(0,\beta]} \frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq \frac{1-\gamma \varepsilon}{1+\gamma\varepsilon}, \ \ \forall \beta<\min\{\beta_1,\beta_2\}.
\]
Therefore,
\[
\liminf_{\beta\to 0}\inf_{t\in(0,\beta]} \frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq \frac{1-\gamma \varepsilon}{1+\gamma\varepsilon} .
\]
Since $\varepsilon>0$ is arbitrary, the result is established for $\bar F_Q\in \RV$.

\noindent \textbf{Case ii) $\Lambda_Q\in \RV$: } Recall that from Lemma~\ref{lem:RVs_lt} $v_{1-t}(Q_\beta) =v_{1-\beta_0}(Q)(\log(t) /\log(\beta_0))^{1/\gamma}$. Further, with $\Lambda_Q^\leftarrow\in \RV(1/\gamma)$, Theorem B.1.9, \cite{deHaan} shows that
\[
\sup_{b\in [1,M]} \left\vert\frac{\Lambda_Q^{\leftarrow}(b\log (1/t))}{\Lambda_Q^{\leftarrow}(\log (1/t))}  -b^{1/\gamma}\right\vert \to 0,\  \text{ as }t\to 0.
\]
Hence, for any $\kappa>1$
\begin{align*}
    \sup_{t\in[\beta^\kappa,\beta]}\left \vert\frac{\Lambda^\leftarrow_Q(\log(1/t))}{\Lambda^\leftarrow_Q(\log(1/\beta)} - \left(\frac{\log t}{\log \beta}\right)^{1/\gamma}\right\vert \to 0.
\end{align*}
Fix $\varepsilon>0$. Then, there exists a $\beta_3>0$ such that for every $\beta<\beta_3$, 
\[
\frac{\Lambda^\leftarrow_Q(\log(1/t))}{v_{1-\beta}(Q)} \leq (1+\varepsilon)\left(\frac{\log t}{\log \beta}\right)^{1/\gamma} \ \forall t\in (\beta^\kappa,\beta].
\]
Therefore,
\[
\frac{v_{1-t}(Q_\beta)}{\Lambda_Q^\leftarrow(\log(1/t))} \geq \frac{1}{(1+\varepsilon)} v_{1-\beta_0}(Q)\left(\frac{\log(1/\beta)}{\log(1/\beta_0)}\right)^{1/\gamma} .
\]
Set $\log \beta_0= c\log \beta$,  and note that there exists a $\beta_4$ such that whenever $\beta_0<\beta_4$, $v_{1-\beta}(Q) \geq (1-\varepsilon) c^{-1/\gamma} v_{1-\beta_0}(Q) $. Then 
for all $t<\min\{\beta_3,\beta_4^{1/c}\}$,
\[
\frac{v_{1-t}(Q_\beta)}{\Lambda_Q^\leftarrow(\log(1/t))} \geq  \frac{1-\varepsilon}{1+\varepsilon}.
\]
This implies that 
\[
\inf_{t\in[\beta^\kappa,\beta]} \frac{ v_{1-t}(Q_\beta)}{ v_{1-t}(Q)} \geq \frac{1- \varepsilon}{1+\varepsilon}, \ \ \forall \beta<\min\{\beta_3, \beta_4^{1/c}\}.
\]
Since $\varepsilon$ is arbitrary, 
\[
\liminf_{\beta\to 0}\inf_{t\in[\beta^\kappa,\beta]} \frac{v_{1-t}(Q_\beta)}{v_{1-t}(Q)} \geq 1. \qed
\]
\noindent \textbf{Proof of Theorem~\ref{thm:scale_preserving_dro}: }\noindent  \textbf{i)} 
To complete the proof, it is only necessary to establish the upper bound in Proposition~\ref{prop:rate_preserving_suffcient}, since the corresponding
lower bound has already been established in Lemma~\ref{lem:lb_suff}. As usual, we consider two cases:


\noindent \textbf{Case i) $\bar F_Q\in \RV$: }
From Proposition~\ref{prop:sol_of_inverse_unif} the worst case tail-cdf in $\Dphi(Q_{\beta})$ satisfies 
\begin{equation}\label{eqn:prop_asymptotics}
    \bar F_{\tt wc,\beta}(x) \sim \phi^{\leftarrow}\left(\frac{\delta}{\bar F_{Q_{\beta}}(x)}\right) \bar F_{Q_{\beta}}(x),
\end{equation}
where the $\sim$ above is to be understood as uniform convergence over $x\in[v_{1-\beta_0}(Q),\infty)$ from Proposition \ref{prop:sol_of_inverse_unif}. 
Note that $x_t = v_{1-t}(\Dphi(Q_{\beta})) \geq v_{1-t}(Q_{\beta})$. Consequently, both $x_t\to\infty$ as $t\to\infty$, and  $x_t \geq  v_{1-\beta_0}(Q)$ whenever $t\in(0,\beta]$. Substituting $x=x_t$ in \eqref{eqn:prop_asymptotics}, 
\[
    \frac{1}{t}\sim \frac{1}{\phi^{\leftarrow}\left(\delta/\bar F_{Q_{\beta}}(x_t)\right) \bar F_{Q_{\beta}}(x_t)} = w\left(\frac{1}{\bar F_{Q_{\beta}}(x_t)}\right)
\]
uniformly over $t\in (0,\beta]$.
Under \eqref{eqn:phi_growth}, $\phi(x) = \exp(g(x))$ where $g\in \RV(p)$. Consequently, $\phi^{\leftarrow} = g^{\leftarrow}\circ \log \in \RV(0)$. Therefore,  $w\in \RV(1)$. 
Further note that since $Q_\beta\in \mathcal \Dphi(Q_\beta)$,  $x_t \geq v_{1-t}(Q_\beta)\geq v_{1-\beta_0}(Q)$ whenever $t\in (0,\beta]$.
It follows from \eqref{eqn:nominal_tail} that $\bar F_{Q_\beta}(x_t) = \beta_0\left(\frac{x_t}{v_{1-\beta_0}(Q)}\right)^{-\gamma}$. Substituting these values in the above display,
\[
w^{\leftarrow}\left(\frac{1}{t}\right) \sim \beta_0^{-1}\left(\frac{v_{1-\beta_0}(Q)}{x_t}\right)^{-\gamma}.
\]
Upon re-arrangement,
\[
x_t\sim \frac{v_{1-\beta_0}(Q)}{\beta_0^{-1/\gamma}}[w^{\leftarrow}(1/t)]^{1/\gamma} = t^{-1/\gamma+o(1)}.
\]
To see the last part, note that by assumption, $\beta_0^{1/\gamma}v_{1-\beta_0}(Q) = \beta_0^{o(1)} =t^{o(1)}$. 
Now, for every $\varepsilon>0$, there exists a $\beta_1$ such that $\forall t<\beta_1$ $v_{1-t}(Q) \geq t^{-1/\gamma+\varepsilon}$ and $x_t \leq t^{-1/\gamma-\varepsilon}$. Then whenever $\beta<\beta_1$, 
\[
\sup_{t\in (0,\beta]} \frac{\log v_{1-t}(\Dphi( Q_\beta))}{\log v_{1-t}(Q)} \leq \frac{1+\gamma \varepsilon}{1-\gamma \varepsilon}.
\]
Since $\varepsilon>0$ was arbitrary, the above suggests that 
\[
\limsup_{\beta\to 0}\sup_{t\in(0,\beta]}\frac{\log v_{1-t}(\Dphi( Q_\beta))}{\log v_{1-t}(Q)} \leq 1.
\]


\noindent \textbf{Case ii) $\Lambda_Q\in \RV$:}  As in part \textbf{(i)},
\[
 \frac{1}{t}\sim \frac{1}{\phi^{\leftarrow}\left(\delta/\bar F_{Q_\beta}(x_t)\right) \bar F_{Q_\beta}(x_t)}.
\]
Then,
\begin{equation}\label{eqn:disp_1}
    \log(1/t) \sim \Lambda_{Q_\beta}(x_t) -\ln \phi^{\leftarrow}\left(\delta/\bar F_{Q_\beta}(x_t)\right).
\end{equation}
Since $\phi^\leftarrow \in \RV(0)$,  $\phi^\leftarrow(\delta/\bar F_{Q_\beta}(x)) = (\delta/\bar F_{Q_\beta}(x))^{o(1)}$ uniformly over $x\in[v_{1-\beta_0}(Q_{\beta_{0}}),\infty)$ as $\beta\to 0$. Then, \eqref{eqn:disp_1}  
may be simplified as
$\log(1/t) \sim \Lambda_{Q_\beta}(x_t)  - o(1)\log \bar F(x_t) \sim \Lambda_{Q_\beta}(x_t)$.
This implies that $\Lambda^{\leftarrow}_{Q_\beta}(\log(1/t)) \sim x_t$, or that $v_{1-t}(Q_{\beta}) \sim x_t$.  
Now, let us verify the upper bound in Proposition~\ref{prop:rate_preserving_suffcient}. Fix $\kappa>0$, and note that the following hold uniformly over $t\in[\beta^\kappa,\beta]$
\begin{align*}
   \frac{v_{1-t}(\Dphi( Q_\beta))}{v_{1-t}(Q)} &\sim \frac{v_{1-t}(Q_\beta)}{v_{1-t}(Q)} = \frac{v_{1-\beta_0}(Q)}{v_{1-t}(Q)} \left(\frac{\log(1/t)}{\log(1/\beta_0)}\right)^{1/\gamma} \\
   &\sim \frac{\Lambda_{Q}^{\leftarrow}(\log(1/\beta_0))}{\Lambda^\leftarrow_Q(\log(1/t))} \left(\frac{\log(1/t)}{\log(1/\beta_0)}\right)^{1/\gamma}\\
    &\sim \left(\frac{\log(1/t)}{\log(1/\beta_0)}\right)^{-1/\gamma}\left(\frac{\log(1/t)}{\log(1/\beta_0)}\right)^{1/\gamma}
\end{align*}
where the last statement follows since whenever $t\in[\beta^\kappa,\beta]$, $\log(1/t)/\log(1/\beta_0) \in [c,c\kappa] $. This proves the first part of the upper bound in Proposition~\ref{prop:rate_preserving_suffcient}. For the second part, note that with $x_t\sim v_{1-t}(Q_\beta)$ uniformly over $t\in (0,\beta]$,
\[
\sup_{t\in(0,\beta^\kappa]} \frac{\log v_{1-t}(\Dphi( Q_\beta)))}{\log v_{1-t}(Q)}\leq (1+\varepsilon), \text{ since } v_{1-t}(Q) \geq (\log(1/t))^{1/\gamma-\varepsilon}
\]
whenever $\beta$ is small enough.
\qed


\noindent \textbf{Proof of Lemma~\ref{lem:intermidiate_var}: } \textbf{i) }First let $\bar F\in \RV$.
Let $U_{1},\ldots U_n$ be i.i.d. random variables which are uniformly distributed in $[0,1]$. 
Observe that $Z_i = \bar F_Q^\leftarrow(U_i)$, almost surely. Note that $v_{1-\beta_0}(\hat Q^{(n)})$ is defined as the $\lfloor n\beta_0\rfloor$th largest element of the collection $\{Z_i\}_{i\leq n}$.  
Since $F_Q^\leftarrow(\cdot)$ is a decreasing function on $[0,1]$, this equals $\bar F_{Q}^{\leftarrow}\left(U_{\lfloor n\beta_0\rfloor:n}\right)$,
where $U_{i:n}$ is the $i$th order statistic of $\{U_{i}\}_{\leq n}$.
Since $\beta_0=n^{-\kappa}$, $\beta_0 \to 0$ and $\frac{n\beta_0}{\log\log n}\to \infty$  as $n\to\infty$. 
Applying \cite{einmahl1988laws}, Theorem 3(III) yields 
\[
 \left(\beta_0 {U_{\lfloor n\beta_0\rfloor:n}} -1\right)\xrightarrow{a.s}0.
\]
Utilizing the convergence above,
\[
\frac{\bar F_{Q}^{\leftarrow}\left(U_{\lfloor n\beta_0\rfloor:n}\right)}{\bar F_{Q}^{\leftarrow}(\beta_0)} = \frac{\bar F_{Q}^{\leftarrow}\left(\frac{1}{\beta_0} \beta_0 U_{\lfloor n\beta_0\rfloor:n  }\right)}{\bar F_{Q}^{\leftarrow}(\beta_0)} = \frac{\bar F_{Q}^{\leftarrow}(\beta_0 (1+o(1)))}{\bar F_{Q}^{\leftarrow}(\beta_0)} = (1+o(1))
\]
where the last statement follows since $U_{Q}(t) = \bar F(1/t)$ is regularly varying. Thus,
\[
\frac{v_{1-\beta_0}(\hat Q^{(n)})}{U(1/\beta_0)} -1 = o(1), \ \text{ almost surely}.
\]
\textbf{ii) }Now suppose $\Lambda_Q\in \RV$. Here, observe that $Z_i = \Lambda_Q(\log(1/U_i))$. Then once again, since $\Lambda_Q^\leftarrow(1/t)$ is a decreasing function on $t\in [0,1]$, $v_{1-t}(\hat Q^{(n)})$ equals $\Lambda_{Q}^{\leftarrow}\left(-\log U_{\lfloor n\beta_0\rfloor:n}\right)$. Similar to the previous case, note that 
\[
\frac{\Lambda^{\leftarrow}(-\log U_{\lfloor n\beta_0\rfloor:n})}{\Lambda^{\leftarrow}(\log(1/\beta_0))} = \frac{\Lambda^{\leftarrow}\left(\frac{\log (1/U_{\lfloor n\beta_0\rfloor:n})}{\log(1/\beta_0)} \log(1/\beta_0)\right)}{\Lambda^{\leftarrow}(\log(1/\beta_0))} (1+o(1)).
\]
Note that $\Lambda^\leftarrow(y) = \bar F^{\leftarrow}(e^{-y}) = U(e^y)$. Substituting $y=\log(1/\beta_0)$,
\[
\frac{v_{1-\beta_0}(\hat Q^{(n)})}{v_{1-\beta_0}(Q)} = (1+o(1)), \  \text{ almost surely}
\]
thereby completing the proof.\qed

\noindent \textbf{Proof of Proposition~\ref{prop:correctness_of_algo}: } Observe that one can write 
\[
\frac{1}{n}\sum_{i=1}^n \varphi^*\left(\frac{(Z_i-u)^+ -\eta}{\lambda}\right ) \mv{1}(x\leq v_{1-\beta_0}(\hat Q^{(n)})  = \int \varphi^*\left(\frac{(x-u)^+ -\eta}{\lambda}\right)\mv{1}(x\leq v_{1-\beta_0}(\hat Q^{(n)}))d\hat Q^{(n)}(x).
\]
Define the \textit{deterministic} (since here $\hat Q^{(n)}$ is fixed) and stochastic functions
\begin{align*}
    f(u, \eta,\lambda) &=  E_{\hat Q_{\beta}^{(n)}}\left[\varphi^*\left(\frac{(Z-u)^+ -\eta}{\lambda}\right)\right]\quad \text{and}\\
    f_N(u,\eta,\lambda) & = \int \varphi^*\left(\frac{(x-u)^+ -\eta}{\lambda}\right)\mv{1}(x\leq v_{1-\beta_0}(\hat Q^{(n)}))d\hat Q^{(n)}(x)  + \frac{\beta_0}{N}\sum_{i=1}^N \varphi^*\left(\frac{(\tilde Z_i-u)^+ -\eta}{\lambda}\right).
\end{align*}
Suppose in addition, that  $f_N\to f$ uniformly over $(u,\eta,\lambda)$. Then, applying \cite{shapiro2021lectures} Proposition 5.2, it can be established that $\hat C_{1-\beta}^{N}(\Dphi(\hat Q_{\beta}^{(n)})) \to  C_{1-\beta}(\Dphi(\hat Q_{\beta}^{(n)}))$ almost surely as $N\to\infty $. The rest of the proof therefore focuses on proving $f_N\to f$, uniformly.

\noindent \textbf{i) } Recall the inverse transform method (see \cite{Glynn}, Chapter 1): for a random variable $Z$ with  distribution $P$, $F^{\leftarrow}_P(U_t)$ has the distribution of $(Z\mid Z\geq v_{1-t}(P))$ where $F$ is the cdf of $P$, and $U_t$ is uniformly distributed in $[1-t,1]$. 
Note that for $t\in [v_{1-\beta_0}(Q),\infty)$
\[
G_{\beta}(t) = \begin{cases}
    1-\beta_0 \left(\frac{t}{v_{1-\beta_0}(Q)}\right)^{-\gamma} \quad \quad\quad\quad\  \quad\text{ if $\bar F_Q\in \RV(\gamma)$}\\
1-\exp\left(\log(\beta_0)\left(\frac{t}{v_{1-\beta_0}(Q)}\right)^\gamma\right)      \quad\text{ if } \Lambda_Q\in \RV(\gamma),
    \end{cases}  
\]
Thus whenever $y\in [1-\beta_0,1]$,
\[
[G_{\beta}]^{\leftarrow}(y) = \begin{cases}
    v_{1-\beta_0}(Q) \left(\frac{1-y}{\beta_0} \right)^{1/\gamma} \quad \quad\quad\quad\  \quad\text{ if $\bar F_Q\in \RV(\gamma)$}\\
 v_{1-\beta_0}(Q) \left(\frac{\log(1-y)}{\log(\beta_0)} \right)^{1/\gamma}      \quad\quad\quad \quad \text{ if } \Lambda_Q\in \RV(\gamma).
    \end{cases} 
\]
Hence, by construction,
$\tilde Z = [\hat G_{\beta_0}^{(n)}]^{\leftarrow}(U_{\beta_0})$. Therefore, $\tilde Z_i$ are i.i.d. draws from the distribution of $(X_\beta \mid X_\beta \geq v_{1-\beta_0}(\hat Q^{(n)}_\beta)$ where $X_\beta$ has a cdf $\hat G_{\beta_0}^{(n)}$. 

\noindent \textbf{ii) } Now, the expected value of $\hat f_N(u,\eta,\lambda)$ equals $E_{\hat Q^{(n)}} [\phi^*(\lambda^{-1}(Z-u)^+-\eta));Z\leq v_{1-\beta_0
}(\hat Q^{(n)})]$ plus 
\begin{align*}
    \beta_0 E\left[\phi^*\left(\frac{(X_\beta-u)^++\eta}{\lambda}\right)\,\Bigg \vert\  X_{\beta}\geq v_{1-\beta_0}(\hat Q^{(n)})\right] = \int_{x\geq v_{1-\beta}(\hat Q^{(n)})} \phi^*\left(\frac{(x-u)^++\eta}{\lambda}\right)d{\hat G_{\beta}^{(n)}}(x),  
\end{align*}
where the second statement follows since by definition $\hat G_{\beta}(v_{1-\beta_0}(\hat Q^{(n)}))  = 1-\beta_0$. Putting both the above together suggests that the expected value of $f_N(u,\eta,\lambda)$ equals $f(u,\eta,\lambda)$. Applying the law of large numbers, $f_N \to f$ point-wise in $(u,\eta,\lambda)$.  

\noindent \textbf{iii)} Finally, note that since the function $\ell(z,u) = (z-u)^+$ is convex in $u$ for all $z$, and $\phi$ is convex, $f_N(\cdot)$ is jointly convex in $(u,\eta,\lambda)$.  
Further $f(\cdot)$ is continuous and its domain has a non-empty interior. 
Coupled together with the point-wise convergence from step (ii),    \cite{shapiro2021lectures} Theorem 9.61 implies that $f_N\to f$ uniformly over $(u,\eta,\lambda)$. \qed
