In order to prove the consistency result in Theorem~\ref{thm:consistency_of_dro}, the following stochastic versions of Propositions~\ref{prop:sol_of_inverse} and \ref{prop:rate_preserving_suffcient} are required:


\begin{lemma}\label{lema:sol_of_inverse_dd}
    Let the conditions of Proposition~\ref{prop:sol_of_inverse} hold, and let $Q_\beta$ be given by \eqref{eqn:nominal_dist}. Then 
    \begin{equation}\label{eqn:sol_of_inverse_dd}
       \sup_{x\geq v_{1-\beta_0}(\hat Q^{(n)})}\left\vert \frac{\bar F_{{\tt wc},n}(x) }{\phi^\leftarrow\left(\frac{\delta}{\bar F_{\hat Q_\beta^{(n)}}(x)}\right)\bar F_{\hat Q_\beta^{(n)}}(x)}  -1\right\vert = o(1)
\end{equation}
almost surely, where $\bar F_{{\tt wc},n}(x) = \sup\{ \bar F_P(x): {P\in \mathcal \Dphi(\hat Q_\beta^{(n)})}\}$ is the worst-case cdf.
\end{lemma}

\begin{lemma}\label{lem:stochastic_sufficient}
     In the setup of Theorem~\ref{thm:consistency_of_dro} 
     the following hold almost surely as $n\to\infty$:
    \begin{enumerate}
        \item[(i)] If $\bar F_Q\in \RV$, then 
        \[
        \inf_{t\in (0,\beta]}\frac{\log v_{1-t}(\hat Q_\beta^{(n)})}{\log v_{1-t}(Q)} = 1+o(1) \quad \text{ and }\quad  \sup_{t\in (0,\beta]}\frac{\log v_{1-t}(\Dphi(\hat Q^{(n)}_\beta))}{\log v_{1-t}(Q)} = 1+o(1). 
        \]
        \item[(ii)] If instead $\Lambda_Q\in \RV$, then for any $\kappa>0$
        \[
        \inf_{t\in (\beta^\kappa,\beta]}\frac{ v_{1-t}(\hat Q_\beta^{(n)})}{ v_{1-t}(Q)} = 1+o(1) \quad \text{ and }\quad  \sup_{t\in (\beta^\kappa,\beta]}\frac{ v_{1-t}(\Dphi(\hat Q^{(n)}_\beta))}{ v_{1-t}(Q)} = 1+o(1). 
        \]
        Further, the second stochastic bound in part (i) above holds over $t\in (0,\beta^\kappa]$.
    \end{enumerate}
\end{lemma}


\noindent \textbf{Proof of Theorem~\ref{thm:consistency_of_dro}: }
Let $\Omega_0$ be the set on which the convergence in Lemma~\ref{lem:stochastic_sufficient} occurs. For every $\omega\in \Omega_0$, Proposition~\ref{prop:rate_preserving_suffcient} implies that the ambiguity sets $\mathcal Q_\beta  = \Dphi(\hat Q_{\beta}^{(n)})$ are strongly (weakly) $Q-$rate preserving. Since $\mathbb P(\Omega_0)=1$,  the proof of the theorem is complete.\qed

\subsection{Proofs from Section~\ref{sec:distortion} and \ref{sec:application}}
\textbf{Proof of Lemma~\ref{lem:distortion_asymptotics}: } The first part of the lemma is already established in \cite{zhu2012asymptotic}, Example 3. For the second, suppose that $\Lambda_P\in \RV$. Then,
\begin{align}
\rho_{g,1-\beta}(P) &= k\beta^{-k}\int_{0}^\beta t^{k-1}v_{1-t}(P)dp =k\beta^{-k} \int_{0}^\beta t^{k-1}\Lambda_P^{\leftarrow}(\log (1/t)) dp\nonumber\\
&=k\beta^{-k}\int_{\log(1/\beta)}^\infty e^{-kp}\Lambda^{\leftarrow}(p)dp, \quad \text{ setting } \log(1/t)=p\nonumber\\
& =\Lambda^{\leftarrow}(\log(1/\beta)) \underbrace{k\beta^{-k}\int_{\log(1/\beta)}^{M\log(1/\beta)}\frac{\Lambda^{\leftarrow}(p)}{\Lambda^{\leftarrow}(\log(1/\beta))} e^{-kt}dt}_{(\mv a)}  + \underbrace{k\beta^{-k}\int_{M\log(1/\beta)}^\infty {\Lambda^{\leftarrow}(p)} e^{-kt}dt}_{(\mv b)}  .\label{eqn:light_integral}
\end{align}
Note that using \cite{deHaan}, Proposition B.1.4, uniformly over $p\in[\log(1/\beta),  M\log(1/\beta)]$, $\Lambda^{\leftarrow}(p) \sim (p/\log(1/\beta))^{1/\gamma}\Lambda^\leftarrow(p)$. This implies that the integral in $(\mv a)$ is asymptotically
\[
k\int_{\log(1/\beta)}^{M\log(1/\beta)} p^{1/\gamma}e^{-kp}dp =k^{-1/\gamma}\left[\Gamma\left(\frac{1}{\gamma}+1, k\log(1/\beta)\right) -\Gamma\left(\frac{1}{\gamma}+1, ck\log(1/\beta)\right)  \right]
\]
where  $\Gamma(s,x)=\int_x^\infty x^{s-1}e^{-x}dx$. Since $\Gamma(s,x) \sim x^{s-1}e^{-x}$ as $x\to\infty$, for any $c>0$,
\[
\Gamma\left(\frac{1}{\gamma}+1, M k\log(1/\beta)\right) \sim M^{1/\gamma}k^{1/\gamma}\log^{1/\gamma}(1/\beta) e^{-k\log(1/\beta)} = (Mk)^{1/\gamma}\beta^{Mk} \log^{1/\gamma}(1/\beta).
\]
This implies that $\Gamma\left(\frac{1}{\gamma}+1, Mk\log(1/\beta)\right) = o\left(\Gamma\left(\frac{1}{\gamma}+1, k\log(1/\beta)\right)\right)$. Use this observation in \eqref{eqn:light_integral} to bound $(\mv a)$ as $\Lambda_{P}^\leftarrow(\log (1/\beta))(1+o(1))$. Since $\Lambda^{\leftarrow}\in \RV(1/\gamma)$, for all small enough $\beta$, $(\mv{b})$ is upper bounded by 
\begin{align*}
    \int_{M\log(1/\beta)}^\infty p^{1/\gamma+\varepsilon}e^{-kp}dt &\leq \Gamma\left(\frac{1}{\gamma}+\varepsilon , M\log(1/\beta)\right) \sim [M \log(1/\beta)]^{1/\gamma+\varepsilon}\beta^{-M(1/\gamma+\varepsilon)}\\
    &= o(\Lambda^{\leftarrow}_P(\log(1/\beta))\ \  \text{( since $M>1$ and $\varepsilon>0$ is arbitrary).}
\end{align*}
Then, $\rho_{g,1-\beta}(P) \sim \Lambda_{P}^{\leftarrow}(\log(1/\beta))$. \qed

\noindent\textbf{Proof of Proposition~\ref{prop:Robust_distortion_measures}: }Note that $g_{\beta}(x) = \mv{1}(x>v_{1-\beta}(P_0)) + g(x/\beta) \mv{1}(x\geq v_{1-\beta}(P_0))$. Therefore, with $g(x) = x^k, $ $g^\prime_\beta(x) = k \beta^{-k} x^{k-1}\mv{1}(x\geq v_{1-\beta}(P_0))$. Consequently,
\begin{align*}
    \|g^\prime\|_{q}  &= k\beta^{-k} \left(\int_0^\beta t^{q (k-1)} dt\right)^{1/q} =\frac{k}{(k-1)q+1)^{1/q}} \beta^{\frac{(k-1)q+1}{q}-k} \\
    &= \frac{k}{(k-1)q+1)^{1/q}} \beta^{-1+1/q} =   C_0 \beta^{-1/p},
\end{align*}
where the last equality follows since $1/p+1/q=1$.
Therefore, for an appropriate $C_1>0$
\[
\rho_{g,1-\beta}(\mathcal W_{p,\delta}) = \rho_{g,1-\beta}(P_0) + C_1\beta^{-1/p}.
\]
First suppose that $\bar F_{P_0}\in \RV$. Then, from Lemma~\ref{lem:distortion_asymptotics},  $ \rho_{g,1-\beta}(P_0) = \beta^{-1/\gamma+o(1)}$. Therefore,
\[
\lim_{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\mathcal W_{p,\delta}) }{\log \rho_{g}(P_0)} =\frac{\gamma}{p},
\]
and the first statement of the proposition follows. Next, suppose that $\Lambda_{P_0}\in \RV$. Then, $\rho_{g,1-\beta}(P_0) =\log^{1/\gamma+o(1)}(1/\beta)$, and the second statement follows.\qed

\noindent\textbf{Proof of Proposition~\ref{prop:Robust_distortion_measures_poly_divergence}: }\textbf{i)} From Proposition~\ref{prop:f_div_contents}, whenever $\bar F_Q\in \RV(-\gamma)$ for any $\varepsilon>0$, there exists a distribution $P_1\in \Dphi(Q)$ with $\bar F_{P_1}\in \RV(-\gamma^\prime - \varepsilon)$ where $\gamma^\prime = \frac{p-1}{p}\gamma$. Then, 
\[
\rho_{g,1-\beta}(\Dphi(Q)) \geq \rho_{g,1-\beta}(P_1) = \left(\frac{1}{\beta}\right)^{1/\gamma^\prime -\varepsilon + o(1)}. 
\]
Combining the above display with Lemma~\ref{lem:distortion_asymptotics} implies that 
\[
\liminf{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\Dphi(Q))}{\rho_{g,1-\beta}(Q)} \geq \frac{p}{p-1}.
\]
 Note that with $\bar F_Q\in \RV(\gamma) $ and $\phi\in \RV(p)$, the proof of Theorem~\ref{thm:poly_divergence} implies that $v_{1-\beta}(\Dphi(Q)) = (1/\beta)^{1/\gamma^\prime+o(1)}$. Then, the upper bound \eqref{eqn:ub_risk_measure} reduces to 
 \[
 \rho_{g,1-\beta}(\Dphi(P_0)) \leq  k\beta^{-k}\int_{0}^\beta (1/t)^{1/\gamma^\prime+o(1)} t^{k-1}dt. 
 \]
 As before, changing variable and applying Karamata's theorem shows that the right hand side above is asymptotically similar to $\frac{k\gamma^\prime}{k\gamma^\prime -1}v_{1-\beta}(\Dphi(Q))$. Now,
 \[
 \limsup_{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\Dphi(Q))}{\rho_{g,1-\beta}(Q)} \leq \frac{p}{p-1}.
 \]
 Combining the above with the lower bound completes the proof in case $\bar F_{Q}\in \RV$.\qed

\noindent \textbf{ii)} Next, suppose that $\Lambda_Q\in \RV$. Then, note the following bounds:
\begin{align*}
    \rho_{g,1-\beta}(\Dphi(Q)) &\geq \rho_{g,1-\beta}(\tilde P) \geq (1-\varepsilon) v_{1-\beta}(\tilde P) \\
    & \geq (1-\varepsilon)\left(\left(\frac{p}{p-1}\right)^{1/\gamma}-\varepsilon \right)v_{1-\beta}(Q) \quad\  \text{ choosing $\tilde P$ to satisfy Proposition~\ref{prop:f_div_contents}(iii)}\\
    & \geq  (1-\varepsilon)\left(\left(\frac{p}{p-1}\right)^{1/\gamma}-\varepsilon \right)\rho_{g,1-\beta}(Q),
\end{align*}
where the first and last steps above are obtained  using Lemma~\ref{lem:distortion_asymptotics}.
 Since $\varepsilon>0$ above is arbitrary, 
\[
\liminf_{\beta\to 0}\frac{ C_{1-\beta}(\Dphi(Q))}{C_{1-\beta}(Q) } \geq \left(\frac{p}{p-1}\right)^{1/\gamma}.
\]
To prove the matching upper bound, we turn back to \eqref{eqn:ub_risk_measure}. First recall that 
\[
v_{1-\beta}(\Dphi(Q)) \sim \left(\frac{p}{p-1}\right)^{1/\gamma}v_{1-\beta}(Q)
\]
Consequently, one has the following upper bound for all sufficiently small $\beta$:
\[
\rho_{1-\beta}(\Dphi(Q)) \leq (1+\varepsilon)\left(\frac{p}{p-1}\right)^{1/\gamma} \beta^{-k}\int_{0}^\beta t^{k-1}v_{1-t}(Q)dt 
\]
The integral in the right hand side above equals $ \rho_{g,1-\beta}(Q)$. Therefore,
\[
\limsup_{\beta\to 0}\frac{\rho_{g,1-\beta}(\Dphi(Q))}{\rho_{g,1-\beta}(Q)} \leq \left(\frac{p}{p-1}\right)^{1/\gamma}
\]
Combining this with the upper bound above concludes the proof\qed

\noindent \textbf{Proof of Theorem~\ref{thm:dist_measure_calib}: }We will demonstrate that the conditions of Proposition~\ref{prop:rate_preserving_suffcient} are sufficient for the required conclusions. Recall that in the proofs of Lemma~\ref{lem:lb_suff} and Theorem~\ref{thm:scale_preserving_dro}, we have already shown $\Dphi(Q_\beta)$ satisfies the conditions of Proposition~\ref{prop:rate_preserving_suffcient}. We demonstrate the proof only for the case where $\bar F_Q\in \RV$. The proof of the result when $\Lambda_Q\in \RV$ follows using steps similar to ones used in Theorem~\ref{thm:scale_preserving_dro}, and is therefore skipped.

\noindent  \textbf{i) Lower Bound: } Note that given any $\varepsilon>0$, 
\[
\liminf_{\beta\to 0}\inf_{t\in(0,\beta]}\frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq 1 \implies \inf_{t\in (0,\beta]} \frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq 1-\varepsilon , \ \ \forall \beta<\beta_1.
\]
Conclude now, that whenever $\beta<\beta_1$, uniformly over $t\in(0,\beta]$, $v_{1-t}(Q_\beta)\geq [v_{1-t}(Q)]^{1-\varepsilon}$. Now, 
\[
\rho_{g,1-\beta}(\Dphi(Q_\beta)) \geq \beta^{-k}\int_{0}^\beta v_{1-t}(Q_\beta) dt \geq\beta^{-k}\int_{0}^\beta [v_{1-t}(Q)]^{1-\varepsilon} dt.
\]
Change variables as $1/t=r$ in the integral above to obtain that 
\[
\rho_{g,1-\beta}(\Dphi(Q_\beta)) \geq k\beta^{-k}\int_{1/\beta}^\infty r^{-(k+1)} [v_{1-1/r}(Q)]^{1-\varepsilon}dr.
\]
Recall that $v_{1-1/r}(Q)\in \RV(1/\gamma)$.  
Then, $t^{-(k+1)}[v_{1-1/t}(Q)]^{1-\varepsilon}$ is regularly varying with tail index $1/\gamma-k-1-\varepsilon$.
With $1/\gamma-k<0$, use Karamata's theorem to infer that
\[
k\beta^{-k}\int_{1/\beta}^\infty r^{-(k+1)} [v_{1-1/r}(Q)]^{1-\varepsilon}dr \sim \frac{k}{k-1/\gamma-\varepsilon} [v_{1-t}(Q)]^{1-\varepsilon}.
\]
Apply Lemma~\ref{lem:distortion_asymptotics} to note that for $\varepsilon>0$, there exists a $\beta_2$ such that for all $\beta<\beta_2$,
\[
\rho_{g,1-\beta}(\Dphi(Q_\beta)) \geq [\rho_{g,1-\beta}(Q)]^{1-\varepsilon}.
\]
Then, with $\varepsilon$ being arbitrary
\[
\liminf_{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\Dphi(Q_\beta))}{\log \rho_{g,1-\beta}(Q)} \geq 1.
\]
\noindent \textbf{ii) Upper Bound: }Recall that 
\[
\rho_{g,1-\beta}(\Dphi(Q_\beta)) \leq \beta^{-k}\int_0^\beta t^{(k-1)}v_{1-t}(\Dphi(Q_\beta))dt.
\]
Note that given any $\varepsilon>0$,
\[
\limsup_{\beta\to 0}\sup_{t\in(0,\beta]}\frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq 1 \implies \sup_{t\in (0,\beta]} \frac{\log v_{1-t}(Q_\beta)}{\log v_{1-t}(Q)} \geq 1+\varepsilon , \ \ \forall \beta<\beta_3.
\]
Now
\[
\rho_{g,1-\beta}(\Dphi(Q_\beta)) \leq k\beta^{-k} \int_{1/\beta}^\infty r^{-(k+1)} [v_{1-1/r}(Q)]^{1+\varepsilon}dr
\]
Then, $t^{-(k+1)}[v_{1-1/t}(Q)]^{1-\varepsilon}$ is regularly varying with tail index $1/\gamma-k-1+ \varepsilon<-1$.
Repeating the steps from part i), note that then, for all sufficiently small $\beta$, 
\[
\rho_{g,1-\beta}(\Dphi(Q_\beta)) \leq [\rho_{g,1-\beta}(Q)]^{1+\varepsilon}
\implies
\limsup_{\beta\to 0}\frac{\log \rho_{g,1-\beta}(\Dphi(Q_\beta))}{\log \rho_{g,1-\beta}(Q)} \leq 1.  \qed 
\]

\noindent \textbf{Proof of Proposition~\ref{prop:mv_cvar}: }Let Assumption~\ref{assume:mrv} hold. Then, an application of Theorem 3 of \cite{Rootzen} followed by Theorem 5.3 of \cite{Resnick}, implies that for any set $A$ which does not contain the origin, $nQ_0(a(n) A)\to \nu(A)$. Note that given $t\in \R$, by definition  $\bar F_Q(t) = Q_0(L(\XX) \geq t)$. The following sequence of asymptotic bounds are obtained:
\begin{align*}
    a^\leftarrow(t^{1/\rho}) Q_0(L(\XX) \geq t) &= a^\leftarrow(t^{1/\rho})Q(L(\XX/t^{1/\rho})\geq 1) \\
    &=a^\leftarrow(t^{1/\rho}) Q(\XX/t^{1/\rho}\in A) \to \nu(A).
\end{align*}
Note that if the function $a\in \RV(1/\gamma)$, then $a^\leftarrow\in \RV(\gamma)$.
This suggests that $\bar F_{Q}(t) \sim [a^{\leftarrow}(t)]\nu(A)$ or $\bar F_Q\in \RV(-\gamma/\rho)$. \qed
\section{Proofs of Technical Lemmas}
\noindent \textbf{Proof of Lemmas~\ref{lem:RVs_ht} and \ref{lem:RVs_lt}: }Note that the tail cdf of $Q_\beta$ is given by 
\[
\bar F_{Q_\beta} (x) = \bar F_Q(x) \mv{1}(x\leq v_{1-\beta_0}(x)) + G_\beta(x) \mv{1}(x> v_{1-\beta_0}(x)).
\]
Fix $t<\beta_0$ above, and note that by construction, $v_{1-t}(Q_\beta) = G_\beta^{\leftarrow}(t)$. With $\log \beta  \sim c\log\beta$ for $c<1$, one has that 
Recall that
\[
G_{\beta_0}(x) = \begin{cases}
    \beta_0 \left(\frac{x}{v_{1-\beta_0}(Q)}\right)^{-\gamma} \quad \quad\quad\quad\  \quad\text{ if $\bar F_Q\in \RV(\gamma)$}\\
\exp\left(\log(\beta_0)\left(\frac{x}{v_{1-\beta_0}(Q)}\right)^\gamma\right)      \quad\text{ if } \Lambda_Q\in \RV(\gamma)
    \end{cases}  
\]
Taking the inverse of the above expression completes the proof.
\qed 

\noindent \textbf{Proof of Lemma~\ref{lem:consistency_of_gamma}: }The proof is standard when $\bar F_Q\in \RV$ using the consistency of Hill estimator (see \cite{deHaan}). For the case where $\Lambda_Q\in \RV$, note with $\beta_i$, $i \in\{0,1\}$ being intermediate quantiles, the conclusion of Lemma~\ref{lem:intermidiate_var} apply. Therefore, 
\begin{align*}
    \log \left(\frac{Z_{\lfloor n\beta_0(n)\rfloor:n}}{Z_{\lfloor n\beta_1(n)\rfloor:n}}\right) & = \log \left(\frac{v_{1-\beta_0}(Q)}{v_{1-\beta_1}(Q)} (1+o_p(1)\right)\\
    & =(1+o_p(1)) \log\left(\frac{\log^{1/\gamma}(1/\beta_0) L_0(\log(1/\beta_0)}{\log^{1/\gamma}(1/\beta_1) L_0(\log(1/\beta_1)}\right) \quad \text{since $\Lambda_Q\in \RV$}\\
    &=(1+o_p(1)) \log\left(\frac{1}{\kappa^{1/\gamma}}\right).
\end{align*}
Here the last step is because $L_0\in \RV(0)$. Rearranging the last line above $\hat \gamma_n = \gamma(1+o_p(1))$ which proves the lemma.\qed 

\noindent \textbf{Proof of Proposition~\ref{prop:sol_of_inverse_unif}: }Note that from \cite{blanchet2020distributionally}, Corollary 1, the following must hold true
\begin{align}\label{eqn:wc_probs}
    \delta & = (1-\bar F_{Q_\beta}(x)) \phi\left(\frac{1-s_{\beta}(x) \bar F_{Q_\beta}(x)}{1-\bar F_{Q_\beta}(x)}\right) + \bar F_{Q_\beta}(x) \phi(s_\beta(x)) \nonumber\\
    \bar F_{{\tt wc},\beta}&=s_\beta(x) \bar F_{Q_\beta}(x)
\end{align}
Recall that $\phi(1) = \phi^\prime(1)=0$. Expanding the first equation of \eqref{eqn:wc_probs} about $y=1$ using a Taylor series and simplifying yields
\begin{equation}\label{eqn:tse}
    \frac{\delta}{\bar F_{Q_\beta}(x)} = \underbrace{\frac{\phi^{\prime\prime} (r_\beta(x))}{2} \bar F_{Q_\beta}(x) (s_\beta(x)-1) \left(1-\frac{1}{s_\beta(x)}\right)}_{(a)} + \phi(s_\beta(x)), 
\end{equation}
where $r_\beta(x) \in (1-s_\beta(x) \bar F_{Q_\beta}(x),1)$. Note two points: first, from \eqref{eqn:nominal_tail} in the region $x\geq v_{1-\beta}(Q)$, $\bar F_{Q_\beta}(x) \leq  \beta^{1+o(1)}_0$. 
As a consequence, $\inf_{x\geq v_{1-\beta_0}(Q)} s_{\beta}(x) \to \infty$ as $\beta\to 0$, since other, for otherwise  right hand side of \eqref{eqn:tse} will become infinite, but the left hand side will remain finite as $\beta\to 0$. For a similar reason, since $\phi(x) /x\to \infty$, dividing both sides of \eqref{eqn:tse} by $s_\beta(x)$, we have that $\sup_{x\geq v_{1-\beta_0}(Q)} \bar F_{Q_\beta}(x) s_\beta(x) \to 0$ as $\beta$ to $0$. Putting these two facts together,  the term labeled \textbf{(a)} in \eqref{eqn:tse} can be made arbitrarily small, uniformly over $x\geq v_{1-\beta}(Q)$ as $\beta\to 0$. Thus, 
\[
\frac{\delta}{\bar F_{Q_\beta}(x)}\sim \phi(s_\beta(x)) \implies s_\beta(x) \sim \phi^\leftarrow\left(\frac{\delta}{\bar F_{Q_\beta}(x)}\right)
\]
where once again $\sim$ is to be read in the context of Proposition~\ref{prop:sol_of_inverse_unif}. This further implies that $F_{{\tt wc},\beta}(x) \sim \bar F_{Q_\beta}(x) \phi^\leftarrow(\delta/F_{Q_\beta}(x))$, thereby establishing Proposition~\ref{prop:sol_of_inverse_unif}.\qed

\noindent\textbf{{Proof of Lemma~\ref{lema:sol_of_inverse_dd}: }}From Lemma~\ref{lem:intermidiate_var}, $v_{1-\beta_0}(\hat Q^{(n)}) = v_{1-\beta_0}(Q) (1+o(1))$ on a set $\Omega_0$ whose probability is $1$.  
In particular with probability 1, $v_{1-\beta_0}(\hat Q^{(n)}) \to \infty$.
Applying the proof of Proposition~\ref{prop:sol_of_inverse_unif} point-wise on $\Omega_0$ shows that for every $\omega\in \Omega_0$,
\begin{equation}\label{eqn:dd_uc}
    \sup_{x\geq v_{1-\beta_0}(\hat Q^{(n)})}\left\vert \frac{\bar F_{{\tt wc},n}(x) }{\phi^\leftarrow\left(\frac{\delta}{\bar F_{\hat Q_\beta^{(n)}}(x)}\right)\bar F_{\hat Q_\beta^{(n)}}(x)}  -1\right\vert = o(1),
\end{equation}
which establishes the conclusion of the lemma. \qed


\noindent \textbf{Proof of Lemma~\ref{lem:stochastic_sufficient}: }
\textbf{Case i) $\bar F_Q\in \RV$:} \textbf{i) Lower Bound:} Let  $\Omega_1$ be the set on which $\hat \gamma_n \to \gamma$. 
Note that for $\omega\in \Omega_1$,  for all $x\geq v_{1-\beta_0}(\hat Q^{(n)})$,
\[
\bar F_{\hat Q_\beta^{(n)}}(x) =  \beta_0 \left(\frac{x}{v_{1-\beta_0}(Q) (1+o(1)}\right)^{\gamma+o(1)}.
\]
For $t\in (0,\beta]$, set $x = v_{1-t}(\hat Q_\beta^{(n)})$. Simplify the above equation to 
\[
v_{1-t}(\hat Q_\beta^{(n)}) = \left(\frac{t}{\beta_0}\right)^{1/\gamma+o(1)}  v_{1-\beta_0}(Q) (1+o(1))
\]
Now, proceeding as in the proof of Lemma~\ref{lem:lb_suff} shows that for every $\omega\in \Omega_1$ (which has a probability $1$),
\[
\inf_{t\in(0,\beta]} \frac{\log v_{1-t}(\hat Q_\beta^{(n)})}{\log v_{1-t}(Q)} = 1+o(1). 
\]

\noindent \textbf{i) Upper Bound: } Set $\Omega^\prime = \Omega_0\cap \Omega_1$. 
Then, for every $\omega\in \Omega^\prime$,
\[
\bar F_{{\tt wc},n}(x) \sim \phi^\leftarrow\left(\frac{\delta}{\bar F_{\hat Q_\beta^{(n)}}(x)}\right)\bar F_{\hat Q_\beta^{(n)}}(x) 
\]
uniformly over $x\geq v_{1-\beta_0}(\hat Q^{(n)})$. Set $x_t = v_{1-t}(\Dphi(\hat Q_{\beta}^{(n)}))$ and note that whenever $t\in(0,\beta]$, $v_{1-t}(\hat Q^{(n)}) \geq  v_{1-\beta_0}(\hat Q^{(n)})  =   v_{1-\beta_0}(\hat Q^{(n)}_\beta) $.  Thus, $x_t\geq v_{1-\beta_0}(\hat Q^{(n)}_\beta)  $. Then, uniformly over $t\in(0,\beta]$, 
\[
\frac{1}{t }\sim  w\left(\frac{1}{\bar F_{\hat Q_{\beta}^{(n)}}(x_t)}\right), \text{ where } w(x) = \frac{1}{x \phi^\leftarrow(\delta/x) }.
\]
With $\hat \gamma_n= \gamma+o(1)$ on $\Omega^\prime$, re-arranging the above and substituting the value of $\bar F_{\hat Q_{\beta}^{(n)}}$ yields that 
\[
w^{\leftarrow}\left(\frac{1}{t}\right) \sim \beta_0^{-1}\left(\frac{v_{1-\beta_0}(Q)}{x_t}\right)^{-\gamma+o(1)} \implies x_t \sim \frac{v_{1-\beta_0}(Q)}{\beta_0^{-1/\gamma+o(1)}} [w^\leftarrow(1/t)]^{1/\gamma+o(1)} = t^{-1/\gamma+o(1)}.
\]
This suggests that 
\[
\sup_{t\in (0,\beta]}\frac{\log v_{1-t}(\Dphi(\hat Q_\beta^{(n)}))}{\log v_{1-t}(Q)} = 1+o(1). 
\]
This completes the proof in the case where $\bar F_Q\in \RV$. 

\noindent \textbf{Case ii) $\Lambda_Q\in \RV$: }\textbf{i) Lower Bound:}  On the set $\Omega_0$, $v_{1-\beta_0}(\hat Q_\beta^{(n)}) = v_{1-\beta_0}(Q_\beta)$. Therefore, repeating the calculations in the proof of Case ii) of Lemma~\ref{lem:lb_suff}, for any $\kappa>1$, uniformly over $t\in[\beta^\kappa,\beta]$
\begin{align*}
     v_{1-t}(\hat Q_\beta^{(n)}) & = v_{1-\beta_0}(Q_\beta)(1+o(1)) \\
     & = v_{1-t}(Q) \left(\frac{\log(1/t)}{\log(1/\beta_0)}\right)^{1/\gamma}(1+o(1))\\
     & = v_{1-t}(Q) (1+o(1)) 
\end{align*}
where the last statement follows from the regular variation of $\Lambda^\leftarrow_Q$. This proves the lower bound. 

\noindent \textbf{ii) Upper Bound:} Following the proof of Case ii) from Theorem~\ref{thm:scale_preserving_dro}, observe that on the set $\Omega_0$ where the uniform convergence \eqref{eqn:dd_uc} occurs, one has that 
$\log(1/t) = \Lambda_{\hat Q_\beta^{(n)}}(x_t)(1+o(1))$ uniformly over $t\in(0,\beta]$ where recall that $x_t = v_{1-t}(\Dphi(\hat Q_\beta^{(n)}))$ is the worst case VaR. Then, proceeding as in that case, $v_{1-t}(\hat Q_{\beta}^{(n)}) \sim x_t$. Further on $\Omega_0$, from the previous part, $v_{1-t}(\hat Q^{(n)}_\beta) = v_{1-t}(Q_\beta) (1+o(1))$. Putting these two together, on $\Omega^\prime$, we get 
\begin{align*}
    \sup_{t\in[\beta^\kappa,\beta]}\frac{v_{1-t}(\Dphi( \hat Q_\beta^{(n)}))}{v_{1-t}(Q)} &\sim \sup_{t\in [\beta^\kappa,\beta]}\frac{\Lambda_{Q_{\beta}^{(n)}}^{\leftarrow}(\log(1/t))}{\Lambda^\leftarrow_Q(\log(1/t))}(1+o(1))  \\
    &\sim \sup_{t\in [\beta^\kappa,\beta]} \frac{\Lambda_{Q_\beta}(\log(1/t))}{\Lambda_Q^\leftarrow(\log 1/t)} \ \ \  \text{ since } v_{1-t}(\hat Q^{(n)}_\beta) = v_{1-t}(Q_\beta)\\
    &=(1+o(1))
\end{align*}
where the last bound follows from the proof of Theorem~\ref{thm:scale_preserving_dro}. The second statement follows because $v_{1-\beta}(Q) = [\log(1/\beta)]^{1/\gamma+o(1)}$ and on the set $\Omega^\prime$, with $\hat \gamma = \gamma +o(1)$ 
\[
v_{1-t}(\hat Q_{\beta}^{(n)}) = v_{1-\beta_0}\left(\frac{\log(1/t)}{\log(1/\beta_0)}\right)^{1/\gamma+o(1)}.
\]
Noting that the above bound is uniform over $t\in (0,\beta]$, taking logs and simplifying
\[
\sup_{t\in (0,\beta^\kappa]} \frac{\log v_{1-t}(\hat Q_\beta^{(n)})}{\log v_{1-t}(Q)} = 1+o(1)
\]
thereby completing the proof.\qed 
