\section{Convergence Analysis}
Assume $\mathcal{L}(\bm{u},\bm{v},\bm{w})$ is $L$-smooth where $\bm{u}\in \mathbb{R}^{n_1}$, $\bm{v}\in \mathbb{R}^{n_2}$,$\bm{w}\in [0,1]^d $ represents continuous variables, dual variables, and relaxed variables, respectively. 
The objective function with regularization term $\mathcal{G}(\bm{w})$ is:
\begin{equation}
\mathcal{F}(\bm{u},\bm{v},\bm{w}) = \mathcal{L}(\bm{u},\bm{v},\bm{w}) + \mathcal{G}(\bm{w})
\end{equation}
where $\mathcal{G}(\bm{w})$ is defined as follows:
\begin{equation}
\label{regularization function}
\begin{aligned}
     &\mathcal{G}(\bm{w}) = \|\bm{w}-\hat{\bm{x}}\|^2\\
     &s.t.\quad  \hat{\bm{x}}=\arg\min_{\bm{x}} \|\bm{w}-\bm{x}\|^2, \\
     &\qquad \  \bm{x}\in\{0,1\}^d,\bm{w}\in [0,1]^d.
\end{aligned}
\end{equation}
We define
\begin{equation}
    prox_{\eta,\mathcal{G}}(\bm{w}) = \arg\min_{\bm{x}} \left(\frac{1}{2\eta} \|\bm{x} - \bm{w}\|^2 + \mathcal{G}(\bm{x}) \right).
\end{equation}

The above proximal operation is equivalent to the following closed-form expression:
\begin{equation}
    prox_{\eta,\mathcal{G}}(\bm{w}) = [prox_{\eta,\mathcal{G}}(w_1), prox_{\eta,\mathcal{G}}(w_2), \ldots, prox_{\eta,\mathcal{G}}(w_d)],
\end{equation}
\begin{equation}
    prox_{\eta,\mathcal{G}}(w_i) = \begin{cases}
        \frac{w_i/\eta}{\frac{1}{\eta} + 2} & , w_i \in [0, \frac{1}{2}] \\
        \frac{w_i/\eta + 2}{\frac{1}{\eta} + 2} & , w_i\in (\frac{1}{2}, 1].
    \end{cases}
\end{equation}
When variables are updated as:
\begin{equation}
\begin{aligned}
    \bm{u}_{k+1} &= \bm{u}_k - \eta_k \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k) \\
    \bm{v}_{k+1} &= \bm{v}_k + \eta_k \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)\\
    \bar{\bm{w}}_{k+1} &= \bar{\bm{w}}_k - \eta_k \nabla_{\bm{w}} \mathcal{L}(\bar{\bm{w}}_k, \bm{v}_k, \bm{w}_k; \xi_k)\\
    \bm{w}_{k+1}&=prox_{\eta_k,\mathcal{G}}(\bar{\bm{w}}_{k+1}),
\end{aligned}
\end{equation}
the L-smooth property follows:
\begin{equation}
\resizebox{\columnwidth}{!}{$
    \begin{aligned}
        & \mathcal{L}(\bm{u}_{k+1}, \bm{v}_{k+1}, \bm{w}_{k+1}) 
        \\   \leq  & \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) 
         + 
        \begin{pmatrix}
            \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) \\
            \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) \\
            \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)
        \end{pmatrix}^T 
        \begin{pmatrix}
            \bm{u}_{k+1} - \bm{u}_k \\
            \bm{v}_{k+1} - \bm{v}_k \\
            \bm{w}_{k+1} - \bm{w}_k
        \end{pmatrix} \\
         &+ \frac{L}{2} \left\| \begin{pmatrix}
            \bm{u}_{k+1} - \bm{u}_k \\
            \bm{v}_{k+1} - \bm{v}_k \\
            \bm{w}_{k+1} - \bm{w}_k
        \end{pmatrix} \right\|^2.
    \end{aligned}
$}
\end{equation}

\subsection{Proof of Theorem 1 (Convergence of $\bm{w}$)}
Since the updating of $\bm{w}$ satisfies: 
\begin{equation}
\resizebox{\columnwidth}{!}{$
\begin{aligned}
&\bm{w}_{k+1} \\
=& \arg \min_{\bm{w}} \left(\mathcal{G}(\bm{w}) + \frac{1}{2\eta_k}\|\bm{w} - (\bm{w}_k - \eta_k \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_k))\|^2\right),
\end{aligned}
$}
\end{equation}
where $\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_k) $ is the stochastic gradient with samples $\bm{\xi}_k$.

With the L-smooth assumption, we have
\begin{equation}
\resizebox{\columnwidth}{!}{$
\label{L-smooth equality}
\begin{aligned}
    &\mathcal{L}(\bm{u}_{k+1}, \bm{v}_{k+1}, \bm{w}_{k+1}) \\
    \leq & \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) 
     + 
    \begin{pmatrix}
        \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) \\
        \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) \\
        \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)
    \end{pmatrix}^T 
    \begin{pmatrix}
        \bm{u}_{k+1} - \bm{u}_k \\
        \bm{v}_{k+1} - \bm{v}_k \\
        \bm{w}_{k+1} - \bm{w}_k
    \end{pmatrix} \\
     &+ \frac{L}{2} \left\| \begin{pmatrix}
        \bm{u}_{k+1} - \bm{u}_k \\
        \bm{v}_{k+1} - \bm{v}_k \\
        \bm{w}_{k+1} - \bm{w}_k
    \end{pmatrix} \right\|^2.
\end{aligned}
$}
\end{equation}
Since $\bm{w}_{k+1}$ is the minimizer, we have
\begin{equation}
\label{mimimizer equality}
\resizebox{\columnwidth}{!}{$
\begin{aligned}
    &\mathcal{G}(\bm{w}_{k+1}) + \frac{1}{2\eta_k} \|\bm{w}_{k+1} - (\bm{w}_k - \eta_k \nabla_{\bm{w}_t} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \boldsymbol{\xi}_t))\|^2 \\
    \leq &\mathcal{G}(\bm{w}_k) + \frac{1}{2\eta_k} \|\bm{w}_k - (\bm{w}_k - \eta_k \nabla_{\bm{w}_t} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \boldsymbol{\xi}_t))\|^2.
\end{aligned}
$}
\end{equation}
Combining the above (\ref{L-smooth equality}) and (\ref{mimimizer equality}) leads to the following inequality:
\begin{equation}
\resizebox{\columnwidth}{!}{$
\begin{aligned}
& \mathcal{L}(\bm{u}_{k+1}, \bm{v}_{k+1}, \bm{w}_{k+1}) + \mathcal{G}(\bm{w}_{k+1})\\
&+ \frac{1}{2\eta_k} \|\bm{w}_{k+1} - (\bm{w}_k - \eta_k \nabla \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_t))\|^2 \\
\leq & \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k) + \mathcal{G}(\bm{w}_k) \\
&+ \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)^T (\bm{w}_{k+1} - \bm{w}_k) + \frac{L}{2} \|\bm{w}_{k+1} - \bm{w}_k\|^2 \\
 & +\frac{\eta_k}{2} \|\nabla \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_t)\|^2+\mathcal{R}_k(\bm{u},\bm{v}),
\end{aligned}
$}
\end{equation}
where $\mathcal{R}_k(\bm{u},\bm{v})$ is given as:
\begin{equation}
\begin{aligned}
    &\mathcal{R}_k(\bm{u},\bm{v})\\
    =&
    \begin{bmatrix}
    \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{u}_k) \\
    \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{v}_k)
    \end{bmatrix}^T
    \begin{bmatrix}
    \bm{u}_{k+1} - \bm{u}_k \\
    \bm{v}_{k+1} - \bm{v}_k
    \end{bmatrix}\\
&+ \frac{L}{2} \left( \|\bm{u}_{k+1} - \bm{u}_k\|^2 + \|\bm{v}_{k+1} - \bm{v}_k\|^2 \right)\\
= & \left(- \eta_k + \frac{L}{2} \eta_k^2\right) \|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)\|^2 \\
&+ \left(\eta_k + \frac{L}{2} \eta_k^2\right) \|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)\|^2.
\end{aligned}
\end{equation}
Replacing $\mathcal{L}(\bm{u},\bm{v},\bm{w})+\mathcal{G}(\bm{w})$ with $\mathcal{F}(\bm{u},\bm{v},\bm{w})$ and expanding the left side of the inequality, we have
\begin{equation}
    \begin{aligned}
    & \mathcal{F}(\bm{u}_{k+1}, \bm{v}_{k+1}, \bm{w}_{k+1}) \\
    &+ \frac{1}{2\eta_k} \|\bm{w}_{k+1} - (\bm{w}_k - \eta_k \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_k))\|^2 \\
    \leq & \mathcal{F}(\bm{u}_k, \bm{v}_k, \bm{w}_k) + \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)^T (\bm{w}_{k+1} - \bm{w}_k)\\
    &+ \frac{L}{2} \|\bm{w}_{k+1} - \bm{w}_k\|^2 \\
    & + \frac{\eta_k}{2} \|\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_t)\|^2 + \mathcal{R}_k(\bm{u}, \bm{v}).
    \end{aligned}
\end{equation}
Thus,
\begin{equation}
    \begin{aligned}
    &\mathcal{F}(\bm{u}_{k+1}, \bm{v}_{k+1}, \bm{w}_{k+1})+\frac{1}{2\eta_k}\|\bm{w}_{k+1} - \bm{w}_k\|^2 \\
    &+ \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_k)^T (\bm{w}_{k+1} - \bm{w}_k)\\
    \leq & \mathcal{F}(\bm{u}_k, \bm{v}_k, \bm{w}_k)  + \frac{L}{2} \|\bm{w}_{k+1} - \bm{w}_k\|^2\\
    &+ \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)^T (\bm{w}_{k+1} - \bm{w}_k)  + \mathcal{R}_k(\bm{u}, \bm{v}).
    \end{aligned}
\end{equation}
Taking the expectation of the stochastic gradient as:
\begin{equation}
\begin{aligned}
        & \mathcal{F}(\bm{u}_{k+1}, \bm{v}_{k+1},\bm{w}_{k+1})-\mathcal{F}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\\
        &+\mathbb{E}[\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_k)^T ](\bm{w}_{k+1} - \bm{w}_k)\\
        \leq &\left(\frac{L}{2} - \frac{1}{2\eta_k}\right) \|\bm{w}_{k+1} - \bm{w}_k\|^2\\
        &+\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)^T (\bm{w}_{k+1} - \bm{w}_k) \\
        &+\mathbb{E}[\mathcal{R}_k(\bm{u}, \bm{v})].
\end{aligned}
\end{equation}
Since
\begin{equation}
    \begin{aligned}
        &\mathbb{E}[\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \bm{\xi}_k)]=\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k).
    \end{aligned}
\end{equation}
We have the following:
\begin{equation}
\begin{aligned}
     &\mathcal{F}(\bm{u}_{k+1}, \bm{v}_{k+1},\bm{w}_{k+1})-\mathcal{F}(\bm{u}_k, \bm{v}_k, \bm{w}_k) \\
    \leq &\left(\frac{L}{2} - \frac{1}{2\eta_k}\right) \|\bm{w}_{k+1} - \bm{w}_k\|^2 \\
    &+\mathbb{E}[\mathcal{R}_k(\bm{u}, \bm{v})].
\end{aligned}
\end{equation}
By summing up $T$ steps, we have
\begin{equation}
\label{T steps equality of w}
\begin{aligned} 
&\sum_{k=1}^T \left(\frac{1}{2\eta_k}-\frac{L}{2} \right)\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2] \\
    \leq & \mathcal{F}(\bm{u}_{1}, \bm{v}_{1}, \bm{w}_{1})-\mathcal{F}(\bm{u}_{T+1}, \bm{v}_{T+1}, \bm{w}_{T+1})\\
    &+\sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{u}, \bm{v})].
\end{aligned}
\end{equation}
Taking step-size $\eta_k = \frac{\eta}{\sqrt{k}}$ and $\frac{1}{2\eta_k}-\frac{L}{2}>0$, we have
\begin{equation}
\label{sums with stepsize}
\begin{aligned}
   \sum_{k=1}^T \left( \frac{\sqrt{k}}{2\eta}-\frac{L}{2} \right) &\approx \frac{T^{3/2}+1}{3\eta} -\frac{LT}{2}   \\
   \sum_{k=1}^T\frac{1}{k} &\approx \log(T)\\
   \sum_{k=1}^T\frac{1}{\sqrt{k}} &\approx 2\sqrt{T}.
\end{aligned}
\end{equation}
Denoting $\sigma_{\bm{u}},\sigma_{\bm{v}},\sigma_{\bm{w}}$ as the variance of the stochastic gradient of $\bm{u},\bm{v},\bm{w}$, we have
\begin{equation}
\begin{aligned}
    &\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)\|^2] \\
    \leq & \mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)-\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2\\
    &+\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
\leq & \sigma_{\bm{u}}^2 + \mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2].
\end{aligned}
\end{equation}
Thus, we have
\begin{equation}
\label{expectation of R(u,v)}
\begin{aligned}
&\sum_{k=1}^T\mathbb{E}[\mathcal{R}_k(\bm{u}, \bm{v})] \\
\approx &  \left(\frac{L\eta^2}{2} \log(T)-2\eta\sqrt{T}\right)\left(\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}, \bm{v}, \bm{w})\|^2]+\sigma_{\bm{u}}\right) \\
& +\left(\frac{L\eta^2}{2} \log(T)+2\eta\sqrt{T}\right) \left(\mathbb{E}[\| \nabla_{\bm{v}} \mathcal{L}(\bm{u}, \bm{v}, \bm{w})\|^2 ]+\sigma_{\bm{v}}\right).
\end{aligned}
\end{equation}
Combining (\ref{T steps equality of w}), (\ref{sums with stepsize}) and (\ref{expectation of R(u,v)}), we have
\begin{equation}
\resizebox{\columnwidth}{!}{$
\begin{aligned}
    &\frac{1}{T} \sum_{k=1}^T \mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2]\\
    \leq & \left( \frac{6\eta}{2\sqrt{T}+\frac{2}{T}-3\eta L}\right)\left(\mathcal{F}(\bm{u}_{1}, \bm{v}_{1}, \bm{w}_{1})-\mathcal{F}(\bm{u}_{T+1}, \bm{v}_{T+1}, \bm{w}_{T+1})\right)\\
   &+\left(\frac{L\eta^2\log(T)}{2T} -\frac{2\eta}{\sqrt{T}}\right)\left(\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}, \bm{v}, \bm{w})\|^2]+\sigma_{\bm{u}}\right)\\
   &+\left(\frac{L\eta^2\log(T)}{2T} + \frac{2\eta}{\sqrt{T}}\right)\left(\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}, \bm{v}, \bm{w})\|^2]+\sigma_{\bm{v}}\right).
\end{aligned}
$}
\end{equation}
With the assumptions that the gradient is bounded, such that $\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|\leq G_{\bm{u}}$ and $\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|\leq G_{\bm{v}}$,$\mathcal{F}$ has a lower bound, such that $
\mathcal{F}^*\leq \mathcal{F}(\bm{u}_{T+1}, \bm{v}_{T+1}, \bm{w}_{T+1})$, we have
\begin{equation}
\begin{aligned}
    &\frac{1}{T} \sum_{k=1}^T \mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2]\\
    \leq & \left( \frac{6\eta}{2\sqrt{T}+\frac{2}{T}-3\eta L}\right)\left(\mathcal{F}(\bm{u}_{1}, \bm{v}_{1}, \bm{w}_{1})-\mathcal{F}^*\right)\\
   &+\left(\frac{L\eta^2\log(T)}{2T} -\frac{2\eta}{\sqrt{T}}\right)\left(G_{\bm{u}}^2+\sigma_{\bm{u}}\right)\\
   &+\left(\frac{L\eta^2\log(T)}{2T} + \frac{2\eta}{\sqrt{T}}\right)\left(G_{\bm{v}}^2+\sigma_{\bm{v}}\right).
\end{aligned}
\end{equation}
Thus, $\bm{w}$ has a convergence rate of $\mathcal{O}(\frac{1}{\sqrt{T}})$.
\subsection{Proof of Theorem 2 (Convergence of $\bm{u}$)}
Based on the L-smooth assumption we have
\begin{equation}
\begin{aligned}
    &\mathcal{L}(\bm{u}_{k+1},\bm{v}_{k+1},\bm{w}_{k+1}) \\
    \leq & \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k) + \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k)^\top (\bm{u}_{k+1}-\bm{u}_k) \\
    &+ \frac{L}{2} \|\bm{u}_{k+1}-\bm{u}_k\|^2+\mathcal{R}_k(\bm{v},\bm{w}),
\end{aligned}
\end{equation}
where $\mathcal{R}_k(\bm{v},\bm{w})$ is as follows:
\begin{equation}
\begin{aligned}
    \mathcal{R}_k(\bm{v},\bm{w})=&
    \begin{bmatrix}
    \nabla_{\bm{v}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{v}_k) \\
    \nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)
    \end{bmatrix}^T
    \begin{bmatrix}
    \bm{v}_{k+1} - \bm{v}_k \\
    \bm{w}_{k+1} - \bm{w}_k
    \end{bmatrix}\\
&+ \frac{L}{2} \left( \|\bm{v}_{k+1} - \bm{v}_k\|^2 + \|\bm{w}_{k+1} - \bm{w}_k\|^2 \right)\\
= & \left(\eta_k + \frac{L}{2} \eta_k^2\right) \|\nabla_{\bm{v}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k; \xi_k)\|^2 \\
&+  \nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)\\
&+\frac{L}{2}\|\bm{w}_{k+1} - \bm{w}_k\|^2.
\end{aligned}
\end{equation}
With $\bm{u}_{k+1} = \bm{u}_k - \eta_k \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)$, we have
\begin{equation}
\resizebox{\columnwidth}{!}{$
\begin{aligned}
       &\mathcal{L}(\bm{u}_{k+1},\bm{v}_{k+1},\bm{w}_{k+1})\\
       \leq &\mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k) - \eta_k \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k)^\top \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)  \\
       &+ \frac{L}{2} \eta_k^2\| \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)\|^2 +\mathcal{R}_k(\bm{v},\bm{w}).
\end{aligned}
$}
\end{equation}
Taking the expectation of the stochastic gradient, we have
\begin{equation}
\label{inequality with expection of gradient u}
\begin{aligned}
     &\mathcal{L}(\bm{u}_{k+1},\bm{v}_{k+1},\bm{w}_{k+1})-\mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k) \\
     \leq &\frac{L}{2} \eta_k^2\mathbb{E}[\| \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)\|^2]\\
     &-\eta_k \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k)^\top \mathbb{E}[\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k) ]\\
     &+\mathbb{E}[\mathcal{R}_k(\bm{v},\bm{w})].
\end{aligned}
\end{equation}
According to the assumption of the unbiased estimation of the stochastic gradient and defining the variance of the stochastic gradient of $\bm{u}$ as $\sigma_{\bm{u}}$, we have
\begin{equation}
\begin{aligned}
    \mathbb{E}[\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)] &= \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\\
    \mathbb{E}[\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)] &= \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k),
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
    &\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)\|^2]\\
    =&\mathbb{E}[\|(\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)-\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k))\\
    &+\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
    \leq& \sigma_{\bm{u}}^2 + \mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2].
\end{aligned}
\end{equation}
Thus, by summing up (\ref{inequality with expection of gradient u}) for $T$ steps, we have
\begin{equation}
\label{inequality summed over k}
\begin{aligned}
     &\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})-\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1) \\
     \leq &\sum_{k=1}^T(\frac{L}{2} \eta_k^2-\eta_k)\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
     &+\frac{L}{2} \eta_k^2\sigma_{\bm{u}}^2+\sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{v},\bm{w})].
\end{aligned}
\end{equation}
Taking stepsize $\eta_k=\frac{\eta}{\sqrt{k}}$, we have
\begin{equation}
\begin{aligned}
     &\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})-\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1) \\
     \leq &\sum_{k=1}^T \left(\frac{L\eta^2}{2k} - \frac{\eta}{\sqrt{k}}\right) \mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
     &+ \frac{L\eta^2}{2} \sum_{k=1}^T \frac{\sigma_{\bm{u}}^2}{k} + \sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{v},\bm{w})],
\end{aligned}
\end{equation}
where
\begin{equation}
\begin{aligned}
    &\sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{v},\bm{w})]\\
    =&\frac{LT}{2}\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2]\\
     &+\sum_{k=1}^T \left(\frac{L\eta^2}{2k} + \frac{\eta}{\sqrt{k}}\right)\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
     &+\sum_{k=1}^T\mathbb{E}[\nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)]
\end{aligned}
\end{equation}
With $\sum_{k=1}^T \frac{1}{k}\approx \log(T),\sum_{k=1}^T \frac{1}{\sqrt{k}}\approx 2\sqrt{T}$, we have
\begin{equation}
    \begin{aligned}
        \frac{L\eta^2}{2k} - \frac{\eta}{\sqrt{k}} &\approx \frac{L\eta^2\log(T)}{2} - 2\eta\sqrt{T}\\
       \frac{L\eta^2}{2k} + \frac{\eta}{\sqrt{k}} &\approx \frac{L\eta^2\log(T)}{2} + 2\eta\sqrt{T}.
    \end{aligned}
\end{equation}
Thus, we have :
\begin{equation}
    \begin{aligned}
        &\frac{1}{T}\sum_{k=1}^T\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
        \leq &  \frac{\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1)-\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})}{\mathcal{C}_{\eta,L}(T)}+\frac{L\eta^2\sigma_{\bm{u}}^2\log(T)}{\mathcal{C}_{\eta,L}(T)}\\
        &+\frac{LT\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2]}{2\mathcal{C}_{\eta,L}(T)}\\
        &+\frac{(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]}{\mathcal{C}_{\eta,L}(T)}\\
        &+\frac{\sum_{k=1}^T\mathbb{E}[\nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)]}{\mathcal{C}_{\eta,L}(T)},
    \end{aligned}
\end{equation}
where $\mathcal{C}_{\eta,L}(T) = T(2\eta\sqrt{T}-\frac{L\eta^2\log(T)}{2})$.

With the assumption that the gradient is bounded, such that $\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|\leq G_{\bm{v}}$ and $\|\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|\leq G_{\bm{w}}$, we have the following:
\begin{equation}
\begin{aligned}
        &\frac{(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]}{\mathcal{C}_{\eta,L}(T)}\\
        \leq   &\frac{(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})G_{\bm{v}}^2}{\mathcal{C}_{\eta,L}(T)},\\
        &\frac{\sum_{k=1}^T\nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)}{\mathcal{C}_{\eta,L}(T)}\\
        \leq &\frac{G_{\bm{w}}\sum_{k=1}^T \mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|]}{\mathcal{C}_{\eta,L}(T)}.
\end{aligned}
\end{equation}
Since $\bm{w}_k$ is convergent, then $ \mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|]$ is bounded, assuming $\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|\leq M_{\bm{w}}$ thus, we have the following:
\begin{equation}
    \begin{aligned}
        &\frac{1}{T}\sum_{k=1}^T\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
        \leq &  \frac{\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1)-\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})}{\mathcal{C}_{\eta,L}(T)}+\frac{L\eta^2\sigma_{\bm{u}}^2\log(T)}{\mathcal{C}_{\eta,L}(T)}\\
        &+\frac{LTM_{\bm{w}}^2}{2\mathcal{C}_{\eta,L}(T)}+\frac{(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})G_{\bm{v}}}{\mathcal{C}_{\eta,L}(T)}+\frac{G_{\bm{w}}TM_{\bm{w}}}{\mathcal{C}_{\eta,L}(T)}.
    \end{aligned}
\end{equation}
Since $\mathcal{C}_{\eta,L}(T) = T(2\eta\sqrt{T}-\frac{L\eta^2\log(T)}{2})=\mathcal{O}(T^{1.5})$, we have
\begin{equation}
\begin{aligned}
    &\max\{\frac{1}{\mathcal{C}_{\eta,L}(T)},\frac{L\eta^2\sigma_{\bm{u}}^2\log(T)}{\mathcal{C}_{\eta,L}(T)},\frac{LTM_{\bm{w}}^2}{2\mathcal{C}_{\eta,L}(T)},\\
    &\frac{(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})G_{\bm{v}}}{\mathcal{C}_{\eta,L}(T)},\frac{G_{\bm{w}}TM_{\bm{w}}}{\mathcal{C}_{\eta,L}(T)}\}\\
    = & \mathcal{O}(\frac{1}{\sqrt{T}}).
\end{aligned}
\end{equation}
Thus, $\bm{u}$ as a convergence rate of $\mathcal{O}(\frac{1}{\sqrt{T}})$.
\subsection{Proof of Theorem 3 (Convergence of $\bm{v}$)}
Based on the L-smooth assumption we have
\begin{equation}
\begin{aligned}
    &\mathcal{L}(\bm{u}_{k+1},\bm{v}_{k+1},\bm{w}_{k+1}) \\
    \leq & \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k) + \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k)^\top (\bm{v}_{k+1}-\bm{v}_k) \\
    &+ \frac{L}{2} \|\bm{v}_{k+1}-\bm{v}_k\|^2 + \mathcal{R}_k(\bm{u}, \bm{w}),
\end{aligned}
\end{equation}
where $\mathcal{R}_k(\bm{u},\bm{w})$ is as follows:
\begin{equation}
\begin{aligned}
    \mathcal{R}_k(\bm{u},\bm{w})=&
