    \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{w}_k, \bm{u}_k) \\
    \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{w}_k, \bm{w}_k)
    \end{bmatrix}^T
    \begin{bmatrix}
    \bm{u}_{k+1} - \bm{u}_k \\
    \bm{w}_{k+1} - \bm{w}_k
