& +  \nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)\\
&+\frac{L}{2}\|\bm{w}_{k+1} - \bm{w}_k\|^2.
\end{aligned}
\end{equation}
With $\bm{v}_{k+1} = \bm{v}_k + \eta_k \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)$ , we have
\begin{equation}
\begin{aligned}
       &\mathcal{L}(\bm{u}_{k+1},\bm{v}_{k+1},\bm{w}_{k+1})\\
  \leq &\mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k) + \eta_k \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k)^\top \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)  \\
       &+ \frac{L}{2} \eta_k^2\| \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)\|^2 +\mathcal{R}_k(\bm{u},\bm{w}).
\end{aligned}
\end{equation}
Taking the expectation of the stochastic gradient, we have
\begin{equation}
\label{inequality with expection of gradient v}
\begin{aligned}
     &\mathcal{L}(\bm{u}_{k+1},\bm{v}_{k+1},\bm{w}_{k+1})-\mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k) \\
     \leq &\frac{L}{2} \eta_k^2 \mathbb{E}[\| \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k) \|^2]\\
     &+ \eta_k \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k)^\top \mathbb{E}[\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k,\bm{v}_k,\bm{w}_k; \xi_k)] \\
     &+ \mathbb{E}[\mathcal{R}_k(\bm{u}, \bm{w})]. 
\end{aligned}
\end{equation}
According to the assumption of the unbiased estimation of the stochastic gradient and defining the variance of the stochastic gradient of $\bm{v}$ as $\sigma_{\bm{v}}$, we have
\begin{equation}
\begin{aligned}
    \mathbb{E}[\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)] &= \nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\\
    \mathbb{E}[\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)] &= \nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k),
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
    &\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)\|^2]\\
    =&\mathbb{E}[\|(\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k; \xi_k)-\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k))\\
    &+\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
    \leq& \sigma_{\bm{v}}^2 + \mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2].
\end{aligned}
\end{equation}
Thus, by summing up (\ref{inequality with expection of gradient v}) for $T$ steps, we have the following:
\begin{equation}
\label{inequality summed over k with v}
\begin{aligned}
     &\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})-\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1) \\
