     &+\frac{L}{2} \eta_k^2\sigma_{\bm{v}}^2+\sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{u},\bm{w})].
\end{aligned}
\end{equation}
Taking stepsize $\eta_k=\frac{\eta}{\sqrt{k}}$, we have
\begin{equation}
\begin{aligned}
     &\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})-\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1) \\
     \leq &\sum_{k=1}^T \left(\frac{L\eta^2}{2k} + \frac{\eta}{\sqrt{k}}\right) \mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
     &+ \frac{L\eta^2}{2} \sum_{k=1}^T \frac{\sigma_{\bm{v}}^2}{k} + \sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{u},\bm{w})],
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
    &\sum_{k=1}^T \mathbb{E}[\mathcal{R}_k(\bm{u},\bm{w})]\\
    =&\frac{LT}{2}\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2]
     \\
     &+\sum_{k=1}^T \left(\frac{L\eta^2}{2k} - \frac{\eta}{\sqrt{k}}\right)\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
