\end{aligned}
\end{equation}
With $\sum_{k=1}^T \frac{1}{k}\approx \log(T), \sum_{k=1}^T \frac{1}{\sqrt{k}}\approx 2\sqrt{T}$, we have
\begin{equation}
    \begin{aligned}
        \frac{L\eta^2}{2k} - \frac{\eta}{\sqrt{k}} &\approx \frac{L\eta^2\log(T)}{2} - 2\eta\sqrt{T},\\
       \frac{L\eta^2}{2k} + \frac{\eta}{\sqrt{k}} &\approx \frac{L\eta^2\log(T)}{2} + 2\eta\sqrt{T}.
    \end{aligned}
\end{equation}
Thus, we have the following:
\begin{equation}
    \begin{aligned}
        &\frac{1}{T}\sum_{k=1}^T\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
        \leq &  \frac{\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1)-\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})}{\mathcal{C}'_{\eta,L}(T)}\\
        &+\frac{L\eta^2\sigma_{\bm{v}}^2\log(T)}{\mathcal{C}'_{\eta,L}(T)}+\frac{LT\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|^2]}{2\mathcal{C}'_{\eta,L}(T)}\\
        &+\frac{(\frac{L\eta^2\log(T)}{2}-2\eta\sqrt{T})\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]}{\mathcal{C}'_{\eta,L}(T)}\\
        &+\frac{\sum_{k=1}^T\mathbb{E}[\nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)]}{\mathcal{C}'_{\eta,L}(T)},
    \end{aligned}
\end{equation}
where $\mathcal{C}'_{\eta,L}(T) = T(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})$.

With the assumption that the gradient is bounded, such that $\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|\leq G_{\bm{u}}$ and $\|\nabla_{\bm{w}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|\leq G_{\bm{w}}$, we have the following:
\begin{equation}
\begin{aligned}
        &\frac{(2\eta\sqrt{T}-\frac{L\eta^2\log(T)}{2})\mathbb{E}[\|\nabla_{\bm{u}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]}{\mathcal{C}'_{\eta,L}(T)}\\
        \leq &   \frac{(\frac{L\eta^2\log(T)-2\eta\sqrt{T}}{2})G_{\bm{u}}^2}{\mathcal{C}'_{\eta,L}(T)},\\
        &\frac{\sum_{k=1}^T\nabla_{\bm{w}} \mathcal{L}(\bm{v}_k, \bm{w}_k, \bm{w}_k)^T(\bm{w}_{k+1} - \bm{w}_k)}{\mathcal{C}'_{\eta,L}(T)}\\
        \leq & \frac{G_{\bm{w}}\sum_{k=1}^T \mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|]}{\mathcal{C}'_{\eta,L}(T)}.
\end{aligned}
\end{equation}
Since $\bm{w}_k$ is convergent, then $ \mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|]$ is bounded, assuming $\mathbb{E}[\|\bm{w}_{k+1} - \bm{w}_k\|\leq M_{\bm{w}}$, we have the following.
\begin{equation}
    \begin{aligned}
        &\frac{1}{T}\sum_{k=1}^T\mathbb{E}[\|\nabla_{\bm{v}} \mathcal{L}(\bm{u}_k, \bm{v}_k, \bm{w}_k)\|^2]\\
        \leq &  \frac{\mathcal{L}(\bm{u}_1,\bm{v}_1,\bm{w}_1)-\mathcal{L}(\bm{u}_{T+1},\bm{v}_{T+1},\bm{w}_{T+1})}{\mathcal{C}'_{\eta,L}(T)}+\frac{L\eta^2\sigma_{\bm{v}}^2\log(T)}{\mathcal{C}'_{\eta,L}(T)}\\
        &+\frac{LTM_{\bm{w}}^2}{2\mathcal{C}'_{\eta,L}(T)}+\frac{(\frac{L\eta^2\log(T)}{2}-2\eta\sqrt{T})G_{\bm{u}}}{\mathcal{C}'_{\eta,L}(T)}+\frac{G_{\bm{w}}TM_{\bm{w}}}{\mathcal{C}'_{\eta,L}(T)}
    \end{aligned}
\end{equation}
Since $\mathcal{C}'_{\eta,L}(T) = T(2\eta\sqrt{T}+\frac{L\eta^2\log(T)}{2})=\mathcal{O}(T^{1.5})$, we have
\begin{equation}
\begin{aligned}
    &\max\{\frac{1}{\mathcal{C}'_{\eta,L}(T)},\frac{L\eta^2\sigma_{\bm{v}}^2\log(T)}{\mathcal{C}'_{\eta,L}(T)},\frac{LTM_{\bm{w}}^2}{2\mathcal{C}'_{\eta,L}(T)},\\
    &\frac{(\frac{L\eta^2\log(T)}{2}-2\eta\sqrt{T})G_{\bm{u}}}{\mathcal{C}'_{\eta,L}(T)},\frac{G_{\bm{w}}TM_{\bm{w}}}{\mathcal{C}'_{\eta,L}(T)}\}\\
