\section{Distributional Derivatives}
    If they exist, the partial derivatives of $f_i(x)$ with respect to parameters $p_i$ and $y_i$ are:
    \begin{align*}
        \frac{\partial f_i(x)}{\partial p_i} & =
        - \beta f_i(x) + \beta f_i(x)^2 = -\beta f_i(x) (1 - f_i(x))\\
        \frac{\partial f_i(x)}{\partial y_i^j} & = - \beta f_i(x) (1 - f_i(x)) \cdot \nabla_{y_i^j} d_\mathcal{M}(x, y_i)
    \end{align*}

    On a general smooth and compact submanifold $\mathcal{M}$, the term $\nabla_{y_i} d_\mathcal{M}(x, y_i)$ is only defined $d \mathcal V_\mathcal{M}$-almost everywhere due to the Lipschitz continuity of the distance function and Rademacher's theorem. However, we can rigorously define these derivatives in the distributional sense.

    Assuming that for each fixed $(p_i, y_i)$, the function $f_i(\cdot; p_i, y_i): \mathcal{M} \rightarrow \mathbb{R}$ belongs to $L^1(\mathcal{M}, d\mathcal{V}_\mathcal{M})$, and that the formal derivatives are also in $L^1(\mathcal{M}, d\mathcal{V}_\mathcal{M})$:
    \begin{align*}
        &f_i(\cdot; p_i, y_i), \frac{\partial f_i}{\partial p_i}(\cdot; p_i, y_i), \frac{\partial f_i}{\partial y_i^j}(\cdot; p_i, y_i), \frac{\partial^2 f_i}{\partial p_i^2}(\cdot; p_i, y_i),\\ &\frac{\partial^2 f_i}{\partial y_i^j \partial y_i^k}(\cdot; p_i, y_i), \frac{\partial^2 f_i}{\partial y_i^j \partial p_i}(\cdot; p_i, y_i) \in L^1(\mathcal{M}, d\mathcal{V}_\mathcal{M})
    \end{align*}

    Then, for any test function $\phi \in C_c^\infty(\mathcal{M})$, we can characterize the distributional derivatives of $f_i$ with respect to parameters as:
    \begin{align*}
        & \langle \nabla_{p_i} f_i, \phi \rangle = \int_\mathcal{M} \frac{\partial f_i(x)}{\partial p_i} \phi(x) d\mathcal{V}_\mathcal{M} = -\int_\mathcal{M} \beta f_i(x) (1 - f_i(x)) \phi(x) d\mathcal{V}_\mathcal{M} \\
        & \langle \nabla_{y_i^j} f_i, \phi \rangle = \int_\mathcal{M} \frac{\partial f_i(x)}{\partial y_i^j} \phi(x) d\mathcal{V}_\mathcal{M} = -\int_\mathcal{M} \beta f_i(x) (1 - f_i(x)) \nabla_{y_i^j} d_\mathcal{M}(x, y_i) \phi(x) d\mathcal{V}_\mathcal{M}
    \end{align*}

\section{No Concentration without manifold boundaries}
\label{proof:concentrated_noboundary}
\begin{proof}[Proof (Theorem \ref{thm:concentrated_noboundary})]
    Let's consider the function $F(y) = \int_{\mathcal{M}} d_\mathcal{M}(x,y)d\mathcal{V}_\mathcal{M}(x)$. 

    Fix any \( x \in \mathcal{M} \). The Riemannian distance function $(x, y) \mapsto d_{\mathcal{M}}(x, y)$ is continuous on \( \mathcal{M} \times \mathcal{M} \), so for fixed \( x \), the function \( y \mapsto d_{\mathcal{M}}(x, y) \) is continuous.

    The triangle inequality for the Riemannian distance implies that for all \( x, y, y' \in \mathcal{M} \),
    \[
    \left| d_{\mathcal{M}}(x, y) - d_{\mathcal{M}}(x, y') \right| \leq d_{\mathcal{M}}(y, y').
    \]

    This shows that the map \( y \mapsto d_{\mathcal{M}}(x, y) \) is 1-Lipschitz uniformly in \( x \). In particular, for any sequence \( y_n \to y \), we have
    \[
    \sup_{x \in \mathcal{M}} \left| d_{\mathcal{M}}(x, y_n) - d_{\mathcal{M}}(x, y) \right| \leq d_{\mathcal{M}}(y_n, y) \to 0,
    \]
    so \( d_{\mathcal{M}}(x, y_n) \to d_{\mathcal{M}}(x, y) \) uniformly in \( x \).

    We apply the Dominated Convergence Theorem (DCT), with the constant function \( d_{\mathcal{M}}(y_n, y) \cdot 1 \) as an integrable dominating function (bounded if \( \mathcal{M} \) is compact), to conclude:
    \[
    \lim_{n \to \infty} F(y_n) = \lim_{n \to \infty} \int_{\mathcal{M}} d_{\mathcal{M}}(x, y_n)d\mathcal{V}_\mathcal{M}(x)
    = \int_{\mathcal{M}} d_{\mathcal{M}}(x, y) d\mathcal{V}_\mathcal{M}(x)= F(y).
    \]


    The function \( F(y) \) is continuous on \( \mathcal{M} \). The estimate
    \(
    |F(y') - F(y)| \leq \mathrm{Vol}(\mathcal{M}) \cdot d_{\mathcal{M}}(y, y')
    \)
    shows that \( F \) is globally Lipschitz on \( \mathcal{M} \), hence uniformly continuous.

    As \( F \) is continuous, and as $\mathcal{M}$ is a compact set, we have that \(F(\mathcal{M})\) is a compact set by the Weierstrass theorem. As $\mathcal{M}$ does not have a boundary by assumption, the minimizer $\bar y$ is an interior point:
    \[
    \bar y \in \left\{y\in \mathcal{M}: \int_{\mathcal{M}} \nabla_{y_i}d_\mathcal{M}(x, y_i)d\mathcal{V}_\mathcal{M}(x) = 0 \right\}
    \]

    It remains to show that
    \[
    \nabla^2 F(\bar y)
    \quad\text{is \emph{not} positive definite.}
    \]

    Fix normal coordinates $(y^1,\dots,y^n)$ centered at $\bar y$.  Along any geodesic
    \(
    \gamma(t)=\exp_{\bar y}(t\,v),
    \quad
    v\in T_{\bar y}\mathcal{M},
    \)
    the second derivative of $F(\gamma(t))$ at $t=0$ is
    \[
    \frac{d^2}{dt^2}\Big|_{t=0}F(\gamma(t))
    =
    \int_{\mathcal{M}}
    \frac{d^2}{dt^2}\Big|_{t=0}
    \,d_{\mathcal{M}}\bigl(x,\gamma(t)\bigr)
    \;d\mathcal{V}(x).
    \]

    But it is well–known (via the Hessian comparison for distance functions) that
    \[
    \frac{d^2}{dt^2}\Big|_{t=0}
    \,d_{\mathcal{M}}(x,\gamma(t))
    \;\ge\;0,
    \]

    and in fact vanishes whenever the geodesic from $\bar y$ to $x$ is orthogonal to $v$.  Since $\mathcal{M}$ is boundaryless, for each nonzero $v$ there is a nonempty open cone of directions $x$ for which the minimal geodesic from $\bar y$ to $x$ meets $v$ orthogonally.  Hence for every $v$,
    \[
    \int_{\mathcal{M}}
    \frac{d^2}{dt^2}\Big|_{t=0}
    \,d_{\mathcal{M}}(x,\gamma(t))
    \,d\mathcal{V}(x)
    \;=\;
    0
    \]

    Equivalently,
    \[
    v^\top\bigl(\nabla^2F(\bar y)\bigr)\,v
    \;=\;
    \frac{d^2}{dt^2}\Big|_{t=0}F(\gamma(t))
    \;=\;0,
    \]

    Therefore $\nabla^2F(\bar y)$ cannot be positive definite.
\end{proof}


\section{Separability on the generalized cylinder}
\label{proof:separability_cylinder}
\begin{proof}[Proof (Proposition \ref{prop:separability_cylinder})]
    We seek to find the stationary points for a set of locations $\{y_i\}_{i=1}^N$ on an immersed Riemannian manifold $\mathcal{M}\subseteq \mathbb{R}^n$. We consider $M=M_1 \times M_2 \subseteq \mathbb{R}^d$ where $M_1$ is the set corresponding to bounded components on the manifold (of dimension $k_1$), and $M_2$ to periodic ones (of dimension $k_2$). $\mathfrak{M}$ is the immersion such that $\mathcal{M} = \mathfrak{M}(M)$ is a generalized cylinder. 
    \[
    \begin{aligned}
    \Phi_1\:&\:M_1\to\mathbb{R}^{n-2k_2},\quad \Phi_2\!:M_2\to\mathbb{R}^{2k_2}\quad\text{(immersions),}\\
    \Phi_1(u) &= (u^1,\dots,u^{k_1},\,0,\dots,0)\in \mathbb{R}^{n - 2k_2}, \\
    \Phi_2(\theta) &= (\cos\theta^1,\sin\theta^1,\dots,\cos\theta^{k_2},\sin\theta^{k_2}) \in \mathbb{R}^{2k_2}, \\
    \mathfrak M\!:\;M_1\times M_2&\;\to\;\mathbb{R}^n,\quad
    \mathfrak M(p,q)\;=\;(\,\Phi_1(p),\,\Phi_2(q)\,),\\
    D\mathfrak M(p,q)&=\begin{pmatrix}D\Phi_1(p)&0\\0&D\Phi_2(q)\end{pmatrix}
    \quad\Longrightarrow\quad\operatorname{rank}(D\mathfrak M) = k_1+k_2,\\
    %d_\mathcal{M}&((u_a, \theta_a), (u_b, \theta_b)) =\sqrt{d_{M_1}^2(u_a,u_b)+d_{M_2}^2(\theta_a,\theta_b)},
    \end{aligned}
    \]

    The stationary points are solutions to the following first-order condition (FOC) for each $i \in \{1, \dots, N\}$:
        \begin{equation} \label{eq:foc_full}
            \int_{M} f_i(x)\left(1-f_i(x)\right)\nabla_{y_i}d_\mathcal{M}(x,y_i)\sqrt{\det(g_\mathcal{M}(x))}dx = 0,
        \end{equation}

    with $f_i(x) = \text{softmin}_\beta(d_\mathcal{M}(x, y_i) + p_i) = \frac{\exp(-\beta (d_\mathcal{M}(x, y_i) +p_i))}{\sum_{k=1}^N \exp(-\beta (d_\mathcal{M}(x, y_k) +p_k))}$

    We will prove that any solution $\{y_i^*\}_{i=1}^N$ to this system of equations must satisfy the property of separability.

    \begin{lem}[Distance–Squared Splitting]
        Under the product metric, the Riemannian distance satisfies
        \[
        d_{\mathcal M}(x,y)^2
        \;=\;
        d_{M_1}\bigl(u_x,u_y\bigr)^2
        \;+\;
        d_{M_2}\bigl(\theta_x,\theta_y\bigr)^2.
        \]
        with $x=(u_x, \theta_x)$ and $y=(u_y, \theta_y)$\footnote{If $M_2=T^k=\prod_{j=1}^kS^1(R_j)$ with its flat metric, then 
        \[
        d(x,y)^2
        =
        d_{M_1}\bigl(x^{(1)},y^{(1)}\bigr)^2
        +
        \sum_{j=1}^k
        R_j^2\,\mathrm{dist}_{S^1}(\phi^j,\theta^j)^2.
        \]}
    \end{lem}

    \begin{proof}
        Let $x=(u_x, \theta_x)$ and $y=(u_y, \theta_y)$. Let \( \gamma(t) = (\gamma_1(t), \gamma_2(t)) \) be a smooth curve in the product Riemannian manifold \( \mathcal{M} = M_1 \times M_2 \), with corresponding Riemannian metrics \( g_{M_1} \) and \( g_{M_2} \). Define the speed vector:
        \[
        F(t) = \left( \|\dot\gamma_1(t)\|_{g_{M_1}}, \|\dot\gamma_2(t)\|_{g_{M_2}} \right) \in \mathbb{R}^2.
        \]

        Then the length of the curve \( \gamma \) in \( \mathcal{M} \) can be written as an \( L^1 \)-norm in \( \mathbb{R}^2 \):
        \[
        L(\gamma)
        = \int_0^1 \left\| \dot\gamma(t) \right\|_{g_{\mathcal{M}}} \, dt
        = \int_0^1 \sqrt{ \|\dot\gamma_1(t)\|^2 + \|\dot\gamma_2(t)\|^2 } \, dt
        = \int_0^1 \|F(t)\|_{\ell^2} \, dt
        = \|F\|_{L^1([0,1]; \mathbb{R}^2)}.
        \]

        By Jensen inequality in \( \mathbb{R}^2 \), we have:
        \[
        \left\| \int_0^1 F(t) \, dt \right\|_{\ell^2}
        \le
        \int_0^1 \|F(t)\|_{\ell^2} \, dt
        = \|F\|_{L^1} = L(\gamma).
        \]

        Now observe that:
        \[
        \int_0^1 F(t)\,dt
        = \left( \int_0^1 \|\dot\gamma_1(t)\|\,dt, \int_0^1 \|\dot\gamma_2(t)\|\,dt \right)
        = \left( L(\gamma_1), L(\gamma_2) \right),
        \]
        so we conclude:
        \[
        \sqrt{ L(\gamma_1)^2 + L(\gamma_2)^2 }
        = \left\| \int_0^1 F(t)\,dt \right\|_{\ell^2}
        \le L(\gamma).
        \]
        where $L(\gamma_i)$ is the length of the projection curve $\gamma_i$ in $M_i$. Taking the infimum over all such $\gamma$ gives
        \[
        d_{\mathcal M}(x,y)
        =\inf_\gamma L(\gamma)
        \;\ge\;
        \sqrt{
        d_{M_1}(u_x,u_y)^2
        +
        d_{M_2}(\theta_x,\theta_y)^2
        }.
        \]

        On the other hand, since each $M_i$ is complete, there exist minimizing geodesics $\eta_1\colon[0,1]\to M_1$ joining $u_x$ to $u_y$ with length $d_{M_1}(u_x,u_y)$, and $\eta_2\colon[0,1]\to M_2$ joining $\theta_x$ to $\theta_y$ with length $d_{M_2}(\theta_x,\theta_y)$. The \emph{product curve}
        \[
        \eta(t) \;=\;\bigl(\eta_1(t),\eta_2(t)\bigr)
        \]
        is then a smooth curve in $\mathcal M$ from $x$ to $y$, whose length is exactly
        \[
        L(\eta)
        =\sqrt{
        L(\eta_1)^2 + L(\eta_2)^2
        }
        =
        \sqrt{
        d_{M_1}(u_x,u_y)^2
        +\,
        d_{M_2}(\theta_x,\theta_y)^2
        }.
        \]
        Since $L(\eta)$ attains the lower bound, it follows that
        \[
        d_{\mathcal M}(x,y)
        =\sqrt{
        d_{M_1}(u_x,u_y)^2
        +\,
        d_{M_2}(\theta_x,\theta_y)^2
        },
        \]
        and hence squaring yields the claimed decomposition.
    \end{proof}

    \paragraph*{Decomposition of the First-Order Condition}
    Let a point $y_i\in M$ be represented by its coordinates $(u_i,\theta_i)$, where $u_i\in M_1$ and $\theta_i \in M_2$. The tangent space to $\mathcal{M}$ at $y_i$ decomposes into a direct sum: $T_{y_i}\mathcal{M}=T_{u_i}M_1\oplus T_{\theta_i}M_2$. The gradient operator $\nabla_{y_i}$ can therefore be decomposed into its components corresponding to these subspaces: $\nabla_{y_i}= (\nabla_{u_i},\nabla_{\theta_i})^\top$.

    The gradient of the distance function $d_\mathcal{M}(x,y_i)$ is related to the logarithmic map, which in a product manifold with a separable metric decomposes as $\mathrm{Log}_{y_i}(x)=(\mathrm{Log}_{u_i}(u), \mathrm{Log}_{\theta_i}(\theta))$ for $x=(u,\theta)$. The gradient of the distance is therefore:

    \[
    \nabla_{y_i} d_\mathcal{M}(x, y_i) = - \frac{1}{d_{\mathcal{M}}(x, y_i)} \left( \mathrm{Log}_{u_i}(u), \mathrm{Log}_{\theta_i}(\theta) \right)
    \]

    The FOC is a vector equation. By decomposing it into its $T_{u_i}M_1$ and $T_{\theta_i}M_2$ components, we obtain two systems of equations that must hold for any stationary solution $\left\{y_i^{*}=(u_i^{*},\theta_i^{*})\right\}_{i=1}^N$. Let's define the scalar weighting function $W_i(x, \{y_k^*\}) := \frac{f_i(x, \{y_k^*\})(1 - f_i(x, \{y_k^*\}))}{d_{\mathcal{M}}(x, y_i^*)}$
    The FOC splits into:

    \textit{System (U):} The set of $N$ equations for the $M_1$ components ($i=1,\ldots,N$):
    $$ \int_{M_1} \int_{M_2} W_i((u,\theta),\{y_k^*\}) \mathrm{Log}_{u_i^*}(u)\,dV_{M_2}(\theta)\,dV_{M_1}(u)=0 \quad (1) $$

    \textit{System (T):} The set of $N$ equations for the $M_2$ components ($i=1,\ldots,N$):
    $$ \int_{M_2} \int_{M_1} W_i((u,\theta),\{y_k^*\}) \mathrm{Log}_{\theta_i^*}(\theta)\,dV_{M_1}(u)\,dV_{M_2}(\theta)=0 \quad (2) $$
    The systems are coupled because $W_i$ depends on $\{y_k^*\}$ through $d_\mathcal{M}(x,y_k^*)$.

    \paragraph*{Introduction of Integrated Kernels\footnote{By Fubini’s theorem, we may split the integral and project onto the two tangent‐space factors}}
    For System (U), we define the kernel $K_i^{(1)}$ as:
    $$K_i^{(1)}(u,\{u_k^*\},\{\theta_k^*\}) := \int_{M_2} W_i((u,\theta),\{(u_k^*,\theta_k^*)\})\,dV_{M_2}(\theta)$$
    System (U) is now written as:
    $$\int_{M_1} K_i^{(1)}(u,\{u_k^*\},\{\theta_k^*\}) \mathrm{Log}_{u_i^*}(u)\,dV_{M_1}(u)=0 \quad (1')$$

    For System (T), we define the kernel $K_i^{(2)}$ by integrating over $M_1$:
    $$K_i^{(2)}(\theta,\{u_k^*\},\{\theta_k^*\}) := \int_{M_1} W_i((u,\theta),\{(u_k^*,\theta_k^*)\})\,dV_{M_1}(u)$$
    System (T) is now written as:
    $$\int_{M_2} K_i^{(2)}(\theta,\{u_k^*\},\{\theta_k^*\}) \mathrm{Log}_{\theta_i^*}(\theta)\,dV_{M_2}(\theta)=0 \quad (2')$$

    \paragraph*{Application of the Homogeneity Property}
    Consider the kernel $K_i^{(1)}$. Its integrand $W_i$ depends on $\theta$ only through the set of distances $\{d_{M_2}(\theta,\theta_k^*)\}_{k=1}^N$. Since $M_2$ is homogeneous, for any point $\delta \in M_2$, there exists an isometry $\phi_\delta: M_2 \to M_2$. Isometries preserve distances and the volume element. The value of the integral for $K_i^{(1)}$ is therefore invariant under an isometric shift of the entire configuration $\{\theta_k^*\}$. It depends only on the \textit{internal geometry} of the configuration, which is characterized by the matrix of pairwise distances.

    Let $D_2=\{d_{M_2}(\theta_j^*,\theta_k^*)\}_{j,k=1}^N$ be the distance matrix for the points on $M_2$. The kernel $K_i^{(1)}$ is independent of the specific locations $\{\theta_k^*\}$ as long as the pairwise distances $D_2$ are fixed. Thus:
    $$K_i^{(1)}=K_i^{(1)}(u,\{u_k^*\},D_2)$$

    Because $M_2$ is a compact homogeneous manifold, for any isometry:
    \[
    \phi:M_2\to M_2\text{ we have }
    d_{M_2}(\phi(\theta),\phi(\theta_k^*))=d_{M_2}(\theta,\theta_k^*)
    \text{ and }dV_{M_2}\circ\phi=dV_{M_2}.
    \]

    Hence \(\;K_i^{(1)}(u,\{u_k^*\},\{\theta_k^*\})\) depends on \(\{\theta_k^*\}\) only through their pairwise distance matrix \(D_2\).

    A symmetric argument applies to the kernel $K_i^{(2)}$. The integration is over the homogeneous manifold $M_1$. The value of the integral is independent of the absolute position of the configuration $\{u_k^*\}$ on $M_1$ and depends only on its internal geometry. Let $D_1=\{d_{M_1}(u_j^*,u_k^*)\}_{j,k=1}^N$ be the distance matrix for the points on $M_1$. The kernel $K_i^{(2)}$ can be written as:
    $$K_i^{(2)}=K_i^{(2)}(\theta,\{\theta_k^*\},D_1)$$

    \paragraph*{The Separated System and Conclusion}
    Substituting the simplified kernels back, we find that any stationary solution $\{y_i^*=(u_i^*,\theta_i^*)\}$ must satisfy the following pair of decoupled systems:

    \textit{System for $M_1$ coordinates:} For $i=1,\ldots,N$,
    $$ \int_{M_1} K_i^{(1)}(u,\{u_k^*\},D_2) \mathrm{Log}_{u_i^*}(u)\,dV_{M_1}(u)=0 $$
    where the parameters $D_2=\{d_{M_2}(\theta_j^*,\theta_k^*)\}_{j,k=1}^N$ are treated as constants. This is a self-contained system of $N k_1$ scalar equations for the $N$ points $\{u_k^*\}$ on $M_1$.

    \textit{System for $M_2$ coordinates:} For $i=1,\ldots,N$,
    $$ \int_{M_2} K_i^{(2)}(\theta,\{\theta_k^*\},D_1) \mathrm{Log}_{\theta_i^*}(\theta)\,dV_{M_2}(\theta)=0 $$
    where the parameters $D_1=\{d_{M_1}(u_j^*,u_k^*)\}_{j,k=1}^N$ are treated as constants. This is a self-contained system of $N k_2$ scalar equations for the $N$ points $\{\theta_k^*\}$ on $M_2$.

    This decoupling is the property of separability. The original FOC has been separated into two distinct problems for the components on $M_1$ and $M_2$. The equilibrium condition for the points on one manifold only depends on the pairwise distances of the points on the other, not their specific locations. This completes the proof.

\end{proof}


\section{Derivatives and second derivatives}
\subsection{General derivatives}
We can compute the partial derivatives of \( f_i(x) \):
    \begin{align*}
        \nabla_{p_i} f_i(x) &= -\beta f_i(x) (1 - f_i(x))\\
        \nabla_{y_i} f_i(x) &= - \beta f_i(x) (1 - f_i(x)) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i)
    \end{align*}

    This enables us to compute the derivatives of $\Lambda(V_i)$:
    \begin{align*}
        \nabla_{p_i} \Lambda(V_i) &= \frac{1}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{p_i} f_i(x) d\mathcal{V}_\mathcal{M}(x)\\
        &= \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x)) d\mathcal{V}_\mathcal{M}(x)\\
        \nabla_{y_i} \Lambda(V_i) &= \frac{1}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{y_i} f_i(x) d\mathcal{V}_\mathcal{M}(x)\\
        &= \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x)) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x)
    \end{align*}

The second order derivatives are,
\begin{align*}
    \nabla^2_{p_i} \Lambda(V_i) =& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{p_i}\big[f_i(x) (1 - f_i(x))\big] d\mathcal{V}_\mathcal{M}(x)\\
    =& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \big[1 - 2f_i(x) \big] \nabla_{p_i} f_i(x) d\mathcal{V}_\mathcal{M}(x)\\
    =& \frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) [1-f_i(x)]   d\mathcal{V}_\mathcal{M}(x)\\
    \nabla^2_{y_i} \Lambda(V_i) =& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{y_i} \big[ f_i(x) (1 - f_i(x)) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) \big] d\mathcal{V}_\mathcal{M}(x) \\
    =& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x))\left[ \nabla_{y_i}^2  d_\mathcal{M}(x, y_i)\right.\\
    &\left.-\beta (1 - 2f_i(x)) \cdot \nabla_{y_i}  d_\mathcal{M}(x, y_i)^2 \right] d\mathcal{V}_\mathcal{M}(x)\\
    \nabla^2_{p_i, y_i} \Lambda(V_i)  =& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{p_i} \big[ f_i(x) (1 - f_i(x)) \big] \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) \\
    =& \frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) [1-f_i(x)]  \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x)\\
    \nabla^2_{y_j, y_i} \Lambda(V_i) =& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{y_j} \big[ f_i(x) f_j(x) \big] \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) \\
    & = \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \nabla_{y_j} f_j(x) \big[1 - 2 f_j(x) \big] \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) \\
     & = \frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) f_j(x) \nabla_{y_j} d_\mathcal{M}(x, y_j) \big[f_i(x) - f_j(x) \big]\\
     &\qquad\ \qquad \ \qquad \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) 
\end{align*}

Note that for $N=2$ we have $f_j = 1-f_i$ and thus,
\begin{equation*}
    \nabla^2_{p_i} \Lambda(V_i) = \nabla^2_{p_j} \Lambda(V_i) = \nabla^2_{p_j, p_i} \Lambda(V_i) \quad
    \nabla^2_{p_j, y_i} \Lambda(V_i) = \nabla^2_{p_i, y_i} \Lambda(V_i)
\end{equation*}

\subsection{Hessian with respect to individual decision variables}
\begin{align*}
    \nabla^2_{p_i} \Pi_i =& 2 \nabla_{p_i} \Lambda(V_i) + (p_i - c) \nabla^2_{p_i} \Lambda(V_i)\\
    =& \frac{-2\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x)) d\mathcal{V}_\mathcal{M}(x) \\
    &+ (p_i-c)\frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) [1-f_i(x)]   d\mathcal{V}_\mathcal{M}(x)\\
    \nabla^2_{y_i} \Pi_i =&  (p_i - c) \nabla^2_{y_i} \Lambda(V_i)\\
    =&(p_i - c)\frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x))\left[ \nabla_{y_i}^2  d_\mathcal{M}(x, y_i) \right.\\
    &\left. -\beta (1 - 2f_i(x)) \cdot \left(\nabla_{y_i} d_{\mathcal{M}}(x, y_i)\right)\otimes\left(\nabla_{y_i} d_{\mathcal{M}}(x, y_i)\right) \right] d\mathcal{V}_\mathcal{M}(x)\\
    \nabla^2_{p_i, y_i} \Pi_i &= \nabla_{y_i} \Lambda(V_i) + (p_i - c) \nabla^2_{p_i, y_i} \Lambda(V_i)\\
    =&\frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x)) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) \\
    &+ (p_i - c) \frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) [1-f_i(x)]  \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x)
\end{align*}

\subsection{Hessian with respect to all decision variables}
\subsubsection{General formulas}
For $N=2$,
\begin{align*}
    \nabla^2_{p_j, p_i} \Pi_i & = \nabla_{p_j} \Lambda(V_i) + (p_i - c) \nabla^2_{p_j, p_i} \Lambda(V_i) = \nabla_{p_i} \Lambda(V_i) + (p_i - c) \nabla^2_{p_i} \Lambda(V_i)\\
    \nabla^2_{y_j, p_i} \Pi_i & = \nabla_{y_j} \Lambda(V_i) + (p_i - c) \nabla^2_{y_j, p_i} \Lambda(V_i) = - \nabla_{y_j} \Lambda(V_j) + (p_i - c) \nabla^2_{y_j, p_j} \Lambda(V_j) \\
    \nabla^2_{p_j, y_i} \Pi_i & = (p_i - c) \nabla^2_{p_j, y_i} \Lambda(V_i) = (p_i - c) \nabla^2_{p_i, y_i} \Lambda(V_i)\\
    \nabla^2_{y_j, y_i} \Pi_i & = (p_i - c) \nabla^2_{y_j, y_i} \Lambda(V_i)
\end{align*}

\subsubsection{Concentrated equilibrium}
The first order derivatives are,
\begin{align*}
    \nabla_{p_i} \Lambda(V_i)
    &= \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x)) d\mathcal{V}_\mathcal{M}(x)= \frac{-\beta(N-1)}{N^2} \\
    \nabla_{y_i} \Lambda(V_i)
    &= \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x)) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) = 0
\end{align*}

The second order derivatives are,
\begin{align*}
\nabla^2_{p_i} \Lambda(V_i)
=& \frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) [1-f_i(x)] d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{\beta^2(N-2)(N-1)}{N^3} \\
\nabla^2_{y_i} \Lambda(V_i)
=& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) (1 - f_i(x))\left[ \nabla_{y_i}^2 d_\mathcal{M}(x, y_i)\right.\\
&\left. -\beta (1 - 2f_i(x)) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i)^2 \right] d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} \frac{N-1}{N^2}\left[ \nabla_{y_i}^2 d_\mathcal{M}(x, y_i)\right.\\ % CORRECTED: Removed \left.
&\left. -\beta \left(\frac{N-2}{N}\right) \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i)^2 \right] d\mathcal{V}_\mathcal{M}(x)\\
\nabla^2_{y_i, p_i} \Lambda(V_i)
=& \frac{\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) [1-f_i(x)] \cdot \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) = 0\\
\nabla^2_{p_i} \Pi_i &= 2\frac{\partial \Lambda(V_i)}{\partial p_i} + (p_i -c)\nabla^2_{p_i} \Lambda(V_i)\\
=& \frac{-2\beta(N-1)}{N^2} + (p_i-c) \frac{\beta^2(N-2)(N-1)}{N^3} \\
=& \frac{-2\beta(N-1)}{N^2} + \frac{\beta(N-2)}{N^2} =\frac{-\beta}{N}\\
\nabla^2_{ y_i} \Pi_i &= (p_i -c)\nabla^2_{y_i} \Lambda(V_i)\\
=& \frac{-N}{(N-1)\mathcal{V}_\mathcal{M}(\mathcal{M})}\int_{\mathcal{M}} \frac{N-1}{N^2}\left[ \nabla_{y_i}^2 d_\mathcal{M}(x, y_i) \right.\\
&\left. -\beta \left(\frac{N-2}{N}\right) \cdot \left(\nabla_{y_i} d_{\mathcal{M}}(x, y_i)\right)\otimes\left(\nabla_{y_i} d_{\mathcal{M}}(x, y_i)\right) \right] d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{1}{N\cdot\mathcal{V}_\mathcal{M}(\mathcal{M})}\left(-\int_{\mathcal{M}} \nabla_{y_i}^2 d_\mathcal{M}(x, y_i)d\mathcal{V}_\mathcal{M}(x)\right.\\ % CORRECTED: Added closing parenthesis and removed extra \left.
&\left. +\frac{\beta(N-2)}{N}\int_{\mathcal{M}} \left(\nabla_{y_i} d_{\mathcal{M}}(x, y_i)\right)\otimes\left(\nabla_{y_i} d_{\mathcal{M}}(x, y_i)\right) d\mathcal{V}_\mathcal{M}(x)\right)\\
\nabla^2_{p_i, y_i} \Pi_i =& \frac{\partial \Lambda(V_i)}{\partial y_i} + (p_i -c)\nabla^2_{p_i, y_i} \Lambda(V_i) =0\\
\nabla^2_{p_j, p_i} \Lambda(V_i)
=& \frac{-\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} [1 - 2 f_i(x)]f_i(x) f_j(x) d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{-\beta^2 (N-2)}{N^3}\\
\nabla^2_{p_j, y_i} \Lambda(V_i)
=& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}}\left(\beta f_i(x)f_j(x)(1-2f_i(x)) \nabla_{y_i} d_\mathcal{M}(x, y_i) \right) d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \frac{\beta(N-2)}{N^3}\int_{\mathcal{M}}\nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x) = 0 \\
\nabla^2_{y_j, y_i} \Lambda(V_i)
=& \frac{-\beta^2}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} f_i(x) f_j(x) (1 - 2f_i(x)) \cdot \nabla_{y_j} d_\mathcal{M}(x, y_j) \otimes \nabla_{y_i} d_\mathcal{M}(x, y_i) d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{-\beta^2 (N-2)}{N^3 \cdot \mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} (\nabla_{y_i} d_\mathcal{M}(x, y_i) \otimes \nabla_{y_i} d_\mathcal{M}(x, y_i)) d\mathcal{V}_\mathcal{M}(x)\\
\nabla^2_{p_j, p_i} \Pi_i =& \frac{\partial \Lambda(V_i)}{\partial p_j} + (p_i - c)\nabla^2_{p_j, p_i} \Lambda(V_i)\\
=& \frac{\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}}f_i(x)f_j(x)d\mathcal{V}_\mathcal{M}(x)\\
&+ (p_i-c)\frac{-\beta}{\mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}}\left(\beta f_i(x)f_j(x)(1-2f_i(x)) \nabla_{y_i} d_\mathcal{M}(x, y_i) \right) d\mathcal{V}_\mathcal{M}(x)\\
=& \frac{\beta}{N^2} + \frac{N}{\beta(N-1)}\frac{-\beta^2 (N-2)}{N^3}= \frac{\beta}{N^2(N-1)} \\
\nabla^2_{p_j, y_i} \Pi_i =& (p_i - c)\nabla^2_{y_i, p_j} \Lambda(V_i) = 0\\
\nabla^2_{y_i,y_j} \Pi_i =& (p_i - c)\nabla^2_{y_i, y_j} \Lambda(V_i)\\
=& \frac{-\beta^2 (N-2)}{N^3 \cdot \mathcal{V}_\mathcal{M}(\mathcal{M})} \frac{N}{\beta(N-1)}\int_{\mathcal{M}} (\nabla_{y_i} d_\mathcal{M}(x, y_i)\otimes\nabla_{y_i} d_\mathcal{M}(x, y_i)) d\mathcal{V}_\mathcal{M}(x) \\
=& \frac{-\beta (N-2)}{N^2 (N-1)\cdot \mathcal{V}_\mathcal{M}(\mathcal{M})} \int_{\mathcal{M}} (\nabla_{y_i} d_\mathcal{M}(x, y_i))^2 d\mathcal{V}_\mathcal{M}(x)
\end{align*}

