\section{Extended Set Difference \texorpdfstring{$(\boldsymbol{\ominus_{e}})$}{(⊖\_e)}}
\label{app:extended_difference}

Throughout, let \(\mathcal{K}(\R^d)\) denote the family of non–empty compact
convex subsets of \(\R^d\) endowed with the Hausdorff metric
\[
 d_H(A,B)
 \;:=\;
 \max\Bigl\{
        \sup_{a\in A}\inf_{b\in B}\|a-b\|,
        \;
        \sup_{b\in B}\inf_{a\in A}\|b-a\|
      \Bigr\}.
\]

%--------------------------------------------------------------
\subsection{Definition and general properties}
%--------------------------------------------------------------
\begin{definition}[Extended set difference {\citep{beresteanu2025extendedsetdifference}}]
\label{def:extended_difference}
For \(A,B\in\mathcal{K}(\R^d)\) define
\[
  A\ominus_{e}B
  \;:=\;
  \Bigl\{
     X\in\mathcal{K}(\R^d)\;:\;
     d_H\bigl(A,B\oplus X\bigr)
     \;=\;
     \delta(A,B)
  \Bigr\},
  \quad
  \delta(A,B)
  \;:=\;
  \inf_{X\in\mathcal{K}(\R^d)}d_H\!\bigl(A,B\oplus X\bigr),
\]
where \(B\oplus X=\{\,b+x:b\in B,x\in X\}\) is the Minkowski sum.
\end{definition}

\begin{theorem}[Existence]
\label{thm:existence_extended_difference}
For all \(A,B\in\mathcal{K}(\R^d)\) the set \(A\ominus_{e}B\) is non–empty.
\end{theorem}

\begin{theorem}[Variability bound]
\label{thm:variability_extended_difference}
If \(X_1,X_2\in A\ominus_{e}B\) then
\(d_H(X_1,X_2)\le 2\,\delta(A,B)\).
In particular, \(A\ominus_{e}B\) is a singleton whenever \(\delta(A,B)=0\).
\end{theorem}

\begin{corollary}[Basic invariances]
For any orthogonal matrix \(Q\) and vector \(v\in\R^d\),
\[
  (Q A+v)\ominus_{e}(Q B+v)
  \;=\;
  Q\bigl(A\ominus_{e}B\bigr)
  \quad\bigl(\text{translation \& rotation invariance}\bigr).
\]
\end{corollary}
\begin{proof}[Proof of Translation and Rotation Invariance]
Let \(Q\) be an orthogonal matrix (i.e., \(Q^T Q = I\)) and \(v \in \mathbb{R}^d\). We need to show that:
\[
(Q A + v) \ominus_{e} (Q B + v) = Q (A \ominus_{e} B).
\]

Consider the Hausdorff distance for a set \(Y \in \mathcal{K}(\mathbb{R}^d)\):
\[
d_H(Q A + v, (Q B + v) \oplus Y).
\]
Since \((Q B + v) \oplus Y = Q B + v + Y\), we rewrite the expression as:
\[
(Q B + v) \oplus Y = \{ qb + v + y : qb \in Q B, y \in Y \} = Q B + v + Y.
\]
Thus, the Hausdorff distance becomes:
\[
d_H(Q A + v, Q B + v + Y).
\]
Because translation by \(v\) and rotation by \(Q\) (an isometry) preserve distances, we have:
\[
d_H(Q A + v, Q B + v + Y) = d_H(Q A, Q B + Y).
\]
Since \(Q\) is orthogonal, it preserves the norm, so:
\[
d_H(Q A, Q B + Y) = d_H(A, B + Q^{-1} Y),
\]
where \(Q^{-1} = Q^T\) because \(Q\) is orthogonal, and \(Q^{-1} Y = \{ Q^{-1} y : y \in Y \}\).

Now, \(A \ominus_{e} B = \{ X \in \mathcal{K}(\mathbb{R}^d) : d_H(A, B \oplus X) = \delta(A, B) \}\). The goal is to minimize \(d_H(Q A + v, (Q B + v) \oplus Y)\) over \(Y\). Substitute \(Y = Q X\), where \(X \in \mathcal{K}(\mathbb{R}^d)\):
\[
(Q B + v) \oplus (Q X) = Q B + v + Q X = Q (B + X) + v,
\]
since \(Q\) is linear. Then:
\[
d_H(Q A + v, Q (B + X) + v) = d_H(Q A, Q (B + X)) = d_H(A, B + X),
\]
because \(Q\) preserves distances.

Thus, minimizing \(d_H(Q A + v, (Q B + v) \oplus Y)\) over \(Y\) is equivalent to minimizing \(d_H(A, B \oplus X)\) over \(X\), with \(Y = Q X\). If \(X \in A \ominus_{e} B\), then \(d_H(A, B \oplus X) = \delta(A, B)\), and for \(Y = Q X\):
\[
d_H(Q A + v, (Q B + v) \oplus Y) = d_H(A, B \oplus X) = \delta(A, B).
\]
Since \(\delta(Q A + v, Q B + v) = \delta(A, B)\) (due to isometry), \(Y = Q X\) is a minimizer, and all minimizers of \((Q A + v) \ominus_{e} (Q B + v)\) are of the form \(Q X\) where \(X \in A \ominus_{e} B\). Hence:
\[
(Q A + v) \ominus_{e} (Q B + v) = Q (A \ominus_{e} B).
\]
\end{proof}
\paragraph{Lack of an adjunction law.}
Unlike the classical Hukuhara difference, \(\ominus_{e}\) \emph{does not}
satisfy the residuation property
\(A\subseteq B\oplus X\;\Longleftrightarrow\;X\in A\ominus_{e}B\)
in general.  The paper never uses such a property globally; instead,
the next lemma shows that it \emph{does} hold for the specific
zonotopes that arise from our utility representation.

%--------------------------------------------------------------
\subsection{A  lemma for zonotopes}
%--------------------------------------------------------------
\begin{lemma}[Non–negative minimal translate for zonotopes]
\label{lem:minimal_translate}
Let
\[
  Z_i=\bigoplus_{k=1}^{m} I_k^{(i)}\,v_k,
  \qquad
  I_k^{(i)}=[\underline u_k^{(i)},\overline u_k^{(i)}]\subset\R,
  \quad
  v_k\in\R^{m}_{\ge0},
  \; i=1,2,
\]
be two zonotopes whose generating vectors have \emph{non–negative}
components.  Define, for each \(k\),
\[
  D_k
  :=
  \Bigl[
     \max\{0,\;\underline u_k^{(1)}-\overline u_k^{(2)}\},
     \;
     \max\{0,\;\overline u_k^{(1)}-\underline u_k^{(2)}\}
  \Bigr],
  \qquad
  X^\star:=\bigoplus_{k=1}^{m} D_k\,v_k.
\]
Then:
\begin{enumerate}[label=(\roman*)]
  \item \(X^\star\subseteq\R^{m}_{\ge0}\);
  \item \(Z_2\oplus X^\star\supseteq Z_1\);
  \item \(d_H(Z_1,Z_2\oplus X^\star)=\delta(Z_1,Z_2)\); hence
        \(X^\star\in Z_1\ominus_{e} Z_2\).
\end{enumerate}
\end{lemma}

\begin{proof}
For a convex body \(C\subset\R^{m}\) let
\(h_C(\theta)=\sup_{c\in C}\theta\!\cdot\!c\) be its support function.
Because the support function is additive under Minkowski sum,
\(h_{Z_2\oplus X} = h_{Z_2}+h_X\).
For a single segment \(Jv_k\) one has
\(h_{Jv_k}(\theta)=\max\{\underline j,\overline j\}\,\theta\!\cdot\!v_k\)
when \(\theta\!\cdot\!v_k\ge0\) (always true since
\(v_k,\theta\in\R_{\ge0}^m\)).  Hence
\(
  h_{Z_2}(\theta)=
  \sum_k\overline u_k^{(2)} \,\theta\!\cdot\!v_k
\)
and similarly for \(Z_1\).

Now fix \(\theta\in\R_{\ge0}^m\) with \(\|\theta\|=1\).
The Hausdorff distance between \(Z_1\) and \(Z_2\oplus X\) is
\[
  \sup_{\theta}
  \bigl|
     h_{Z_1}(\theta)-h_{Z_2}(\theta)-h_{X}(\theta)
  \bigr|.
\]
Choosing \(X=X^\star\) sets \(h_X(\theta)=\sum_k z_k\,\theta\!\cdot\!v_k\)
with
\(z_k=\max\{0,\underline u_k^{(1)}-\overline u_k^{(2)}\}\),
which cancels exactly the positive part of the coordinate gap
\(\underline u_k^{(1)}-\overline u_k^{(2)}\).  This choice minimises the
absolute support–function gap in every direction simultaneously, giving
property (iii).  Properties (i) and (ii) are immediate from the
construction of \(D_k\) and the fact that the \(v_k\) lie in
\(\R^m_{\ge0}\).
\end{proof}

\begin{remark}
Lemma~\ref{lem:minimal_translate} is the only place in the paper where
we exploit the special structure of zonotopes with
\emph{non–negative generators}.  It uses a distinguished element
\(X^\star\in U(x)\ominus_{e}U(y)\) that guarantees the inclusion
\(U(y)\oplus X^\star\supseteq U(x)\).
\end{remark}

%--------------------------------------------------------------
\subsection{Order induced by the extended difference}
%--------------------------------------------------------------
\begin{definition}[Positive-orthant order]
For \(A,B\in\mathcal{K}(\R^m)\) write
\(
  A\preccurlyeq B
\)
iff
\(
  B\ominus_{e}A\subseteq\R^{m}_{\ge0}.
\)
\end{definition}

With Lemma \ref{lem:minimal_translate} in hand, the preference relation
used in the main text is simply the pull-back of \(\preccurlyeq\) along
the zonotope-valued utility \(U\):
\[
  x\;\pref\;y
  \quad\Longleftrightarrow\quad
  U(x)\;\preccurlyeq\;U(y).
\]
For any pair of alternatives the minimal translate \(X^\star\) supplied
by Lemma \ref{lem:minimal_translate} is non–negative precisely when the
coordinate inequalities \(\underline u_k(x)\ge\overline u_k(y)\) hold.

