\section{Proofs of the Main Results}
\label{app:proofs}

\begin{proof}[Proof of Theorem \ref{thm:existence_countable}]
\textbf{Step 1: $U(x)$ is a compact convex zonotope.}
Each interval
$I_k(x)=[\underline u_k(x),\overline u_k(x)]$ is compact and convex in
$\R$.  Minkowski addition is continuous and preserves both properties,
hence
$U(x)=\sum_{k=1}^m I_k(x)v_k\in\mathcal K(\R^m)$.
Because it is a finite sum of line segments, $U(x)$ is a \emph{zonotope}.

\medskip\noindent
\textbf{Step 2: If $x\pref y$ then $U(x)\ominus_e U(y)\subseteq\R^m_{\ge0}$.}
Assume $x\pref y$.  For every $k$ we have
$\underline u_k(x)\ge\overline u_k(y)$.
Set
\[
  D_k=[\underline u_k(x)-\overline u_k(y),\;
       \overline u_k(x)-\underline u_k(y)]\subset[0,\infty),
  \qquad
  X:=\bigoplus_{k=1}^m D_k\,v_k\subset\R^m_{\ge0}.
\]
A direct computation shows
\(U(y)\oplus X=U(x)\), so
$d_H\!\bigl(U(x),U(y)\oplus X\bigr)=0$.
Consequently \(X\in U(x)\ominus_e U(y)\)
and the set‐difference is contained in the positive orthant.

\medskip\noindent
\textbf{Step 3: If $U(x)\ominus_e U(y)\subseteq\R^m_{\ge0}$
then $x\pref y$.}
Suppose the inclusion holds.
Choose the distinguished element
\(X^\star\in U(x)\ominus_e U(y)\) supplied by
Lemma~\ref{lem:minimal_translate}.  Part (ii) of that lemma yields
\(U(y)\oplus X^\star\supseteq U(x)\).
Write
\(X^\star=\sum_{k=1}^m [d_k^-,d_k^+]v_k\)
with $d_k^\pm\ge0$.
Examining the extreme points in the $k$-th generator direction gives
\(
  \underline u_k(x)\ge\overline u_k(y)
\)
for every $k$, i.e.\ $x\pref_k y$ for all $k$.
Because $\pref=\bigcap_k\pref_k$, we conclude $x\pref y$.

\medskip\noindent
\textbf{Step 4: Equivalence.}
Steps 2 and 3 establish
\(
  x\pref y
  \Longleftrightarrow
  U(x)\ominus_e U(y)\subseteq\R^m_{\ge0},
\)
so $U$ is a zonotope-valued representation of $\pref$.
\end{proof}
\begin{proof}[Proof of Corollary \ref{cor:minimal_dimension}]
Let $d=\dim_{\mathrm{int}}(X,\pref)$.

\noindent\emph{Upper bound $m\le d$.}
By definition of interval dimension there exist
interval orders $\{\pref_1,\dots,\pref_d\}$ whose intersection is $\pref$.
Applying Theorem \ref{thm:existence_countable} with those $d$ orders
produces a representation in $\R^d$, so one can take $m=d$.

\noindent\emph{Lower bound $m\ge d$.}
Conversely, suppose $\pref$ admits any zonotope representation in
$\R^m$.
For each $k$ define
\(x\pref^{(k)} y \iff
  \underline u_k(x)\ge\overline u_k(y)\).
These relations are interval orders (no \(2{+}2\) pattern),
and their intersection equals $\pref$ by the same argument
as in Step 3 of the previous proof.
Hence $\pref$ is the intersection of $m$ interval orders, so
$d\le m$.

Combining the two inequalities yields $m=d$.
\end{proof}
\begin{proof}[Proof of Theorem \ref{thm:existence_uncountable}]
The construction of $U(x)$ is identical to the countable case.
Only Step 3 (reverse implication) needs attention, because $X$
is now uncountable.

Assume
\(U(x)\ominus_e U(y)\subseteq\R^m_{\ge0}\).
Pick $X^\star$ from Lemma \ref{lem:minimal_translate};
again \(U(y)\oplus X^\star\supseteq U(x)\) and
\(X^\star\subseteq\R^m_{\ge0}\).
Since each interval order $\pref_k$ is numerically representable and
separable (Axiom (A4)), the same vertex-inspection argument gives
\(\underline u_k(x)\ge\overline u_k(y)\) for all $k$,
hence $x\pref y$.
The forward direction is unchanged, completing the proof.
\end{proof}
\begin{proof}[Proof of Corollary \ref{cor:convcomp}]
Compactness:
$\prod_{k=1}^m I_k(x)$ is compact by Tychonoff’s theorem.
The linear map
\(\phi(t_1,\dots,t_m)=\sum_k t_k v_k\)
is continuous, so
\(U(x)=\phi\bigl(\prod_k I_k(x)\bigr)\) is compact.

Convexity:
each $I_k(x)v_k$ is a line segment.
For $z^{(1)},z^{(2)}\in U(x)$ write
\(z^{(i)}=\sum_k t_{k}^{(i)}v_k\) with
\(t_{k}^{(i)}\in I_k(x)\).
Convexity of intervals implies
\(\lambda t_{k}^{(1)}+(1-\lambda)t_{k}^{(2)}\in I_k(x)\)
for any $0\le\lambda\le1$.
Hence the convex combination
\(\lambda z^{(1)}+(1-\lambda)z^{(2)}\) lies in $U(x)$.
\end{proof}
\begin{proof}[Proof of Proposition \ref{prop:continuity}]
Fix $\varepsilon>0$.
Because each endpoint map
$\underline u_k,\overline u_k\!:X\to\R$
is continuous, there is $\delta>0$ such that
\(
  d_X(x_n,x)<\delta
  \Rightarrow
  |\underline u_k(x_n)-\underline u_k(x)|<\varepsilon
\)
and the same for $\overline u_k$.

The Hausdorff distance between intervals satisfies
\(d_H\bigl(I_k(x_n),I_k(x)\bigr)<\varepsilon\).
Multiplication by $v_k$ scales distances by
$\lVert v_k\rVert_2$, hence
\(
  d_H\bigl(I_k(x_n)v_k,\,I_k(x)v_k\bigr)
  <\lVert v_k\rVert_2\,\varepsilon.
\)

For zonotopes
\(Z=\sum_k A_k,\;Z'=\sum_k B_k\)
one has
\(d_H(Z,Z')\le\sum_k d_H(A_k,B_k)\).
Therefore
\[
  d_H\!\bigl(U(x_n),U(x)\bigr)
  \;\le\;
  \Bigl(\sum_{k=1}^m \lVert v_k\rVert_2\Bigr)\,\varepsilon,
\]
which can be made arbitrarily small.  Hence
\(x_n\to x\) implies \(U(x_n)\to U(x)\) in the Hausdorff metric.
\end{proof}
\begin{proof}[Proof of Theorem \ref{thm:representation}]
\emph{Sufficiency.}
If $\pref$ satisfies the axioms (countable or uncountable as
appropriate), Theorems
\ref{thm:existence_countable} and
\ref{thm:existence_uncountable}
construct a zonotope-valued map $U$
such that
\(x\pref y\iff U(x)\ominus_e U(y)\subseteq\R^m_{\ge0}\).
Corollary \ref{cor:minimal_dimension}
gives minimal dimension $m=\dim_{\mathrm{int}}(X,\pref)$.

\medskip\noindent
\emph{Necessity.}
Conversely assume such a representation exists.

\smallskip
(i)  For each $k$ define
\(x\pref_k y \iff \underline u_k(x)\ge\overline u_k(y)\).
These are interval orders; their intersection is $\pref$
by the same vertex argument as before, so
Axiom (A1) (interval-order decomposition) holds.

(ii)  If $x$ and $y$ are incomparable under $\pref$ then
\(U(x)\ominus_e U(y)\) and
\(U(y)\ominus_e U(x)\) are \emph{not} subsets of $\R^m_{\ge0}$.
Lemma \ref{lem:minimal_translate} shows this fails because
$\underline u_k(x)<\overline u_k(y)$ and
$\underline u_k(y)<\overline u_k(x)$ for some $k$,
verifying non-degeneracy (A2).

(iii)  If $x\spref y$ then the inclusion holds one way but not the other;
Lemma \ref{lem:minimal_translate} forces
\(\underline u_{k_0}(x)>\overline u_{k_0}(y)\)
for some $k_0$, yielding strict preference consistency (A3).

(iv)  The numerical representability/separability axiom
(A4) is inherited from the fact that
each $\pref_k$ is expressed through the continuous functions
\(\underline u_k,\overline u_k\).

Hence all axioms are necessary.

\medskip\noindent
\emph{Minimal dimension.}
If a representation lives in $\R^m$ then, as in the proof of
Corollary \ref{cor:minimal_dimension}, $\pref$ is the intersection
of $m$ interval orders, so
\(m\ge\dim_{\mathrm{int}}(X,\pref)\).
Combining with the sufficiency part yields equality.

\end{proof}
%--------------------------------------------------------------

\begin{proof}
Recall that $x\spref y$ means
$x\pref y$ and $\lnot\,(y\pref x)$, i.e.
\[
   U(x)\ominus_e U(y)\subseteq\R^m_{\ge0},
   \quad
   U(y)\ominus_e U(x)\not\subseteq\R^m_{\ge0}.
\]

\smallskip
\noindent\emph{(i) $\Longrightarrow$ (ii).}
Assume Condition (i):
for every $u\in U(y)$ there is $v\in U(x)$ with
$v\ge u$ (coordinate-wise) and $v_j>u_j$ for some $j$.
By compactness of $U(x)$ and $U(y)$, define
\[
   \Delta
   :=\min_{u\in U(y)}\max_{v\in U(x)}\min_{1\le j\le m}(v_j-u_j)
   \;>\;0 .
\]
Choose $\varepsilon\in(0,\Delta)$ and let
$w=(1,\dots,1)\in\R^m_{>0}$.
For every $u\in U(y)$ there is $v\in U(x)$ with
$v_j\ge u_j+\varepsilon$ for at least one $j$; hence
\[
   \sup_{u\in U(y)}w\!\cdot\!u
   \;\le\;
   \inf_{v\in U(x)}w\!\cdot\!v-\varepsilon
   \;<\;
   \inf_{v\in U(x)}w\!\cdot\!v .
\]
Setting $c:=\tfrac12\bigl(\sup_{u\in U(y)}w\!\cdot\!u
   +\inf_{v\in U(x)}w\!\cdot\!v\bigr)$
gives the required strict positive-normal hyperplane.

\smallskip
\noindent\emph{(ii) $\Longrightarrow$ (i).}
Suppose there exist $w\in\R^m_{>0}$ and $c\in\R$ with
\[
   \sup_{u\in U(y)}\!w\!\cdot\!u
   \;<\;c
   \;\le\;
   \inf_{v\in U(x)}\!w\!\cdot\!v .
\]
Let $u\in U(y)$ be arbitrary.  Because
$U(x)$ is compact, choose $v^\star\in U(x)$ minimising
$w\!\cdot\!v$.
Then $\langle w,v^\star\rangle\ge c>\langle w,u\rangle$,
and $w>0$ forces $v^\star\ge u$ component-wise with
strict inequality in at least one coordinate.
Thus Condition (i) holds.

\smallskip
\noindent\emph{(ii) $\Longleftrightarrow$ strict preference.}
The forward implication follows from
Lemma A.\ref{lem:minimal_translate}:
strict separation by a positive normal implies
the distinguished translate $X^\star\in U(x)\ominus_e U(y)$
satisfies $X^\star\subset\R^m_{\ge0}$, while the opposite
difference contains a vector with a negative dot-product
against $w$, so is \emph{not} contained in $\R^m_{\ge0}$.
The reverse implication uses the separating-hyperplane theorem
with respect to the closed convex cones
$U(x)$ and $U(y)+\R^m_{\ge0}$.
\end{proof}
%--------------------------------------------------------------

\begin{proof}
Assume the hypothesis: there exist
$w\in\R^m_{>0}$ and $c\in\R$ such that
\[
   \sup_{u\in U(y)}w\!\cdot\!u
   \;\le\;c
   \;\le\;
   \inf_{v\in U(x)}w\!\cdot\!v ,
\]
with at least one strict inequality.
Let $X^\star$ be the translate supplied by
Lemma A.\ref{lem:minimal_translate}.
Part (ii) of the lemma gives
$U(y)\oplus X^\star\supseteq U(x)$.
For any $z\in X^\star$ pick
$b\in U(y)$, $a\in U(x)$ such that $a=b+z$.
Then
\[
   w\!\cdot\!z
   = w\!\cdot\!a-w\!\cdot\!b
   \;\ge\;
   \inf_{v\in U(x)}w\!\cdot\!v
   -\sup_{u\in U(y)}w\!\cdot\!u
   \;>\;0 .
\]
Because $w>0$, the inequality
$w\!\cdot\!z>0$ implies $z\in\R^m_{>0}$.
Since $X^\star$ is compact and
$X^\star\subseteq\R^m_{>0}$,
there is a margin $\eta>0$ such that each coordinate
$z_i\ge\eta$ for all $z\in X^\star$.
Finally, \(\ominus_e\) is \emph{closed} downward in the
Hausdorff metric, so every
$Z\in U(x)\ominus_e U(y)$ is contained in
$X^\star+\R^m_{\ge0}\subseteq\R^m_{>0}$.
Hence
\(U(x)\ominus_e U(y)\subseteq\R^m_{>0}\),
as claimed.
\end{proof}







