\begin{align}
    \sigma^i_{\varrho, noise, j} &= 0.15[m] + 0.43[m]\exp\left(-\frac{\theta_j^i[deg]}{6.9} \right) \\
    \sigma^i_{\varrho, multipath, j} &= 0.13[m] + 0.53[m]\exp\left(-\frac{\theta_j^i[deg]}{10} \right) \,,
\end{align}
\end{subequations}
where $\theta^i_j$ is the elevation angle associated with the receiver $j$ and the satellite $i$. \par

