    \begin{tabular}{c|c|c|c|c|c|c|c|c|c}
         & 0 & 1 & 2 & 3 & 4 & 5 & 6 & 7 & 8  \\ \hline \hline
$0$ & $[ 6, 2 ]$ & $[ 8, 0 ]$ & $[ -2, 0 ]$ & $[ -6, 2 ]$ & $[ -4, 0 ]$ & $[ 4, 0 ]$ & $[ 0, 2 ]$ & $[ 2, 0 ]$ & $[ -8, 0 ]$ \\ \hline
$1$ & $[ 0, 0 ]$ & $[ -4, 2 ]$ & $[ -2, 0 ]$ & $[ 6, 0 ]$ & $[ 2, 2 ]$ & $[ 4, 0 ]$ & $[ -6, 0 ]$ & $[ 8, 2 ]$ & $[ -8, 0 ]$ \\ \hline
$2$ & $[ 0, 0 ]$ & $[ 8, 0 ]$ & $[ 4, 2 ]$ & $[ 6, 0 ]$ & $[ -4, 0 ]$ & $[ -8, 2 ]$ & $[ -6, 0 ]$ & $[ 2, 0 ]$ & $[ -2, 2 ]$ \\
