    \label{tab:case_q_3r}
\end{table}

In order to apply \cite[Lemma 11]{HOWE2002139}, we verify
{\footnotesize
\begin{align}
\left\vert \frac{a_s}{2^{s/2}} \right\vert  + \dots + \left\vert \frac{a_{g-2}}{2^{(g-2)/2}} \right\vert + \left\vert \frac{a_{g-1}}{2^{(g-1)/2}} \right\vert + \frac{1}{2} \left\vert \frac{a_g}{2^{g/2}} \right\vert <& \left\vert \frac{1}{2^{s/2}} \right\vert  + \dots + \left\vert \frac{3}{2^{(g-2)/2}} \right\vert + \left\vert \frac{3}{2^{(g-1)/2}} \right\vert + \frac{1}{2} \left\vert \frac{17}{2^{g/2}} \right\vert
\end{align}
}
which is $<1$ for $s=4$ and $g\geq 14$. Finally, both results \cite[Corollary 3.2]{HSU199685} and \cite[Lemma 11]{HOWE2002139} can be applied, as in the previous case.
This completes the proof of Proposition \ref{prop:g_ge_14}.

