Madagascar, Malawi, Mozambique, Rwanda, Somalia, South Sudan, Uganda, Zimbabwe, Angola, Cameroon, Sudan, Burkina Faso, Cote d'Ivoire, Ghana, Niger

\item \textbf{Asia}:
Kazakhstan, Afghanistan, Nepal, Cambodia, Malaysia, Iraq, Saudi Arabia, Syrian Arab Republic, United Arab Emirates, Yemen

\item \textbf{Europe}:
Belarus, Czech Republic, Hungary, Bosnia and Herzegovina, Greece, Portugal, Serbia, Belgium, Netherlands

\item \textbf{America}:
Cuba, Chile, Ecuador
\item \textbf{Oceania}: Australia
\end{itemize}

