    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/jv1_0.1.pdf}
    \caption{DGP12. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 13.] \textit{Main model}: $X_i(t)=2\sin(15\pi t)+e_i(t)$.

    \textit{Outlier model}: $X_i(t)=2\sin(15\pi t +4)+e_i(t)$. 

    \textit{Type of outliers:} \textbf{shape outliers} in phase.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/jv2_0.1.pdf}
    \caption{DGP13. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 14.] \textit{Main model}: $X_i(t)=0.1+\arctan(t)+e_i(t)$.

    \textit{Outlier model}: $X_i(t)=0.1+\arctan(t)+e^*_i(t),$ where $e^*_i$ is another zero-mean Gaussian process with covariance function \\ $c^*(s,t)=0.1\exp\{-\frac{|s-t|^{0.1}}{4}\}.$ 

    \textit{Type of outliers:} both \textbf{shape and amplitude outliers}.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/jv3_0.1.pdf}
    \caption{DGP14. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 15.] \textit{Main model}: $X_i(t)=30t(1-t)^{3/2}+e_i(t)$.

    \textit{Outlier model}: $X_i(t)=30t(1-t)^{3/2}+e^*_i(t)$.

    \textit{Type of outliers:} both \textbf{shape and amplitude outliers}.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/jv4_0.1.pdf}
    \caption{DGP15. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 16.] \textit{Main model}: $X_i(t)=e_i(t)$.

    \textit{Outlier model}: $X_i(t)=0.1\sin(40(t+\theta)\pi)+e^*_i(t),$ where $\theta \sim \mathcal{U}(0.25,0.5).$ 

    \textit{Type of outliers:} both \textbf{shape and amplitude outliers}.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/jv5_0.1.pdf}
    \caption{DGP16. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 17.] \textit{Main model}: $X_i(t) = A+B \arctan(t)+G(t),$ where $A \sim \mathcal{N}(\mu=0,\,\sigma=2)$, $B \sim Exp(1)$, and $G:[0,1] \to \mathbb{R}$ is an independent Gaussian process with $Cov(G(s),G(t))=0.2 exp(\frac{-|s-t|}{0.3})$ for $s,t \in \mathcal{I}.$ 

    \textit{Outlier model}: $X_i(t)=1- 2 \arctan(t)+\Tilde{G}(t),$ where $\Tilde{G}$ is defined in the same way as $G$, but it is independent of it. 

    \textit{Type of outliers:} \textbf{shape outliers}, where the outlier curve tends to increase when the inliers decrease.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/sn1_0.1.pdf}
    \caption{DGP17. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 18.] \textit{Main model}: same as DGP 12. 

    \textit{Outlier model}: $X_i(t)=y_i(t)+ \Tilde{G}(t),$ where $$y_i(t) = \left\{ 
    \begin{array}{lll}
		 0.5+\log(2)\arctan(t)  & for & t \in [0,0.5], \\
		 -0.5+\log(2)\arctan(t) & for & t \in \left(0.5,1].\right.
	       \end{array}
        \right.$$ 

        \textit{Type of outliers:} \textbf{shape outliers}.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/sn2_0.1.pdf}
    \caption{DGP18. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}

    \item[DGP 19.] \textit{Main model}: These curves are generated by first creating a B-splines basis with 25 basis functions. Coefficients for these curves are generated from a unit sphere by drawing from a standard normal distribution and normalizing them to lie on the unit sphere in the plane defined by the first two dimensions. These coefficients are then rotated into the basis-dimensional space using a random orthonormal rotation matrix obtained via QR decomposition.

    \textit{Outlier model}: it is similar to the main one. However, an additional step modifies the rotation matrix. Specifically, a new random orthonormal matrix is generated, scaled by a factor of $1.1$, and combined with the original rotation matrix using matrix multiplication and QR decomposition to ensure orthonormality. This combined matrix is then used to rotate the outlier coefficients. Finally, white noise with $\sigma = 0.3$ is added to the resulting curves. 

    \textit{Type of outliers:} \textbf{shape outliers}.

    \begin{figure}[htbp]
    \centering
    \includegraphics[width=.5\textwidth]{imagenes/sphere_0.1.pdf}
    \caption{DGP19. A sample of 200 simulated curves with 10\% of outliers (red).  }
    \end{figure}
\end{itemize}

