\title{Type-1.5 SNSPD: Interacting vortex theory of two bandgap superconducting single photon detectors} 

\author{Leif Bauer}\altaffiliation{These authors contributed equally to the work}
\author{Daien He}\altaffiliation{These authors contributed equally to the work}
\author{Sathwik Bharadwaj}
\affiliation{The Elmore Family School of Electrical and Computer Engineering, Purdue University, West Lafayette, 47907, IN, USA}
