\title{A Common Interface for Automatic Differentiation}

\author{\name Guillaume Dalle \email guillaume.dalle@enpc.fr \\
  \addr LVMT, ENPC, Institut Polytechnique de Paris, Univ Gustave Eiffel, Marne-la-Vallée, France
