  \begin{subfigure}{0.32\textwidth}
    \centering
    \scalebox{0.85}{
      \begin{tikzpicture}
        \node[roundednode, fill=red] (Optax) at (-0.8, 0) {\texttt{Optax}};
        \node[roundednode, fill=red] (Diffrax) at (0, 0.8) {\texttt{Diffrax}};
        \node[roundednode, fill=red] (oryx) at (0.8, 0) {\texttt{oryx}};

