\section{HJB Derivation}\label{AS:HJB}

Here we informally derive \eqref{E:G_HJB}, but we stress that we will use other methods to verify solutions to \eqref{E:G_HJB} are the certainty equivalent. Fix $x\in \OO$ and $t\leq T$, and  for $\pi \in \A$ from \eqref{E:admiss} define
\begin{equation*}
    J(\pi) \dfn \expvs{U\left(\We^{\pi}_T + \phi(X_T)1_{\tau > T} + \psi(\tau,X_{\tau})1_{\tau\leq T}\right)}.
\end{equation*}
Using the jump in wealth at default we obtain
\begin{equation*}
    J(\pi) = \expvs{U\left(\We^{\pi}_{(T\wedge\tau)-} - \pi_{\tau}'\ell(\tau,X_{\tau})1_{\tau\leq T} + \phi(X_T)1_{\tau > T} + \psi(\tau,X_{\tau})1_{\tau\leq T}\right)}.
\end{equation*}
As $\pi\in\mcp(\filtg)$, we know that both $\pi$ and the left limit process associated to $\We^{\pi}$ coincide with $\filt^{W,B}$ predictable processes on $[0,\tau]$, and hence we use the intensity function $\gamma$ to obtain
\begin{equation*}
    \begin{split}
        J(\pi) &= \mathbb{E}\bigg[\int_{t}^{\infty} U\bigg(\We^{\pi}_{(T\wedge u)-} - \pi_{u}'\ell(u,X_u) 1_{u\leq T} + \phi(X_T)1_{u > T} + \psi(u,X_u)1_{u\leq T}\bigg)\\
        &\qquad\qquad \times \gamma(u,X_u) e^{-\int_0^u \gamma(v,X_v) dv}du\bigg],\\
        &=\mathbb{E}\bigg[\int_t^T U\left(W^{\pi}_u - \pi_u'\ell(u,X_u)  + \psi(u,X_u)\right)\gamma(u,X_u) e^{-\int_t^u \gamma(v,X_v) dv}du\\
        &\qquad\qquad + e^{-\int_t^T \gamma(v,X_v) dv}U\left(W^{\pi}_{T} + \phi(X_T)\right)\bigg].
    \end{split}
\end{equation*}
Using again that $\pi$ coincides with an $\filt^{W,B}$ predictable process prior to default, and writing $X= X^{t,x}$, we are left with the control problem of identifying $v(t,x,w) \dfn \sup_{\pi \in \mcp(\filt)} \wt{J}(t,x,w;\pi)$ where
\begin{equation*}
    \begin{split}
        \wt{J}(t,x,w,\pi) &= \mathbb{E}\bigg[\int_t^T U\left(W^{\pi}_u - \pi_u'\ell(u,X^{t,x}_u)  + \psi(u,X^{t,x}_u)\right)\gamma(u,X^{t,x}_u) e^{-\int_t^u \gamma(v,X^{t,x}_v) dv}du\\
        &\qquad\qquad + e^{-\int_t^T \gamma(v,X^{t,x}_v) dv}U\left(W^{\pi}_{T} + \phi(X^{t,x}_T)\right) \bigg| \We^{\pi}_t = w\bigg].
    \end{split}
\end{equation*}
This is a standard control problem, and from (for example) \cite{MR2533355} we obtain the HJB equation for $v$, suppressing function arguments,
\begin{equation*}
    0  = v_t + \max_{\pi}\bra{-\gamma v + \pi'\left(v_w \mu +  v_w \Upsilon \nabla\right) + \frac{1}{2}v_{ww} \pi'\Sigma \pi + Lv - \gamma e^{-\alpha(w-\pi'\ell + \psi)}},
\end{equation*}
with boundary condition $v(T,x,w) = e^{-\alpha(w + \phi(x))}$.  Writing $v(t,x,w) = -e^{-\alpha(w+G(t,x))}$ and simplifying gives the HJB equation \eqref{E:G_HJB} for $G$.  


\section{Proofs from Section \ref{S:opt_invest}}\label{AS:opt_invest}

\begin{proof}[Proof of Proposition \ref{P:cds_dynamics}]

Recall the extended generator $\wt{L}$ in \eqref{E:wtL_def} for $X$ under $\tprob$. By \cite[Theorem 1, Lemma 2]{Heath-Schweizer} and our given assumptions, we know that $\wt{u}, \wt{v}$ respectively solve the PDEs
\begin{equation*}
    \begin{split}
        0 & = \wt{u}_s + \wt{L}\wt{u} -\wt{\gamma}(\wt{u}-1),\hspace{30pt} \wt{u}(T,\cdot) = 0,\\
        1 &= \wt{v}_s + \wt{L}\wt{v} - \wt{\gamma}\wt{v},\hspace{60pt} \wt{v}(T,\cdot) = 0.
    \end{split}
\end{equation*}
Next, using the notation of \cite{MR2474544} we have $r_s \equiv 0$, $B_s \equiv 1$, $\delta_s \equiv 1$, $M_s = H_s - \int_t^{\tau \wedge s} \wt{\gamma}(u,X_u)du$, $G_s = e^{-\int_t^s \wt{\gamma}(u,X_u)}$ and $\kappa(s,T) = \wt{u}(s,X_s)/\wt{v}(s,X_s)$.  Additionally,
\begin{equation*}
    m^1_s = 1 - G_s(1-\wt{u}_s);\qquad  m^2_s = G_s \wt{v}_s + \int_t^s G_u du.
\end{equation*}
The dynamics in \eqref{E:cds_dynamics} now follow from \cite[Lemma 2.4]{MR2474544} by direct computations. 


\end{proof}

