\section{Proofs from Section \ref{S:HJB_CE}}\label{AS:HJB_CE}

We begin with Proposition \ref{P:general_hamil_11}.  Throughout, we suppress $(t,x)$ keeping only the dependence upon $(p,g)$ and $\sigma = \sigma_r(t,x)$ explicit. We also write $\pi =(\theta,\delta)$. As identification of the optimal equity policy function $\wh{\theta}$ for fixed $(p,g,\delta)$ is the same under both Assumptions \ref{A:complete_mkt}, \ref{A:incomplete_mkt}, we start with this identification. To ease the notational burden we  define
\begin{equation}\label{E:ACE_def}
    \begin{split}
        \Afn(\sigma) &\dfn \sigma'\bAfn\sigma;\hspace{20pt}\Bfn(p,\sigma) \dfn -\wt{\gamma} + \sigma'\bBfn(p);\hspace{20pt} \Cfn \dfn \ell_e'\Sigma_e^{-1}\ell_e;\\
        \Dfn(g,p) &\dfn \Cfn \times \gamma e^{\alpha(g-\psi) + \ell_e'\Sigma_e^{-1}\left(\mu_e - \alpha\Upsilon_e p\right)}; \hspace{20pt} \Efn(\sigma) \dfn 1 + \sigma'\bEfn,
    \end{split}
\end{equation}
where
\begin{equation}\label{E:BD_def}
    \begin{split} 
         \bAfn &\dfn A - \Upsilon_e' \Sigma_e^{-1} \Upsilon_e;\hspace{10pt}\bBfn(p) \dfn a\tprobnu - \Upsilon_e' \Sigma_e^{-1} \mu_e - \alpha \bAfn p\hspace{10pt} \bEfn \dfn \Upsilon_e' \Sigma_e^{-1} \ell_e.
    \end{split}
\end{equation}
Note from \eqref{E:SigE_UpsE} and \eqref{E:E_barA_def} that $\Efn(\sigma_r) = \Efnalt$ when $k=d,\rho = \idmat{d}$. Now, fix $\delta$ and consider maximizing the right side of \eqref{E:hamil} over $\theta$. Using \eqref{E:SigE_UpsE} and noting that $\Sigma_e$ is invertible, direct computation yields the optimal equity policy function
\begin{equation}\label{E:opt_theta_1}
    \wh{\theta}(p,g,\delta) = \frac{1}{\alpha}\Sigma_e^{-1}\left(\mu_e -\alpha \Upsilon_e p - \frac{1}{\Cfn}\plog{\Dfn(g,p) e^{-\alpha\Efn(\sigma_r) \delta}}\ell_e - \alpha\delta \Upsilon_e \sigma_r\right).
\end{equation}
Plugging this into the right side of \eqref{E:hamil} and simplifying yields (recall \eqref{E:MF_hamil})
\begin{equation}\label{E:mid_hcal}
    \begin{split}
        \Hcal(g,p) &= \frac{1}{2\alpha}\left(\mu_e - \alpha\Upsilon_e p\right)'\Sigma_e^{-1}\left(\mu_e - \alpha\Upsilon_e p\right)\\
        &\qquad + \sup_{\delta}\bigg( -\frac{1}{2}\alpha \Afn(\sigma_r) \delta^2 + \Bfn(p,\sigma_r) \delta - \frac{1}{2\alpha\Cfn}\bigg(\plog{\Dfn(g,p) e^{-\alpha\Efn(\sigma_r)\delta}}^2\\
        &\qquad\qquad + 2\plog{\Dfn(g,p) e^{-\alpha \Efn(\sigma_r) \delta}}\bigg)\bigg).
    \end{split}
\end{equation} 

\subsection{Proof of Proposition \ref{P:general_hamil_11}}

When Assumption \ref{A:complete_mkt} holds, $\Afn(\sigma_r) =0$ and $\Bfn(\sigma,p) = -\wt{\gamma}\Efn(\sigma)$ (because $\tprobnu = \sigma_e^{-1}(\mu_e-\wt{\gamma}\ell_e)$).  This implies we are trying to maximize
\begin{equation*}
     -\wt{\gamma}\Efn(\sigma_r) \delta - \frac{1}{2\alpha\Cfn}\left(\plog{\Dfn(g,p) e^{-\alpha\Efn(\sigma_r)\delta}}^2 + 2\plog{\Dfn(g,p) e^{-\alpha \Efn(\sigma_r) \delta}}\right).
\end{equation*}
Using \eqref{E:plog_deriv} below, direct computations give the first order conditions and  solution
\begin{equation}\label{E:p1_foc_opt_delta}
    \wt{\gamma}\Cfn = \plog{\Dfn(g,p) e^{-\alpha\Efn(\sigma_r)\wh{\delta}}} \quad \Longrightarrow \quad \wh{\delta} = \frac{1}{\alpha\Efn(\sigma_r)}\left(-\wt{\gamma}\Cfn  + \log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right)\right),
\end{equation}
which is well defined because $\Efn(\sigma_r)\neq 0$.  Using $\wh{\delta}$ in \eqref{E:opt_theta_1} yields the formula for $\wh{\theta}$ in \eqref{E:gen_opt_strat_1}, and plugging in for $\Cfn$ and $\Dfn(g,p)$ yields the formula for $\wh{\delta}$ in \eqref{E:gen_opt_strat_1}. Continuing, plugging for $\wh{\delta}$ in \eqref{E:mid_hcal} gives
\begin{equation*}
    \begin{split}
        \Hcal(g,p) &= \frac{1}{2\alpha}\left(\mu_e - \alpha\Upsilon_e p\right)'\Sigma_e^{-1}\left(\mu_e - \alpha\Upsilon_e p\right)+ \frac{\wt{\gamma}^2 \Cfn}{2\alpha} - \frac{\wt{\gamma}}{\alpha} - \frac{\wt{\gamma}}{\alpha}\log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right).
    \end{split}
\end{equation*}
Plugging in again for $\Cfn,\Dfn(g,p)$ and using \eqref{E:Qval_complete} gives \eqref{E:Hcal_is_ok_1}.  The PDE \eqref{E:PDE_1} follows from \eqref{E:G_HJB} using $\wt{L}$ from \eqref{E:wtL_def} and \eqref{E:SigE_UpsE} at $\rho = \idmat{d}$ which shows $\Upsilon_e'\Sigma_e^{-1}\Upsilon_e = A$.


\subsection{Proof of Proposition \ref{P:general_hamil_2}}
We use the notation of \eqref{E:ACE_def}, \eqref{E:BD_def} as well as the optimal equity policy function in \eqref{E:opt_theta_1} for fixed $\delta$ and the Hamiltonian in \eqref{E:mid_hcal}.  Define the residual function
\begin{equation}\label{E:GR_def_new}
    \begin{split}
        R_{\Hcal}(\sigma,g,p) &\dfn \sup_{\delta}\bigg( -\frac{1}{2}\alpha \Afn(\sigma) \delta^2 + \Bfn(p,\sigma) \delta - \frac{1}{2\alpha\Cfn}\bigg(\plog{\Dfn(g,p) e^{-\alpha\Efn(\sigma)\delta}}^2\\
        &\qquad\qquad + 2\plog{\Dfn(g,p) e^{-\alpha \Efn(\sigma) \delta}}\bigg)\bigg) - \frac{\wt{\gamma}^2 \Cfn}{2\alpha} + \frac{\wt{\gamma}}{\alpha} + \frac{\wt{\gamma}}{\alpha}\log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right).
    \end{split}
\end{equation}
From \eqref{E:mid_hcal} we see
\begin{equation*}
    \begin{split}
        \Hcal(g,p) = \frac{1}{2\alpha}\left(\mu_e - \alpha\Upsilon_e p\right)'\Sigma_e^{-1}\left(\mu_e - \alpha\Upsilon_e p\right) + \frac{\wt{\gamma}^2 \Cfn}{2\alpha} - \frac{\wt{\gamma}}{\alpha} - \frac{\wt{\gamma}}{\alpha}\log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right) + R_{\Hcal}(\sigma,g,p).
    \end{split}
\end{equation*}
Using \eqref{E:Qval_complete}, a direct computation shows 
\begin{equation*}
    \begin{split}
        &\frac{1}{2\alpha}\left(\mu_e - \alpha\Upsilon_e p\right)'\Sigma_e^{-1}\left(\mu_e - \alpha\Upsilon_e p\right) + \frac{\wt{\gamma}^2 \Cfn}{2\alpha} - \frac{\wt{\gamma}}{\alpha} - \frac{\wt{\gamma}}{\alpha}\log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right)\\
        &\qquad = \frac{1}{\alpha}(Q_c-\gamma) + \wt{\gamma}(\psi-g)  + \frac{\alpha}{2}p'\Upsilon_e'\Sigma_e^{-1}\Upsilon_e p - p'\Upsilon_e'\Sigma_e^{-1}(\mu_e-\wt{\gamma}\ell_e).
    \end{split}
\end{equation*}
Therefore, the PDE \eqref{E:PDE_2} is obtained by substituting in for $\Hcal(G,\nabla G)$, and noting $\Upsilon_e'\Sigma_e^{-1}\Upsilon_e = a\rho'\rho a'$ and $\Upsilon_e'\Sigma_e^{-1} = a\rho'\sigma_e^{-1}$. We now show $R_{\Hcal}(0_d,p,g) = 0$. If $\sigma_r = 0_d$ then $\Afn(0_d) = 0, \Bfn(p, 0_d) = -\wt{\gamma}, \Efn(0_d) = 1$ and we solve
\begin{equation}\label{E:sup_delt_sigr_0}
    \sup_{\delta}\left( - \wt{\gamma}\delta - \frac{1}{2\alpha\Cfn}\left(\plog{\Dfn(g,p) e^{-\alpha\delta}}^2 + 2\plog{\Dfn(g,p) e^{-\alpha \delta}}\right)\right).
\end{equation}
Similarly to \eqref{E:p1_foc_opt_delta}, the first order conditions and optimizer are
\begin{equation}\label{E:opt_delta_sigr_0}
    \wt{\gamma}\Cfn = \plog{\Dfn(g,p) e^{-\alpha\wh{\delta}}} \quad \Longrightarrow \wh{\delta} = \frac{1}{\alpha}\left(-\wt{\gamma}\Cfn  + \log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right)\right).
\end{equation}
Plugging in for $\wh{\delta}$ in \eqref{E:sup_delt_sigr_0} gives the value
\begin{equation*}
    \frac{\wt{\gamma}^2 \Cfn,}{2\alpha} - \frac{\wt{\gamma}}{\alpha} - \frac{\wt{\gamma}}{\alpha}\log\left(\frac{\Dfn(g,p)}{\wt{\gamma}\Cfn}\right),
\end{equation*}
so that from \eqref{E:GR_def_new} we see $R_{\Hcal}(0_d,g,p) = 0$. Note from \eqref{E:opt_theta_1} and \eqref{E:opt_delta_sigr_0} we also obtain the formula for $\wh{\theta}_i$ in \eqref{E:gen_opt_strat_2} when $\sigma_r = 0$.  Next, consider when $\abs{\sigma_r}>0$.  Using \eqref{E:plog_deriv} below the first order conditions in \eqref{E:GR_def_new} are
\begin{equation*}
    0 = -\alpha\Afn(\sigma_r) \wh{\delta} + \Bfn(p,\sigma_r) + \frac{\Efn(\sigma_r)}{\Cfn}\plog{\Dfn(g,p) e^{-\alpha\Efn(\sigma_r)\wh{\delta}}}. 
\end{equation*}
This has unique solution
\begin{equation}\label{E:sigmaR_not_0_foc}
    \wh{\delta}(g,p) = \frac{\Bfn(p, \sigma_r)}{\alpha\Afn(\sigma_r)} +\frac{\Efn(\sigma_r)}{\alpha\Afn(\sigma_r)\mbf{K}_6(\sigma_r)}\plog{\frac{\Dfn(g,p)\mbf{K}_6(\sigma_r)}{\Cfn} e^{-\frac{\Efn(\sigma_r)\Bfn(p,\sigma_r)}{\Afn(\sigma_r)}}}.
\end{equation}
where
\begin{equation*}
\mbf{K}_6(\sigma) = \frac{\Afn(\sigma)\Cfn + \Efn(\sigma)^2}{\Afn(\sigma)}
\end{equation*}
In view of the equation for $\wh{\delta}$ in \eqref{E:opt_delta_sigr_0} we can write
\begin{equation}\label{E:wgdel_sigr_pos}
