\begin{equation}\label{E:G_HJB_local}
    \begin{split}
        0 &= G^n_s + L G^n -\frac{\alpha}{2}\nabla (G^n)' A \nabla (G^n) + \chi_n \left( \frac{\gamma}{\alpha} + \Hcal(G^n, \nabla G^n )\right),\quad \chi_n \phi = G^n(T,\cdot).
    \end{split}
\end{equation}
In accordance with \cite{MR1465184}, we adjust \eqref{E:G_HJB_local} with the following notations. First, define $v^n(s, x) \dfn G^n(T - s, x)$ and $\Omega_n \dfn (0, T - t) \times \OO_n$. Next, set $\Gamma_n \dfn B \Omega_n \cup S\Omega_n \cup \C \Omega_n$ as the parabolic boundary \footnote{See \cite[Section II.1]{MR1465184} for a definition of parabolic boundary.} of $\Omega_n$ where 
\begin{equation*}
    B \Omega_n \dfn \{0\} \times \OO_n;\quad S \Omega_n \dfn (0, T - t) \times \partial \OO_n;\quad C \Omega_n = \{0\} \times \partial \OO_n. 
\end{equation*}
The definition of $\Gamma_n \in H_{\eta}$ for some $\eta \geq 1$ can be found in \cite[Section IV.7]{MR1465184}. Finally, define $\varphi^n(s, x) \dfn \chi_n(x) \phi(x)$ for all $(s, x) \in \ol{\Omega}_n$ as the boundary condition on $\Gamma_n$. Then, the PDE for $v^n$ is
\begin{align}
    0 = P v^n & \dfn -v^n_s + \frac{1}{2}\tr\left( A D^2 v^n \right) + \ca^n(v^n, \nabla v^n), \label{E:localized_PDE} \\
    \ca^n(g, p) & \dfn b' p - \frac{\alpha}{2} p' A p + \chi_n \left( \frac{\gamma}{\alpha} + \Hcal(g, p)\right). \label{E:checka_def}
\end{align}
with $v^n = \varphi^n$ on $\Gamma_n$. 

Lastly, we briefly discuss the smoothness of $\Gamma_n$ and $\varphi^n$ here. For $\Gamma_n$, given $B \Omega_n = \{ 0 \} \times \Omega_n \subseteq \{ 0 \} \times \reals^d$ and $S \Omega_n = (0, T - t) \times \partial \OO_n$ with $\partial \OO_n \in C^{2, \beta}$ by Assumption \ref{A:region}, one can easily verify that $\Gamma_n \in H_{\eta}$ for $1 \leq \eta \leq 2 + \beta$. For $\varphi^n$, the independence of $s$ and $\chi_n \phi \in C^{2, \beta}(\OO; \reals)$ by Assumption \ref{A:phi_psi_alt} imply $\varphi^n \in H_{\eta, \Omega_n}$ for $1 \leq \eta \leq 2 + \beta$.

\begin{proposition}\label{P:localied_PDE_existence}
There exists a unique solution $v^n \in H_{2 + \beta, \Omega_n}$ to \eqref{E:localized_PDE}.
\end{proposition}
\begin{proof}[Proof of Proposition \ref{P:localied_PDE_existence}]
Analogous to the proof of \textit{Proposition A.1}, the existence of a solution to localized PDE \eqref{E:localized_PDE} is based on \cite[Theorem 12.16]{MR1465184}. To invoke this theorem, we need to verify the following:
\begin{enumerate}[(1)]
    \item  $\Gamma_n \in H_{1 + \beta'}$ and $\varphi^n \in H_{1 + \beta', \Omega_n}$ for some $\beta' \in (0, 1)$.

    \item $A^{i j} \in H_{1, K}$ for all bounded subsets $K$ of $\Omega_n$, and $\ca^n(g, p) \in H_{\beta, K}$ for all bounded subsets $K$ of $\Omega_n \times \reals \times \reals^d$.

    \item There exists a constant $C(n)$ such that $g \ca^n(g, 0) \leq C(n)(1 + g^2)$ for $(s, x) \in [0, T] \times \OO_n$.

    \item For any given interval $[g_1, g_2]$,
    \begin{equation*}
        \limsup_{\abs{p} \uparrow \infty} \sup_{\substack{(s, x) \in [0, T] \times \ol{\OO}_n, \\ g \in [g_1, g_2]}} \frac{\abs{\ca^n(g, p)}}{\abs{p}^2} < \infty.
    \end{equation*}
    \item
    \begin{equation*}
        \limsup_{\abs{p} \uparrow \infty}  \sup_{(s, x) \in [0, T] \times \ol{\OO}_n} \frac{\abs{\nabla_x A_{i j}}}{\abs{p}^2} < \infty,
    \end{equation*} 

\end{enumerate}


Since $1 \leq 1 + \beta' \leq 2 + \beta$, the previous discussion on the smoothness of $\Gamma_n$ and $\varphi_n$ implies part (1).  By Assumption \ref{A:region}, $A^{i j} \in C^{(1, 1)}(K; \reals) \subset H_{1, K}$ for all bounded subsets $K \in \Omega_n$. As $b$, $A$, $\chi_n$, $\gamma$ and $\Hcal$ are all continuously differentiable functions with respect to their variables, it follows that $\ca^n$ is continuously differentiable with respect to $(s, x, g, p)$. This implies that $\ca^n \in H_{1, K} \subseteq H_{\beta, K}$ for all bounded subsets $K$ of $\Omega_n \times \reals \times \reals^d$ and part (2) follows. Parts (3) and (4) are shown in Lemmas \ref{L:g_checka_bnd},  \ref{L:p_checka_bnd} respectively below. As for part (5), $A$ being independent of $p$ implies $\abs{\nabla_x A_{i j}}$ is of order 1 with respect to $\abs{p}$, giving the result. 

Putting all this together, \cite[Theorem 12.16]{MR1465184} yields a solution $v^n \in H^{- 1 - \beta'}_{2 + \beta, \Omega_n}$\footnote{The space $H^{-1-\beta'}_{2+\beta,\Omega_n}$ is defined in \cite[Chapter IV.1]{MR1465184} and is written $H^{(-1-\beta')}_{2+\beta,\Omega_n}$.}. By the remark at the end of \cite[Theorem 12.16]{MR1465184}, this solution is unique as $A$ is independent of $g$, and $\ca$ is Lipschitz with respect to $g$ and $p$. 

Lastly, we need to verify that $\varphi^n$ satisfies the compatibility condition of the first order, $P \varphi^n = 0$ on $C \Omega_n$. Indeed, $\nabla \varphi^n = 0$ and $\chi_n = 0$ on $C \Omega_n$ imply $\ca = 0$ on $C \Omega_n$. Moreover, as $\varphi^n_s = 0$ and $D^2 \varphi^n = 0$ on $C \Omega_n$, it follows $P \varphi^n = 0$ on $C \Omega_n$. Then, since $\Gamma_n \in H_{2 + \beta}$ and $\varphi^n \in H_{2 + \beta}$, we can further conclude that $v^n \in H_{2 + \beta, \Omega_n}$.

\end{proof}
\begin{remark}\label{R:gradient_bnd}
    Analogous to \cite[Remark A.2]{MR4086602}, $\abs{G^n}_{2 + \beta, \Omega_n}$ implies $$\sup_{(s, x) \in [0, T] \times \ol{\OO}_n} \abs{\nabla G^n} < \infty.$$
\end{remark}


\subsection{Localized optimal investment problem} We now define a localized optimal investment problem for the localized PDE defined above.  To do so, fix $t\leq T, x\in\OO$ and take $n$ large enough so that $x\in\OO_n$. Define the localized default time
\begin{equation}\label{E:tau_n_def}
