%     \ol{\sigma}^B = \begin{pmatrix} \sigma_e \ol{\rho}_n \\ 0 \end{pmatrix}.
% \end{equation}
The random endowment is $(\chi_n \phi)(X_{T \wedge \zeta^n}) \mathbbm{1}_{\tau^n > T \wedge \zeta^n} + \Psi(\tau^n , X_{\tau^n}) \mathbbm{1}_{\tau^n \leq T \wedge \zeta^n}$. The value function is
\begin{equation} \label{local_utility_function}
    u^n(t, x) \coloneqq \sup_{\pi^n \in \A^n} \E \left[ - \e^{- \alpha \left( \We^{\pi^n}_{T \wedge \zeta^n} + (\chi_n \phi)(X_{T \wedge \zeta^n}) \mathbbm{1}_{\tau^n > T \wedge \zeta^n} + \Psi(\tau^n , X_{\tau}^n) \mathbbm{1}_{\tau^n \leq T \wedge \zeta^n} \right) } \right].
\end{equation}

Analogously to \eqref{certainty equivalent}, and with an eye towards \eqref{E:G_HJB_local} we define the certainty equivalent $G^n(t,x) = -(1/\alpha)\log(-u^n(t,x))$, which analogously to \eqref{E:G_HJB} is expected to solve
\begin{equation*}
    0 = G^n_t + LG - \frac{\alpha}{2}\nabla (G^n)'A\nabla G^n + \frac{\chi_n\gamma}{\alpha} +  \sup_{\pi} H^n(\pi,G^n,\nabla G^n),\quad \chi_n\phi = G^n(T,\cdot).
\end{equation*}
To obtain \eqref{E:G_HJB_local} we must first obtain the local Hamiltonian, which has the same form as the right side of \eqref{E:hamil}, but for the localized assets.  As such, we note the local analog of \eqref{E:SigE_UpsE} is
\begin{equation*}
    \begin{split}
        \Sigma^n_{e} &= d\langle S^{e,n}, S^{e,n}\rangle / ds = \chi_n \Sigma_e;\quad \Upsilon^n_{e} = d\langle S^{e,n}, X \rangle /ds = \chi_n \Upsilon_e,\\
        \Sigma^n &= d\langle S^n, S^n \rangle /ds = \chi_n\Sigma;\quad \Upsilon^n = d\langle S^n, X\rangle / ds = \chi_n \Upsilon.
    \end{split}
\end{equation*}
Note that $\chi_n$ factors our of each quantity above.  Therefore, from \eqref{E:hamil} we obtain $H^n = \chi_n H$ and hence \eqref{E:G_HJB_local} follows.

Next, we recall \textit{Lemmas A.3 and A.4} specified to our notation. The first one is regarding the structure of $\qprob^n \sim \prob$ on $\G^n_{T \wedge \zeta^n}$, and the second one is regarding when $\qprob^n \in \M^n$. Below, our notation follows \eqref{E:mm_den}.

\begin{lemma}\label{L:local_ELLM_density_rep}
    Any measure $\qprob^n \sim \prob$ on $\G^n_{T \wedge \zeta^n}$ has representation
    \begin{equation}\label{E:local_elmm}
        \left. \frac{d \qprob^n}{d \prob} \right|_{T \wedge \zeta^n} = \Ecal\left(\int (\mbf{A}^n_s) 'dW_s + (\mbf{B}^n_s)' d B_s + \mbf{C}^n_s d M_s+ (\mbf{D}^n_s)' d \wh{W}_s \right)_t^{T \wedge \zeta^n}
    \end{equation}
    where $\mbf{A}^n$, $\mbf{B}^n$, $\mbf{C}^n$, and $\mbf{D}^n$ are $\filtg^n$ predictable processes. Additionally, $(W^{\qprob^n}, B^{\qprob^n}, \wh{W}^{\qprob^n})$ is a $\qprob^n$ Brownian motion over $[t,T \wedge \zeta^n]$ where $dW^{\qprob^n}_s = dW_s - \mbf{A}^n_s d s$, $dB^{\qprob^n}_{s} = dB_{s} -  \mbf{B}^n_s ds$, $d\wh{W}^{\qprob^n}_{s}  = d\wh{W}_{s} - \mbf{D}^n_s ds$, and $dM^{\qprob^n}_{s} = dM_{s} - 1_{s\leq \tau^n}(\chi_n \gamma)(s, X_s) \mbf{C}^n_s ds$ is a $\qprob^n$ martingale stopped at $T \wedge \zeta^n$.
\end{lemma}

\begin{lemma}
Let $\qprob^n \sim \prob$ on $\G^n_{T \wedge \zeta^n}$, and $\mbf{A}^n$, $\mbf{B}^n$, $\mbf{C}^n$, $\mbf{D}^n$ be in Lemma \ref{L:local_ELLM_density_rep}. Then $\qprob^n \in \M^n$ if and only if for $\prob \times \text{Leb}_{[t, T]}$ almost all $(\omega, s)$ on the set $\{ s \leq \tau^n \wedge T \wedge \zeta^n \}$, we have (suppressing the $(s,X_s)$ function arguments)
\begin{align}\label{E:risk_neutral_drift_condition}
    0 = 
    & \chi_n(\mu - \gamma \ell) + \chi_n \sigma_W \mbf{A}^n_s + \sqrt{\chi_n} \sigma_B \mbf{B}^n_s + \sqrt{\chi_n(1 - \chi_n)} \sigma_W \mbf{D}^n_s - \chi_n \gamma \mbf{C}^n_s \ell.
\end{align}
\end{lemma}
Now, we give the counterpart to \textit{Proposition A.5}. It shows that $G^n$ from Proposition \ref{P:localied_PDE_existence} is the certainty equivalent to \eqref{local_utility_function}. 

\begin{proposition}\label{P:localized_verification}
There is a unique solution $G_n \in H_{2 + \beta', \Omega_n}$ to the PDE in \eqref{E:G_HJB_local} that takes the form $G^n(t, x) = -\frac{1}{\alpha} \log \bigl( -u^n(t, x) \bigr)$, for $u^n$ defined in \eqref{local_utility_function}. The optimal policy functions are given in \eqref{E:gen_opt_strat_1} and \eqref{E:gen_opt_strat_2} except with $G$ and $\nabla G$ replaced by $G^n$ and $\nabla G^n$. The optimal martingale density process for $s \in [t, T \wedge \zeta^n]$ is
\begin{equation}\label{E:optimal_loc_martingale_density_local}
    \wh{Z}^n_s \dfn \wh{Z}^{\wh{\qprob}^n}_s = \e^{-\alpha \Bigl( \We^{\wh{\pi}^n} + 1_{\tau^n > s} G^n(s, X_s) + 1_{\tau^n \leq s} \Psi(\tau^n , X_{\tau^n}) - G^n(t, x) \Bigr)}.
\end{equation}
\end{proposition}
\begin{proof}[Proof of Proposition \ref{P:localized_verification}]
Due to the existence of the Brownian motion $\wh{W}$ in the localized optimal investment problem, we need to change the proof of \textit{Proposition A.5} slightly. Denoting $\wh{\We}^n \dfn \We^{\wh{\pi}_n}$, we need to show (1) $\wh{\We}^n$ is a $\qprob^n$ martingale for all $\qprob^n \in \wt{\M}^n$; (2) $\wh{Z}^n$ given by \eqref{E:optimal_loc_martingale_density_local} is a strictly positive martingale and $\wh{\qprob}^n$ defined by $\wh{Z}^n_{T \wedge \zeta^n}$ is in $\wt{\M}^n$. We begin with proof of (1). For $\qprob^n \in \wt{\M}^n$, by \eqref{E:risk_neutral_drift_condition} we know
\begin{align*}
    d \wh{\We}^n_s = 
    & \mathbbm{1}_{s \leq \tau^n \wedge \zeta^n} \Bigl( (\chi_n \sigma_W)(s, X_s)' d W^{\qprob^n}_s + ( \sqrt{\chi_n} \sigma_B ) (s, X_s) d B^{\qprob^n}_s \\
    & \qquad + ( \sqrt{\chi_n(1 - \chi_n)} \sigma_W) (s, X_s) d \wh{W}^{\qprob^n}_s \Bigr) - 1_{s \leq \zeta^n } \left( \pi^n_s \right)' l(s, X_s) d M^{\qprob^n}_s.
\end{align*}
Hence,
\begin{equation*}
    \left[ \wh{\We}^{\pi^n} \right]_{T \wedge \zeta^n} = \int_{t}^{T \wedge \zeta^n \wedge \tau^n} \bigl( \chi_n (\wh{\pi}^n)' \Sigma \wh{\pi}^n \bigr)(s,X_s) ds + 1_{\tau^n \leq T \wedge \zeta^n} \bigl( l' \wh{\pi}^n \bigr)^2(\tau^n,X_{\tau^n}).
\end{equation*}
Remark \ref{R:gradient_bnd} shows $\abs{\wh{\pi}^n}$ is bounded on $[t, T] \times \ol{\OO}_n$. As $\Sigma$ and $l$ are bounded on $[t, T] \times \ol{\OO}_n$ and $\chi_n$ is bounded on $\ol{\OO}_n$, we conclude that  
$\left[ \wh{\We}^{\pi^n} \right]_{T \wedge \zeta^n}$ is $\qprob^n$ almost surely bounded by a constant depending on $n$, which implies that $\wh{\We}^{\pi^n}$ is a $\qprob^n$ martingale.

Next, we move to prove (2). Using the arguments in the proof of \textit{Proposition A.5}, we know that $\wh{Z}^n$ has dynamics on $[t, T \wedge \zeta^n]$ of 
\begin{equation*}
    \frac{d \wh{Z}^n_s}{\wh{Z}^n_{s -}} = \mathbbm{1}_{s \leq \tau^n} \bigl( (\mbf{A}^n_s)' d W_s + (\mbf{B}^n_s)' d B_s + (\mbf{D}^n_s)' d \wh{W}_s \bigr) + \mbf{C}^n_s d M^n_s,
\end{equation*}
where $\mbf{A}^n_s = -\alpha \left( \chi_n \sigma_W' \wh{\pi}^n + a' \nabla G^n \right)_s$, $\mbf{B}^n_s = -\alpha \left( \sqrt{\chi_n} \sigma_B' \wh{\pi}^n \right)_s$, $\mbf{D}^n_s = - \alpha \left( \sqrt{\chi_n(1 - \chi_n)} \sigma_W' \wh{\pi}^n \right)_s$, and $\mbf{C}^n_s = \left( \e^{\alpha G^n - \alpha \psi + \alpha (\wh{\pi}^n)' l} - 1 \right)_s$. Remark \ref{R:gradient_bnd} shows $\abs{\mbf{A}^n_s}$, $\abs{\mbf{B}^n_s}$, $\abs{\mbf{C}^n_s}$, $\abs{\mbf{D}^n_s}$ are all bounded and $\filt^W$ predictable. Also, there is also a $\eps_n$ such that $\mbf{D}^n_s > - (1 - \eps_n)$. By \cite[Theorem 9]{MR2574236}, we know that $\wh{Z}^n$ is a strictly positive martingale. Then we can apply the same argument in the proof of \textit{Proposition A.5 and Lemma C.7}\footnote{The proof therein assumes $\Sigma$ does not degenerate, but calculation shows the result still holds even wtih degeneracy. Also, there is a typo in the second to last line of the proof of \textit{Lemma C.7}, as $+\gamma\ell$ should be $-\gamma\ell$.} to conclude $\wh{\qprob}^n$ defined by $\wh{Z}^n_{T \wedge \zeta^n}$ is in $\wt{\M}^n$.

\end{proof}
