\subsection{Unwinding the localization: analytical results}
Now, we need to unwind the existence result of local PDE to the global one. 

\begin{proposition}\label{P:analytical_unwind_lower_bnd}
Let $G^n$ from Proposition \ref{P:localied_PDE_existence} and \ref{P:localized_verification} and $\underline{\phi}$ from Proposition \ref{A:phi_psi_alt}. Then $G^n(s, y) \geq \underline{\phi}$ on $[0, T] \times \ol{\OO}_n$.
\end{proposition}

\begin{proof}[Proof of Proposition \ref{P:analytical_unwind_lower_bnd}]
Under Assumption \ref{A:incomplete_mkt} with $\abs{\sigma_r} > 0$, we can apply the same argument in \textit{Proposition A.6} to prove this result. Therefore, we only need to show $G^n$ is bounded from below by $\underline{\phi}$ on $[0, T] \times \ol{\OO}_n$ under Assumption \eqref{A:complete_mkt} or under Assumption \ref{A:incomplete_mkt} with $\abs{\sigma_r} \equiv 0$. Note that in both cases, we have
\begin{equation*}
    \check{a}^n(g, 0) = \chi_n \left( \frac{\gamma}{\alpha} + \Hcal_c(g, 0) \right).
\end{equation*}
Assume $G^n$ has the minimum in $[0, T) \times \OO_n$ at $(s_0, y_0)$. If $s_0 > 0$, then $G^n_s(s_0, y_0)= 0$; otherwise, $G^n_s(s_0, y_0) \geq 0$. Also, $\nabla G^n(s_0, y_0) = 0$. By the ellipticity of $A$ in $\OO_n$, we know that at $(s_0, y_0)$,
\begin{equation*}
    \begin{split}
    0 \geq & \chi_n \left( \frac{\gamma}{\alpha} + \Hcal_c(G^n, 0)\right)\\
    \geq & \frac{\chi_n}{2\alpha}\left(\mu_e - \wt{\gamma}\ell_e \right)'\Sigma_e^{-1}\left(\mu_e - \wt{\gamma}\ell_e \right) + \frac{\wt{\gamma}}{\alpha}\left(\frac{\gamma}{\wt{\gamma}} - 1 - \log\left(\frac{\gamma}{\wt{\gamma}}\right)\right)- \wt{\gamma}(G^n - \psi) \\
    \geq & - \wt{\gamma}(G^n - \psi).
    \end{split}
\end{equation*}
Therefore, we have $G^n(s_0, y_0) \geq \psi \geq 0 \geq \underline{\phi}$ by Assumption \ref{A:phi_psi_alt}. Moreover, as $G^n(T, \cdot) = \chi_n \phi \geq 0 \geq \underline{\phi}$ and $G^n(t, \partial \OO_n) = 0 \geq \underline{\phi}$ for every $t \in [0, T]$, we can conclude that $G^n(s, y) \geq \underline{\phi}$ on $[0, T] \times \ol{\OO}_n$.
\end{proof}


