\begin{proposition}\label{P:analytical_unwind}
Let $G^n$ from Proposition \ref{P:localied_PDE_existence} and \ref{P:localized_verification}. Assume for each $k \in \mathbb{N}$ that
\begin{equation}\label{E:Gn_bnd_assumption}
    \sup_{n \geq k + 1} \sup_{0 \leq s \leq T, y \in \ol{\OO}_k} G^n(s, y) = C(k) < \infty.
\end{equation}
Then there exists a solution $G$ to \eqref{E:PDE_2}. In particular, there is a subsequence (still labeled $n$) such that $G^n$ converges to $G$ in $H_{2 + \beta, (0, T) \times \OO, loc}$.
\end{proposition}

\begin{proof}[Proof of Proposition \ref{P:analytical_unwind}]
The proof of \textit{Proposition A.7} is divided into $4$ steps. Here, we need only verify the quantities $A_k^{\infty}$, $B_k^{\infty}$, $C_k^{\infty}$, and $D_k^{\infty}$ defined in \textit{Step $1$, equations (A.16), (A.17)} are all finite with $A_k^{\infty} = 1$ and $C_k^{\infty} = 0$. Then we can apply the same arguments in the remaining part of \textit{Step $1$}, with \cite[Theorem 11.3(b)]{MR1465184}, Proposition \ref{P:analytical_unwind_lower_bnd}, and Equation \eqref{E:Gn_bnd_assumption} to show
\begin{equation*}
    \sup_{n \geq k + 2} \sup_{(s, y) \in [0, T] \times \ol{\OO}_k} \abs{\nabla G^n(s, y)} < \infty.
\end{equation*} 
Using this bound, we can apply the same arguments in \textit{Steps 2-4} to finish the proof. To define $A_k^{\infty}$, $B_k^{\infty}$, $C_k^{\infty}$, and $D_k^{\infty}$ we first define the  the Bernstein function
\begin{equation*}
\Ecal(s, y, p) \dfn \frac{1}{2} p' A(s, y) p;\qquad (s,y,p)\in [0,T]\times \OO \times \reals^d.
\end{equation*}
Under our assumptions, for each $k$ there exists $0 < \lambda_k < \Lambda_k$ such that $\lambda_k p' p \leq \Ecal(s, y, p) \leq \Lambda_k p' p$ on $[0, T] \times \ol{\OO}_k \times \reals^d$. Next, we define the operators $\delta(p)$, and $\ol{\delta}(p)$, which act on functions $f$ of $(s,y,g,p)$ by 
\begin{equation*}
    \delta(p)[f] \dfn  f_g + \frac{1}{p' p} p' \nabla_x f; \qquad \ol{\delta}(p)[f] \dfn p' \nabla_p f.
\end{equation*}
Lastly, we note that for $n \geq k + 1$, $\chi_n(x) = 1$ on $\ol{\OO}_k$, and hence in \eqref{E:checka_def} we write  $\ca(g, p)$ for $\ca^n(g, p)$ as it no longer depends upon $n$. With all this preparation, \textit{equations (A.16), (A.17)} take the form
\begin{equation}\label{E:ABCD_def}
    \begin{split}
    A_k& \dfn  \frac{1}{\Ecal} \Bigl( \frac{p' p}{8 \lambda_k} \sum_{i, j = 1}^{d} \bigl( \ol{\delta}(p)[A^{i j}] \bigr)^2 + \bigl( \ol{\delta}(p) - 1 \bigr) [\Ecal] \Bigr)\\
    B_k& \dfn \frac{1}{\Ecal} \Bigl( \delta(p) [\Ecal] +  \bigl( \ol{\delta}(p) - 1 \bigr)[\check{a}] \Bigr),\\
    C_k& \dfn \frac{1}{\Ecal} \Bigl( \frac{p' p}{8 \lambda_k} \sum_{i, j = 1}^{d} \bigl( \delta(p) [A^{i j}] \bigr)^2 + \delta(p) [\check{a}] \Bigr),\\
    D_k& \dfn \frac{1}{\Ecal} \Bigl( \Lambda_k p' p + \abs{p} \bigl( \abs{\nabla_p \Ecal} + \abs{\nabla_p \check{a}} \bigr) \Bigr).
    \end{split}
\end{equation}
Next, for any constant $C(k) > 0$, and $Y \in \cbra{A,B,C,D}$ we define
\begin{equation}\label{E:ABCD_k_infty}
    \begin{split}
        Y^\infty_k & \dfn \limsup_{\abs{p} \uparrow \infty} \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_k, \\ g \in [-C(k), C(k)]}} \abs{Y_k(s, y, g, p)}.
    \end{split}
\end{equation}
As mentioned above, our goal is to verify 
\begin{equation*}
    A_k^{\infty} = 1, \quad B^{\infty}_k < \infty, \quad C^{\infty}_k = 0, \quad D^{\infty}_k < \infty.
\end{equation*}
As $A=A(s,y)$ does not depend on $p$ and $(\ol{\delta}(p)-1)[\Ecal] = \Ecal$ we obtain $A_k \equiv  1$, and hence $A^{\infty}_k = 1$. As for the other quantities, we show $B^{\infty}_k < \infty$, $C^{\infty}_k = 0$, and $D^{\infty}_k < \infty$ in Lemmas \ref{L:BCD_k_infty_finite_1} and \ref{L:BD_k_infty_finite_2} below. As the rest of the proof holds by repeating the steps in the proof of \textit{Proposition A.7}, we obtain the result.
