\subsection{Unwinding the localization: probabilistic results}\text{}

We now unwind the localization from a probabilistic perspective, culminating in Proposition \ref{P:unwind_prob}, which will finish the proof of Theorem \ref{T:main_result}.  A key result from \cite{MR4086602} which we use throughout, and which holds in our setting with no changes to the proof\footnote{Presently we have the independent Brownian motion $\wh{W}$ which was absent in \cite{MR4086602}. However, it is clear from \eqref{E:loc_wealth_dynamics} and the proof of \textit{Proposition A.9} that the integral with respect to $\wh{W}$ vanishes in probability as $n\to\infty$.}, is \textit{Proposition A.9}, which we repeat here for ease of reference. 

\begin{proposition}\label{P:unwind_prob_0}
Assume \eqref{E:Gn_bnd_assumption} and let $G$ be the solution to \eqref{E:G_HJB} obtained in Proposition \ref{P:analytical_unwind}. Define $\wh{\pi}$ using \eqref{E:hat_pi} (more precisely \eqref{E:gen_opt_strat_1}, \eqref{E:gen_opt_strat_2}) and $\wh{Z}$ as in \eqref{E:opt_mm_dens}. Then
\begin{enumerate}[(i)]
\item $\wh{Z}$ defines a measure $\wh{\qprob} \in \tM$.
\item $\We^{\wh{\pi}}$ is a $\wh{\qprob}$ sub-martingale.
\item For $u$ defined in \eqref{E:vf_tx} we have $G(t,x) \geq -(1/\alpha)\log(-u(t,x,0))$.
\end{enumerate}
\end{proposition}

Net, we introduce the inequalities that will appear frequently below. For $x > 0$, $y \in \reals$, $K > 0$ and $p > 1$, $q = \frac{p}{p - 1}$,
\begin{equation}\label{E:inequalities_prob_result}
    x y \leq \frac{1}{K} \bigl( x \log x + \e^{K y} \bigr),\quad \e^{y} \leq \frac{1}{p} \e^{p y} + \frac{1}{q} \e^{q y}.
\end{equation}

\begin{proposition}\label{P:unwind_prob}
Under Assumption \ref{A:complete_mkt} the conclusions of Theorem \ref{T:main_result_complete} follow.  Similarly, under Assumption \ref{A:incomplete_mkt} the conclusions of Theorem \ref{T:main_result} follow.
\end{proposition}
\begin{proof}[Proof of Proposition \ref{P:unwind_prob}] To ease the notational burden, define
\begin{equation}\label{E:wh_an_bn_def}
    \wh{a}_n \dfn T\wedge \zeta^{n-1};\qquad \wh{b}_n \dfn T\wedge \zeta^n.
\end{equation}
According to the outline in the proof of \textit{Proposition A.11} the result in each respective case will follow provided (for a starting time $t$ and location $x$)
\begin{enumerate}[(1)]
\item For each $k$ and $n\geq k+1$, find a probability measure $\ol{\qprob}^n \in \wt{\M}^n$ such that
\begin{equation}\label{E:dual_quant}
    \frac{1}{\alpha} \expvs{Z^{\ol{\qprob}^n}_{\wh{b}_n} \log Z^{\ol{\qprob}^n}_{\wh{b}_n}} + \expvs{Z^{\ol{\qprob}^n}_{\wh{b}_n} \Bigl( 1_{\tau^n > \wh{b}_n}(\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n, X_{\tau^n}) \Bigr)},
\end{equation}
is bounded from above by a constant $C(k)$ when $x\in\ol{\OO}_k$, $t\leq T$ and $n\geq k+1$. By duality, this will establish \eqref{E:Gn_bnd_assumption} and allow us to invoke Propositions \ref{P:analytical_unwind} and \ref{P:unwind_prob_0}.

\item For each $\qprob \in \wt{\M}$, adjust the density process $Z^{\qprob}$ in $( \tau \wedge \wh{a}_n, \tau \wedge \wh{b}_n]$ using $Z^{\ol{\qprob}^n}$ to obtain a new density process $Z^n$, and show that $\qprob^n$ defined by $Z^n$ is in $\wt{\M}^n$. Next, show that as $n \to \infty$
\begin{equation*}
    \begin{split}
        &\expvs{Z^n_{\wh{b}_n} \log Z^n_{\wh{b}_n}} \to \expvs{Z^{\qprob}_{T \wedge \tau}\log \left( Z^{\qprob}_{T \wedge \tau} \right)},\\
        &\expvs{Z^n_{\wh{b}_n} \bigl(1_{\tau^n > \wh{b}_n} (\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n,X_{\tau^n}) \bigr) } \to \expvs{Z^{\qprob}_{T\wedge\tau} \left( 1_{\tau > T} \phi(X_T) + 1_{\tau \leq T} \psi(\tau,X_{\tau}) \right)}.
    \end{split}
\end{equation*}
This will give us the upper bound on $G$,
\begin{equation*}
    \begin{split}
        G(t, x) &\leq \inf_{\qprob \in \wt{\M}} \Bigl( \frac{1}{\alpha} \expvs{Z^{\qprob}_{\tau \wedge T}\log \left( Z^{\qprob}_{\tau \wedge T} \right)} + \expvs{Z^{\qprob} \left( 1_{\tau > T} \phi_T + 1_{\tau \leq T} \psi_\tau \right)} \Bigr),\\
        &= -\frac{1}{\alpha}\log(-u(t,x,0)),
    \end{split}
\end{equation*}
where the last equality follows according to the standard duality theory.  In view of Proposition \ref{P:unwind_prob_0} we conclude that $G$ is the certainty equivalent, and $\wh{\pi},\wh{\qprob}$ are optimal, as \eqref{E:opt_mm_dens} verifies the first order optimality conditions, and  $\wh{\qprob}\in\tM$ implies $\We^{\wh{\pi}}$ is a $\wh{\qprob}$ super-martingale, hence martingale by Proposition \ref{P:unwind_prob_0}. This will yield Theorems \ref{T:main_result_complete} and \ref{T:main_result}.
\end{enumerate}

We start with step $(1)$ and use the notation of \eqref{E:local_elmm}. The idea is to set $\ol{\qprob}^n = \tprob$, but we have to make slight adjustments due to the localization (in particular because of the martingale $M^n$). First, under Assumption \ref{A:complete_mkt} we set (see \eqref{E:tprob_mpr_c})
\begin{equation}\label{E:bar_qprob_n_1}
    \ol{\mbf{A}}^n = \ol{\mbf{A}} = -\tprobnu = -\sigma_e^{-1}(\mu_e - \wt{\gamma}\ell_e);\quad \ol{\mbf{B}}^n \equiv 0;\quad \ol{\mbf{C}}^n = \ol{\mbf{C}} =  \frac{\wt{\gamma}}{\gamma}-1;\quad \ol{\mbf{D}}^n \equiv 0.
\end{equation}
The market price of risk equations \eqref{E:risk_neutral_drift_condition} are easily seen to hold. Alternatively, under Assumption \ref{A:incomplete_mkt}, we set
\begin{equation}\label{E:bar_qprob_n_2}
    \ol{\mbf{A}}^n = \ol{\mbf{A}} = -\tprobnu ;\quad \ol{\mbf{B}}^n =  -\sqrt{\chi}_n(\ol{\rho})^{-1}\left(\sigma_e^{-1}(\mu_e -\wt{\gamma}\ell_e) - \rho\tprobnu\right);\quad \ol{\mbf{C}}^n = \ol{\mbf{C}} = \frac{\wt{\gamma}}{\gamma}-1;\quad \ol{\mbf{D}}^n \equiv 0.
\end{equation}
The market price of risk equations \eqref{E:risk_neutral_drift_condition} again hold. With these assignments, we now show \eqref{E:dual_quant}. 
By first conditioning on $\F^{W,H^n}_{\tau^n\wedge \wh{b}_n}$ we obtain
\begin{equation*}
    \begin{split}
        &\expv{}{}{Z^{\ol{\qprob}^n}_{\wh{b}_n} \Bigl( 1_{\tau^n > \wh{b}_n}(\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n, X_{\tau^n}) \Bigr)} = \expv{\ol{\qprob}^n}{}{\Bigl( 1_{\tau^n > \wh{b}_n}(\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n, X_{\tau^n}) \Bigr)},\\
        & \qquad = \expv{\ol{\qprob}^n}{}{(\chi_n\phi)(X_{\wh{b}_n})e^{-\int_t^{\wh{b}_n}(\chi_n\wt{\gamma})(v,X_v)dv} + \int_t^{\wh{b}_n} \psi(u,X_u)(\chi_n\wt{\gamma})(u,X_u)e^{-\int_t^u (\chi_n\wt{\gamma})(v,X_v)dv}du}, \\
        & \qquad = \wtexpv{}{}{(\chi_n\phi)(X_{\wh{b}_n})e^{-\int_t^{\wh{b}_n}(\chi_n\wt{\gamma})(v,X_v)dv} + \int_t^{\wh{b}_n} \psi(u,X_u)(\chi_n\wt{\gamma})(u,X_u)e^{-\int_t^u (\chi_n\wt{\gamma})(v,X_v)dv}du}.
    \end{split}
\end{equation*}
The last equality follows as $\ol{\qprob}^n$ and $\tprob$ agree on $\F^{W}_{\wh{b}_n}$. As $\chi_n$ vanishes on $\partial \OO_n$ and $\chi_n,\wt{\gamma}\geq 0$ the first term is bounded above by
\begin{equation*}
    \wtexpv{}{}{1_{\zeta^n>T}(\chi_n\phi)(X_{\wh{b}_n})e^{-\int_t^{\wh{b}_n}(\chi_n\wt{\gamma})(v,X_v)dv}} \leq -\ul{\phi} + \wtexpv{}{}{\phi(X^{t,x}_T)},
\end{equation*}
where we brought back in the $(t,x)$ dependency.  Therefore, from part (1) of Assumption \ref{A:phi_psi_alt}, for $t\leq T$ and $x\in \ol{\OO_k}$ this term is bounded from above by some $c(k)$. As for the second term, if $\psi$ is bounded from above by a constant $K$ then so is the expected value.  Else, using $0\leq \chi_n\leq 1$ and $\wt{\gamma}\geq 0$ we deduce
\begin{equation*}
    \wtexpv{}{}{\int_t^{\wh{b}_n} \psi(u,X_u)(\chi_n\wt{\gamma})(u,X_u)e^{-\int_t^u (\chi_n\wt{\gamma})(v,X_v)dv}du} \leq \wtexpv{}{}{\int_t^T (\psi\wt{\gamma})(u,X^{t,x}_u)du}.
\end{equation*}
This term is also bounded from above by a constant $C(k)$ when $t\leq T$ and $x\in\ol{\OO}_k$ by Assumption \ref{A:phi_psi_alt}. It remains to bound the relative entropy. To this end, and because $\ol{\mbf{D}}^n$ vanishes in each case, we write
\begin{equation*}
    \ol{Z}^n_{\cdot} = \Ecal \Bigl(  \int_t\ol{\mbf{A}}_u' d W_u + (\ol{\mbf{B}}^n_u)' d B_u + \ol{\mbf{C}}_u d M^n_u \Bigr)_{\cdot},
\end{equation*}
Using the identity $\Ecal \left( U + V + [U, V] \right) = \Ecal \left( U \right) \Ecal \left( V \right)$ we can write $\ol{Z}^n = \ol{Z}^{\mbf{A}}\ol{Z}^{\mbf{B},n}\ol{Z}^{\mbf{C},n}$ where
\begin{equation}\label{E:bZ_ABD_n}
    \ol{Z}^{\mbf{A}}_{\cdot} = \Ecal \Bigl( \int_t^{\cdot} \ol{\mbf{A}}_u' d W_u \Bigr);\quad \ol{Z}^{\mbf{B},n}_{\cdot} = \Ecal \Bigl( \int_t^{\cdot} (\ol{\mbf{B}}^n_u)' d B_u \Bigr);\quad 
    \ol{Z}^{\mbf{C}, n}_{\cdot} = \Ecal \Bigl( \int_t^{\cdot} \ol{\mbf{C}}_u d M^n_u \Bigr).
\end{equation}
Below, we will verify the identity
\begin{equation}\label{E:loc_rel_ent_ident}
    \begin{split}
        &\expvs{Z^{\ol{\qprob}^n}_{\wh{b}_n} \log Z^{\ol{\qprob}^n}_{\wh{b}_n}} = \mathbb{E}\bigg[\ol{Z}^{\mbf{A}}_{\wh{b}_n}\bigg(\log\left(\ol{Z}^{\mbf{A}}_{\wh{b}_n}\right) + \int_t^{\wh{b}_n} \bigg(\frac{1}{2}|\ol{\mbf{B}}^n_u|^2 \\
        &\qquad + (\chi_n\wt{\gamma})(u,X_u) e^{-\int_t^u (\chi_n\wt{\gamma})(v,X_v)dv}\left(\frac{\gamma}{\wt{\gamma}} - \log\left(\frac{\gamma}{\wt{\gamma}}\right) -1 \right)(u,X_u)\bigg)du\bigg)\bigg].
    \end{split}
\end{equation}
Admitting this, using the non-negativity of $\wt{\gamma}$ and $z\to z - \log(z) - 1$ on $(0,\infty)$; that $0\leq \chi_n \leq 1$; the definition of $\tprob$ and $\ol{\mbf{A}}$ (in particular that $\tprobnu$ is bounded on $\OO_n$); and the definitions of $Q =  Q_c$ or $Q = Q_i$ in \eqref{E:Qval_complete},\eqref{E:Qval_incomplete} respectively we obtain
\begin{equation*}
    \expvs{Z^{\ol{\qprob}^n}_{\wh{b}_n} \log Z^{\ol{\qprob}^n}_{\wh{b}_n}} \leq \wtexpv{}{}{\int_t^{\wh{b}_n} Q(u,X^{t,x}_u)du} \leq \wtexpv{}{}{\int_t^{T} Q(u,X^{t,x}_u)du}.
\end{equation*}
The upper bound for each $t\leq T, x\in\ol{\OO}_k$ and all $n\geq k+1$ now follows from Assumption \ref{A:complete_mkt} when $Q=Q_c$ and (using Jensen's inequality) from Assumption \ref{A:incomplete_mkt} when $Q=Q_i$. To show \eqref{E:loc_rel_ent_ident}, by conditioning on $\F^{W,H^n}_{\wh{b}_n}$ and using the conditional normality of $\int_t^{\wh{b}_n} (\ol{\mbf{B}}^n_u)'dB_u$ we obtain
\begin{equation*}
    \begin{split}
        &\expvs{Z^{\ol{\qprob}^n}_{\wh{b}_n} \log Z^{\ol{\qprob}^n}_{\wh{b}_n}} = \mathbb{E}\bigg[\ol{Z}^{\mbf{A}}_{\wh{b}_n}\ol{Z}^{\mbf{C},n}_{\wh{b}_n}\bigg(\log\left(\ol{Z}^{\mbf{A}}_{\wh{b}_n}\ol{Z}^{\mbf{C},n}_{\wh{b}_n}\right) + \frac{1}{2}\int_t^{\wh{b}_n}\abs{\ol{\mbf{B}}^n_u}^2du\bigg)\bigg].
    \end{split}
\end{equation*}
The stochastic exponential $\ol{Z}^{\mbf{C},n}$ satisfies
\begin{equation*}
    \begin{split}
        \ol{Z}^{\mbf{C},n}_{\wh{b}_n} &= 1_{\tau^n > \wh{b}_n} e^{-\int_t^{\wh{b}_n} (\ol{\mbf{C}}\chi_n\gamma)(v,X_v)dv} + 1_{\tau^n\leq \wh{b}_n} e^{-\int_t^{\tau^n} (\ol{\mbf{C}}\chi_n\gamma)(v,X_v)dv}\left(1+ \ol{\mbf{C}}(\tau^n,X_{\tau^n})\right),\\
        &= 1_{\tau^n > \wh{b}_n} e^{-\int_t^{\wh{b}_n} ((\wt{\gamma}-\gamma)\chi_n)(v,X_v)dv} + 1_{\tau^n\leq \wh{b}_n} e^{-\int_t^{\tau^n} ((\wt{\gamma}-\gamma)\chi_n)(v,X_v)dv}\left(\frac{\wt{\gamma}}{\gamma}\right)(\tau^n,X_{\tau^n}).
    \end{split}
\end{equation*}
Using \eqref{E:tau_n_def} we first obtain
\begin{equation}\label{E:jump_part_good}
    \begin{split}
        \condexpvs{\ol{Z}^{\mbf{C},n}_{\wh{b}_n}}{\F^W_{\wh{b}_n}} &= e^{-\int_t^{\wh{b}_n} ((\wt{\gamma}-\gamma)\chi_n)(v,X_v)dv - \int_t^{\wh{b}_n} (\chi_n\gamma)(v,X_v)dv}\\
        &\qquad + \int_t^{\wh{b}_n} e^{-\int_t^u ((\wt{\gamma}-\gamma)\chi_n)(v,X_v)dv}\left(\frac{\wt{\gamma}}{\gamma}\right)(u,X_{u})(\chi_n\gamma)(u,X_u) e^{-\int_t^u (\chi_n\gamma)(v,X_v)dv}du,\\
        &= e^{-\int_t^{\wh{b}_n} (\chi_n\wt{\gamma})(v,X_v)dv}  + \int_t^{\wh{b}_n} e^{-\int_t^v (\chi_n\wt{\gamma})(v,X_v)dv}(\chi_n\wt{\gamma})(u,X_{u})du = 1,
    \end{split}
\end{equation}
using integration by parts. This implies
\begin{equation*}
    \begin{split}
        &\expvs{Z^{\ol{\qprob}^n}_{\wh{b}_n} \log Z^{\ol{\qprob}^n}_{\wh{b}_n}} = \mathbb{E}\bigg[\ol{Z}^{\mbf{A}}_{\wh{b}_n}\bigg(\log\left(\ol{Z}^{\mbf{A}}_{\wh{b}_n}\right) + \frac{1}{2}\int_t^{\wh{b}_n}\abs{\ol{\mbf{B}}^n_u}^2du\bigg)\bigg]\\
        &\qquad + \mathbb{E}\bigg[\ol{Z}^{\mbf{A}}_{\wh{b}_n}\condexpvs{\ol{Z}^{\mbf{C},n}_{}\log\left(\ol{Z}^{\mbf{C},n}_{\wh{b}_n}\right)}{\F^{W}_{\wh{b}_n}}\bigg].
    \end{split}
\end{equation*}
Again using \eqref{E:tau_n_def} and similar calculations we obtain 
\begin{equation*}
    \begin{split}    &\condexpvs{\ol{Z}^{\mbf{C},n}_{\wh{b}_n}\log\left(\ol{Z}^{\mbf{C},n}_{\wh{b}_n}\right)}{\F^{W}_{\wh{b}_n}} = - e^{-\int_t^{\wh{b}_n} (\chi_n\wt{\gamma})(v,X_v)dv}\times \int_t^{\wh{b}_n} ((\wt{\gamma}-\gamma)\chi_n)(u,X_u)du\\
    &\qquad + \int_t^{\wh{b}_n} (\chi_n\wt{\gamma})(u,X_u)e^{-\int_t^v (\chi_n\wt{\gamma})(v,X_v)dv}\left(-\int_t^u ((\wt{\gamma}-\gamma)\chi_n)(u,X_u) + \log\left(\frac{\wt{\gamma}}{\gamma}\right)(u,X_u)\right)du,\\
    &\quad = \int_t^{\wh{b}_n} (\chi_n\wt{\gamma})(u,X_u)e^{-\int_t^v (\chi_n\wt{\gamma})(v,X_v)dv}\left(\frac{\gamma}{\wt{\gamma}} - \log\left(\frac{\gamma}{\wt{\gamma}}\right) - 1\right)(u,X_u)d u,
    \end{split}
\end{equation*}
where we again used integration by parts to obtain the last equality.  This gives \eqref{E:loc_rel_ent_ident} and finishes the proof of step (1).

Moving to step $(2)$, recall the Brownian motion $\wh{W}$ is absent in the non-localized market. As such, for each $\qprob \in \M$, the density process $Z^{\qprob}$ takes the form on $[t,T]$
\begin{equation*}
    Z^{\qprob}_{\cdot} = \Ecal\left(\int_t^{\cdot} \mbf{A}_u'dW_u + \mbf{B}_u' d B_u +  \mbf{C}_u d M_u \right),
\end{equation*}
where from \eqref{E:S_def} we deduce $\mbf{A},\mbf{B},\mbf{C}$ must satisfy the market price of risk equations
\begin{equation*}
    0 = (\mu - \gamma\ell)(s,X_s) + \sigma_W(s,X_s) \mbf{A}_s + \sigma_B(s,X_s) \mbf{B}_s - (\gamma\ell)(s,X_s) \mbf{C}_s,  
\end{equation*}
almost surely on the stochastic interval $[t,T\wedge\tau]$. From  \textit{Lemma A.8} we deduce that any optimizer $\wh{\qprob}\in\tM$ to \eqref{E:dual_problem} must have $\filt^{W,B}$ predictable $\mbf{A},\mbf{B},\mbf{C}$, and density process $Z^{\wh{\qprob}}$ stopped at $\tau$. As such, without loss of generality we will assume these facts throughout.

Next, similarly to \eqref{E:wh_an_bn_def} (and as in \textit{equation (A.37)}), define
\begin{equation*}
a_n = \tau^n \wedge T \wedge \zeta^{n - 1} = \tau^n \wedge \wh{a}_n,\qquad b_n = \tau^n \wedge T \wedge \zeta^{n} = \tau^n\wedge\wh{b}_n.
\end{equation*}
We also use \textit{Lemma C.8} which shows almost surely that $a_n = \tau^n \wedge T \wedge \zeta^{n-1}$ so that $a_n < b_n$. Next, recalling $\ol{\qprob}^n$ defined via either \eqref{E:bar_qprob_n_1} or \eqref{E:bar_qprob_n_2}, we modify $Z^{\qprob}$ to create a density process $Z^n$ by setting 
\begin{equation*}
    \begin{split}
        \mbf{A}^n_u &= \mbf{A}_u 1_{u \leq a_n} + \ol{\mbf{A}}_u 1_{a_n < u \leq b_n};\quad \mbf{B}^n_u = \mbf{B}_u 1_{u\leq a_n} + \ol{\mbf{B}}^n_u 1_{a_n < u \leq b_n};\quad \mbf{C}^n_u = \mbf{C}_u 1_{u \leq a_n} + \ol{\mbf{C}} 1_{a_n < u \leq b_n}.
    \end{split}
\end{equation*}
As $\chi_n = 1$ on $\OO_{n-1}$ it is clear that \eqref{E:risk_neutral_drift_condition} holds, and in what follows we show the associated measure $\qprob^n$ is well defined and in $\tM^n$. First, using the same arguments in the proof of \textit{Proposition A.11}, we obtain $\expvs{Z^n_{\wh{b}_n}} = 1$, which shows $\qprob^n$ is well defined an in $\M^n$. Next, we need to show $\expvs{Z^n_{\wh{b}_n} \log (Z^n_{\wh{b}_n})} < \infty$ so that $\qprob^n \in \tM^n$. To do so,  note that
\begin{equation*}
    \expvs{Z^n_{\wh{b}_n} \log (Z^n_{\wh{b}_n})} = \expvs{Z^n_{b_n} \log (Z^n_{b_n})} = \expvs{Z^{\qprob}_{a_n} \log Z^{\qprob}_{a_n}} + \expvs{Z^{\qprob}_{a_n} \condexpvs{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} }.
\end{equation*}
As $s \to Z^{\qprob}_s\log(Z^{\qprob}_s)$ is a sub-martingale and $\qprob\in\tM$ we know
\begin{equation*}
    \expvs{Z^{\qprob}_{a_n} \log Z^{\qprob}_{a_n}} \leq \expvs{Z^{\qprob}_{T \wedge \tau} \log Z^{\qprob}_{T \wedge \tau}} < \infty.
\end{equation*}
% \srcom{Zhe: please provide a proof the next lemma.}

For the second term, by Lemma \ref{L:long_cond_exp} with $Q=Q_c$ from \eqref{E:Qval_complete} or $Q=Q_i$ from \eqref{E:Qval_incomplete}, we have
% \begin{lemma} %\label{L:long_cond_exp}
% \begin{equation*}
%     \begin{split}
%         &\condexpvs{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} = 1_{\tau^n > \wh{a}_n} \wt{\mathbb{E}}\bigg[\int_{\wh{a}_n}^{\wh{b}_n} e^{-\int_{\wh{a}_n}^u (\chi_n\wt{\gamma})(v,X_v)dv}\bigg(\frac{1}{2}\abs{\mbf{A}_u}^2\\
%         &\qquad\qquad + \frac{1}{2}\abs{\ol{\mbf{B}}^{n}_u}^2 + \bigg(\chi_n\wt{\gamma}\bigg(\frac{\gamma}{\wt{\gamma}} - 1 - \log\bigg(\frac{\gamma}{\wt{\gamma}}\bigg)\bigg)\bigg)(u,X_u)\bigg)du\ \bigg| \ \F^W_{\wh{a}_n}\bigg].
%     \end{split}
% \end{equation*}
% \end{lemma}
\begin{equation}\label{E:cond_inequality_Q}
    \condexpvs{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} \leq 1_{\tau^n>\wh{a}_n} \wtcondexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} Q(u,X_u) du}{\F^W_{\wh{a}_n}}.
\end{equation}
Therefore, as $a_n = \wh{a}_n$ on $\cbra{\tau^n > \wh{a_n}}$ we have
\begin{equation*}
    \begin{split}
        &\expvs{Z^{\qprob}_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} } \leq  \expvs{Z^{\qprob}_{\wh{a}_n} 1_{\tau^n>\wh{a}_n}\wtcondexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} Q(u,X_u) du}{\F^W_{\wh{a}_n}}}.
    \end{split}
\end{equation*}
Under Assumption \ref{A:complete_mkt}, the market is complete with unique martingale measure $\tprob$. Thus $Z^{\qprob}_{\wh{a}_n} = Z^{\tprob}_{\wh{a}_n}$ and
\begin{equation*}
    \begin{split}
        &\expvs{Z^{\qprob}_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} } \leq  \wtexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} Q_c(u,X_u) du} \leq \wtexpv{}{}{\int_{t}^{T} Q_c(u,X^{t,x}) du}.
    \end{split}
\end{equation*}
The upper bound for each $t\leq T, x\in\ol{\OO}_k$ and all $n\geq k+1$ now follows form Assumption \ref{A:complete_mkt}. Alternatively, when Assumption \ref{A:incomplete_mkt} holds, we  use \eqref{E:inequalities_prob_result} to say for any $K>0$ that
\begin{equation*}
    \begin{split}
        \expvs{Z^{\qprob}_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} } &\leq \frac{1}{K}\left(\expvs{Z^{\qprob}_{\wh{a}_n} \log\left(Z^{\qprob}_{\wh{a}_n}\right)} + \frac{1}{e}\right)\\
        &\qquad + \frac{1}{K} \expvs{1_{\tau^n>\wh{a}_n} \e^{K \wtcondexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} Q_i(u,X_u) d u}{\F^W_{\wh{a}_n}}} }.
    \end{split}
\end{equation*}
The first term on the right above is finite as $\qprob\in\tM$. As for the second term,  straight-forward computations (similar to those which established \eqref{E:jump_part_good}) show that on $\tau^n > \wh{a}^n$ we have $Z^{\tprob}_{\wh{a}_n} = \ol{Z}^{\mbf{A}}_{\wh{a}_n}$ for $\ol{Z}^{\mbf{A}}$ from \eqref{E:bZ_ABD_n}. Next, using Jensen's inequality, iterated conditioning and H\"{o}lder inequality with $p > 1$, we obtain
\begin{equation}\label{E:holder_inequality_Qi}
    \begin{split}
        \expvs{1_{\tau^n>\wh{a}_n} \e^{K \wtcondexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} Q_i(u,X_u) d u}{\F^W_{\wh{a}_n}}} } & = \expv{}{}{1_{\tau^n>\wh{a}_n} Z^{\tprob}_{\wh{a}_n}\left(\ol{Z}^{\mbf{A}}_{\wh{a}_n}\right)^{-1} \e^{K \wtcondexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} Q_i(u,X_u) d u}{\F^W_{\wh{a}_n}}} },\\
        &\leq \wtexpv{}{}{\left(\ol{Z}^{\mbf{A}}_{\wh{a}_n}\right)^{-1} \e^{ K \int_{\wh{a}_n}^{\wh{b}_n} Q_i(u,X_u) d u }},\\
        &\leq \wtexpv{}{}{\left(\ol{Z}^{\mbf{A}}_{\wh{a}_n}\right)^{-p}}^{\frac{1}{p}} \wtexpv{}{}{\e^{ \frac{K p}{p - 1} \int_{\wh{a}_n}^{\wh{b}_n} Q_i(u,X_u) d u } }^{\frac{p - 1}{p}}.
    \end{split}
\end{equation}
For the first term on the right above, we have
\begin{equation*}
    \wtexpv{}{}{\left(\ol{Z}^{\mbf{A}}_{\wh{a}_n}\right)^{-p}} = \expvs{\Ecal\Bigl(\int_t^{\cdot} (1 - p) \ol{\mbf{A}}_u 'dW_u \Bigr)_{\wh{a}_n}\e^{\frac{p(p - 1)}{2} \int_t^{\wh{a}_n} \abs{\tprobnu_u}^2 d u}}.
\end{equation*}
From part (ii) of Assumption \ref{A:incomplete_mkt}, we obtain by strong uniqueness (which holds under our assumptions) that the quantity on the right above is bounded from above by
\begin{equation*}
    \expvs{\e^{\frac{p(p - 1)}{2}\int_t^T \abs{\tprobnu(u,X^{(p),t,x})}^2 d u}},
\end{equation*}
which for $t\leq T, x\in \ol{\OO}_k$ is bounded by a constant $C(p, k)$. As for the second term in \eqref{E:holder_inequality_Qi}, we also have from Assumption \ref{A:incomplete_mkt} that for $K>0$ small enough 
\begin{equation*}
    \wtexpv{}{}{\e^{ \frac{K p}{p - 1} \int_{\wh{a}_n}^{\wh{b}_n} Q_i(u,X_u) d u } } \leq \wtexpv{}{}{\e^{\eps_2 \int_{t}^{T} Q_i(u,X^{t,x}) du } },
\end{equation*}
which for $t\leq T$ and $x\in\ol{\OO}_k$ is bounded by some constant $C(k)$.  This finishes showing $\qprob^n\in \tM^n$. 

We move to show that $\{ Z^n_{\wh{b}_n} \log (Z^n_{\wh{b}_n}) \}$ is uniformly integrable.  Once this is done, we can apply the same arguments in the proof of \textit{Proposition A.10}  to show that 
\begin{equation*}
\left\{ Z^n_{\wh{b}_n} \bigl(1_{\tau^n > \wh{b}_n} (\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n, X_{\tau^n}) \bigr) \right\}
\end{equation*} 
is uniformly integrable. Given this uniform integrability and 
\begin{equation*} 
Z^n_{\wh{b}_n} \bigl( 1_{\tau^n > \wh{b}_n} (\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n,X_{\tau^n}) \bigr) \cvas Z^{\qprob}_{T \wedge \tau} \bigl( 1_{\tau > T} \phi(X_{T}) + 1_{\tau \leq T} \psi(\tau,X_{\tau}) \bigr),
\end{equation*}
we obtain the limit
\begin{equation*}
    \lim_{n \to \infty} \expv{}{}{Z^n_{\wh{b}_n} \bigl(1_{\tau^n > \wh{b}_n} (\chi_n \phi)(X_{\wh{b}_n}) + 1_{\tau^n \leq \wh{b}_n} \psi(\tau^n,X_{\tau^n}) \bigr) } = \expv{}{}{Z^{\qprob}_{T \wedge \tau} \bigl( 1_{\tau > T} \phi(X_{T}) + 1_{\tau \leq T} \psi(\tau,X_{\tau}) \bigr)}.
\end{equation*}
To show the uniform integrability of $\{ Z^n_{\wh{b}_n} \log (Z^n_{\wh{b}_n}) \}$, note that as
\begin{equation*}
    Z^n_{\wh{b}_n} \log (Z^n_{\wh{b}_n}) = Z^{\qprob}_{a_n} \log(Z^{\qprob}_{a_n}) + Z^{\qprob}_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}},
\end{equation*}
if we can show each of the families of random variables on the right above are uniformly integrable, then we have the uniform integrability of $\{ Z^n_{\wh{b}_n} \log (Z^n_{\wh{b}_n)} \}$. 

To obtain uniform integrability of $\{ Z^{\qprob}_{a_n} \log(Z^{\qprob}_{a_n})\}$, first we have $Z^{\qprob}_{a_n} \log (Z^{\qprob}_{a_n}) \cvas Z^{\qprob}_{T \wedge \tau} \log(Z^{\qprob}_{T \wedge \tau})$. Next, by non-negativity of $x \log x + \frac{1}{e}$ for $x \in (0, \infty)$, Jensen's inequality and Fatou's lemma imply
\begin{align*}
    \expvs{Z^{\qprob}_{a_n} \log(Z^{\qprob}_{a_n}) + \frac{1}{e}} & \leq \expvs{Z^{\qprob}_{T \wedge \tau} \log(Z^{\qprob}_{T \wedge \tau}) + \frac{1}{e}} < \infty, \\
    \lim_{n \to \infty} \expvs{Z^{\qprob}_{a_n} \log(Z^{\qprob}_{a_n}) + \frac{1}{e}} & = \expvs{Z^{\qprob}_{T \wedge \tau} \log(Z^{\qprob}_{T \wedge \tau}) + \frac{1}{e}}.
\end{align*} 
By Theorem 4.6.3 in \cite{MR3930614} we can conclude that $\{ Z^{\qprob}_{a_n} \log(Z^{\qprob}_{a_n}) + \frac{1}{e} \}$ is uniformly integrable, which further implies that $\{ Z^{\qprob}_{a_n} \log(Z^{\qprob}_{a_n}) \}$ is uniformly integrable. For the second family of random variables, by \eqref{E:inequalities_prob_result} and \eqref{E:cond_inequality_Q}, we have for $K > 0$,
\begin{equation*}
    Z^{\qprob}_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} \leq \frac{1}{K} Z^{\qprob}_{a_n} \log Z^{\qprob}_{a_n} + \frac{1}{K} \wtcondexpv{}{}{\e^{K \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u}}{\F^W_{\wh{a}_n}}. 
\end{equation*}
As we have already shown that $\{ Z^{\qprob}_{a_n} \log Z^{\qprob}_{a_n}\}$ is uniformly integrable, we just need to show that $\wtcondexpv{}{}{\e^{K \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u}}{\F^W_{\wh{a}_n}}$ is uniformly integrable. For $\wt{p} > 1$, and let $p > 1$ from part (ii) of Assumption \ref{A:incomplete_mkt},
\begin{equation*}
\begin{split}
& \expvs{\left( \wtcondexpv{}{}{\e^{K \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u}}{\F^W_{\wh{a}_n}} \right)^{\wt{p}}} 
\leq \expvs{\wtcondexpv{}{}{\e^{ \wt{p} K \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u}}{\F^W_{\wh{a}_n}}} \\
& \quad = \wtcondexpv{}{}{(Z^{\tprob}_{\wh{a}_n})^{-1} \e^{K \wt{p} \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u}}{\F^W_{\wh{a}_n}} \leq \left( \wtexpv{}{}{(Z^{\tprob}_{\wh{a}_n})^{-p}} \right)^{\frac{1}{p}} \left( \wtexpv{}{}{\e^{ \frac{K \wt{p} p}{p - 1} \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u } }\right)^{\frac{p - 1}{p}}.
\end{split}
\end{equation*}
We already showed that $\wtexpv{}{}{(Z^{\tprob}_{\wh{a}_n})^{-p}}$ is bounded, and pick $K > 0$ small enough such that $K \wt{p} p/(p - 1) < \eps_2$ in part (i) of Assumption \ref{A:incomplete_mkt}, we know that $\wtexpv{}{}{\e^{ \frac{K \wt{p} p}{p - 1} \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u } }^{\frac{p - 1}{p}}$ is also bounded. Hence, $\wtcondexpv{}{}{\e^{K \int_{\wh{a}_n}^{\wh{b}_n} Q(u, X_u) d u}}{\F^W_{\wh{a}_n}}$ is bounded in $L^{\wt{p}}$, which implies uniform integrability. Putting together, the uniform integrability of $\left\{Z_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} \right\}$ follows.

Finally, by applying the same arguments in the proof of \textit{Proposition A.11}, we can show that $Z_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} \cvprob 0$ as $\condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} \cvprob 0$ and $Z_{a_n} \cvas Z_{T \wedge \tau}$. Along with uniform integrability, we obtain 
\begin{equation*}
    \lim_{n \to \infty} \expvs{Z_{a_n} \condexpv{}{}{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} } = 0.
\end{equation*} 
%Putting above together, we obtain for any $\qprob \in \wt{\M}$, 
%\begin{equation*}
%    G(t, x) \leq \frac{1}{\alpha} \expvs{Z^{\qprob}_{\tau \wedge T}\log \left( Z^{\qprob}_{\tau \wedge T} \right)} + \expvs{Z^{\qprob} \left( 1_{\tau > T} \phi_T + 1_{\tau \leq T} \psi_\tau \right)}.
%\end{equation*}
\end{proof}

