\section{Lemmas for Proposition \ref{P:localied_PDE_existence}}

Throughout, we continue to write all references to \cite{MR4086602} in italics.

\begin{lemma}\label{L:L_inv_bnd}
Under Assumption \ref{A:incomplete_mkt}, for any $\eps > 0$ when $\abs{\sigma_r} \geq \eps$, there exists constants $\ul{C}(\eps, n)$ and $\ol{C}(\eps, n)$ such that for all $(s,y) \in [0,T]\times \ol{\OO}_n$.
\begin{equation}\label{E:L_inv_bnd_res}
     \ul{C}(\eps, n) \leq \Sigma^{-1}_{i j} \leq  \ol{C}(\eps, n),\quad 1 \leq i,\ j \leq k + 1.
\end{equation}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{L:L_inv_bnd}]
Given $\Sigma_e$ is invertible, and $\Afn(\sigma_r)$ is the Schur complement of $\Sigma_e$ in $\Sigma$, by the standard result in linear algebra, we obtain
\begin{equation*}
    \Sigma^{-1} =
    \begin{pmatrix}
        \Sigma_e^{-1} + \frac{1}{\Afn(\sigma_r)} \Sigma_e^{-1} \Upsilon_e \sigma_r \sigma_r' \Upsilon_e' \Sigma_e^{-1} & - \frac{1}{\Afn(\sigma_r)} \Sigma_e^{-1} \Upsilon_e \sigma_r \\
        - \frac{1}{\Afn(\sigma_r)} \sigma_r' \Upsilon_e'\Sigma_e^{-1} & \frac{1}{\Afn(\sigma_r)}
    \end{pmatrix}.
\end{equation*}
Every term in $\Sigma^{-1}$ except $\frac{1}{\Afn(\sigma_r)}$ is bounded on $[0, T] \times \ol{\OO}_n$. By Assumption \ref{A:region} and \ref{A:incomplete_mkt}, we know that $\bAfn$ is strictly positive definite on $[0, T] \times \ol{\OO}_n$. Hence, there exists $\ol{\lambda}_n>0$ and $\ol{\Lambda}_n > 0$ such that $\ol{\lambda}_n z' z \leq z' \bAfn(s, y) z \leq \ol{\Lambda}_n z' z$ holds for any $z \neq 0 \in \reals^d$, $(s, y) \in [0, T] \times \ol{\OO}_n$. This indicates that when $\abs{\sigma_r} \geq \eps$,
\begin{equation*}
     \frac{1}{\eps^2 \ol{\Lambda}_n} \leq \frac{1}{\Afn(\sigma_r)} \leq \frac{1}{\eps^2 \ol{\lambda}_n}.
\end{equation*}
Therefore, we can find $\ul{C}(\eps, n)$ and $\ol{C}(\eps, n)$ such that equation \eqref{E:L_inv_bnd_res} holds when $\abs{\sigma_r} \geq \eps$.
\end{proof}

