\begin{lemma}\label{L:g_checka_bnd}
For $\ca^n$ defined in \eqref{E:checka_def}, there exists a constant $C(n)$ such that $g \ca^n(g, 0) \leq C(n)(1 + g^2)$ for all $(s, x) \in [0, T] \times \OO_n$.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{L:g_checka_bnd}]
We will separate our proof based upon if Assumption \ref{A:complete_mkt} or Assumption \ref{A:incomplete_mkt} holds, and unless explicitly stated otherwise, omit the functional dependence on $(s,y)$. When Assumption \ref{A:complete_mkt} holds, from \eqref{E:checka_def} and \eqref{E:Hcal_is_ok_1} we obtain  $\ca^n(g, 0) = \chi_n \left(\gamma/\alpha + \wh{\Hcal}(g) \right)$ where 
\begin{equation*}
    \wh{\Hcal}(g) = -\frac{\gamma}{\alpha}-\wt{\gamma}g + F.
\end{equation*}
This clearly implies
\begin{equation*}
    \sup_{(s, y) \in [0, T] \times \ol{\OO}_n} \frac{g \ca^n(g, 0)}{1 + g^2} < \infty.
\end{equation*}
Similarly, under Assumption \ref{A:incomplete_mkt} from \eqref{E:Hcal_is_ok_2} we find
\begin{equation*}
    \ca^n(g, 0) = \chi_n \left( \frac{\gamma}{\alpha} + \wh{\Hcal}(g) + R_{\Hcal}(\sigma_r, g, 0) \right).
\end{equation*}
First consider when $\abs{\sigma}_r \equiv 0$. As $R_{\Hcal} = 0$ we similarly obtain 
\begin{equation*}
    \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_n, \\ \abs{\sigma_r} \equiv 0}} \frac{g \ca^n(g, 0)}{1 + g^2}  < \infty.
\end{equation*}
Next, consider when $\abs{\sigma_r}(s,y) > 0$ for each fixed $(s,y)$.  Using the regularity of $(s,y)\to \sigma_r(s,y)$ we deduce the existence of an $\eps(n)>0$ such that $\abs{\sigma_r} \geq \eps(n)$ for $(s,y)\in [0,T]\times \ol{\OO_n}$. From Lemma \ref{L:L_inv_bnd} we see the matrix $\Sigma$ in \eqref{E:SigE_UpsE} is uniformly elliptic in $[0,T]\times \ol{\OO}_n$ (with ellipticity constant depending on $n$) and hence we can invoke \textit{Lemma C.2} to obtain
\begin{equation*}
    \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_n, \\ \abs{\sigma_r} \geq \eps(n)}} \frac{g \ca^n(g, 0)}{1 + g^2} < \infty.
\end{equation*}
This finishes the result.
\end{proof}


%-------------------------------------------------------%

\begin{lemma}\label{L:p_checka_bnd}
For $\ca^n$ defined in \eqref{E:checka_def}, and any interval $[g_1, g_2]$,
\begin{equation*}
    \limsup_{\abs{p} \uparrow \infty} \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_n, \\ g \in [g_1, g_2]}} \frac{\abs{\ca^n(g, p)}}{\abs{p}^2} < \infty.
\end{equation*}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{L:p_checka_bnd}]
We will separate our proof based on Assumptions \ref{A:complete_mkt} and \ref{A:incomplete_mkt}, and omit the functional dependence on $(s,y)$. First, under Assumption \eqref{A:complete_mkt}, using \eqref{E:checka_def} and \eqref{E:Hcal_is_ok_1} we see that $\ca^n(g, p)$ is a quadratic function with respect to $p$, with quadratic term $-\frac{\alpha}{2} p' (A - \chi_n \Upsilon_e' \Sigma_e^{-1} \Upsilon_e) p$. Since $\rho = \idmat{d}$ we have $A - \chi_n \Upsilon_e' \Sigma_e^{-1} \Upsilon_e = (1 - \chi_n) A$ and hence
\begin{equation*}
    \limsup_{\abs{p} \uparrow \infty} \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_n, \\ g \in [g_1, g_2]}} \frac{\abs{\ca^n(g, p)}}{\abs{p}^2} < \infty.
\end{equation*}
Under Assumption \ref{A:incomplete_mkt} from \eqref{E:Hcal_is_ok_2} we see
\begin{equation*}
    \ca^n(g, p) = b' p - \frac{\alpha}{2} p' A p + \chi_n \left( - \wt{\gamma}g + F + \frac{\alpha}{2}p'\Upsilon_e'\Sigma_e^{-1}\Upsilon_e p - p'\Upsilon_e'\Sigma_e^{-1}(\mu_e-\wt{\gamma}\ell_e) + R_{\Hcal}(\sigma_r,g,p) \right).
\end{equation*}
When $\abs{\sigma_r} \equiv 0$ we  know $R_{\Hcal} = 0$ and hence $\ca^n(g, p)$ is a quadratic function with respect to $p$. Therefore 
\begin{equation*}
    \limsup_{\abs{p} \uparrow \infty} \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_n, \\ g \in [g_1, g_2],\ \abs{\sigma_r} \equiv 0}} \frac{\abs{\ca^n(g, p)}}{\abs{p}^2}  < \infty.
\end{equation*}
Alternatively, when $\abs{\sigma}_r(s,y) > 0$ for all $(s,y)$ by the regularity of $(s,y)\to\sigma_r(s,y)$ we know there is an $\eps(n)$ so that $\abs{\sigma_r}\geq \eps(n)$ on $[0,T]\times \ol{\OO}_n$. Therefore, using Lemma \ref{L:L_inv_bnd} we may invoke \textit{Lemma C.3} to obtain 
\begin{equation*}
    C(\eps, n) \dfn  \limsup_{\abs{p} \uparrow \infty} \sup_{\substack{(s, y) \in [0, T] \times \ol{\OO}_n, \\ g \in [g_1, g_2], \abs{\sigma_r} \geq \eps(n)}} \frac{\abs{\ca^n(g, p)}}{\abs{p}^2} < \infty,
\end{equation*}
finishing the result.
\end{proof}

