\section{Lemmas for Proposition \ref{P:analytical_unwind}} Throughout, we continue to write all references to \cite{MR4086602} in italics.


\begin{lemma}\label{L:BCD_k_infty_finite_1}
Under Assumption \ref{A:complete_mkt}, for $B^{\infty}_k$, $C^{\infty}_k$, and $D^{\infty}_k$ defined in \eqref{E:ABCD_def}, \eqref{E:ABCD_k_infty}, we have
\begin{equation*}
    B^{\infty}_k < \infty, \quad C^{\infty}_k = 0, \quad D^{\infty}_k < \infty.
\end{equation*}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{L:BCD_k_infty_finite_1}] Recall that for $n\geq k+1$ we have $\chi_n = 1$ on $\ol{\OO}_k$ and hence we write $\check{a}$ for $\check{a}^n$ in \eqref{E:checka_def}. Next, under Assumption \ref{A:complete_mkt} we know from  \eqref{E:Hcal_is_ok_1} that 
\begin{equation}\label{E:check_a_comp_0}
    \ca(g, p) = \bigl( b -\Upsilon_e'\Sigma_e^{-1}(\mu_e-\wt{\gamma}\ell_e)\bigr)'p  - \wt{\gamma}g + F.
\end{equation}
(the quadratic term $-(\alpha/2)p' (A - \Upsilon_e' \Sigma_e^{-1} \Upsilon_e) p$ vanishes as $\rho = \idmat{d}$). Therefore, 
\begin{equation*}
    \begin{split}
    \nabla_p \Ecal &= Ap;\quad (\ol{\delta}(p)-1)[\Ecal] = \Ecal;\quad \delta(p)[\Ecal] = \frac{1}{2\abs{p}^2} p'\bigg(\sum_{i,j=1}^d p_i p_j \nabla_x A^{ij}\bigg),\\
    \nabla_p \ca(g, p) &= b - \Upsilon_e' \Sigma_e^{-1} \left(\mu_e - \wt{\gamma}\ell_e\right);\quad \bigl( \ol{\delta}(p) - 1 \bigr) [\ca](g, p) =  \wt{\gamma}g - F,\\
    %& - \frac{1}{2 \alpha} \left(\mu_e - \wt{\gamma}\ell_e\right)'\Sigma_e^{-1}\left(\mu_e - \wt{\gamma}\ell_e\right) \\
    %& \qquad - \frac{\gamma}{\alpha} + \frac{\wt{\gamma}}{\alpha}\left(\alpha(g-\psi) + 1 + \log\left(\frac{\gamma}{\wt{\gamma}}\right)\right). \\
    \delta(p) [\ca](g, p) &= -\wt{\gamma} + \frac{1}{\abs{p}^2} p'\bigg(\sum_{i = 1}^{d} p^i \nabla_x \bigl( b -\Upsilon_e'\Sigma_e^{-1}(\mu_e-\wt{\gamma}\ell_e)\bigr)^i -g\nabla_x \wt{\gamma} + \nabla_x F\bigg).
    %& \qquad + \frac{1}{\abs{p}^2} \frac{1}{2 \alpha} \sum_{i = 1}^{d} p_i \nabla_x \bigl( \left(\mu_e - \wt{\gamma}\ell_e\right)'\Sigma_e^{-1}\left(\mu_e - \wt{\gamma}\ell_e\right) \bigr)^i \\ 
    %& \qquad + \frac{1}{\abs{p}^2} \sum_{i = 1}^{d} p_i \nabla_x \left( \frac{\gamma}{\alpha} - \frac{\wt{\gamma}}{\alpha}\left(\alpha(g-\psi) + 1 + \log\left(\frac{\gamma}{\wt{\gamma}}\right)\right) \right)^i.
    \end{split}
\end{equation*}
As $\delta(p) [\Ecal]$ is on the order of $\abs{p}$ and $\bigl( \ol{\delta}(p) - 1 \bigr) [\ca]$ is on the order of $1$, $B_k^\infty < \infty$ (in fact $B^k_{\infty} = 0$). As $\delta(p)[A^{ij}]$ is on the order of $1/\abs{p}$ and $\delta(p) [\ca]$ is on the order of $1$, $C_k^\infty = 0$. Finally, as $\Lambda_k p' p$ is on the order of $\abs{p}^2$ and $\abs{p} \left( \abs{\nabla_p \Ecal} + \abs{\nabla_p \ca} \right)$ is on the order of $\abs{p}^2$, $D_k^\infty < \infty$. This finishes the result.
\end{proof}


