\begin{lemma}\label{L:BD_k_infty_finite_2}
Under Assumption \ref{A:incomplete_mkt}, for $B^{\infty}_k$ and $D^{\infty}_k$ defined in \eqref{E:ABCD_k_infty}, we have
\begin{equation*}
    B^{\infty}_k < \infty,\quad C^{\infty}_k = 0,\quad D^{\infty}_k < \infty.
\end{equation*}
\end{lemma}

\begin{proof}[Proof of Lemma \ref{L:BD_k_infty_finite_2}]
We start by considering when  $\abs{\sigma_r} = 0$.  Here, from \eqref{E:Hcal_is_ok_2} we find
\begin{equation*}
    \check{a} = \left(b-\Upsilon_e'\Sigma_e^{-1}(\mu_e - \wt{\gamma}\ell_e)\right)'p - \frac{\alpha}{2}p'\left(A-\Upsilon_e'\Sigma_e^{-1}\Upsilon_e\right)p  -\wt{\gamma} g + F.
\end{equation*}
This is very similar to \eqref{E:check_a_comp_0} and direct computation shows
\begin{equation*}
    \begin{split}
    \nabla_p \ca(g, p) &= b - \Upsilon_e' \Sigma_e^{-1} \left(\mu_e - \wt{\gamma}\ell_e\right) - \alpha \left(A-\Upsilon_e'\Sigma_e^{-1}\Upsilon_e\right)p,\\
    \bigl( \ol{\delta}(p) - 1 \bigr) [\ca](g, p) &=  -\frac{\alpha}{2}p'\left(A-\Upsilon_e'\Sigma_e^{-1}\Upsilon_e\right)p + \wt{\gamma}g - F,\\
    \delta(p) [\ca](g, p) &= -\wt{\gamma} + \frac{1}{\abs{p}^2} p'\bigg(\sum_{i = 1}^{d} p^i \nabla_x \bigl( b -\Upsilon_e'\Sigma_e^{-1}(\mu_e-\wt{\gamma}\ell_e)\bigr)^i \\
    &\qquad\qquad - \frac{\alpha}{2}\sum_{i,j=1}^d p^ip^j \nabla_x \left(A-\Upsilon_e'\Sigma_e^{-1}\Upsilon_e\right)^{ij} -g\nabla_x \wt{\gamma} + \nabla_x F\bigg).
    \end{split}
\end{equation*}
Just like in Lemma \ref{L:BCD_k_infty_finite_1}, as $\delta(p) [\Ecal]$ is on the order of $\abs{p}$ and $\bigl( \ol{\delta}(p) - 1 \bigr) [\ca]$ is on the order of $\abs{p}^2$, $B_k^{\infty} < \infty$. As $\delta(p)[A^{ij}]$ is on the order of $1/\abs{p}$ and $\delta(p) [\ca]$ is on the order of $\abs{p}$, $C_k^{\infty} = 0$. Finally, as $\Lambda_k p' p$ is on the order of $\abs{p}^2$ and $\abs{p} \left( \abs{\nabla_p \Ecal} + \abs{\nabla_p \ca} \right)$ is on the order of $\abs{p}^2$, $D_k^{\infty} < \infty$. This finishes the result restricting to $\abs{\sigma_r} = 0$. 

Next, when $\abs{\sigma}_r(s,y) > 0$ for all $(s,y)$, just like above, the regularity of $(s,y)\to\sigma_r(s,y)$ yields an $\eps(k)$ so that $\abs{\sigma_r}\geq \eps(k)$ on $[0,T]\times \ol{\OO}_k$. Therefore, using Lemma \ref{L:L_inv_bnd} we may invoke \textit{Lemma C.5} to obtain $B^{\infty}_k <\infty$, $C^{\infty}_k = 0$ and $D^{\infty}_k < \infty$.  This finishes the result.

\end{proof}

