\section{Lemma for Proposition \ref{P:unwind_prob}}\label{AS:PropE9Lem}

\begin{lemma}\label{L:long_cond_exp}
\begin{equation*}
    \begin{split}
        &\condexpvs{\frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \log \left( \frac{\ol{Z}^n_{b_n}}{\ol{Z}^n_{a_n}} \right)}{\G^n_{a_n}} = 1_{\tau^n > \wh{a}_n} \wt{\mathbb{E}}\bigg[\int_{\wh{a}_n}^{\wh{b}_n} e^{-\int_{\wh{a}_n}^u (\chi_n\wt{\gamma})(v,X_v)dv}\bigg(\frac{1}{2}\abs{\mbf{\ol{A}}_u}^2\\
        &\qquad\qquad + \frac{1}{2}\abs{\ol{\mbf{B}}^{n}_u}^2 + \bigg(\chi_n\wt{\gamma}\bigg(\frac{\gamma}{\wt{\gamma}} - 1 - \log\bigg(\frac{\gamma}{\wt{\gamma}}\bigg)\bigg)\bigg)(u,X_u)\bigg)du\ \bigg| \ \F^W_{\wh{a}_n}\bigg].
    \end{split}
\end{equation*}
\end{lemma}

\begin{proof}
Throughout this proof, we write $Z_{a,b} = Z_b/Z_a$ for any strictly positive process $Z$. First, on the set $\{ \tau^n \leq \wh{a}_n\}$, $a_n = b_n$ and $\ol{Z}^n_{a_n} = \ol{Z}^n_{b_n}$, which implies $\ol{Z}^n_{a_n,b_n} = \ol{Z}_{a_n,a_n} = 1$ and hence 
\begin{equation*}
    \condexpvs{ \ol{Z}^n_{a_n,b_n}\log \left( \ol{Z}^n_{a_n,b_n}\right)}{\G^n_{a_n}} = 0,\quad \left(\textrm{ on } \{ \tau^n \leq \wh{a}_n\}\right).
\end{equation*}
Therefore, from now on, we restrict to $\{ \tau^n > \wh{a}_n\}$ where  $a_n = \tau^n \wedge \wh{a}_n = \wh{a}_n$ and hence $\ol{Z}^n_{a_n,b_n} = \ol{Z}^n_{\wh{a}_n,b_n}$. Using \eqref{E:bZ_ABD_n} we have
\begin{equation*}
    \ol{Z}^n_{\wh{a}_n,b_n} = \ol{Z}^{\mbf{A}}_{\wh{a}_n,b_n} \times \ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}\times \ol{Z}^{\mbf{C},n}_{\wh{a}_n,b_n}.
\end{equation*}
From \cite[Chapter 1]{MR1121940}, we may replace $\G^n_{a_n}$ with $\G^n_{\wh{a}_n}$ as we are restricting to $\cbra{\tau^n > \wh{a}_n}$.  Lastly, we write $Y^{a}$ for any process $Y$ stopped at any random time $a$.  Given all of this, let $A_{\wh{a}_n} \in \F^{W,B,\wh{W}}_{\wh{a}_n}$ and let $\varphi$ any function of the path $H^n$.  First, we have
\begin{equation*}
    \begin{split}
        &\expvs{\ol{Z}^n_{\wh{a}_n,b_n}\log\left(\ol{Z}^n_{\wh{a}_n,b_n}\right)1_{\tau^n > \wh{a}_n} 1_{A_{\wh{a}_n}} \varphi((H^n)^{\wh{a}_n})}\\
        &\qquad\qquad = \expvs{\ol{Z}^{\mbf{A}}_{\wh{a}_n,b_n} \ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n} \ol{Z}^{\mbf{C},n}_{\wh{a}_n,b_n}\log\left(\ol{Z}^{\mbf{A}}_{\wh{a}_n,b_n}  \ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n} \ol{Z}^{\mbf{C},n}_{\wh{a}_n,b_n}\right) 1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n})\left(1_{\tau^n > \wh{b}_n} + 1_{\wh{b}_n\geq \tau^n > \wh{a}_n}\right)}.
    \end{split}
\end{equation*}
Let us focus on the term with $\tau^n > \wh{b}^n$ (so that $b_n = \wh{b}_n$), labeling it $\mbf{Q}_1$.  Here, (omitting function arguments so e.g.$f(v,X_v)$ is written $f_v$ and defining $\Hcal_n = \F^{W,B,\wh{W}}_{\wh{a}_n} \vee \F^{W}_{\wh{b}_n}\vee \sigma(\tau^n)$)
\begin{equation*}
    \begin{split}
        \mbf{Q}_1 &= \E\Bigg[1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n}) 1_{\tau^n > \wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,\wh{b}_n} e^{-\int_{\wh{a}_n}^{\wh{b}_n} (\chi_n(\wt{\gamma}-\gamma))_vdv}\bigg(\bigg(\log\big(\ol{Z}^{\mbf{A}}_{\wh{a}_n,\wh{b}_n}\big) - \int_{\wh{a}_n}^{\wh{b}_n} (\chi_n(\wt{\gamma}-\gamma))_u du\bigg)\\
        &\qquad \times \condexpvs{\ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}}{\Hcal_n} + \condexpvs{\ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}\log\big(\ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}\big)}{\Hcal_n}\bigg)\Bigg],\\
        &= \E\Bigg[1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n}) 1_{\tau^n > \wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,\wh{b}_n} e^{-\int_{\wh{a}_n}^{\wh{b}_n} (\chi_n(\wt{\gamma}-\gamma))_v dv}\bigg(\int_{\wh{a}_n}^{\wh{b}_n} \mbf{\ol{A}}_u'd\wt{W}_u + \frac{1}{2}\int_{\wh{a}_n}^{\wh{b}_n} \abs{\mbf{\ol{A}}_u}^2 du\\
        &\qquad - \int_{\wh{a}_n}^{\wh{b}_n} (\chi_n(\wt{\gamma}-\gamma))_u du  + \frac{1}{2}\int_{\wh{a}_n}^{\wh{b}_n} \abs{\mbf{\ol{B}}^n_u}^2 du\bigg)\Bigg],\\
        &= \E\Bigg[1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n}) e^{-\int_t^{\wh{a}_n} (\chi_n\gamma)_v dv} \E\bigg[\ol{Z}^{\mbf{A}}_{\wh{a}_n,\wh{b}_n} e^{-\int_{\wh{a}_n}^{\wh{b}_n} (\chi_n\wt{\gamma})_v dv}\bigg(\int_{\wh{a}_n}^{\wh{b}_n} \mbf{\ol{A}}_u'd\wt{W}_u + \frac{1}{2}\int_{\wh{a}_n}^{\wh{b}_n} \abs{\mbf{\ol{A}}_u}^2 du\\
        &\qquad - \int_{\wh{a}_n}^{\wh{b}_n} (\chi_n(\wt{\gamma}-\gamma))_u du  + \frac{1}{2}\int_{\wh{a}_n}^{\wh{b}_n} \abs{\mbf{\ol{B}}^n_u}^2 du\bigg)\ \bigg| \ \F^W_{\wh{a}_n} \bigg]\Bigg],\\
    \end{split}
\end{equation*}
Above, to obtain the third equality we first conditioned on $\F^W_{\wh{b}_n}$ and used the intensity function of $\tau^n$ under $\prob$, and then we conditioned on $\F^W_{\wh{a}_n}$.  Next, we focus on the term with $\wh{a}_n \leq \tau^n < \wh{b}_n$, labeling it $\mbf{Q}_2$.
\begin{equation*}
    \begin{split}
        \mbf{Q}_2 &= \E\Bigg[1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n}) 1_{\wh{a}_n\leq \tau^n < \wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,\tau^n} e^{-\int_{\wh{a}_n}^{\tau^n} (\chi_n(\wt{\gamma}-\gamma))_vdv}\left(\frac{\wt{\gamma}}{\gamma}\right)_{\tau^n}\bigg(\bigg(\log\big(\ol{Z}^{\mbf{A}}_{\wh{a}_n,\tau^n}\big)\\
        &\qquad - \int_{\wh{a}_n}^{\tau^n} (\chi_n(\wt{\gamma}-\gamma))_u du + \left(\frac{\wt{\gamma}}{\gamma}\right)_{\tau^n}\bigg)\condexpvs{\ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}}{\Hcal_n} + \condexpvs{\ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}\log\big(\ol{Z}^{\mbf{B},n}_{\wh{a}_n,b_n}\big)}{\Hcal_n}\bigg)\Bigg],\\
        &= \E\Bigg[1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n}) 1_{\wh{a}_n\leq \tau^n < \wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,\tau^n} e^{-\int_{\wh{a}_n}^{\tau^n} (\chi_n(\wt{\gamma}-\gamma))_vdv}\left(\frac{\wt{\gamma}}{\gamma}\right)_{\tau^n}\bigg(\int_{\wh{a}_n}^{\tau^n} \mbf{\ol{A}}_u'd\wt{W}_u\\
        &\qquad + \frac{1}{2}\int_{\wh{a}_n}^{\tau^n} \abs{\mbf{\ol{A}}_u}^2 du - \int_{\wh{a}_n}^{\tau^n} (\chi_n(\wt{\gamma}-\gamma))_u du + \left(\frac{\wt{\gamma}}{\gamma}\right)_{\tau^n} + \frac{1}{2}\int_{\wh{a}_n}^{\tau^n} \abs{\mbf{\ol{B}}^n_u}^2 du\bigg)\Bigg],\\
        &= \E\Bigg[1_{A_{\wh{a}_n}} \varphi((0)^{\wh{a}_n})e^{-\int_t^{\wh{a}_n}(\chi_n\gamma)_v dv}\E\bigg[\bigg( \int_{\wh{a}_n}^{\wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,u} (\chi_n\wt{\gamma})_u e^{-\int_{\wh{a}_n}^{u} (\chi_n\wt{\gamma})_vdv}\bigg(\int_{\wh{a}_n}^{u} \mbf{\ol{A}}_v'd\wt{W}_v\\
        &\qquad + \frac{1}{2}\int_{\wh{a}_n}^{u} \abs{\mbf{\ol{A}}_v}^2 dv  - \int_{\wh{a}_n}^{u} (\chi_n(\wt{\gamma}-\gamma))_v dv + \left(\frac{\wt{\gamma}}{\gamma}\right)_{u} + \frac{1}{2}\int_{\wh{a}_n}^{u} \abs{\mbf{\ol{B}}^n_v}^2 dv\bigg)du\bigg)\ \bigg| \ \F^W_{\wh{a}_n}\bigg]\Bigg].
    \end{split}
\end{equation*}
For a generic $\F^W_{\wh{a}_n}$ measurable random variable $Y_n$ one has
\begin{equation*}
    \E\Bigg[Y_n 1_{\tau^n>\wh{a}_n}1_{A_{\wh{a}_n}}\varphi((H^n)^{\wh{a}_n}\Bigg] = \E\Bigg[1_{A_{\wh{a}_n}}\varphi((0)^{\wh{a}_n})e^{-\int_t^{\wh{a}_n}(\chi_n\gamma)_v dv} Y_n\Bigg].
\end{equation*}
This shows that
\begin{equation*}
    \condexpvs{\ol{Z}^n_{\wh{a}_n,b_n}\log\left(\ol{Z}^n_{\wh{a}_n,b_n}\right)1_{\tau^n > \wh{a}_n}}{\G^n_{\wh{a}_n}} = 1_{\tau^n>\wh{a}_n} \times \mbf{Q}_3,
\end{equation*}
where
\begin{equation*}
    \begin{split}
         \mbf{Q}_3 &=  \E\bigg[\ol{Z}^{\mbf{A}}_{\wh{a}_n,\wh{b}_n} e^{-\int_{\wh{a}_n}^{\wh{b}_n} (\chi_n\wt{\gamma})_v dv}\bigg(\int_{\wh{a}_n}^{\wh{b}_n} \mbf{\ol{A}}_u'd\wt{W}_u + \frac{1}{2}\int_{\wh{a}_n}^{\wh{b}_n} \abs{\mbf{\ol{A}}_u}^2 du \\
        &\quad - \int_{\wh{a}_n}^{\wh{b}_n} (\chi_n(\wt{\gamma}-\gamma))_u du  + \frac{1}{2}\int_{\wh{a}_n}^{\wh{b}_n} \abs{\mbf{\ol{B}}^n_u}^2 du\bigg) + \int_{\wh{a}_n}^{\wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,u} (\chi_n\wt{\gamma})_u e^{-\int_{\wh{a}_n}^{u} (\chi_n\wt{\gamma})_vdv}\\
        &\quad \times \bigg(\int_{\wh{a}_n}^{u} \mbf{\ol{A}}_v'd\wt{W}_v + \frac{1}{2}\int_{\wh{a}_n}^{u} \abs{\mbf{\ol{A}}_v}^2 dv  - \int_{\wh{a}_n}^{u} (\chi_n(\wt{\gamma}-\gamma))_v dv + \left(\frac{\wt{\gamma}}{\gamma}\right)_{u} + \frac{1}{2}\int_{\wh{a}_n}^{u} \abs{\mbf{\ol{B}}^n_v}^2 dv\bigg)du \ \bigg| \ \F^W_{\wh{a}_n}\bigg]. 
    \end{split}
\end{equation*}
For any $\filt^{W}$ adapted process $R$ one can show
\begin{equation*}
    \condexpvs{\int_{\wh{a}_n}^{\wh{b}_n} \ol{Z}^{\mbf{A}}_{\wh{a}_n,u} R_u du}{\F^W_{\wh{a}_n}} = \wtcondexpv{}{}{\int_{\wh{a}_n}^{\wh{b}_n} R_u du}{\F^W_{\wh{a}_n}}.
\end{equation*}
So, with 
\begin{equation*}
    \begin{split}
        R_u &= \int_{\wh{a}_n}^u \mbf{\ol{A}}_v'd\wt{W}_v + \frac{1}{2}\int_{\wh{a}_n}^u \abs{\mbf{\ol{A}}_v}^2 dv - \int_{\wh{a}_n}^u (\chi_n(\wt{\gamma}-\gamma))_v dv + \frac{1}{2}\int_{\wh{a}_n}^u \abs{\mbf{\ol{B}}^n_v}^2 dv,\\
        D_u &= e^{-\int_{\wh{a}_n}^u (\chi_n\wt{\gamma})_v dv},
    \end{split}
\end{equation*}
we obtain
\begin{equation*}
    \begin{split}
        \mbf{Q}_3 &= \wt{\E}\Bigg[ D_{\wh{b}_n} R_{\wh{b}_n} - \int_{\wh{a}_n}^{\wh{b}_n} R_u dD_u + \int_{\wh{a}_n}^{\wh{b}_n} (\chi_n\wt{\gamma})_u e^{-\int_{\wh{a}_n}^u (\chi_n\wt{\gamma})_v dv}\log\left(\frac{\wt{\gamma}}{\gamma}\right)_u du \ \bigg| \ \F^W_{\wh{a}_n} \Bigg],\\
        &= \wt{\E}\Bigg[ \int_{\wh{a}_n}^{\wh{b}_n} D_u dR_u + \int_{\wh{a}_n}^{\wh{b}_n} (\chi_n\wt{\gamma})_u e^{-\int_{\wh{a}_n}^u (\chi_n\wt{\gamma})_v dv}\log\left(\frac{\wt{\gamma}}{\gamma}\right)_u du \ \bigg| \ \F^W_{\wh{a}_n} \Bigg],\\
        &= \wt{\E}\Bigg[ \int_{\wh{a}_n}^{\wh{b}_n} D_u \bigg( \bar{A}_u'd\wt{W}_u + \bigg((\chi_n\wt{\gamma})_u \log\left(\frac{\wt{\gamma}}{\gamma}\right)_u   + \frac{1}{2}\abs{\mbf{\ol{A}}_u}^2  -  (\chi_n(\wt{\gamma}-\gamma))_u  + \frac{1}{2}\abs{\mbf{\ol{B}}^n_u}^2\bigg) du\bigg) \ \bigg| \ \F^W_{\wh{a}_n} \Bigg],\\
        &= \wt{\E}\Bigg[ \int_{\wh{a}_n}^{\wh{b}_n} D_u \bigg(\frac{1}{2}\abs{\mbf{\ol{A}}_u}^2 + \frac{1}{2}\abs{\mbf{\ol{B}}^n_u}^2 + (\chi_n\wt{\gamma})_u\bigg(\frac{\gamma}{\gamma} - 1 - \log\left(\frac{\gamma}{\wt{\gamma}}\right)\bigg)_u \bigg)du \ \bigg| \ \F^W_{\wh{a}_n} \Bigg].
    \end{split}
\end{equation*}
This gives the result.

\end{proof}
